export default [{"id":45,"question":"ما حكم الغش في الاختبارات الدراسية، علمًا بأن المدرس على علم من ذلك؟","title":"ما حكم الغش بالاختبارات مع عِلْم المُعَلِّم؟","answer":"الجواب: الغش مُحَرّم في الاختبارات كما أنه محرم في المعاملات، فليس لأحد أن يغش في الاختبارات في أي مادة، وإذا رضي الأستاذ بذلك فهو شريكه في الإثم، إذا رضي الأستاذ بذلك فهم شريكان في الإثم والخيانة، والله المستعان.","link":"https://binbaz.org.sa/fatwas/2825/ما-حكم-الغش-بالاختبارات-مع-علم-المعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0018.mp3","categories":["الأخلاق المذمومة"]},{"id":154,"question":"كما أوضحتَ فضيلتكم الخيانة -ومنها الغشّ في الامتحان- أرجو توضيح الحكم الشرعي في ذلك مع ذكر الدَّليل؟","title":"ما حكم الغش في الامتحان ونحوه؟","answer":"الجواب: الغشُّ في الامتحان لا شكَّ أنه يدخل في العموم، والدليل: يقول النبيُّ ﷺ: مَن غشَّنا فليس منا، هكذا قال النبيُّ ﷺ: مَن غشَّنا فليس منا.\nوإذا كان الغشُّ في البيع والشراء حرامًا فهو في العلم كذلك؛ لأنَّ طالب العلم تُعلّق عليه آمال، وتُعلّق عليه أحكام، فإذا غشَّ في امتحاناته واختباراته فقد يُنسب إلى العلم ويُعدّ من العلماء وهو ليس كذلك، وإنما حصل ما حصل من الشَّهادات من طريق الخيانات، ومن طريق الكذب، ومن طريق التزوير، فيضرّ نفسَه، ويضرّ الناس، والحديث عام: مَن غشَّنا فليس منا.\nولما مرَّ النبيُّ ﷺ على صبرةٍ من طعامٍ أدخل يده فيها، فنالت أصابعه بللًا، فقال: ما هذا يا صاحب الطعام؟ قال: أصابته السَّماء يا رسول الله، يعني: المطر، قال: أفلا جعلتَه فوق الطعام كي يراه الناسُ، مَن غشَّ فليس منا.","link":"https://binbaz.org.sa/fatwas/3691/ما-حكم-الغش-في-الامتحان-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0147.mp3","categories":["الأخلاق المذمومة"]},{"id":455,"question":"بالنسبة لمن أصابته جائحة هل يسأل بمقدار ما فقد؟","title":"ما مقدار ما يسأل من أصابته جائحة؟","answer":"الجواب: مقدار حاجته، مقدار ما يغنيه ويسد حاجته، مثل ما قال: حتى يصيب قوامًا من عيش - أو قال سداد يسأل ما يسد حاجته وحاجة عياله من ملبس ومأكل ومشرب.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6179/ما-مقدار-ما-يسال-من-اصابته-جاىحة","audio":"https://files.zadapps.info/binbaz.org.sa/7aga014.mp3","categories":["الأخلاق المذمومة"]},{"id":681,"question":"إذا كان في ميت كثير الفساد، ونحذر أصحابه الذين بقوا من أفعاله؟","title":"حكم ذكر مساوئ ميت كثير الفساد","answer":"الجواب: إذا كان الفساد ظاهرًا فلا بأس، النبي ﷺ لما مر عليه بجنازة، فأثنوا عليها شرًا قال: وجبت! ما أنكر عليهم، وهذا محمول على أن معاصيه ظاهرة، فالذي معاصيه ظاهرة ليس له غيبة.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6827/حكم-ذكر-مساوى-ميت-كثير-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/maram248.mp3","categories":["الأخلاق المذمومة"]},{"id":742,"question":"لقد سمعتُ في جهاز الراديو عن سؤالٍ سأله سائلٌ ولم يرد عليه، وهو: أنا شابٌّ كثير الاحتلام في الليل، حتى إنه في كلِّ ليلٍ، وقد أشار الطبيبُ عليَّ باستعمال العادة السرية، وبالفعل استعملتُها وخفّ الحال، فما رأي فضيلتكم؟ أفيدونا أفادكم الله.","title":"ما حكم استعمال العادة السرية لعلاج الاحتلام؟","answer":"الجواب: العادة السّرية لا تجوز، وهي الاستمناء، وهي تُسبب مشاكل كثيرة، وأضرارًا عظيمة، وهي داخلة في قوله جلَّ وعلا: فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:7]، قال سبحانه: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:5- 7] يعني: الظالمون.\nوالأطباء ليسوا محلَّ استفتاء، ولا معرفة بالأحكام، وإنما يُخبرون عمَّا يُؤديهم إليه طبُّهم ومعرفتُهم بأمراض الناس ومشاكل الناس المتعلقة بالأمراض التي تعتري الإنسان.\nفالواجب على مَن بُلي بكثرة الاحتلام أن يجتهد في أسباب السلامة من ذلك بالمبادرة إلى الزواج إذا قدر، بالصيام كما قال النبيُّ ﷺ: يا معشر الشباب، مَن استطاع منكم الباءة فليتزوج، فإنه أغضُّ للبصر، وأحصن للفرج، ومَن لم يستطع فعليه بالصوم؛ فإنه له وجاء، يبتعد عن أسباب خروج المني، فيبتعد عن مخالطة النساء، أو النظر إليهن، أو التعرض للأسواق التي فيها النساء، يبتعد عن أسباب هذه الفتنة، حتى لا يكثر عليه الاحتلام.\nوإذا نام ووضع جسده في الفراش يقرأ ما تيسر: يقرأ آية الكرسي، ويقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين في يديه ثلاث مرات، يمسح بهما على وجهه وصدغيه وما أقبل من جسده، ويقول: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات، \"بسم الله الذي لا يضرُّ مع اسمه شيءٌ في الأرض ولا في السماء وهو السميع العليم\" ثلاث مرات.\nكل هذا من أسباب السلامة من كيد الشيطان، ومن كلِّ ما يضرُّه.","link":"https://binbaz.org.sa/fatwas/20661/ما-حكم-استعمال-العادة-السرية-لعلاج-الاحتلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0577ما حكم استعمال العادة السرية لعلاج الاحتلام؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأخلاق المذمومة"]},{"id":743,"question":"كثيرًا ما ترد على بعض الألسن كلمات غريبة وألفاظ ليست من عقيدتنا الإسلامية، ومن هذه الألفاظ كلمة: حمار وكلب..، وغير ذلك من الألفاظ التي لا تُقرّها شريعتنا الإسلامية، فما رأي فضيلتكم في هذه الألفاظ؟ والله الموفق.","title":"حكم السب بألفاظ \"يا كلب\" و\"حمار\" ونحوها","answer":"الجواب: لا شكَّ أن مثل هذه الألفاظ لا تليق من المؤمن مع أخيه، الله يقول جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ عَسَى أَنْ يَكُونُوا خَيْرًا مِنْهُمْ وَلَا نِسَاءٌ مِنْ نِسَاءٍ عَسَى أَنْ يَكُنَّ خَيْرًا مِنْهُنَّ وَلَا تَلْمِزُوا أَنْفُسَكُمْ وَلَا تَنَابَزُوا بِالْأَلْقَابِ بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْإِيمَانِ وَمَنْ لَمْ يَتُبْ فَأُولَئِكَ هُمُ الظَّالِمُونَ [الحجرات:11].\nمعنى وَلَا تَنَابَزُوا بِالْأَلْقَابِ أي: لا يقل أحدُكم للآخر: يا حمار، يا قط، يا كلب، يا نيص، يا خنزير، يا كذا، يا كذا، لا، يُخاطبه بالتي هي أحسن، يُخاطبه بأحسن أسمائه، وأطيب أسمائه؛ لأنَّ الخطاب بهذه الألقاب الشَّنيعة يُثير الشَّحناء والعداوة والفتن، ويُوغر الصُّدور، وربما أفضى إلى المقاتلة والمضاربة.\nفلا يجوز التَّنابز بالألقاب، كما لا يجوز اللَّمز: وَلَا تَلْمِزُوا أَنْفُسَكُمْ، واللَّمز: الغيب والغيبة، يا كذا، يلمزه بأشياء يعيبه بها: أنك تفعل كذا، وتفعل كذا، من أشياء يكرهها، بخيل، جاسوس، كذا، كذا، يعني: يرميه بأشياء هو براء منها، أو أشياء لم تُعرف عنه.\nفالواجب حفظ اللسان وعدم اللَّمز بما يجرح أخاك من أي كلمةٍ فيها جرحٌ له وعيبٌ له وإيغارٌ لصدره؛ عملًا بقوله سبحانه: وَلَا تَلْمِزُوا أَنْفُسَكُمْ، وقد يكون اللَّمز بالإشارة بالإصبع، أو بالعين، أو بغير هذا، فلا يجوز اللَّمز لا بالإشارة، ولا بالقول، ولا بالفعل، ولا يجوز أيضًا التنابز بالألقاب كما سأل السَّائل.","link":"https://binbaz.org.sa/fatwas/20659/حكم-السب-بالفاظ-يا-كلب-وحمار-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0576حكم التلفظ بكلمات سيئة مثل يا كلب يا حمار وغيره ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأخلاق المذمومة"]},{"id":757,"question":"فضيلة الشيخ حفظه الله وأطال عمره، ما حكم الشرع في الظُّلم، حيث إن بعض الأشخاص ممن ولَّاهم الله جلَّ وعلا أمورَ المسلمين يظلم مرؤوسَه، ولو أقسم له المظلومُ أنه لم يُخطئ لا يُصدّقه، مُعللًا ذلك بأنه يوجد مَن يُقسم بالله وهو كاذبٌ، وأنه يحتمل أن يكون منهم؟ وجزاك الله  خيرًا في الدنيا والآخرة، وأطال الله عمرك على عملٍ صالحٍ.","title":"ما حكم الظلم وعاقبة الظالمين؟","answer":"الجواب: الظلم من أقبح الكبائر، وهو ظلماتٌ يوم القيامة كما قاله النبيُّ ﷺ، قال: اتَّقوا الظلم، فإنَّ الظلم ظُلمات يوم القيامة، وقال عليه الصلاة والسلام: يقول الله : يا عبادي، إني حرمتُ الظلم على نفسي، وجعلتُه بينكم محرَّمًا، فلا تظالموا، ويقول الله في القرآن الكريم في سورة الفرقان: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19]، ويقول: وَالظَّالِمُونَ مَا لَهُمْ مِنْ وَلِيٍّ وَلَا نَصِيرٍ [الشورى:8].\nفالظلم شرُّه عظيم، وعاقبته وخيمة.\nويقول النبيُّ ﷺ: كل المسلم على المسلم حرام: دمه، وماله، وعِرْضه، ويقول ﷺ في حجّة الوداع: إنَّ دماءكم وأموالكم وأعراضكم عليكم حرامٌ كحُرمة يومكم هذا، في شهركم هذا، في بلدكم هذا.\nفالوالي عليه أن يتَّقي الله في الرعية، ويُحسن إليها، وأن يُؤدّبها إذا زلَّت وأخطأت، ويُوجّهها إلى الخير، ويأخذ على يد السَّفيه حتى يستقيم، فهو طبيبٌ لهم، ومُؤدِّبٌ لهم، فمَن أساء وجب أن يُوجَّه إلى الخير، وأن يُؤدَّب إذا دعت الحاجةُ إلى تأديبه حتى يستقيم، وحتى يدع العوج والأخلاق الذَّميمة، والتي تجرُّه إلى أسوأ حالةٍ، وإلى عواقب وخيمةٍ، وولي أمره يُلاحظ ذلك منه، ويُعينه على الخُلق الكريم، ويردعه عن الخلق الذَّميم، فإذا كان التأديب في محلِّه؛ لأنَّ الطالب أساء، ولم تنفع فيه النَّصيحة القولية، فالوالي عليه أن يُؤدّب: المدرس والرئيس عليهما أن يُؤدِّبا بما يريانه رادعًا، وهكذا السلطان والأمير وغير ذلك ممن لهم رئاسة، عليهم أن يعملوا ما فيه الصالح لمرؤوسيهم: بالنَّصيحة تارةً، وبالتأديب تارةً، إذا وقع ذلك في محلِّه، أما الظلم فلا.","link":"https://binbaz.org.sa/fatwas/20669/ما-حكم-الظلم-وعاقبة-الظالمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0580ما حكم الشرع في الظلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأخلاق المذمومة"]},{"id":1066,"question":"إني أحبُّك في الله يا سماحة الشيخ، وأسأل الله أن يجعلنا وإيَّاك وجميع المسلمين في ظلِّ عرشه يوم لا ظلَّ إلا ظله، ثم يسأل: نُواجه مشكلةً خطيرةً، ألا وهي: داء الحسد، وحاولتُ فعل الأسباب لدفع داء الحسد عني، ولكن بدون جدوى، وأرجو من فضيلتكم إرشادي إلى الدَّواء النَّاجع، وجزاكم الله خيرًا.","title":"ما العلاج لداء الحسد؟","answer":"الجواب:\nأما المحبَّة في الله فنقول: أحبَّك الله الذي أحببتنا له، وقد سبق ما في المحبَّة من النصوص.\nوأما الحسد: فهو داءٌ عُضالٌ، ولكن يجب عليك أن تُجاهد في إبعاده عن نفسك، وسؤال الله العافية منه، وأن تذكر أنَّ نعم الله ليس لها مَن يردها، وأنك ظالم لنفسك، وظالم لأخيك في هذا، والله هو المنعم الذي أنعم عليك وأنعم على أخيك، فعلامَ تحسده على نِعَم الله؟! عليك أن تتَّقي الله، وأن تعلم أنَّ ربَّك حكيم، وأن الحسد اعتراضٌ على الله، فجاهد نفسك، وسَلْ ربَّك التوفيق والهداية، واحذر هذا الحسد، وأحبّ لأخيك ما تُحب لنفسك من علمٍ وفضلٍ وخيرٍ، واحذر أن تسير مع الشيطان في هذا فيضرَّك ضررًا عظيمًا.\nثم أدهى من هذا وأشرّ أن تُحقق الحسدَ بإيذائه أو ظُلمه، أما مجرد الحسد فيضرّك أنت، لكن إذا زدتَ على ذلك بالقول والفعل صار شرًّا عظيمًا وظلمًا، فاحذر أن تضرَّ نفسك بالحسد، أو تضرَّ أخاك بقولٍ أو فعلٍ، وسَلْ ربَّك التوفيق والإعانة: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].","link":"https://binbaz.org.sa/fatwas/21116/ما-العلاج-لداء-الحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0912ما هو العلاج لداء الحسد؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأخلاق المذمومة"]},{"id":1447,"question":"الظلم عاقبته تُطبَّق على غير المسلمين؟","title":"هل عاقبة الظلم في حق المسلم أشدُّ من غيره؟","answer":"الجواب:\nالظلم عام، المسلمين وغير المسلمين، لكن في حقِّ المسلم أشدّ؛ لأنَّه يعرف حكم الله ويلجأ إلى حكم الله، والكافر قد يكون جاهلًا، لا يفهم، وإلا فهم مخاطبون بفروع الشريعة، ويُعذَّبون على معاصيهم وسيئاتهم مع الشرك -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/21543/هل-عاقبة-الظلم-في-حق-المسلم-اشد-من-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عاقبة الظلم أشد في حق المسلم.mp3","categories":["الأخلاق المذمومة"]},{"id":1449,"question":"يقول النبيُّ ﷺ عن الغيبة: ذِكْرك أخاك بما يكره، هل فيه تحديدٌ أنه الأخ المعلوم أو الأخ غير المعلوم؟","title":"حكم غِيبة المسلم المجهول","answer":"الجواب:\nأخٌ مسلم، يعني: ذكرك أخاك المسلم: بخيل، شحيح، قاطع رحم، يذكره بالأشياء التي يسُبّه بها.\nس: \"لا غيبة لمجهولٍ\" هل هذا صواب؟\nج: نعم، المجهول ما له غيبة، مثل: آل فلان فيهم كذا، أو بعض الناس يفعلون كذا، ما هي بغيبة، لا بدّ من تعيينه.\nس: قال أحد الذين تعرفهم لكن هم ستة فيهم كذا وكذا وكذا؟\nج: الغيبة لا بد أن تكون لمعينٍ، أما المجهول فلا غيبةَ له.\nس: وأي شيءٍ الذي أخرج الحديث؛ لأنَّ النبي ﷺ قال: أخاك يعني: أي أخٍ؟\nج: نعم؛ لأنَّ المجهول ما عرف ضرّه، إذا قال: فيه كذا وكذا، حتى يشيع البغضاء والعداوة، فما عرفوه، مثلما قال ﷺ لما مرُّوا بجنازةٍ وشهدوا لها شرًّا، فقال: وجبت، والآخر شهدوا لها خيرًا فقال: وجبت. ولم يُنْكِر عليهم؛ لظهور الشر، ولأنهم ما سموا وقالوا: فلان بن فلان.","link":"https://binbaz.org.sa/fatwas/21545/حكم-غيبة-المسلم-المجهول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في غيبة المسلم.mp3","categories":["الأخلاق المذمومة"]},{"id":1520,"question":"المُتكبر أو المتغطرس كيف يُتعامل معه؟","title":"كيف تكون معاملة المتكبر؟ وهل يُهْجَر؟","answer":"الجواب:\nيُنْصَح ويُوصَّى بالخير: ثلاثة لا يُكلِّمهم الله يوم القيامة، ولا يُزكِّيهم، ولهم عذاب أليم: شيخ زانٍ، وملك كذَّاب، وعائل مستكبر.\nس: هل يُهْجَر؟\nج: لا، يُنصح ويُوجه أولًا، فإذا أظهر الكبر وأظهر المعاصي فهو يستحق الهجر، لكن قد يكون جاهلًا يحتاج إلى تعليم، ويحتاج إلى تبصير، ويحتاج إلى نصيحة حتى يزول عنه ما بلاه الله به من الكبر، مثل غيره من أهل المعاصي، فإنهم يُنصحون أولًا ويُوجهون إلى الخير، فإذا أصرُّوا على المعاصي الظاهرة استحقُّوا الهجر، إذا كان الهجرُ أصلح في حقِّهم.","link":"https://binbaz.org.sa/fatwas/21619/كيف-تكون-معاملة-المتكبر-وهل-يهجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع المتكبر.mp3","categories":["الأخلاق المذمومة"]},{"id":1642,"question":"لو قال قائلٌ: أنا أزور أقاربي مرتين في السنة: في عيد الفطر، وفي عيد الأضحى، فهل يكون قاطعًا للرحم؟","title":"ما ضابط صلة الرحم وقطعها؟","answer":"الجواب:\nإذا ما صار بينه وبينهم سوءٌ فما هو بقاطع رحم، قاطع الرحم الذي يُؤذيهم، أو يقطع عنهم ما يجب لهم من الحقوق؛ لفقرهم وحاجتهم، أو لأمورٍ تلزمهم، لكن كونه يصلهم بالمكاتبة أو بالزيارة فهذا من باب تثبيت الصلة.","link":"https://binbaz.org.sa/fatwas/21747/ما-ضابط-صلة-الرحم-وقطعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون الشخص قاطع لرحمه.mp3","categories":["الأخلاق المذمومة"]},{"id":1643,"question":"كثر الكلام بأنَّ مَن يضرب أباه فإنَّ ابنه سيضربه بعد زمنٍ، فهل هذا صحيح؟","title":"هل صح أنَّ مَن يضرب أباه سيضربه ابنُه؟","answer":"الجواب:\nيقع، بل منهم مَن قتل أباه -نسأل الله العافية.\nس: هم يقولون: إذا ضرب أباه يجيء ولده فيضربه، حتى إنَّ واحدًا ضرب أباه وأنزله من الدّرج، فجاء ابنه فضربه وأنزله من الدّرج، فهل هذا صحيح؟\nج: قد يقع، والله أعلم، فيُعاقَب بجنس ما فعل -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21748/هل-صح-ان-من-يضرب-اباه-سيضربه-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة قول أنَّ مَن يضرب أباه فإنَّ ابنه سيضربه بعد زمنٍ.mp3","categories":["الأخلاق المذمومة"]},{"id":1675,"question":"يقول: \"أُشْهِد الله أنِّي أُحبُّك في الله\" وهو يُبغضه؟","title":"حكم مَن أخْبَرَ بالحب في الله كذبًا","answer":"الجواب:\nهذا كذَّاب، عليه إثم الكذب.\nس: قالت: \"إني أُحب العالم الفلاني في الله\"، فهل يلزم مَن رأى هذا العالم الفلاني أن يُوصِل هذه المحبة؟\nج: لا، ما هو بلازمٍ، يُستحب لها أن تُعلمه هي بنفسها، فإن أعلمته فهو أفضل.","link":"https://binbaz.org.sa/fatwas/21781/حكم-من-اخبر-بالحب-في-الله-كذبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الحب في الله.mp3","categories":["الأخلاق المذمومة"]},{"id":1774,"question":"اثنان فما فوق لا يُطلق عليهما جماعة عند الحنفية؟","title":"معنى حديث \"لا يتناجى اثنان دون الثالث\"","answer":"الجواب:\nهذا ما له تعلُّقٌ بالجمع، له تعلُّقٌ بإيذاء السامع الذي معهم، ولو كانوا ثلاثة، ولو كانوا أربعة، إذا كان الباقي واحدًا ما يفهم ما يقولون فإنه يحزن؛ لأنه يظن أنهم يتناجون فيه، وكذلك إذا تكلَّموا بلغةٍ لا يفهمها، كأن يتكلَّموا بالإنجليزية أو الفرنسية أو الأردية وهو لا يفهمها، وهو واحدٌ فقط، لا يجوز لهم ذلك؛ لأنه قد يظن أنهم يتناجون فيه، أو يتكلمون فيه بهذه اللغة.","link":"https://binbaz.org.sa/fatwas/21881/معنى-حديث-لا-يتناجى-اثنان-دون-الثالث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حديث لا يتناجى اثنان دون الثالث.mp3","categories":["الأخلاق المذمومة"]},{"id":1930,"question":"الغَيْرة هل هي من الحسد؟","title":"هل الغَيْرة مِن الحسد؟","answer":"الجواب:\nالغَيْرة غيرتان: غَيرة حسدٍ، وهذه ما تجوز. وغَيرة لله؛ لإنكار المنكر، وهذه ممدوحة.\nس: غيرة النساء على أزواجهنَّ؟\nج: هذه قد تكون غيرات طبيعية في النساء، ما هي غيرة لله، بل لأنفسهنَّ.","link":"https://binbaz.org.sa/fatwas/22043/هل-الغيرة-من-الحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الغيرة من الحسد.mp3","categories":["الأخلاق المذمومة"]},{"id":1963,"question":"صفات الفاسق؟","title":"ما صفات \"الفاسق\"؟","answer":"الجواب:\nالفاسق الذي يُعلن المعاصي: يعلن الزنا، يعلن الخمر، هذا الفاسق؛ يعلن المعاصي ويُجاهر بها.\nس: هل الموسيقى من صفات الفسوق؟\nج: المعاصي الظاهرة... مثل: عقوق الوالدين، شرب الخمر، الغِيبة الظاهرة، إذا كان يتساهل فيها ويُعلنها.","link":"https://binbaz.org.sa/fatwas/22078/ما-صفات-الفاسق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفات الفاسق.mp3","categories":["الأخلاق المذمومة"]},{"id":1972,"question":"بعض الناس من باب المِزاح يقول لأحدهم: ملعونٌ والديك؟","title":"حكم لعن الوالدين على سبيل المزاح","answer":"الجواب:\nلا، ما يجوز السّب، لا مزحًا ولا جدًّا، نسأل الله العافية.\nس: هذا يرجع إليه إن لم يكن ملعونًا؟\nج: نعم، يقول ﷺ: لعن المؤمن كقتله، إنَّ اللَّعَّانين ليسوا شهداء ولا شُفعاء يوم القيامة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22087/حكم-لعن-الوالدين-على-سبيل-المزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول ملعونٌ والديك مازحا.mp3","categories":["الأخلاق المذمومة"]},{"id":1974,"question":"النهي عن تسمية العنب (بالكَرْم)؟","title":"هل النهي عن تسمية العنب بالكَرْم للتحريم؟","answer":"الجواب:\nالأصل في النهي التحريم، والأقرب -والله أعلم- الكراهة، لكن الأصل في النهي التحريم، والأصل في الأوامر الوجوب، فينبغي للمؤمن ألا يُسمِّي ذلك.","link":"https://binbaz.org.sa/fatwas/22090/هل-النهي-عن-تسمية-العنب-بالكرم-للتحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن تسمية العنب.mp3","categories":["الأخلاق المذمومة"]},{"id":2011,"question":"إشارة المسلم لأخيه المسلم بيده ليس بعصا ولا بحديدة؟","title":"ما حكم إشارة المسلم لأخيه باليد للتهديد؟","answer":"الجواب:\nإن كان يُعَلِّمُه بشيء، يشير له بشيء، لا بأس.\nس: تهديده بيده؟\nالشيخ: أما التهديد ما يجوز يهدده إلا بحق، وإلا اليد أمرها سهل، لكن إذا كان له حق في ذلك يقول ما فعلت كذا كذا، يحذره؛ لا بأس.\nس: هل يستثنى الجاهل الذي يحمل الحديدة؟\nالشيخ: الجاهل يُعَلَّم، يُعَلَّم بنهي الرسول ﷺ.","link":"https://binbaz.org.sa/fatwas/22127/ما-حكم-اشارة-المسلم-لاخيه-باليد-للتهديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إشارة المسلم لأخيه المسلم بيده ليس بعصا ولا بحديدة.mp3","categories":["الأخلاق المذمومة"]},{"id":2086,"question":"إذا كان الرجلُ يسأل لأمه الفقيرة أو لأبيه أو لأقاربه، فهل يكون من مسألة الناس المذمومة أم لا؟","title":"حكم مسألة الرجل لإعانة أقاربه الفقراء","answer":"الجواب:\nما ينبغي له أن يسأل، ينبغي أن يكتسب ويقوم عليهم إلا للضَّرورة، يقول النبيُّ ﷺ: إنَّ المسألة لا تحلّ إلا لأحد ثلاثةٍ: رجل تحمَّل حمالةً –يعني: للإصلاح– فحلَّت له المسألة حتى يُصيبها ثم يُمْسِك، ورجل أصابته فاقَةٌ، فحلَّت له المسألة حتى يُصيب سدادًا من عيشٍ، ورجل أصابته فاقَةٌ فشهد ثلاثةٌ من ذوي الحِجَى من قومه: لقد أصابت فلانًا فاقةٌ، فحلَّت له المسألة حتى يُصيب سدادًا من عيشٍ، وما سواهنَّ من المسألة سُحْتٌ، يأكله صاحبه سحتًا.","link":"https://binbaz.org.sa/fatwas/22204/حكم-مسالة-الرجل-لاعانة-اقاربه-الفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا سأل الرجل لأقاربه الفقراء فهل يكون من مسألة الناس المذمومة.mp3","categories":["الأخلاق المذمومة"]},{"id":2148,"question":"هذا المسكين الذي لا يُتفطَّن له لو أنه صبر عند الضَّرورة فإنه يتضرّر وقد يهلك؟","title":"حكم المسألة للمسكين الذي لا يُفطن له","answer":"الجواب:\nلا، يسأل.\nس: يجب عليه؟\nج: عليه أن يُنْقِذ نفسه، فإذا دعت الضَّرورة لخوف الهلاك؛ وجب عليه، ويجب على مَن عرف حاله أن يُنْقِذه، وأن يُعطيه.\nس: أقصد شيخنا أنه لو قال: يُستحب لي الصبر، هل يكون هذا صحيحًا أو يجب عليه أن يسأل؟\nج: لا، إذا كان عنده شيءٌ يسدّ حاجتَه وإلا يجب عليه أن يسأل؛ لإنقاذ نفسه ومَن تحت يده.","link":"https://binbaz.org.sa/fatwas/22267/حكم-المسالة-للمسكين-الذي-لا-يفطن-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المسكين الذي لا يفطن له هل له أن يسأل الناس.mp3","categories":["الأخلاق المذمومة"]},{"id":2167,"question":"هل البخل ثمرة من ثمرات الشُّحِّ؟","title":"ما الفرق بين البُخل والشُّح؟","answer":"الجواب:\nالشح أشدّ، فالشح معناه: البخل بالموجود، والحرص على المفقود، فالشحيح حريصٌ على طلب الزيادة، وبخيلٌ بما عنده.","link":"https://binbaz.org.sa/fatwas/22288/ما-الفرق-بين-البخل-والشح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين البخل والشح.mp3","categories":["الأخلاق المذمومة"]},{"id":2213,"question":"كيف الجمع بين الحكم في العادة الشيطانية السرية وقول الإمام أحمد فيها؟","title":"حكم فعل العادة السرية والرد على من أجازها","answer":"الجواب:\nالعادة السرية منكرة، يقول الله جلَّ وعلا: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ  ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:5- 7]، من ابتغى غير الزوجة والسرية فهو عادٍ ظالم، والعادة السرية سوى ذلك، وهي إخراج المني باليد ونحوها.\nس: وعلامَ يُحْمَل قول الإمام أحمد؟\nج: ما أدري، أحمد عالم أم نبي؟!\nس: عالم.\nج: العالم يُؤخذ من قوله ويُترك، منه ما وافق الحقّ، ومنه ما خالف الحقّ.","link":"https://binbaz.org.sa/fatwas/22336/حكم-فعل-العادة-السرية-والرد-على-من-اجازها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الحكم في العادة الشيطانية السرية وقول الإمام أحمد فيها.mp3","categories":["الأخلاق المذمومة"]},{"id":2239,"question":"النّهي عن الكذب في المِزاح للكراهة أم للتَّحريم؟","title":"ما حكم الكذب في المزاح؟","answer":"الجواب:\nيقول النبيُّ ﷺ: ويلٌ للذي يُحدِّث ويكذب ليُضحك به القوم، ويلٌ له، ثم ويلٌ له.","link":"https://binbaz.org.sa/fatwas/22362/ما-حكم-الكذب-في-المزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن الكذب في المزاح.mp3","categories":["الأخلاق المذمومة"]},{"id":2265,"question":"مَن كان سببًا لإدخال الدِّشِّ في بيته أو لعاملٍ كافرٍ هل يُعتبر غاشًّا؟","title":"حكم إدخال الدِّشِّ إلى البيت واستقدام الكافر","answer":"الجواب:\nنعم، الذي يضع الدشَّ بين رعيته وأهل بيته غاشٌّ لهم، والذي يسمح لهم بمثل هذا من الملاهي والمنكرات غاشٌّ لهم، والذي يأمرهم بطاعة الله ويأمرهم بالحقِّ ناصحٌ لهم.\nس: ونفس الشيء بالنسبة لاستقدام العامل الكافر؟\nج: كذلك لا يجوز استقدامه للجزيرة العربية.","link":"https://binbaz.org.sa/fatwas/22388/حكم-ادخال-الدش-الى-البيت-واستقدام-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إدخال الدِّشِّ إلى البيت هل هو من الغش للرعية.mp3","categories":["الأخلاق المذمومة"]},{"id":2324,"question":"الذي يُعدِّل بحوثَه العلميَّة ويبيعها إلى طُلابه؟","title":"حكم باحث يُعدِّل بحوثَه العلميَّة ويبيعها لطُلابه","answer":"الجواب: لا، ما يصلح، هذا غشٌّ، إلا إذا كانوا يستفيدون منها هم، أمَّا أن ينسبها لهم فما يجوز، فإذا كانوا يستفيدون منها فلا بأس، أمَّا أن يُعدّلها ويكفيهم مؤونة البحث فلا، هذا يصير نقصًا عليهم، ما فهموا.","link":"https://binbaz.org.sa/fatwas/22448/حكم-باحث-يعدل-بحوثه-العلمية-ويبيعها-لطلابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يُعدِّل بحوثَه العلميَّة ويبيعها إلى طُلابه.mp3","categories":["الأخلاق المذمومة"]},{"id":2579,"question":"مَنْ يسمع كلام سوء في عزيز، في مجلس، هل يجوز أن ينقل الكلام إليه؟","title":"حكم نقل كلام سوء قيل في شخص عزيز","answer":"الجواب: هذا من النميمة، لكن قد يبلغ الإنسان -ولو من غير الخاصة- الكلام، قد يبلغه لأن الشر ينتشر، يُنقل.\nس: الصحابة الذين غاروا من كلام المنافقين فأبلغوا الرسول؟\nالشيخ: المنافقين لا بأس أن يبلغ عنهم؛ لأنهم كفار وظلمة وشر؛ يُخشى من شرهم، ولهذا ما أنكر عليهم النبي ﷺ التبليغ.","link":"https://binbaz.org.sa/fatwas/22712/حكم-نقل-كلام-سوء-قيل-في-شخص-عزيز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نقل كلام يسوء.mp3","categories":["الأخلاق المذمومة"]},{"id":2694,"question":"من عنده دِشّ يُهْجَر؟","title":"حكم هَجْر مَنْ لديه الدِّش (لاقط القنوات)؟","answer":"الجواب: يستحق الهجر؛ لأن الدش فيه شر كثير، لكن يُنْصَح ويُوَجَّه إلى الخير.\nس:إذا كان رَجَا أنه يَكُفُّ عن هذا؟\nالشيخ: يُنْصَح ويُوجّه إلى الخير ويقال له احذر هذا ولا تستعمل الدش، لعل الله يهديه، فيما بلغنا أن فيه شرًّا كثيرًا، أن فيه مرائي كثيرة خبيثة.\nس: متأكد شره؟\nالشيخ: يستحق الهجر، من أظهر المعصية يستحق الهجر، هذه قاعدة؛ سُنّة مؤكدة هَجْرُه.","link":"https://binbaz.org.sa/fatwas/22833/حكم-هجر-من-لديه-الدش-لاقط-القنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هجر من كان عنده دش.mp3","categories":["الأخلاق المذمومة"]},{"id":2695,"question":"إذا كان مِن الأقرباء ما يكون قاطعًا (من هجره لمعصيته)؟","title":"هل هَجْرُ القريب العاصي قَطْعٌ للرحم؟","answer":"الجواب: لا ما يصير قاطعًا؛ لأن هذا بسبب، يقول ابن عبدالقوي رحمه الله: س: حتى ولو كان عمه مثلًا ؟ الشيخ: نعم ولو أخوه أو عمه إذا كان أظهر المعصية. س: إذا كان يتمادى إذا قطع؟ الشيخ: إذا رأى مواصلة النصح جزاه الله خيرًا، إذا رأى أخوه أو عمه مواصلة النصح حتى لا يستمر لا يهجره، بل يكون لقاؤه له نصيحة، ما هو بلقاء أنس ومحبة، لقاء نصح كلما لقاه نصحه ووجّهه، هذا من باب الخير، من باب التعاون على البر والتقوى.","link":"https://binbaz.org.sa/fatwas/22834/هل-هجر-القريب-العاصي-قطع-للرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هجر أصحاب المعاصي من الأقارب ألا يكون قطعا للرحم.mp3","categories":["الأخلاق المذمومة"]},{"id":2792,"question":"تعيير المرء يقول مثلًا -بعض الناس هدانا الله وإياهم- فلان خضيري، أو فلان كذا أو كذا؟","title":"حكم تَنَقُّص الناس في أنسابهم","answer":"الجواب: إن كان من باب الإخبار بالنسب. لا، أما على سبيل التنقص ما يجوز، لا بالقبيلة ولا بالخِلقة، ما يجوز هذا.\nس: يعد من السَّب؟\nالشيخ: نوع من السَّب.","link":"https://binbaz.org.sa/fatwas/22940/حكم-تنقص-الناس-في-انسابهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تنقص الناس في أنسابهم.mp3","categories":["الأخلاق المذمومة"]},{"id":2938,"question":"ذِكْر الإنسان لأحواله الماضية في المعاصي هل يصرح أو يقول للاتعاظ والاعتبار؟","title":"هل يجوز ذِكْر المعاصي الماضية للاتّعاظ؟","answer":"الجواب: لا بينه وبين ربه، مَنْ ستره الله فليستر نفسه، وليجتهد في التوبة إلى الله وطلبه العفو .","link":"https://binbaz.org.sa/fatwas/23094/هل-يجوز-ذكر-المعاصي-الماضية-للاتعاظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز التصريح بالأحوال الماضية للاتعاظ والاعتبار.mp3","categories":["الأخلاق المذمومة"]},{"id":3023,"question":"إذا استنقص أحدًا مثلا قال: هذا سلفي، أو هذا تبليغي، أو هذا إخواني، وكذا، بقصد تنقيص الشخص، هل تعتبر مِن الغِيبة؟","title":"حكم نِسْبةُُ شخصٍ لجماعة معينة للتنقيص منه؟","answer":"الجواب: لا، ذِكْرُه بهذا ما هو بغِيبة، ذِكْرُه بما أظهر ليس مِن الغيبة، هو الذي أظهر نفسه، هو الذي هتكها.\nس: شخص قال مثلًا: هذا سلفي، يعني استهزاء به مثلًا، يعني يقول إنه يزكي نفسه، أو كذا، أو مثلًا قال: هذا الشخص لا يهمك، هذا إخواني، أو هذا الشخص مثلًا تبليغي؟\nالشيخ: إذا كان فيه بِدعة ينُصح فيها، صفته كذا وصفته كذا، يعني مِن أهل البدع، لا بأس، يُبِلِّغ عنه حتى يُحذر.","link":"https://binbaz.org.sa/fatwas/23182/حكم-نسبة-شخص-لجماعة-معينة-للتنقيص-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القدح في العلماء وفي أهل السنة والجماعة.mp3","categories":["الأخلاق المذمومة","العالم والمتعلم"]},{"id":3034,"question":"مَنْ عمل حركة في حق إنسان يُفهم منها...؟","title":"حكم مَن يَعِيب الناس بالهمز واللمز بالإشارة","answer":"الجواب: كذلك، ولَوْ، ولَوْ، مثلما قال جل وعلا: وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1] الهمزة اللمزة: الذي يعيب الناس بالهمز واللمز بالإشارة، تارة بالهمز، وتارة بأصبعه أو بعينه أو برأسه، أو بغير هذا مما يُفهم وَلَا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ  ۝  هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ [القلم:10، 11].","link":"https://binbaz.org.sa/fatwas/23194/حكم-من-يعيب-الناس-بالهمز-واللمز-بالاشارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الذي يعيب الناس بالهمز واللمز بالإشارة.mp3","categories":["الأخلاق المذمومة"]},{"id":3057,"question":"إذا تكلم شخص في جماعة قال: حسناتهم كذا وسلبياتهم كذا، فهل هذا يعتبر مِن النميمة؟","title":"حكم ذِكْر الناس بالحسنات والسيئات","answer":"الجواب: وأيش الحاجة، يبيّن الحسنات ما يخالف، أما السيئات ما يبيّنها، إذا ذكر السيئات هذه النميمة.\nس: لكن إذا بين حسناته عادي؟\nالشيخ: نعم.  هذه ما تُسمى نَميمة، تُسمى غِيبة.  أما إذا كانوا يتكلمون في عِرضه هذه النميمة. إذا كنت تنقل عن فلان أنه رجل جبان؛ هذه غِيبة.  أما إذا قلت: إن فلان يقول عنك إنك جبان؛ فهذه النميمة...\nس:... مَن غلبت حسناته على سيئاته؟\nالشيخ: هذا... إلى الله، ما هو إليكم أنتم، لا تنقلوا الغِيبة ولا النميمة بس، أما.. العقاب والجزاء هذا إلى الله .\nس: النقل الحسن طيب، نقل الصفات الحسنة طيب؟\nالشيخ: هذا طيب مشكور.\nس: إذا كان من باب التنبيه، مثلًا بعض الجماعات عندهم أخطاء في العقيدة؟\nالشيخ: إذا كان منكرًا ظاهرا ما هو بغِيبة، إذا كانت منكرًا مثل ما تقول عن الجهمية صفتهم كذا، والمعتزلة صفتهم كذا، والرافضة؛ ما في بأس، أما إنسان مستور وتفضحه، لا.","link":"https://binbaz.org.sa/fatwas/23217/حكم-ذكر-الناس-بالحسنات-والسيىات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعتبر من النميمة تكلم شخص في جماعة.mp3","categories":["الأخلاق المذمومة"]},{"id":3058,"question":"تعريف الهَمْز؟","title":"ما معنى الهَمْز واللَّمْز؟","answer":"الجواب: الهَمْز بالشفاة أو بالعين أو بالأصبع، يهمز يشير إلى ذمه وعيبه وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1] بعض الناس بأصبعه: تراه ما هو بجيد، وبعض الناس بعينه، وبعض الناس ببُرْطُمِه..... هو هذا؛ الهَمْز واللَّمْز، تارة بالكلام، وتارة بالإشارة.","link":"https://binbaz.org.sa/fatwas/23218/ما-معنى-الهمز-واللمز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو الهمز واللمز.mp3","categories":["الأخلاق المذمومة"]},{"id":3086,"question":"الأكل بالشِّمال على التحريم؟","title":"ما حُكم الأكل بالشِّمال؟","answer":"الجواب: هذا هو الظاهر، ولهذا دعا النبي ﷺ على مَنْ أكل بشماله قال: لا استطعت.","link":"https://binbaz.org.sa/fatwas/23246/ما-حكم-الاكل-بالشمال","audio":"undefined","categories":["الأخلاق المذمومة"]},{"id":3093,"question":"من اغتاب رجلاً غير معروف عند السامع، يعني ذكر لفلان رجلًا يفعل كذا وكذا، أو ذكر اسمه لكن السامع لا يعرفه؟","title":"هل تجوز غِيبة رجل غير معروف للسامع؟","answer":"الجواب: ولَوْ ولَوْ، لا يجوز الغِيبة، الغِيبة لا تجوز وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] مادام سمّاه لا يجوز.\nس: أهل مدينة أو جماعة كثيرين، يسمى غِيبة؟\nالشيخ: المجهول ما يسمى غِيبة، لو قلت: بعض الناس يفعل كذا، بعض الرجال يفعل كذا، ما تسمى غِيبة.","link":"https://binbaz.org.sa/fatwas/23253/هل-تجوز-غيبة-رجل-غير-معروف-للسامع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اغتاب رجل غير معروف عند السامع.mp3","categories":["الأخلاق المذمومة"]},{"id":3193,"question":"القُبلة تُعتبر زِنًا؟","title":"هل تعتبر القُبلَةُ المُحرّمة مِن الزَّنا؟","answer":"الجواب: زِنًا أصغر، من وسائل الزِّنا، مِن اللَّمَم.\nس: يُعَزَّر الشخص؟\nالشيخ: من وسائل الزِّنا، إلا أن يتوب إلى الله من المعاصي، داخلة في قوله: وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48] داخلة في الذنوب، القبلة والملامسة والكلام السيئ، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23356/هل-تعتبر-القبلة-المحرمة-من-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تعتبر القُبلَة زنا.mp3","categories":["الأخلاق المذمومة"]},{"id":3207,"question":"من قال: الكذب في المنام أشد من الكذب في اليقظة، واستدل بالحديث الذي رواه البخاري إن من أفرى الفرى أن يحدث المرء بما لم ير يعني في المنام؟","title":"هل الكذب في المنام أشدّ منه في اليقظة؟","answer":"الجواب: على كل حال: الكذب قبيح في الرؤيا وفي اليقظة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23370/هل-الكذب-في-المنام-اشد-منه-في-اليقظة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكذب في المنام والكذب في اليقظة.mp3","categories":["الأخلاق المذمومة"]},{"id":3210,"question":"الضجعة هذه (على البطن) أليس فيها النهي الشديد؟ يدل على التحريم أم يدل على التنزيه؟","title":"حكم الاضطجاع على البطن","answer":"الجواب: ويش هو؟\nالطالب: الضجعة التي على البطن.\nالشيخ: ظاهر الحديث التحريم. ضجعة يبغضها الله.","link":"https://binbaz.org.sa/fatwas/23373/حكم-الاضطجاع-على-البطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضجعة على البطن.mp3","categories":["الأخلاق المذمومة"]},{"id":3227,"question":"ما يفعله بعض الكتاب من كتابة القصص: يَجعل في بدايتها: رأيت في المنام كأن كذا وكذا، ويبدأ في كتابة القصة؟","title":"حكم بدء بعض القصص بقول: رأيت في المنام","answer":"الجواب: الذي يظهر لي أنه ما يجوز، من الكذب المُحَرَّم، ما هو من الثلاثة.\nس: يدخل في حديث ابن عباس؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23390/حكم-بدء-بعض-القصص-بقول-رايت-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القصص التي يجعل في بدايتها رأيت في المنام..mp3","categories":["الأخلاق المذمومة"]},{"id":3228,"question":"بعض الكتاب يكتب قصة ويقول: هذا مِن نَسْج الخَيَال؟","title":"حكم قول بعض الكُتّاب \"هذا مِن نَسْج الخَيَال\"","answer":"الجواب: ما ينبغي هذا؛ لأنه يعتبر من الكذب، ما ينبغي للإنسان أن يكتب شيئًا إلا حقيقة؛ يفيد الناس، ونصيحة وقعت ونقلها العلماء فيها فائدة، فيها مصالح. أما أنه يكذب؛ يكتب أشياء من خيال فكره كذب: ما ينبغي، أخشى أنه يَعُمُّه إثمُ الكذب.","link":"https://binbaz.org.sa/fatwas/23391/حكم-قول-بعض-الكتاب-هذا-من-نسج-الخيال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتابات بعض الكتاب ويقول هذا من نسج الخيال.mp3","categories":["الأخلاق المذمومة"]},{"id":3239,"question":"التَّنَقُّصُ لو كان مازحًا؟","title":"هل يجوز التَّنَقُّصُ لو كان فاعله مازحًا؟","answer":"الجواب: ولو مازحًا، ما يصلح المَزْحُ بعَيْب أخيه.","link":"https://binbaz.org.sa/fatwas/23402/هل-يجوز-التنقص-لو-كان-فاعله-مازحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التنقص لو كان مازحا.mp3","categories":["الأخلاق المذمومة"]},{"id":3246,"question":"الذي يكذب لأجل لأنه يخفي عبادة مثل الصوم والصلاة؟","title":"هل يجوز الكذب لأجل إخفاء عبادة؟","answer":"الجواب: هذا ما له حاجة، ما هو مشروع.","link":"https://binbaz.org.sa/fatwas/23410/هل-يجوز-الكذب-لاجل-اخفاء-عبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكذب لأجل إخفاء عبادة.mp3","categories":["الأخلاق المذمومة"]},{"id":3247,"question":"مَنْ حَدّث بحديث يرى أنه كذب (فهو أحد الكذّابين): الذي يحدث بحديث ولا يدري بصحة الحديث يدخل في ذلك؟","title":"ما حكم مَنْ حدّث بحديث لا يدري بصحته؟","answer":"الجواب: لا، الذي يظن أنه كذب، أو يعلم أنه كذب.","link":"https://binbaz.org.sa/fatwas/23411/ما-حكم-من-حدث-بحديث-لا-يدري-بصحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من حدّث بحديث لا يدري بصحته.mp3","categories":["الأخلاق المذمومة"]},{"id":3248,"question":"النقل كالإشاعة؟","title":"معنى الإشاعة ونقل الكلام وحكمهما","answer":"الجواب: نقل الكلام: قال فلان وقال فلان كذا، قالت الإذاعة كذا وقالت الإذاعة كذا، هذا النقل.\nس: والإشاعة؟\nالشيخ: النقل يُكَثِّر الإشاعة، يُكثر الكلام.\nس: نقل كلام شخص يثق فيه: هل يجوز أن يحدّث به؟\nالشيخ: إن كان فيه فائدة، وإلا السكوت أحسن.","link":"https://binbaz.org.sa/fatwas/23412/معنى-الاشاعة-ونقل-الكلام-وحكمهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإشاعة ونقل الكلام.mp3","categories":["الأخلاق المذمومة"]},{"id":3253,"question":"مَنْ لَعَنَ غضبًا لله، لَعَنَ مُعَيَّنًا؟","title":"حكم مَنْ لَعَنَ شخصًا مُعَيَّنًا غضبًا لله","answer":"الجواب: لا، لا يلعن مؤمنًا، ولكن يدعوه إلى الخير، يدعوه وينصحه ويوجهه إلى الخير.  أما لعن الكفار: لا بأس على العموم، لعن الله اليهود والنصارى، لعن الله الفاسقين، لعن الله الظالمين، لعن الله السارقين، هذا على العموم أو غير المعين لا بأس. ولكن قد يُلعن المعين إذا دعت الحاجة إليه؛ لكونه من رؤوس الكفار ومن الظالمين للناس، فقد لعن النبي ﷺ جماعة من قريش قبل صلح الحديبية وبعدها لما صار شرهم أعظم، مثل أبي لهب ومثل عتبة بن ربيعة وأبي جهل بن هشام وأشباههم؛ لشدة كفرهم وظلمهم للناس، وإلا فالأغلب والسنة عدم اللعن مهما أمكن.  ولما قيل له: يا رسول الله إن دوسًا عَتَتْ فادع الله عليهم، قال: اللهم اهد دوسا وائت بهم، وقال ﷺ لما جيء بعبدٍ على حمار كان يشرب الخمر، فقال رجل: لعنه الله ما أكثر ما يُؤتى به، قال: لا تلعنه فإنه يحب الله ورسوله، قد يكون عاصيًا وعنده محبة لله، يُدعى له بالهداية والتوبة، الشيطان يَغْلِب والهوى يَغْلِب، ولا حول ولا قوة إلا بالله. يوصى أهله ويوصي جيرانه ويوصي جلساءه بالخير.","link":"https://binbaz.org.sa/fatwas/23417/حكم-من-لعن-شخصا-معينا-غضبا-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اللعن وحكمه وحكم لعن المعين غضبا لله.mp3","categories":["مسائل متفرقة في العقيدة","الأخلاق المذمومة"]},{"id":3259,"question":"لعنُها الدابة (أي المرأة التي لعنت الدابة) معناها: الدعاء عليها؟","title":"ما معنى وحكم لعن الدابة؟","answer":"الجواب: يعني: الدعاء عليها، لعنُها يعني سَبَّها: اللهم العنها، هي ملعونة، وإذا سَبَّتها بغير ذلك كذلك لا يجوز.","link":"https://binbaz.org.sa/fatwas/23423/ما-معنى-وحكم-لعن-الدابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى لعن الدابة.mp3","categories":["شروح الحديث","الأخلاق المذمومة"]},{"id":3269,"question":"الذي يُطلق على أخيه كلمة يا خنزير أو يا حيوان؟","title":"حكم إطلاق كلمة خنزير وحيوان على مُعَيّن","answer":"الجواب: يقول مثله: أنت الخنزير وأنت الحيوان، وبس، ويكفي ولا يزيد، وإلا يسمح ويعفو.\nس: حكمه؟\nالشيخ: حكمه مُنْكَر، ما يجوز، لكن له القصاص بأن يقول مثل ما قال.","link":"https://binbaz.org.sa/fatwas/23433/حكم-اطلاق-كلمة-خنزير-وحيوان-على-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إطلاق كلمة يا خنزير أو يا حيوان  على معين.mp3","categories":["الأخلاق المذمومة"]},{"id":3270,"question":"الفسق ما ضابطه؟","title":"ما معنى الفسق؟ وما ضابطه؟","answer":"الجواب: إظهار المعاصي والإصرار عليها بينه وبين الله، فسق فيما بينه وبين الله، لكن إظهارها هو الفسق، يقال: فسق: يعني خرج عن الطاعة.","link":"https://binbaz.org.sa/fatwas/23434/ما-معنى-الفسق-وما-ضابطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هو الفسق وما ضابطه.mp3","categories":["الأخلاق المذمومة"]},{"id":3272,"question":"(ما حكم) بعض الناس إذا صار مثلًا يُعَيِّر الميت؟","title":"ما حكم غِيبة الميت؟","answer":"الجواب: ما يجوز، غِيبة الميت أشد من غيبة الحي، إذا كان الشيء مستورًا. وأما الشيء الظاهر الذي يقصد التحذير منه؛ لأن الناس قد يقتدون به: يُبَيّن أن هذا لا يجوز، ولا يجوز الاقتداء بفلان في بدعته أو في معصيته الظاهرة.\nس: يكون داعية إلى الشر؟\nالشيخ: نعم؛ الشيء الذي يُخشى أن يُتبّع في الشر، شر ظاهر.\nس: إذا كان شره قاصرًا على نفسه؟\nالشيخ: أما إذا كان شره خفيًّا ما هو ظاهر لا، لا يبحث فيه.","link":"https://binbaz.org.sa/fatwas/23436/ما-حكم-غيبة-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غيبة الميت.mp3","categories":["الأخلاق المذمومة"]},{"id":3869,"question":"الكبر بطر الحق، وغمط الناس هذا نص الحديث؟","title":"ما تعريف الكِبْر في السُّنَّة؟","answer":"الجواب: نعم، هذا بيان التكبر: الكبر: بطر الحق، وغمط الناس، هذا الكبر.","link":"https://binbaz.org.sa/fatwas/24083/ما-تعريف-الكبر-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكبر وتعريفه.mp3","categories":["الأخلاق المذمومة"]},{"id":3994,"question":"إذا كان الإنسان وحده وليس عنده أحد (حُكم الخَذْف -الرَّمْي بالحصى-)؟","title":"هل يجوز الخَذْف (الرَّمْي بالحصى) للمنفرد؟","answer":"الجواب: ولو وحده، لا يخذف، يشتغل بشيء آخر، يقرأ، يشتغل بحاجة بيته، لا يخذف، هو من المنهيات، منهي عنها مطلقًا سواء مفردًا أو مع الناس، قد يصيب عينه هو، قد يكسر سنه هو.","link":"https://binbaz.org.sa/fatwas/24225/هل-يجوز-الخذف-الرمي-بالحصى-للمنفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يخذف الإنسان إذا كان وحده.mp3","categories":["الأخلاق المذمومة"]},{"id":4009,"question":"استعمال العادة السرية من زنا اليد؟","title":"هل استعمال العادة السرية من زنا اليد؟","answer":"الجواب: هو الظاهر، وقد تكون بغير اليد، قد يستعمل غير اليد، فالحاصل أنه نوع من الزنا المحرم؛ لأنه داخل في قوله تعالى: فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:7] قد يستعمل أشياء غير اليد، أشياء صناعية يفعلونها، نسأل الله العافية.  المقصود أنه محرم منكر عند جمهور أهل العلم، لا يجوز؛ لأنه داخل في قوله تعالى: فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:7] ثم هو فيه مضار كثيرة، قد يفضي بصاحبه إلى الهلوسة وضعف العقل، وقد يفضي إلى انقطاع النسل، وقد ألف في هذا بعض علماء العصر، وذكر أقوال الأطباء في مضاره الكثيرة.","link":"https://binbaz.org.sa/fatwas/24243/هل-استعمال-العادة-السرية-من-زنا-اليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل استعمال العادة السرية من زنا اليد.mp3","categories":["الأخلاق المذمومة"]},{"id":4042,"question":"إذا كانت المناجاة بين مسلمين وجارهم غير مسلم؟","title":"حكم المناجاة بين مسلمين وبينهم غير مسلم","answer":"الجواب: ولو، ما دام معهم في المجلس، أشد وأشد في الإثم إذا كان ما هو مسلم، أشد وأشد؛ صار الظن أقرب أنهم يتناجون فيه.","link":"https://binbaz.org.sa/fatwas/24278/حكم-المناجاة-بين-مسلمين-وبينهم-غير-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المناجاة بين مسلمين وبينهم غير مسلم.mp3","categories":["الأخلاق المذمومة"]},{"id":4063,"question":"س: البُخل.. المقصود بالصدقة؟","title":"ما معنى البُخل عند الإطلاق؟","answer":"الجواب: البُخل عام؛ في الصدقة والجهاد ونحو ذلك.  لكن الأشهر إذا أُطلق هو: البُخل بالمال.","link":"https://binbaz.org.sa/fatwas/24300/ما-معنى-البخل-عند-الاطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى البخل عند الإطلاق.mp3","categories":["الأخلاق المذمومة"]},{"id":4814,"question":"قوله ﷺ: الغيبة ذكرك أخاك بما يكره، هل هذا يشمل غيبته حال حضوره أم حال غيبته إن لم يكن حاضرًا؟","title":"هل تقع الغِيبة في حق من كان حاضرًا؟","answer":"لا، هذا الذكر في حال غيبته أو حال حضوره، فهذا شيء بينه وبينه، كونه يذكره عند الناس في حال غيبته.","link":"https://binbaz.org.sa/fatwas/25214/هل-تقع-الغيبة-في-حق-من-كان-حاضرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث ذكرك أخاك بما يكره... هل يشمل غيبته حال حضوره أم إن لم يكن حاضرًا.mp3","categories":["شروح الحديث","الأخلاق المذمومة"]},{"id":4815,"question":"السابُّ إذا تلفظ بلفظ محرَّم فهل يرد عليه بمثله؟","title":"هل يجوز الرد بالمثل على من سبَّ بلفظ محرم؟","answer":"بمثله فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ [البقرة:194] إذا قال: لعنك الله، قل: بل أنت لعنك الله! وإن عفا فأصلح مثل ما قال جل وعلا: وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِرِينَ [النحل:126].","link":"https://binbaz.org.sa/fatwas/25217/هل-يجوز-الرد-بالمثل-على-من-سب-بلفظ-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الساب إذا تلفظ بلفظ محرم فهل يرد عليه بمثله.mp3","categories":["الأخلاق المذمومة"]},{"id":4816,"question":"الكافر يُسبُّ بعينه؟","title":"هل يجوز سب الكافر المعيَّن؟","answer":"إذا دعت الحاجة؛ فالنبي ﷺ سبَّهم. أما إذا ما دعت الحاجة فيدعو لهم بالهداية، اللهم اهد دوسًا وائت بهم.","link":"https://binbaz.org.sa/fatwas/25218/هل-يجوز-سب-الكافر-المعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُسب الكافر بعينه.mp3","categories":["الأخلاق المذمومة"]},{"id":4871,"question":"بالنسبة لمَن أصابته جائحةٌ: هل يسأل بمقدار ما فقد؟","title":"هل يسأل الناس مَن أصابته جائحة؟","answer":"نعم، مقدار حاجته، مقدار ما يُغنيه ويسدّ حاجته، مثلما قال ﷺ: حتى يُصيب قوامًا من عيشٍ، أو قال: سِدَادًا، الذي يقوم بحاجته، يسأل ما يسدّ حاجته وحاجة عياله: من ملبس، ومأكل، ومشرب.","link":"https://binbaz.org.sa/fatwas/25351/هل-يسال-الناس-من-اصابته-جاىحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سؤال الناس لمَن أصابته جائحةٌ بمقدار ما فقد.mp3","categories":["الأخلاق المذمومة"]},{"id":4898,"question":"من وعد شخصًا آخر بشيء ثم أخلف هل يأثم؟","title":"ما حكم من وعد شخصًا آخر بشيء ثم أخلف؟","answer":"الأصل في المواعيد أنها موجبة، والإخلاف من صفة المنافقين؛ إذا وعدوا أخلفوا. هذا الأصل إلا لعلة شرعية كعجز أو تغيُّر المعطى؛ يعني لأسباب شرعية.","link":"https://binbaz.org.sa/fatwas/25413/ما-حكم-من-وعد-شخصا-اخر-بشيء-ثم-اخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من وعد شخصًا آخر بشيء ثم أخلف.mp3","categories":["الأخلاق المذمومة"]},{"id":4961,"question":"بعض العوام إذا تقابلوا يتلاعنون؟","title":"ما حكم ما يقع مِن تلاعُن العوام والأزواج؟","answer":"الجواب: هذا من جهلهم وسفاهتهم، يُنصحون ويُوجّهون إلى الخير.\nس: وكذلك بعض النساء تلعن أبا أولادها؟\nالشيخ: كلهم يوضّح لهم ويبيّن لهم أن هذا منكر، الله قال جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:3] وقال: من رأى منكم منكرا فليغيره بيده...... لا بدّ.","link":"https://binbaz.org.sa/fatwas/27634/ما-حكم-ما-يقع-من-تلاعن-العوام-والازواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم ما يقع مِن تلاعُن العوام والأزواج؟ .mp3","categories":["الأخلاق المذمومة"]},{"id":5185,"question":"كما أوضحتَ فضيلتكم الخيانة -ومنها الغشّ في الامتحان- أرجو توضيح الحكم الشرعي في ذلك، مع ذكر الدَّليل؟","title":"ما حكم الغشّ في الامتحانات؟","answer":"الجواب: الغشُّ في الامتحان لا شكَّ أنه يدخل في العموم، والدليل: يقول النبيُّ ﷺ: مَن غشَّنا فليس منا، هكذا قال النبيُّ ﷺ: مَن غشَّنا فليس منا. وإذا كان الغشُّ في البيع والشراء حرامًا فهو في العلم كذلك؛ لأنَّ طالب العلم تُعلّق عليه آمال، وتُعلّق عليه أحكام، فإذا غشَّ في امتحاناته واختباراته فقد يُنسب إلى العلم ويُعدّ من العلماء وهو ليس كذلك، وإنما حصل ما حصل من الشَّهادات من طريق الخيانات، ومن طريق الكذب، ومن طريق التزوير، فيضرّ نفسَه، ويضرّ الناس، والحديث عام: مَن غشَّنا فليس منا. ولما مرَّ النبيُّ ﷺ على صبرةٍ من طعامٍ أدخل يده فيها، فنالت أصابعه بللًا، فقال: ما هذا يا صاحب الطعام؟ قال: أصابته السَّماء يا رسول الله، يعني: المطر، قال: أفلا جعلتَه فوق الطعام كي يراه الناسُ، مَن غشَّ فليس منا.","link":"https://binbaz.org.sa/fatwas/30122/ما-حكم-الغش-في-الامتحانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 147.mp3","categories":["الأخلاق المذمومة"]},{"id":5204,"question":"في هذه الأيام تنتشر الإصابة بالعين، وهم يفتخرون بها، وهي تُصيب بعض الناس، فما نصيحتكم لهؤلاء؟","title":"ما حكم من يتعمّد إصابة الناس بالعين؟","answer":"الجواب: الواجب الحذر، وأن الإنسان يتعمّد، فإذا كانت العينُ يتعمّدها فعليه الحذر من ذلك، وإذا عُرف أنه يتعمّد ذلك يجب أن يُؤخذ بهذا ويُعاقب، أما إذا كان بغير اختياره فليس بيده قدرة، لا يُكلِّف الله نفسًا إلا وسعها، والمسلم يقول صباح ومساء: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات، ويقرأ آية الكرسي بعد كلِّ صلاةٍ: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255]، ويقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مراتٍ صباح ومساء ويَسْلَم، ما تضرُّه العين ولا غيرها. فيقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات صباح ومساء، وقايةً من كل سوءٍ، ويقرآ آية الكُرسي بعد كل صلاةٍ، ففيها الوقاية من كل سوءٍ، ويقرأها أيضًا: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ عند النوم. كل هذه من أسباب الوقاية، ويقول: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات في الليل والنهار، و\"بسم الله الذي لا يضرُّ مع اسمه شيءٌ في الأرض ولا في السماء، وهو السميع العليم\" ثلاث مرات ليلًا ونهارًا، من أسباب الوقاية، ويقرأ آخر آيتين من سورة البقرة كل ليلةٍ: آمَنَ الرَّسُولُ [البقرة:285]، فهذه من أسباب العافية من كل سوءٍ.","link":"https://binbaz.org.sa/fatwas/30148/ما-حكم-من-يتعمد-اصابة-الناس-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 180.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":5283,"question":"ما حكم فعل العادة السرية؟","title":"ما حكم فعل العادة السرية؟","answer":"الجواب: فعل العادة السرية منكر لا يجوز، الاستمناء باليد نوع من الزنا، لا يجوز، يقول الله جل وعلا:  وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ  ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ  ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ [المؤمنون:5- 7] فجعل من ابتغى غير الزوجة والسرية \"عادٍ\" يعني ظالم. وفيها مضار، هذه العادة السرية لها مضار كثيرة ذكرها أهل العلم، لها مضار كثيرة؛ فالواجب الحذر منها.[1]","link":"https://binbaz.org.sa/fatwas/30921/ما-حكم-فعل-العادة-السرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 003.mp3","categories":["الأخلاق المذمومة"]},{"id":5399,"question":"المُظْهِر للمعاصي أمام الناس هل له غيبة؟","title":"هل تجوز غِيبة المُجاهِر بالمعاصي؟","answer":"الجواب: المجاهر لا غيبةَ له كُلُّ أُمَّتي مُعافًى إلَّا المُجاهِرِينَ، فالذي يشرب الخمر في السوق ليس له غِيبة، والذي يحلق لحيته ليس له غِيبة في اللحية، وأشباه ذلك -نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31156/هل-تجوز-غيبة-المجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 020.mp3","categories":["الأخلاق المذمومة"]},{"id":5400,"question":"الغيبة هل كفَّارتها الدعاء؟","title":"ما هي كفارة الوقوع في الغِيبة؟","answer":"الجواب: الغيبة من ظلم العباد، فإذا سمحوا له وعفوا عنه، أو دعا لهم وذكرهم بالأعمال الطيبة التي يعرفها منهم، وتاب إلى الله وندم، وكفَّر عن ذلك بذكر حسناتهم الطيبة وأعمالهم الطيبة، بدلًا من أعمالهم الخبيثة؛ فيُرجى له أن يعفو الله عنه.[1]","link":"https://binbaz.org.sa/fatwas/31155/ما-هي-كفارة-الوقوع-في-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 019.mp3","categories":["الأخلاق المذمومة"]},{"id":5687,"question":"قد عزمني أحد الإخوة، وقال لي: لازم تحضر أحد أخويك العزيمة، وحرمت على الذي أمون عليه منهم، ولم يذهب معي؟","title":"حكم من حلف على شخص ولم يبر بقسمه","answer":"الجواب: إذا ما ذهب معه ما عليه شيء، لكن لو أنه أجاب الداعي، وراح معه بعض إخوانه كان أحسن، يحضر له بعض إخوانه معه الذين دعاهم يكون أحسن، ولكن هو لما حرم عليه أن يذهبوا معه، ولم يذهبوا معه، وتمموا له ما عليه شيء. السؤال: ما عليه إطعام؟ الجواب: لا، ما راحوا عليه، حرم عليهم أن يروحوا، وما راحوا، ما نقضوا عليه. السؤال: .......؟ الجواب: أين السائل؟ على كل حال إن كان قصده: أنه شدد عليهم حرم عليهم يروحوا معه، وما راحوا عليه كفارة يمين، وإن كان قصده أن حرم عليهم أنهم ما يروحون وأطاعوه فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/989/حكم-من-حلف-على-شخص-ولم-يبر-بقسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_18.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5691,"question":"قد عزمني أحد الإخوة، وقال لي: لازم تحضر أحد أخويك العزيمة، وحرمت على الذي أمون عليه منهم، ولم يذهب معي؟","title":"حكم من حلف على شخص ولم يبر بقسمه","answer":"الجواب: إذا ما ذهب معه ما عليه شيء، لكن لو أنه أجاب الداعي، وراح معه بعض إخوانه كان أحسن، يحضر له بعض إخوانه معه الذين دعاهم يكون أحسن، ولكن هو لما حرم عليه أن يذهبوا معه، ولم يذهبوا معه، وتمموا له ما عليه شيء. السؤال: ما عليه إطعام؟ الجواب: لا، ما راحوا عليه، حرم عليهم أن يروحوا، وما راحوا، ما نقضوا عليه. السؤال: .......؟ الجواب: أين السائل؟ على كل حال إن كان قصده: أنه شدد عليهم حرم عليهم يروحوا معه، وما راحوا عليه كفارة يمين، وإن كان قصده أن حرم عليهم أنهم ما يروحون وأطاعوه فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/989/حكم-من-حلف-على-شخص-ولم-يبر-بقسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_18.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5758,"question":"مرض ولدي وهو صغير مرضًا شديدًا، وقلت: إن أحياه الله أصوم من كل سنة شهر رجب، وأنا الآن لم أصم ولو شهرًا واحدًا، حيث إني كل سنة حامل، أو مرضع، ومضى لهذا النذر حوالي تسع سنوات، وأنا لا أستطيع، وغير صحيحة، فماذا أفعل؟","title":"نذرت صيام شهر رجب من كل عام","answer":"الجواب:  هذا نذر مكروه، نذرها أن تصوم شهر رجب كل سنة مكروه، فعليها كفارة يمين، ويكفي، فإنه صوم مكروه، والنذر مكروه، فيكفي فيه كفارة يمين، فإذا كفرت كفارة يمين، أطعمت عشرة مساكين لكل مسكين نصف صاع من قوت البلد، أو تكسوهم؛ كفى ذلك، والحمد لله، وليس عليها صيام.","link":"https://binbaz.org.sa/fatwas/1097/نذرت-صيام-شهر-رجب-من-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_103.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5773,"question":"مرض ولدي وهو صغير مرضًا شديدًا، وقلت: إن أحياه الله أصوم من كل سنة شهر رجب، وأنا الآن لم أصم ولو شهرًا واحدًا، حيث إني كل سنة حامل، أو مرضع، ومضى لهذا النذر حوالي تسع سنوات، وأنا لا أستطيع، وغير صحيحة، فماذا أفعل؟","title":"نذرت صيام شهر رجب من كل عام","answer":"الجواب:  هذا نذر مكروه، نذرها أن تصوم شهر رجب كل سنة مكروه، فعليها كفارة يمين، ويكفي، فإنه صوم مكروه، والنذر مكروه، فيكفي فيه كفارة يمين، فإذا كفرت كفارة يمين، أطعمت عشرة مساكين لكل مسكين نصف صاع من قوت البلد، أو تكسوهم؛ كفى ذلك، والحمد لله، وليس عليها صيام.","link":"https://binbaz.org.sa/fatwas/1097/نذرت-صيام-شهر-رجب-من-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_103.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5834,"question":"حلف بالطلاق أن لا يذهب إلى محل كذا، وحلف بقوله: هي علي طالق ثلاث مرات، وهو لم يقصد بهذا الطلاق، بل قصد أن يمنع نفسه عن هذا المحل، وللأسف لقد جهل الأمر، ولم تمض مدة قصيرة حتى ذهب إلى نفس المحل، فحينئذ لم يكن ناسيًا، وإنما ذاكرًا، وإنما تجاهل الأمر فقط، فما حكم ذلك؟","title":"من حلف بالطلاق ونسيه","answer":"الجواب:  إذا طلق الإنسان على شيء يفعله، أو شيء لا يفعله؛ فهذا فيه تفصيل، إذا قال: عليه الطلاق لا يزور فلانًا، ولا يدخل بيت فلان، وعليه الطلاق ألا يأكل ذبيحة فلان، وعليه الطلاق أن تأكل ذبيحتي يا فلان، وأن تبقى حتى تأكل ذبيحتي، أو عليه الطلاق ما يكلم فلانًا، أو ما يسافر إلى كذا.  كل هذه الأمور تقع من الناس، ففيه تفصيل: إن كان أراد إيقاع الطلاق، إذا فعل هذا الشيء، أو ما فعل هذا الشيء يقع عليه الطلاق أنه يسافر، ونيته أنه إذا ما سافر تطلق امرأته؛ فهو على نيته، أو قال: عليه الطلاق أنك تأكل الذبيحة، ونيته إنه إن ما أكلها أنها تطلق؛ فهو على نيته. أما إن كان أراد التأكيد على الموضوع، ولا أراد فراقها، ولا خطر بباله فراقها، ولكن أراد التأكيد، أراد على هذا أن يأكل ضيافته، وهو ليس قصده فراق أهله، ولكن يريد منه أن يأكل الضيافة إذا سمع الطلاق؛ لعله يخضع، لعله يجلس فيأكل الضيافة، فهذا حكمه حكم كفارة يمين، حكمه حكم اليمين، وعليه كفارتها، ولا يقع الطلاق. وهكذا إذا قال: عليه الطلاق أنه ما يزور بيت فلان، أو ما يدخل بيت فلان، ثم فعل ذلك، وقصده منع نفسه من هذا الشيء، ليس قصده فراق أهله، ولكن أراد أن يمنع نفسه من هذا الشيء، وأكد عليها، فهذا يكون له حكم اليمين؛ عليه كفارة يمين، إطعام عشرة فقراء، كل فقير له نصف صاع من قوت البلد، ويكفي ذلك، أو يكسوهم كسوة قميص لكل واحد، أو يعطي لكل واحد إزارًا ورداء، هذه الكسوة مما يجزي في الصلاة. هذا جواب هذه المسائل المتعددة الكثيرة إن أراد إيقاع الطلاق؛ وقع الطلاق، وإن كان ما أراد ذلك، وإنما أراد منع نفسه، أو حثها على الشيء الذي يريده، منع نفسه أنه عليه الطلاق أنه ما يسافر، ما يكلم فلانًا، هذا قصده منع  نفسه من السفر، والكلام، أو أراد حثها عليه، عليه الطلاق أنه يصوم يوم الإثنين والخميس، عليه الطلاق أنه يذبح ذبيحة لفلان، فهذا قصده حث نفسه على الشيء، فهذا حكمه حكم اليمين أيضًا، إذا كان ما قصد إلا حث نفسه، وإلزامها بهذا  الشيء.","link":"https://binbaz.org.sa/fatwas/1180/من-حلف-بالطلاق-ونسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_176.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5854,"question":"أنا مدرس في المرحلة المتوسطة، وإذا دخلت الفصل؛ قام التلاميذ لي تقديرًا، واحترامًا من دون ما آمرهم به، بل إني أكره  ذلك، فما حكم ذلك؟","title":"حكم قيام الطلاب للمدرس عند دخوله","answer":"الجواب: هذا الذي نبه عليه أيضًا الشيخ محمد، وهو مسألة القيام، هذا مما جاء في السنة في النهي عنه، قال أنس : كان الصحابة إذا دخل عليهم النبي لا يقومون له لما يعلمون من كراهيته لذلك، وكان يقولﷺ: من أحب أن يتمثل له الرجال قيامًا؛ فليتبوأ مقعده من النار.  فالواجب على الطلبة إذا دخل الأستاذ ألا يقوموا، بل يلزموا أماكنهم، ويسلموا عليه، ويصبحونه بالخير، ويمسونه بالخير، طيب، أما أنهم يقومون له وقوفًا؛ فلا ينبغي ذلك، أقل أحواله الكراهة الشديدة، وهو لا يحب ذلك ما يجوز له أن يحب ذلك، والأستاذ ما دام أنه لا يحب ذلك، فهو على خير، النبي -عليه الصلاة والسلام- قال: من أحب أن يتمثل له الناس قيامًا؛ فليتبوأ مقعده من النار وفي لفظ: من سره. فالحاصل: أنه إذا كان لا يحب ذلك؛ لا حرج عليه، لكن يلزمه أن يعظهم، وأن يقول لهم: لا تفعلوا، وإذا عرفوا منه الصدق، وأنه لا يرضا بذلك؛ جلسوا، لكن أخشى أنه لا يحب ذلك دعوى، وليست حقيقة، ولو كان لا يحبه حقيقة؛ لأمرهم بالجلوس، ولقال لهم: لا تقوموا. فالحاصل: أن هذا الشيء على الأستاذ أن ينبههم، وأن يقول لهم: لا تفعلوا، لا تقوموا، ولا يرضى عنهم، لا أرضى عنكم أن تفعلوا هذا، فإذا رأوا منه الصدق ما قاموا ما هم حريصين على القيام، لكن خوفًا من شره، أو يرسبهم، أو يفعل بهم أشياء تضرهم. فالحاصل: أنه إذا صدق في ذلك، وقال لهم: لا تقوموا ما قاموا، وهذا الواجب أيضًا على وزارة المعارف؛ أنها تنبه المديرين أن هذا لا يجوز، وأن الأستاذ إذا دخل لا يقومون له، وهكذا البنات، المدرسة لا يقمن لها، وعلى  الرياسة العامة للتعليم أن تنبه على ذلك؛ حتى يزول هذا الشر الذي في المدارس. أما القيام الذي معناه المواجهة، والمقابلة للمصافحة، هذا لا بأس به، إذا دخل الأستاذ، فقام له واحد ليسأله عن شيء، ليصافحه، ليقدم في مكان، أو ليجلسه في مكانه، أو في مجلس من المجالس، قام ليصافحه، ويسأله عن حاله؛ لا بأس. مثلما قام طلحة بن عبيدالله التيمي أحد العشرة المشهود لهم بالجنة، لما دخل كعب بن مالك، لما تاب الله عليه، وجاء إلى الناس، والنبي في المسجد، وعنده الحلقة، ولما رأى كعبًا أقبل؛ قام من الحلقة، وقابله، وصافحه، وهنأه بتوبة الله عليه، ولم ينكر النبي ﷺ عليه، ولم يقل له شيئًا؛ فدل على جوازه في هذا.  ولما جاء سعد بن معاذ الأنصاري  ليحكم في بني قريظة على دابة له، على حمار، لما أقبل قال النبي ﷺ: قوموا إلى سيدكم فقاموا إليه، وسلموا عليه، وأنزلوه من دابته، وكانت فاطمة -رضي الله عنها- إذا دخل والدها النبي -عليه الصلاة والسلام- قامت إليه، وأخذت بيده، وأجلسته في مكانها، وكان إذا دخلت عليه هو قام إليها، وأخذ بيدها، عليه الصلاة والسلام. هذا إذا كان القيام للمقابلة، والمواجهة، والمصافحة، أو القيام ليمشي معه حتى يخرج من المحل، هذا لا حرج فيه، فعله النبي، وفعله الصحابة، المنكر كونهم يقومون، ثم يجلسون، ما في مصافحة، ولا شيء، إنما يقومون تعظيمًا للداخل، ثم يجلسون، هذا الذي أقل أحواله الكراهة، أو التحريم، وكونه يحب ذلك في الداخل، ويسر لهذا، ويحبه هذا، لا يجوز، وقد توعد بالنار على هذا الشيء، وهم لا ينبغي لهم أن يقوموا، يكره لهم القيام، وهو لا يجوز له أن يحب ذلك، ولا يجوز له أن يأمرهم بهذا الشيء، والواجب عليه أن ينهاهم عن هذا الشيء؛ حتى يجلسوا، وحتى يعتادوا على هذا الشيء، وهو الجلوس في أماكنهم؛ حتى يأخذ مكانه، ويبدأ بالدرس، سواء كانوا ذكورًا، أو إناثًا. السؤال: بعض المدرسين يقول: إن هذا تنبيه للطلاب؟ الجواب: لا؛ هذه شبهة شيطانية، يتنبهوا بدخوله إذا قال: السلام عليكم؛ تنبهوا، وإذا واحد نعس يقول: يا فلان صاح، انتبه للدرس، لا بأس أن ينصحهم، ويحذرهم من النعاس. السؤال: ذكر فضيلة المحاضر أن القيام قد يفضي إلى الشرك، وهناك بعض المسؤولين إذا لم يقم له الإنسان؛ فقد يغضب عليه، ويعاقبه، فماذا أعمل معه؟ الجواب: يبين له مر الكلام هذا، وأنه لا يجوز القيام، والذي لا يرضى ينبه، يقال له: إن هذا لا يجوز، لولا أن الرسول كره ذلك، وأنت والحمد لله من أتباع الرسول، أنت لا تحب الشيء الذي لا يحبه الرسول ﷺ.","link":"https://binbaz.org.sa/fatwas/1203/حكم-قيام-الطلاب-للمدرس-عند-دخوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_199.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5904,"question":"قرأت في مجلة المسلمون مقال لمحمد الغزالي، يقول فيه: لا مانع من تولي المرأة القضاء، وقد روى عن عمر أنه ولى الشفاء امرأة من قومه، وقال: أريد، وأنا أعرض الإسلام في بلاد أخرى أن لا يغير سلوكًا في هذه البلد، ويرى بعض فقهائنا أنه لا حرج فيه؟","title":"الرد على من أجاز تولية المرأة للقضاء","answer":"الجواب:\n\nهذا قول ضعيف، والذي عليه جمهور أهل العلم أنه لا يجوز أن تولى المرأة، وإنما تولى ما يناسبها مثل إدارة مدرسة، تدريس طب، وما أشبه ذلك، أما القضاء فلا يتولاه إلا الرجال، هذا الذي عليه جمهور أهل العلم.\n\nفالنبي ﷺ قال: لن يفلح قوم ولوا أمرهم امرأة وهذا حديث عظيم، رواه البخاري، وغيره، وأما الأثر الذي عن عمر فلا نعلم صحته، لا نعلم له أصلًا.","link":"https://binbaz.org.sa/fatwas/1239/الرد-على-من-اجاز-تولية-المراة-للقضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_236.mp3","categories":["القضاء والشهادات","الأخلاق المذمومة"]},{"id":5909,"question":"يدعي البعض أن إتلاف المال مكروه، وليس حرامًا، ومن إتلاف المال في الدخان يقولون أيضًا: إن التحريم يحتاج إلى نص، فما رأيكم في هذا القول؟","title":"حكم إتلاف المال في الدخان وغيره","answer":"الجواب:  إتلاف المال بغير وجه شرعي هو محرم بلا شك، وليس فيه خلاف بين العلماء في هذا؛ بل هو محل إجماع أن إتلاف المال في غير أمر مباح في غير أمر شرعي لا يجوز لوجوه كثيرة، وأدلة كثيرة؛ لأن المال جعله الله، وخلقه الله لنفع الناس، ولتقضى به الحوائج، ويجاهد به في سبيل الله، ويواسى به الفقير، والمسكين، وتقام به المشاريع الخيرية، والمصالح العامة، فلا يجوز أن يضاع.  ومن ذلك قوله -جل وعلا-: وَلَا تُبَذِّرْ تَبْذِيرًا [الإسراء:26] قال العلماء: التبذير إضاعة المال، يعني صرفه في غير وجهه، كصرفه في المسكرات، وصرفه في الدخان، وصرفه في المعاصي، وطرحه في البحر، وما أشبه ذلك، هذا من التبذير.  وكذلك الإسراف، الله نهى عن الإسراف، وقال: وَلَا تُسْرِفُوا [الأنعام:141] فالإسراف: الزيادة على الحاجة، فإن كانت الزيادة عن الحاجة تمنع، فكيف بإضاعة المال أصلًا، ورأسًا! كذلك ما صح في الصحيحين عن النبي ﷺ من حديث المغيرة بن شعبة عن النبي ﷺ قال: إن الله يكره لكم، أو الله يسخط لكم: قيل وقال، وإضاعة المال، وكثرة السؤال أخبر أن الله يسخط لنا: قيل وقال، وكثرة السؤال، وإضاعة المال. والله يسخط هذا، وما سخطه الله؛ وجب علينا تركه في أدلة كثيرة غير هذا؛ لأن صرفه في الدخان، والمسكرات لا ريب أنه من التبذير، والحرام، ولا شك في ذلك، مع ما هو متقرر، ومعلوم من كون الدخان من الخبائث الضارة، والله سبحانه إنما أباح لنا الطيبات، حيث قال : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قال الله لنبيه: قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] ولا يقول عاقل، لا طبيب، ولا غير طبيب: إن الدخان من الطيبات، فعلم حينئذ بنص القرآن أنه ليس من المباحات.  وقال سبحانه في وصف النبي محمد ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157] فكل شيء ليس بطيب؛ فهو من قسم الخبائث، والله بعث نبيه ﷺ يحل الطيبات المآكل، والمشارب، والمراكب، والملابس، وغير ذلك، ويحرم الخبائث التي تضر العبد ضررًا عظيمًا، إما غالبًا، وإما محضًا، والدخان أضراره محضه، خبيثة، لا خير فيها، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1234/حكم-اتلاف-المال-في-الدخان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_231.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5921,"question":"قال أحد الخطباء في خطبة الجمعة: إن على الزوج أن لا يخبر زوجته أنه طلقها، فهل هذا الحكم صحيح، وله سند من الكتاب، والسنة؟","title":"حكم إعلام الزوج بطلاق زوجته","answer":"الجواب: الطلاق لا بدّ أن تخبر به المرأة حتى تعرف أنها مطلقة، أو غير مطلقة، إذا طلقها؛ لا بدّ أن يعرفها الطلقة، ويبين لها الطلاق حتى تحتسب الطلقة، وإذا طلقها الثانية عرفتها، وإذا طلقها الثالثة عرفت أنها حرمت عليه، لا بدّ أن يعرفها ذلك. لكن إذا رأى أن لا يبادر بذلك؛ لعلة، ولأسباب يخشى أن يصدمها بهذه الطلقة، وأن يكون لها رد فعل سيئ ، وأجل إعلامها إلى وقت آخر في غير وقت الطلقة، فالظاهر أنه لا حرج في ذلك، إذا أجل إعلامها بالطلقة إلى وقت آخر، يعني غير وقت الطلاق الذي طلقها فيه؛ لأنه يرى أن في هذا خطر عليه، أو خطر عليها، أو لأسباب أخرى وجيهة، فلا مانع من ذلك. لكن لا بدّ من إعلامها، ولو بعد ذلك، لا بدّ من إعلامها حتى تعرف، وحتى تحسب، وإذا أعلم أيضًا وليها؛ كان هذا أكمل؛ حتى لا يغلب عليه الشيطان، فيجحدها بعد ذلك، أو ينساها، فإعلامها، وإعلام وليها أمر مهم، وحق، لكن لا مانع من تعجيلها إلى وقت ما إذا كان يخشى من ذلك مضرة عليها، أو عليه، فيؤجل بعض الوقت، ثم يخبرها، أو يكتبها عنده كتابة يقيده عنده؛ حتى لا ينسى؛ حتى لا يستحلها بغير ما أنزل الله، جل وعلا.","link":"https://binbaz.org.sa/fatwas/1279/حكم-اعلام-الزوج-بطلاق-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_266.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5928,"question":"قال لزوجته: لا تدخلي هذا الباب، وإن خرجتِ منه؛ فأنت طالق، وفعلًا أن زوجته خرجت، فهل هي طلقت؟","title":"حكم من طلق امرأته لفعلها ما نهاها عنه","answer":"الجواب: كما سمعتم، الكلام فيه أنه إذا قال: إذا خرجت فأنت طالق، أو كلمت فلانًا، إذا كان قصده منعها، ما قصده فراقها؛ فعليه كفارة يمين -كما سمعتم- إذا قال: إن كلمتِ فلانًا، أو خرجت إلى بيت فلان، أو خرجت بغير إذني؛ فأنت طالق، قصده منعها، ما قصده فراقها، فهذا حكمه حكم اليمين، وعليه كفارتها.  وأما إذا كان مقصوده فراقها إذا خرجت؛ فهي مطلقة، تحسب عليه طلقة، فإن طلقها قبلها طلقتان؛ تمت الطلقات، وحرمت عليه حتى تنكح زوجًا غيره. أما إذا كان ما قبلها إلا طلقة واحدة، أو ما قبلها شيء، فيراجعها.","link":"https://binbaz.org.sa/fatwas/1281/حكم-من-طلق-امراته-لفعلها-ما-نهاها-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_268.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5929,"question":"هل يقع الطلاق إذا طلقها طلاقًا بدعيًا؟","title":"حكم إيقاع الطلاق البدعي","answer":"الجواب: اختلف العلماء في الطلاق البدعي، هل يقع، أم لا يقع؟ فذهب الجمهور إلى أنه يقع، جمهور العلماء ذهب إلى أنه يقع مع التحريم، وذهب قوم إلى أنه لا يقع، واختاره جماعة من السلف، وهو مروي عن ابن عمر، وعن طاوس بن كيسان اليماني التابعي الجليل، وعن خلاد بن عمرو التابعي الجليل، واختاره شيخ الإسلام ابن تيمية، وابن القيم، وجماعة، قالوا لأنها وقع على خلاف أمر الله؛ فلا يقع. والجمهور قالوا: أخطأ، وأساء، وينفذ عليه؛ لأن ابن عمر احتسب طلقته التي طلقها في الحيضة، احتسبها، وأمضاها على نفسه، احتسبت عليه تطليقة، لكن لم يثبت أن النبي حسبها عليه، ولكن هو اعتبرها، وأمضاها على نفسه في ظاهر النصوص التي جاءت عنه.  وسئل في رواية عنه عمن طلقها في حال الحيض، فقال: لا يعتد بها، فهذا مما يبين أنه احتسب طلقتها التي طلقها في الحيض، احتسبها اجتهادًا منه والرسول ﷺ قال له: راجعها، ثم أمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شئت فطلق، وإن شئت فأمسك ولو كانت الطلقة واقعة؛ لكان المعنى تكثير الطلاق.","link":"https://binbaz.org.sa/fatwas/1276/حكم-ايقاع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_263.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5932,"question":"قال لزوجته: لا تدخلي هذا الباب، وإن خرجتِ منه؛ فأنت طالق، وفعلًا أن زوجته خرجت، فهل هي طلقت؟","title":"حكم من طلق امرأته لفعلها ما نهاها عنه","answer":"الجواب: كما سمعتم، الكلام فيه أنه إذا قال: إذا خرجت فأنت طالق، أو كلمت فلانًا، إذا كان قصده منعها، ما قصده فراقها؛ فعليه كفارة يمين -كما سمعتم- إذا قال: إن كلمتِ فلانًا، أو خرجت إلى بيت فلان، أو خرجت بغير إذني؛ فأنت طالق، قصده منعها، ما قصده فراقها، فهذا حكمه حكم اليمين، وعليه كفارتها.  وأما إذا كان مقصوده فراقها إذا خرجت؛ فهي مطلقة، تحسب عليه طلقة، فإن طلقها قبلها طلقتان؛ تمت الطلقات، وحرمت عليه حتى تنكح زوجًا غيره. أما إذا كان ما قبلها إلا طلقة واحدة، أو ما قبلها شيء، فيراجعها.","link":"https://binbaz.org.sa/fatwas/1281/حكم-من-طلق-امراته-لفعلها-ما-نهاها-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_268.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5933,"question":"هل يقع الطلاق إذا طلقها طلاقًا بدعيًا؟","title":"حكم إيقاع الطلاق البدعي","answer":"الجواب: اختلف العلماء في الطلاق البدعي، هل يقع، أم لا يقع؟ فذهب الجمهور إلى أنه يقع، جمهور العلماء ذهب إلى أنه يقع مع التحريم، وذهب قوم إلى أنه لا يقع، واختاره جماعة من السلف، وهو مروي عن ابن عمر، وعن طاوس بن كيسان اليماني التابعي الجليل، وعن خلاد بن عمرو التابعي الجليل، واختاره شيخ الإسلام ابن تيمية، وابن القيم، وجماعة، قالوا لأنها وقع على خلاف أمر الله؛ فلا يقع. والجمهور قالوا: أخطأ، وأساء، وينفذ عليه؛ لأن ابن عمر احتسب طلقته التي طلقها في الحيضة، احتسبها، وأمضاها على نفسه، احتسبت عليه تطليقة، لكن لم يثبت أن النبي حسبها عليه، ولكن هو اعتبرها، وأمضاها على نفسه في ظاهر النصوص التي جاءت عنه.  وسئل في رواية عنه عمن طلقها في حال الحيض، فقال: لا يعتد بها، فهذا مما يبين أنه احتسب طلقتها التي طلقها في الحيض، احتسبها اجتهادًا منه والرسول ﷺ قال له: راجعها، ثم أمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شئت فطلق، وإن شئت فأمسك ولو كانت الطلقة واقعة؛ لكان المعنى تكثير الطلاق.","link":"https://binbaz.org.sa/fatwas/1276/حكم-ايقاع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_263.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5934,"question":"كثيرا ما نسمع أن الحامل ليس عليها طلاق، هل هذا صحيح، أم لا؟","title":"حكم طلاق المرأة حال حملها","answer":"الجواب: هذا كلام العامة، كلام باطل، الحامل طلاقها مشروع، لها طلاق، إنما المنكر طلاق الحائض، طلاق النفساء، طلاق التي جامعها في طهر، هذا هو الذي لا يجوز الطلاق فيه، أما الحامل فطلاقها شرعي، النبي ﷺ قال لابن عمر: ثم ليطلقها طاهرًا أو حاملًا.","link":"https://binbaz.org.sa/fatwas/1285/حكم-طلاق-المراة-حال-حملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_272.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5937,"question":"ما حكم طلاق الغضب الشديد الذي من عادته ألا يملك صاحبه نفسه؟","title":"حكم الطلاق حال الغضب المغلق","answer":"الجواب: تقدم الكلام في هذا وهو أن العلماء اختلفوا في ذلك، والأرجح أنه لا يقع إذا اشتد الغضب، وانغلق عليه قصده، ولم يتمالك نفسه، وظهرت الأسباب الدالة على ذلك. فإن الواقع يكون له أسباب، يكون معه أسباب تؤيد دعوى شدة الغضب، وعدم ذلك.","link":"https://binbaz.org.sa/fatwas/1307/حكم-الطلاق-حال-الغضب-المغلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_276.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5946,"question":"تشاجرت مع زوجتي في هذا اليوم بسبب طبخ مناسبة، ولم تأخذ أمرًا بالتنفيذ، وقلت لها: إنك طالق طالق طالق، وحضرني بعض أقربائي، وطلبوا مني أن أسترجع، وأن أذكر الله، فقلت: إنا لله وإنا إليه راجعون، ولي منها ثلاثة أولاد، وهي حامل، وهي راضية، وأنا راضي؟","title":"من طلق زوجته لخلاف حول الطعام","answer":"الجواب: هذا من عجائب الزمان، ما سوت له الطبخ يطلقها من أجل الطبخ..... كونها إذا نقصت الطبخ عما ينبغي في رأيك تطلقها؟ إن كانت رخيصة.. ما سويت كذا، امرأة أم أولادك جاءت بالألوف الكثيرة، ثم تطلقها عند أقل سبب، لا شك أنه نقص في العقل ... في الدين، ما يليق بالمؤمن هذا الشيء. أما الفتوى فتحتاج إلى حضور عندنا -إن شاء الله- ننظر في الفتوى، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/1306/من-طلق-زوجته-لخلاف-حول-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_275.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5949,"question":"ما حكم طلاق الغضب الشديد الذي من عادته ألا يملك صاحبه نفسه؟","title":"حكم الطلاق حال الغضب المغلق","answer":"الجواب: تقدم الكلام في هذا وهو أن العلماء اختلفوا في ذلك، والأرجح أنه لا يقع إذا اشتد الغضب، وانغلق عليه قصده، ولم يتمالك نفسه، وظهرت الأسباب الدالة على ذلك. فإن الواقع يكون له أسباب، يكون معه أسباب تؤيد دعوى شدة الغضب، وعدم ذلك.","link":"https://binbaz.org.sa/fatwas/1307/حكم-الطلاق-حال-الغضب-المغلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_276.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5969,"question":"أنا موظف حكومي،  وأستلم راتب الليل، ولا أحضر؛ لأنني لا أخرج في النهار إلا الساعة الثانية والنصف بعد انتهاء جميع المعاملات، فهل ما آخذه من الليل حلال، أم حرام؟","title":"حكم استلام الراتب بدون عمل","answer":"الجواب: هذا الذي يظهر أنه ليس بحلال، ينبغي أن تأخذ إذا كنت تعمل إذا كان ما هناك عمل تخبرهم أني ما أعمل، ولا أريد هذا الشيء.","link":"https://binbaz.org.sa/fatwas/1358/حكم-استلام-الراتب-بدون-عمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_316.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5971,"question":"إذا طلق رجل زوجته، وتمت ثلاثة قروء، هل تعتبر هذه طلقة، أم ثلاث؟ وإذا كان في رأس كل شهر من ذلك يقول لها: أنت طالق، فما الحكم؟","title":"ما يترتب على الطلاق الرجعي والبائن","answer":"الجواب: إذا طلقها طلقة واحدة، وتركها حتى اعتدت؛ فهي طلقة واحدة، وإذا اعتدت؛ بانت منه، وحلت لغيره من الأزواج، وإذا أحب أن يرجع إليها بعقد جديد؛ فلا بأس، إذا كان ما طلقها إلا واحدة، أو ثنتين، إذا خرجت من العدة؛ له الرجوع إليها بنكاح جديد كالأجنبي، يخطبها إذا رضيت، ورضي أهلها تزوجها. أما في العدة فله أن يراجعها في العدة ... يشهد اثنين أنه راجع زوجته، ما دامت في العدة قبل أن تروح عليها الحيضات الثلاث إن كانت تحيض، أو قبل شهور ثلاث إذا كانت لا تحيض، أو قبل الحمل إن كانت حاملًا؛ له أن يراجعها، سواء كانت طلقة، أو طلقتين. أما إذا طلقها آخر الثلاث، الطلقة الأخيرة؛ فإنها تحرم بذلك حتى تنكح زوجًا غيره، وليس له الرجوع إليها إلا بعد زوج ينكحها، ويطأها زوج شرعي، يتزوجها، ويطأها، لا نكاح تحليل، ولكن نكاح رغبة، يتزوجها زوج شرعي راغب فيها، ثم وطأها، ثم طلقها بعد ذلك، أو مات عنها؛ جاز لمن طلقها آخر الثلاث أن يتزوجها بعد ذلك.","link":"https://binbaz.org.sa/fatwas/1361/ما-يترتب-على-الطلاق-الرجعي-والباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_319.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":5976,"question":"إذا طلق رجل زوجته، وتمت ثلاثة قروء، هل تعتبر هذه طلقة، أم ثلاث؟ وإذا كان في رأس كل شهر من ذلك يقول لها: أنت طالق، فما الحكم؟","title":"ما يترتب على الطلاق الرجعي والبائن","answer":"الجواب: إذا طلقها طلقة واحدة، وتركها حتى اعتدت؛ فهي طلقة واحدة، وإذا اعتدت؛ بانت منه، وحلت لغيره من الأزواج، وإذا أحب أن يرجع إليها بعقد جديد؛ فلا بأس، إذا كان ما طلقها إلا واحدة، أو ثنتين، إذا خرجت من العدة؛ له الرجوع إليها بنكاح جديد كالأجنبي، يخطبها إذا رضيت، ورضي أهلها تزوجها. أما في العدة فله أن يراجعها في العدة ... يشهد اثنين أنه راجع زوجته، ما دامت في العدة قبل أن تروح عليها الحيضات الثلاث إن كانت تحيض، أو قبل شهور ثلاث إذا كانت لا تحيض، أو قبل الحمل إن كانت حاملًا؛ له أن يراجعها، سواء كانت طلقة، أو طلقتين. أما إذا طلقها آخر الثلاث، الطلقة الأخيرة؛ فإنها تحرم بذلك حتى تنكح زوجًا غيره، وليس له الرجوع إليها إلا بعد زوج ينكحها، ويطأها زوج شرعي، يتزوجها، ويطأها، لا نكاح تحليل، ولكن نكاح رغبة، يتزوجها زوج شرعي راغب فيها، ثم وطأها، ثم طلقها بعد ذلك، أو مات عنها؛ جاز لمن طلقها آخر الثلاث أن يتزوجها بعد ذلك.","link":"https://binbaz.org.sa/fatwas/1361/ما-يترتب-على-الطلاق-الرجعي-والباىن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_319.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6057,"question":"في حالة الكفارة باليمين، أو إطعام عشرة مساكين، أو عتق رقبة كيف أطعم عشرة مساكين، هل بواقع النفر خمسة، أو أقل، أو أكثر؟ وكيف أعتق رقبة من أي نوع أفيدونا؟","title":"صفة كفارة اليمين","answer":"الجواب: إذا كان عليه كفارة يمين، أو كفارة ظهار، فكفارة اليمين يخير بين ثلاثة: إما إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد: تمرًا، أو أرزًا، أو نحو ذلك، عشرة، كل واحد نصف صاع، كيلو ونصف للواحد من العشرة، أو يكسوهم كسوة تجزئهم في الصلاة مثل: إزار ورداء، وإلا قميص، أو يعتق رقبة مؤمنة إذا تيسرت، هذا في اليمين، فإن عجز عن هذه الأمور الثلاث يصوم ثلاثة أيام، يجب أن تكون متتابعة فقط.  أما في الظهار إذا ظاهر من امرأته، وحرمها عليه: عتق رقبة مؤمنة إذا تيسر، فإن عجز؛ يصوم شهرين متتابعين قبل أن يمسها، فإن عجز؛ أطعم ستين مسكينًا، كل مسكين له نصف صاع من التمر، أو غيره من قوت البلد، مقدار كيلو ونصف تقريبًا قبل أن يمسها، هذه كفارة الظهار.","link":"https://binbaz.org.sa/fatwas/1468/صفة-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_398.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6091,"question":"هل الزوجة التي طلقها زوجها ثلاث طلقات، ثم تزوجت زوجًا آخر، ثم طلقها، ثم تزوجها الأول، هل لهذا الزوج ثلاث طلقات جديدة؟","title":"الطلقات المتبقية لمن تزوجت مطلقته بآخر ثم عادت إليه","answer":"الجواب: نعم، إذا طلقها الزوج آخر الطلاق، ثم تزوجت زوجًا شرعيًا، ووطئها، ودخل بها، ثم عادت إلى زوجها الأول بعد الطلاق، أو بعد الموت يكون له ثلاث طلقات مثل ما صار في النكاح الأول. لكن لو ما طلقها إلا واحدة، أو طلقها ثنتين، ثم تزوجت، ثم عادت إليه؛ فليس له إلا ما بقي من طلاقها الأول واحدة، أو اثنتين، هذا الذي بقي له، أما إذا كان قد استوفاها، ثم نكحت نكاحًا شرعيًا، ثم طلقت، أو مات زوجها بعد الدخول بها بعد وطئها؛ فإن زوجها الأول إذا تزوجها ترجع له بثلاث طلقات كالنكاح الأول. السؤال: وكذلك البائن بينونة صغرى، ثم تزوجها زوجها، فهل يحسب عليه الطلقة الأولى؟ الجواب: تقدم نعم، إذا كان طلقها واحدة، أو ثنتين، ثم رجعت إليه بنكاح جديد مخلوعة، أو مفسوخة؛ فإنها ترجع على الطلاق الباقي.","link":"https://binbaz.org.sa/fatwas/1510/الطلقات-المتبقية-لمن-تزوجت-مطلقته-باخر-ثم-عادت-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_440.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6092,"question":"ما هي مقدار كفارة اليمين؟ وما هو مذهب أهل نجد؟","title":"كفارة اليمين ونبذة عن مذهب أهل نجد","answer":"الجواب: كفارة اليمين معروفة ،وليس لأهل نجد مذهب يخالف الناس، ولكن الذي هم عليه في الغالب مذهب الحنابلة، هذا معروف، المذهب المعروف مذهب الحنابلة، إمامهم أحمد بن حنبل، رحمه الله.  ولكن علماء أهل نجد إذا عرفوا أن القول في مذهب أحمد صار مرجوحًا؛ أخذوا بالدليل، وقدموا ما يقبل الدليل، تقديمه في مسائل الخلاف. ومسائل كفارة اليمين ما فيها خلاف، بينها الله في كتابه العظيم، وأنها إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، هذه كفارة اليمين عند أهل العلم بالنص؛ فإن عجز عن هذه الثلاث؛ صام ثلاثة أيام، هذه كفارة اليمين، أولًا، يطعم عشرة مساكين، أو يكسوهم، أو يحرر رقبة، هذه مخير، إن أعتق؛ أجزأ، وإن كسا؛ أجزأ، وإن أطعم؛ أجزأ، مخير بين هذه الثلاث، أعظمها العتق، وهو أعلاها، فإن لم يعتق، وكساهم على كسوة كسوة، على قميص قميص، وعلى إزار ورداء عشرة؛ كفى، وإن أطعمهم، عشاهم، أو غداهم، أو أعطاهم نصف صاع تمر، أو رز من قوت البلد، وهو يقارب كيلو ونصف؛ أجزأ ذلك، فإن عجز كأن كان فقيرًا، ما عنده شيء؛ يصوم ثلاثة أيام متتابعة.","link":"https://binbaz.org.sa/fatwas/1505/كفارة-اليمين-ونبذة-عن-مذهب-اهل-نجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_435.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6147,"question":"رجل أضاف علي رجل آخر، وحلف بالطلاق ألا يأكل الذبيحة، وذهب، وجاء بذبيحة أخرى، وأكل منها، ماذا يلزم عليّ؟","title":"حكم الحلف بالطلاق على أمر دون قصد الطلاق","answer":"الجواب: إذا كان قصد الضيف أنه ما يكلف المستضيف الضيف النازل، طلق أنه ما يأكل ذبيحتك يا فلان، إن نزل عليك يبيه ما يتكلف، ولا يشتري ذبيحة، ويأكل من الطعام الحاضر، ثم أبى عليه المضيف، وجاء بذبيحة، وذبحها، وأكل منها، أو ما أكل منها؛ فإنه عليه الحكم في طلاقه إن كان أراد طلاق زوجته إن أكل الذبيحة، مضى عليه طلقة حسب ما قال. وإن كان إنما أراد منعه من الذبيحة، ولم يرد طلاق امرأته، ولكن أراد إذا سمع الطلاق أنه يمنعه ذلك؛ فعليه كفارة يمين، قال: عليه الطلاق ما يأكل الذبيحة، ما تذبح له، عليه الطلاق ما تذبح له، وذبح، أو عليه الطلاق ما يأكل، وأكل؛ فهذا عليه كفارة يمين، حكمه حكم اليمين، إذا كان المقصود من هذا الكلام منع النزول به من التكلف، وليس قصده فراق زوجته، وإنما قصده منع التكلف إذا سمع الطلاق يمتنع لا يأتي الذبيحة، ولا يتكلف، ثم صاحب الضيافة المنزول عليه تكلف، ولم يبال بيمينه، ولا بطلاقه، ثم أكل من ذبيحته إن كان طلاق أن لا يأكل، أو طلق أن لا يذبح، وذبح له؛ فإن الطلاق هذا يكون عن كفارة يمين إن كان ما قصد إيقاعه على الزوجة، ما قصد فراقها، وإنما قصد منعه من التكلف. هذا حكمه حكم اليمين، ما تحسب إذا كان قصده المنع، منع الرجل من التكلف عليه كفارة يمين، ولا يقع، إطعام عشرة مساكين، أو كسوتهم ..","link":"https://binbaz.org.sa/fatwas/1611/حكم-الحلف-بالطلاق-على-امر-دون-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_505.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6179,"question":"هل القات من المخدرات، وما حكم أكله، أفيدونا، جزاكم الله خيرًا؟","title":"هل القات من المخدرات؟ وما حكم أكله؟","answer":"الجواب: ذكر كثير من أهل العلم أنه من المسكرات، والمخدرات، وأنه من جهة اليمن، ما أدري من أين عرفوه؟ ولهذا في المؤتمر الذي عقد أخيرًا في المدينة المنورة أجمع المؤتمرون على تحريمه كالدخان؛ لما يترتب عليه من شر، وفساد، وإن كان بعض إخواننا في اليمن أنكر ذلك، وقال: إن مضرته خفيفة، ولا يترتب عليه الإسكار. ولكن الذي يتعاطاه، ويعيش عليه قد لا يحس بشره، وفساده، وقد يصعب عليه الاعتراف بشره، وتحريمه، أما الذين قد عافاهم الله من شره، وقد عرفوه فقد ذكروا فساده، وأنه قد يسكر بعض الأحيان، وأن شاربه قد يختلط عليه الطريق، ويضيع أهله، وأولاده عندما يتعاطاها، علاوة على ما يترتب عليه من تعطيل الأعمال، وبقائهم مخزنين مدة طويلة، يخزنون، ويبصقون، ويبقون مدة طويلة، وهم معطلون بسبب تعاطيهم هذا البلاء.","link":"https://binbaz.org.sa/fatwas/1636/هل-القات-من-المخدرات-وما-حكم-اكله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_527.mp3","categories":["الأخلاق المذمومة","صلاة الجماعة","الأطعمة والأشربة"]},{"id":6184,"question":"هل لي أن أتجسس على إنسان في بيته؛ لمعرفة إن كان عنده شيء من المحرمات، أو الخمور، أو يستعملها؟","title":"حكم التجسس على شخص لمعرفة إذا كان يعصي","answer":"الجواب: ليس لك التجسس؛ لأن الله يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] والنبي -عليه الصلاة والسلام- قال: لا تجسسوا. فلا يجوز التجسس، وهو التنقيب عن الشخص لعله يجده على معصية، لا بل إذا ستر الله مسلمًا فلا تحرص على كشفه، لكن متى ظهر الأمر، وبان بدون تجسس؛ وجب عليك النصيحة، والتوجيه إلى الخير، وإنكار المنكر، أما التجسس فلا يجوز.","link":"https://binbaz.org.sa/fatwas/1638/حكم-التجسس-على-شخص-لمعرفة-اذا-كان-يعصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_529.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6191,"question":"كانت عندي وليمة، وكان هناك شخص لم يرض أن يقوم معنا، فحلفت عليه، وقلت له: قم، وهكذا عليّ الحرام أنك تقوم، فأرجو من فضيلتكم أن تنصحونا بذلك؟","title":"حكم مقولة: عليَّ الحرام فِعْل كذا وكذا","answer":"الجواب: ما يجوز للإنسان أن يحرِّم ما أحل الله، فيقول: عليَّ الحرام أن تفعل كذا، أو عليّ الحرام أن لا تفعل كذا، أو عليّ الحرام من طعامك، أو شرابك، أو دارك، أو لباسك لا، الله -جل وعلا- أنكر على نبيه ﷺ وقال: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1] فليس للناس أن يحرموا ما أحل الله.  وإذا فعل الإنسان هذا؛ فعليه التوبة، وعليه كفارة اليمين، فإن الله قال: قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:2] فإذا قال: عليه الحرام، ما يأكل كذا، عليه الحرام ما يزور فلانًا، عليه الحرام ما يأكل ذبيحته، عليه الحرام ما يدخل بيتك، فهذا من باب تحريم ما أحل الله، وحكمه حكم اليمين؛ فعليه كفارة يمين إذا فعل ما حرم أن يفعل.","link":"https://binbaz.org.sa/fatwas/1658/حكم-مقولة-علي-الحرام-فعل-كذا-وكذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_539.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6218,"question":"ما قول سماحتكم فيمن سأل عن الإسبال، فقال: هو الكبر، هل هذا يعتبر تفسير، أو تغيير لكلام رسول الله؟ وما حكمه؟","title":"الإسبال وسيلة للكبر","answer":"الجواب: الإسبال وسيلة إلى الكبر، وليس هو الكبر، لكن في الغالب أنه وسيلة، والغالب أنه يدعو إلى الكبر، وأما أنه هو الكبر بعينه لا، لكنه وسيلة إلى الكبر، وذريعة إليه، ولهذا حرمه الإسلام، ونهى عنه؛ لأنه وسيلة إلى الكبر، وهو وسيلة إلى إفساد الثياب، وتنجيسها، وتوسيخها، وإعدامها، ولما رأى عمر  شابًا يمس ثوبه الأرض، قال له: يا عبدالله، ارفع ثوبك؛ فإنه أتقى لربك، وأنقى لثوبك.","link":"https://binbaz.org.sa/fatwas/1707/الاسبال-وسيلة-للكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_564.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6226,"question":"حكم اللوطي يا شيخ؟","title":"حد اللواط","answer":"الجواب: اللوطي نسيته نعم، أما اللوطي فقد ذكر الشيخ إبراهيم، وأفتى العلماء:  اللوطي كما سمعتم، والعياذ بالله، اللوطي الذي يأتي الرجل، إتيان الرجل هذه اللواطة، والله أنكر ذلك، وبين أمر اللوطية في قصة قوم لوط، والله أهلكهم جميعًا، وخسف ببلادهم، وجعل عاليها سافلها -نعوذ بالله- ثم أمطرهم بحجارة من سجيل، نسأل الله العافية. قال الوليد بن عبدالملك أمير المؤمنين: لولا أن الله ذكر قصة اللوطية في القرآن ما كنت أظن أن رجلًا يركب رجلًا! فهي فاحشة شنيعة، أفحش من الزنا -نعوذ بالله- وأقبح، فلهذا جاء أن حكمه القتل الذي عليه أصحاب الرسول ﷺ وقد أجمعوا جميعًا  على قتل اللوطي مطلقًا، سواء كان بكرًا، أو ثيبًا، بعض الفقهاء قالوا: إنه كالزاني يرجم المحصن، ويجلد البكر مائة جلدة، ويغرب عامًا، ولكنه قول ضعيف.  والصواب: أن اللوطي يقتل، هذا هو أحد الأقوال، وهو الصواب، يقتل قتلًا بالسيف، أو بالرجم بالحجارة كالزاني المحصن، وقد أجمع الصحابة -رضي الله عنهم وأرضاهم- على قتله، لكن بعضهم قال: يرجم كما يرجم الزاني المحصن وبعضهم قال: بل يلقى من شاهق، وبعضهم يقال: يحرق بالنار.  والصواب في هذا أنه يقتل قتلًا بالسيف، كما جاء في الحديث عن النبي ﷺ أنه قال: من وجدتموه يعمل عمل قوم لوط؛ فاقتلوا الفاعل والمفعول به نسأل الله العافية، وهذا الحديث لا بأس بإسناده، جيد، وإن كان فيه بعض الاختلاف، لكن يعضده، ويؤيده إجماع الصحابة، وقد أجمع أصحاب الرسول ﷺ على قتله، وأن اللوطي يقتل مطلقًا، سواء كان بكرًا، أو ثيبًا، وإنما اختلفوا في صفة القتل، فهل يقتل بالتحريق بالنار، أو بالرجم، أو بالسيف؟ والصواب: أنه يقتل بالسيف؛ لأن النار لا يعذب بها إلا الله -جل وعلا- والرجم إنما جاء في الزاني المحصن؛ فلا يقاس عليه اللوطي، فاللوطي له شأن آخر، ولكن يقتل بالسيف الفاعل والمفعول به إذا كانا مكلفين لخبث معصيتهما، ولشناعتها العظيمة؛ ولأن الواجب التنفير منها، والتحذير منها، وكان القتل مناسبًا في هذا المقام؛ للتحذير من هذه الفاحشة الشنيعة القبيحة. نسأل الله للجميع العافية، والسلامة.","link":"https://binbaz.org.sa/fatwas/1727/حد-اللواط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_574.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6227,"question":"حكم من يأتي البهيمة؟","title":"حكم إتيان البهيمة","answer":"الجواب: البهيمة جاء فيها حديث في سنده اختلاف أنه يقتل، وجاء عن ابن عباس أنه يعزر تعزيرًا؛ لأن السند وحده لا  يكفي؛ لأن فيه اختلاف عن ابن عباس في قتل البهيمة، وهو الذي عليه أهل العلم، المحققون من أهل العلم أنه يعزر إذا أتى البهيمة، كان حمارًا، أو بقرة، أو عنزًا، أو غير ذلك؛ يعزر، وبعض أهل العلم قال: يقتل للحديث.  ولكن ذهب جملة من أهل العلم إلى أنه يعزر، لأن الحديث ليس في قوته، وسنده ما يشجع على قتل الشخص؛ لأن فيه بعض الاختلاف، والأصل عصمة المؤمن، فوجب أن يعزر بما يراه ولي الأمر من جلدات، أو جلد، وسجن، أو غير ذلك مما يراه ولي الأمر رادعًا عن هذه الفاحشة، نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/1728/حكم-اتيان-البهيمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_575.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6229,"question":"لو قال أبدلك؟","title":"حكم نكاح الشغار البدل","answer":"الجواب: أما نكاح البدل فلا يجوز، إذا كان في نكاح بدل، إذا كان النكاح الذي فيه بدل ما يجوز؛ لأن هذا هو نكاح الشغار، الشغار لا يجوز كونه يقول: زوجني، وأزوجك إذا كان أبوك فعل ذلك، هذا لا يجوز، عليك أن تفارقها إن كان شغارًا، زوجني، وأزوجك، تعطيه بنتك، أو أختك، ويعطيك بنته، أو أخته هذا الشغار المنهي عنه، لا يجوز، ولو فيه مال على الصحيح، ولو بذل فيه مال.  فالواجب: أن تفارقها، وإذا كنت ترغب فيها، وترغب هي فيك؛ فلا بدّ من تجديد النكاح، نكاح جديد بدون شرط المرأة الأخرى، تتفق مع وليها على سبيل النكاح من دون شرط المرأة الأخرى، ويصح العقد حينئذ، وتسلم من شر الأول، والأولاد لاحقون بك لأجل الشبهة، الأولاد في العقد الأول لاحقون بك من أجل الشبهة، وهم أولادك، ولكن لا تبقى معها بعقد الشغار، بل لا بدّ من تجديد العقد، إذا كانت ترغب فيك، وأنت ترغب فيها، تجدد العقد بنكاح شرعي جديد، بولي، وشاهدين على الوجه الشرعي من دون شرط المرأة الأخرى.","link":"https://binbaz.org.sa/fatwas/1752/حكم-نكاح-الشغار-البدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_591.mp3","categories":["الأنكحة المحرمة","الأخلاق المذمومة"]},{"id":6230,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6233,"question":"وسائل يسأل فيقول: أنا رجل أبيع، وأشتري في الدخان، وكل دخلي تقريبًا من الدخان، فهل يجوز لي الطعام، والشراب، والحج، والزكاة، والصدقة، وكل أعمال الخير؟ وأرجو من فضيلتكم أن توضحوا لي هل لي أجر فيما قدمت من أعمال الخير، أم لا؟","title":"حكم التجارة في الدخان","answer":"الجواب:  هذا يا أخي من البلاء العظيم، كونك تتجر بالدخان، وغالب دخلك من الدخان هذا من البلاء؛ فعليك أن تبادر بالتوبة، وأن تقلع عن هذا البلاء، وأن تسأل ربك العافية منه، وأن تسلك مسلكًا آخر من التصرف المالي، والله وسع ويسر. أما الدخان فقد قرر أهل العلم -المعروفون- والبصائر قرروا بتحريمه، وشره العظيم، وأنه يسبب مشاكل كثيرة، ومضار عظيمة، وأنه بهذا محرم لا تجوز التجارة فيه، لا بيعًا، ولا شراءً، وأن الواجب الحذر منه، وعدم استيراده، وعدم الأكل من ثمنه، فما حصل لك من هذا الباب ينبغي أن تصرفه في وجوه البر، وإن كان ما عندك شيء يقوم بحالك؛ أبقيت عندك منه ما تحتاج إليه، ويقوم بحالك، حتى يغنيك الله من فضله بالطرق المباحة، وما زاد على ذلك من هذا الثمن الخبيث من طريق الدخان؛ يصرف في وجوه الخير، للتخفيف من شره، ونفع المسلمين به في مساعدة فقير، ومساعدة غريم، وإصلاح دورات المياه، وأشباه ذلك من الطرق الخيرية؛ حتى تسلم من شره -إن شاء الله- ونرجو أن لا حرج عليك فيما مضى، فالتوبة تجب ما قبلها، ومن تاب؛ تاب الله عليه . السؤال: يقول: وهل هذا يدخل في حديث من غشنا فليس منا؟ الجواب: هذا قد يكون نوعًا من الغش لبيعه على الناس، فالغش يكون بالسر، ويكون بالإخفاء، وأما الدخان بيعه ظاهر، ما هو غش؛ لكنه غش من جهة تمكين الإنسان مما يضره، ويحسب أنه جيد، وأنه نافع، وأنت تمكنه ما يضره إن بيعت عليه الدخان، وتمكينه من الدخان وهو يضره، وقد يظن أنه لا يضره بسبب أنك تبيعه عليه، وربما اعتقد فيك أنك جيد، وأنك لا تبيع ما يضر الناس، فهو نوع من الغش من  هذا  الباب. فالواجب الحذر منه، وأن تتوب إلى الله من ذلك، وأن تبعد ما عندك، وتحرق ما عندك من الدخان، وتستجيب لداعي الله .","link":"https://binbaz.org.sa/fatwas/1757/حكم-التجارة-في-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_596.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6234,"question":"لو قال أبدلك؟","title":"حكم نكاح الشغار البدل","answer":"الجواب: أما نكاح البدل فلا يجوز، إذا كان في نكاح بدل، إذا كان النكاح الذي فيه بدل ما يجوز؛ لأن هذا هو نكاح الشغار، الشغار لا يجوز كونه يقول: زوجني، وأزوجك إذا كان أبوك فعل ذلك، هذا لا يجوز، عليك أن تفارقها إن كان شغارًا، زوجني، وأزوجك، تعطيه بنتك، أو أختك، ويعطيك بنته، أو أخته هذا الشغار المنهي عنه، لا يجوز، ولو فيه مال على الصحيح، ولو بذل فيه مال.  فالواجب: أن تفارقها، وإذا كنت ترغب فيها، وترغب هي فيك؛ فلا بدّ من تجديد النكاح، نكاح جديد بدون شرط المرأة الأخرى، تتفق مع وليها على سبيل النكاح من دون شرط المرأة الأخرى، ويصح العقد حينئذ، وتسلم من شر الأول، والأولاد لاحقون بك لأجل الشبهة، الأولاد في العقد الأول لاحقون بك من أجل الشبهة، وهم أولادك، ولكن لا تبقى معها بعقد الشغار، بل لا بدّ من تجديد العقد، إذا كانت ترغب فيك، وأنت ترغب فيها، تجدد العقد بنكاح شرعي جديد، بولي، وشاهدين على الوجه الشرعي من دون شرط المرأة الأخرى.","link":"https://binbaz.org.sa/fatwas/1752/حكم-نكاح-الشغار-البدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_591.mp3","categories":["الأنكحة المحرمة","الأخلاق المذمومة"]},{"id":6235,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6240,"question":"ما رد سماحتكم على من يقول: أن تقبيل الأجنبية ونوال منها كل شيء عدا الزنا ذنب يغسله الاستغفار؟","title":"الرد على من زعم أن تقبيل المرأة الأجنبية يمحوه الاستغفار","answer":"الجواب: هذا منكر، والإصرار عليه يكون كبيرة، ومن الكبائر لا يزيله الاستغفار، ولا يزيله إلا التوبة فإذا قبلها بغير حق قبلها وهي غير محرم له أو مسها أو ما أشبه ذلك فهذا لا يمحوه إلا التوبة، والذنب الإصرار عليه كبيرة، نسأل الله العافية.\nإذا تاب إلى الله جل وعلا ولم يصر وندم على ذلك أو حافظ على الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان، وتجنب الكبائر غفر الله له الصغائر التي لم يصر عليها، أما إذا أصر عليها صارت كبيرة، نعوذ بالله لا بدّ فيها من التوبة.","link":"https://binbaz.org.sa/fatwas/1744/الرد-على-من-زعم-ان-تقبيل-المراة-الاجنبية-يمحوه-الاستغفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_583.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6243,"question":"هل يلزم جلد الزاني المتزوج مع الرجم؟ وما هو موقفكم من الأسباب التي تؤدي إلى الزنا مثل آلات اللهو، والغناء، والموسيقى التي تأتي في الإذاعات المسلمة؟","title":"الموقف من الأسباب المؤدية إلى الزنا وحد الزاني","answer":"الجواب: ليس في هذا عذر له، وعليه أن يتجنبها، ويحذرها من الإذاعة، ومن التلفاز، وليس وجود الغناء في التلفاز، أو آلات الملاهي، أو تكشف بعض النساء، ليس عذرًا في الزنا، وإنما هي من أسباب الزنا، وليس عذرًا، بل يجب أن يحذر هذا، ولا يستعمل هذا الشيء، ولا ينظر إليه، بل يجاهد نفسه، وإذا زنا، وثبت عليه الزنا بإقرار، أو بالبينة ؛رجم إذا كان محصنًا. ولو قال: إن هذا من أسباب رؤيتي للتلفاز، أو من أسباب سماعي للإذاعة! من قال لك تسمع؟! ومن قال لك تنظر؟! أنت الذي جنيت على نفسك. المقصود: أن هذا ليس بعذر متى أقر بالفاحشة، بالزنا، أو ثبت بالبينة الشرعية، أربعة شهود؛ وجب أن يقام عليه حدها، إن كان بكرًا؛ جلد مائة جلدة، وغرب عامًا، وإن كان ثيبًا يرجم بالحجارة حتى يموت، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1745/الموقف-من-الاسباب-المودية-الى-الزنا-وحد-الزاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_584.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6246,"question":"وآخر يقول: أنا متزوج من امرأتين، وفي لحظة غضب قلت : حريمي علي كحرمة أمي، وأريد الآن أن أعرف هل يحرمن جميعًا، أم علي كفارة ؟","title":"حكم الظهار من الزوجتين بلفظ واحد","answer":"الجواب:  ما كان ينبغي عليه أن يحرم زوجاته، ينبغي له إذا أحس بالغضب أن يتعوذ بالله من الشيطان الرجيم، وهكذا ينبغي، ولا يعجل في الأمور. والظهار، والتحريم للزوجات محرم، ومنكر من القول، وزروًا؛ كما سماه الله في الآية، لكن إذا وقع منك ذلك قلت: حريمي مثل أمي، أو مثل ظهر أمي، أو مثل أختي، أو ظهر أختي، فهذا يسمى الظهار. فعليك عتق رقبة مؤمنة، وإن عجزت؛ تصوم شهرين متتابعين، وإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، أو تعشيهم، أو تغديهم قبل أن تقربها، قبل أن تمسها، فهذه هي الكفارة من الظهار، إن عجز عن العتق، والصيام يطعم ستين مسكينًا، يعشيهم، أو يغديهم مجتمعين، أو متفرقين، أو يعطيهم على نصف الصاع تمرًا، أو رزًا، كيلو ونصف تقريبًا لكل واحد قبل أن يمس زوجته التي حرمها، وإذا قال: جميعًا حريمي بكلمة واحدة، أو نسائي، أو زوجاتي عليه مثل أمي، أو حرام مثل أمي؛ كفى كفارة واحدة؛ لأنها كلمة واحدة. السؤال: ما ينفع فلوس؟ الجواب:  لا فلوس لا، طعام.","link":"https://binbaz.org.sa/fatwas/1750/حكم-الظهار-من-الزوجتين-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_589.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6254,"question":"وآخر أرسل إلينا سؤالاً بخط ركيك نحاول قراءته على علته، فيقول: سمعت يوم عرفة محدثًا يقول: العيد أربعة أيام، مثل عدد الرمي، أن الرمي أربعة أيام، فيقول العيد أربعة أيام كذلك، وسمعه يقول: من تعجل؛ فيرمي أربعة بحجر اليوم الثاني عشر مع الحادي عشر، يعني يرمي يوم حادي عشر، ثم يرمي يوم الثاني عشر؟","title":"بيان عدد أيام عيد الأضحى والتعجيل للحاج فيها","answer":"الجواب: هذا كلام معقول، معناه أن أيام العيد التي هي أيام الذبح، وتسمى أيام العيد أربعة، يوم العيد، وثلاثة أيام بعده، وكلها فيها رمي يوم العيد، يرمي جمرة العقبة، والحادي عشر، يرمي الجمرات الثلاث، والثاني عشر، يرمي الجمرات الثلاث، وهكذا الثالث عشر فيمن لم يتعجل، فيرمي الجمرات الثلاث، فهي كلها أيام عيد، كلها أيام رمي، كلها أيام ذبح، كلها أيام أكل، وشرب، وذكر لله .  فإذا رمى يوم العيد، ورمى اليوم الحادي عشر الجمار الثلاث بعد الزوال، ورمى الثاني عشر بعد الزوال، الجمار الثلاث؛ فله التعجل قبل غروب الشمس، له أن يتعجل من منى إلى مكة قبل غروب الشمس، ويعود إلى وطنه إذا شاء؛ فلا بأس في ذلك، يتعجل، ولا شيء عليه، وإن بات ليلة الثالث عشر، ورمى يوم الثالث عشر؛ فهو أفضل؛ لأن الرسول -عليه الصلاة والسلام- بات، ورمى في اليوم الثالث عشر، هذا هو الأفضل؛ لما فيه من زيادة العمل، والتأسي بالنبي -عليه الصلاة والسلام- وإن تعجل بعد الزوال، وبعد الرمي في اليوم الثاني عشر؛ فلا بأس عليه. وله أن يقيم في مكة ما شاء، فإذا أراد السفر؛ طاف للوداع بعد ذلك، وإن تعجل في الحال، وسافر بعد الوداع بعدما رمى يوم الثاني عشر، مر إلى مكة، وطاف الوداع، ومشى، وسافر؛ فلا بأس. ولكن بعض الناس قد يغلط، ويعد يوم العيد هو اليوم الأول من أيام التشريق، وإذا رمى يوم الحادي عشر؛ تعجل، وهذا غلط يوم العيد، ليس من أيام التشريق المذكورة في قوله -جل وعلا-: وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى [البقرة:203] هذه الأيام غير يوم العيد، هي الحادي عشر، والثاني عشر، والثالث عشر، فالتعجل في يومين معناه الثاني عشر، ويوم العيد، لا يعد منها.  فينبغي أن يفهم هذا الأيام الثلاثة، هي: الحادي عشر، والثاني عشر، والثالث عشر، والتعجل يكون في الثاني عشر، والتريث يكون إلى الثالث عشر، ولا يجوز الرمي إلا بعد الزوال في هذه الثلاثة أيام، كله بعد الزوال، والتعجل يكون من بعد رمي الجمار، وبعد زوال الشمس، يرميها بعد الزوال، ثم يتعجل إلى مكة، فيطوف طواف الوداع، ثم يسافر إذا شاء، وإن بقي في مكة؛ فيبقى حتى يعزم على السفر، فإذا عزم على السفر؛ طاف للوداع.","link":"https://binbaz.org.sa/fatwas/1775/بيان-عدد-ايام-عيد-الاضحى-والتعجيل-للحاج-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_614.mp3","categories":["مسائل متفرقة في الحج والعمرة","البيوع","الأخلاق المذمومة"]},{"id":6263,"question":"وآخر أرسل إلينا سؤالاً بخط ركيك نحاول قراءته على علته، فيقول: سمعت يوم عرفة محدثًا يقول: العيد أربعة أيام، مثل عدد الرمي، أن الرمي أربعة أيام، فيقول العيد أربعة أيام كذلك، وسمعه يقول: من تعجل؛ فيرمي أربعة بحجر اليوم الثاني عشر مع الحادي عشر، يعني يرمي يوم حادي عشر، ثم يرمي يوم الثاني عشر؟","title":"بيان عدد أيام عيد الأضحى والتعجيل للحاج فيها","answer":"الجواب: هذا كلام معقول، معناه أن أيام العيد التي هي أيام الذبح، وتسمى أيام العيد أربعة، يوم العيد، وثلاثة أيام بعده، وكلها فيها رمي يوم العيد، يرمي جمرة العقبة، والحادي عشر، يرمي الجمرات الثلاث، والثاني عشر، يرمي الجمرات الثلاث، وهكذا الثالث عشر فيمن لم يتعجل، فيرمي الجمرات الثلاث، فهي كلها أيام عيد، كلها أيام رمي، كلها أيام ذبح، كلها أيام أكل، وشرب، وذكر لله .  فإذا رمى يوم العيد، ورمى اليوم الحادي عشر الجمار الثلاث بعد الزوال، ورمى الثاني عشر بعد الزوال، الجمار الثلاث؛ فله التعجل قبل غروب الشمس، له أن يتعجل من منى إلى مكة قبل غروب الشمس، ويعود إلى وطنه إذا شاء؛ فلا بأس في ذلك، يتعجل، ولا شيء عليه، وإن بات ليلة الثالث عشر، ورمى يوم الثالث عشر؛ فهو أفضل؛ لأن الرسول -عليه الصلاة والسلام- بات، ورمى في اليوم الثالث عشر، هذا هو الأفضل؛ لما فيه من زيادة العمل، والتأسي بالنبي -عليه الصلاة والسلام- وإن تعجل بعد الزوال، وبعد الرمي في اليوم الثاني عشر؛ فلا بأس عليه. وله أن يقيم في مكة ما شاء، فإذا أراد السفر؛ طاف للوداع بعد ذلك، وإن تعجل في الحال، وسافر بعد الوداع بعدما رمى يوم الثاني عشر، مر إلى مكة، وطاف الوداع، ومشى، وسافر؛ فلا بأس. ولكن بعض الناس قد يغلط، ويعد يوم العيد هو اليوم الأول من أيام التشريق، وإذا رمى يوم الحادي عشر؛ تعجل، وهذا غلط يوم العيد، ليس من أيام التشريق المذكورة في قوله -جل وعلا-: وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى [البقرة:203] هذه الأيام غير يوم العيد، هي الحادي عشر، والثاني عشر، والثالث عشر، فالتعجل في يومين معناه الثاني عشر، ويوم العيد، لا يعد منها.  فينبغي أن يفهم هذا الأيام الثلاثة، هي: الحادي عشر، والثاني عشر، والثالث عشر، والتعجل يكون في الثاني عشر، والتريث يكون إلى الثالث عشر، ولا يجوز الرمي إلا بعد الزوال في هذه الثلاثة أيام، كله بعد الزوال، والتعجل يكون من بعد رمي الجمار، وبعد زوال الشمس، يرميها بعد الزوال، ثم يتعجل إلى مكة، فيطوف طواف الوداع، ثم يسافر إذا شاء، وإن بقي في مكة؛ فيبقى حتى يعزم على السفر، فإذا عزم على السفر؛ طاف للوداع.","link":"https://binbaz.org.sa/fatwas/1775/بيان-عدد-ايام-عيد-الاضحى-والتعجيل-للحاج-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_614.mp3","categories":["مسائل متفرقة في الحج والعمرة","البيوع","الأخلاق المذمومة"]},{"id":6270,"question":"وآخر يقول: أغضبتني أختي غضبًا شديدًا، فحلفت بالطلاق ثلاثًا أن لا أكلمها، وأن لا أسلم عليها ما دامت على قيد الحياة، ولا تدخل بيتي، وأنا الآن نادم، وأريد أن أزورها، وقد غيرت محل السكن من الطائف إلى بلاد بني مالك، فما حكمه؟","title":"حكم من حلف بالطلاق ثلاثاً أن لا يكلم أخته","answer":"الجواب: إذا طلق الإنسان أن لا يزور فلانًا، أو أن لا يكلم فلانًا؛ فالحكم ما يتعلق بالبيت، بل يتعلق بالشخص أينما كان، البيت إذا تغير ما يتغير الحكم إلا إذا قال في هذا البيت المعين، لا أزورها في هذا البيت المعين، قصده البيت المعين، أو لا يكلمها ما دامت في البيت المعين، إذا قصد البيت المعين، فإذا انتقل عنه؛ زال الحكم، لكن ما دام مقصود هجره، ما دام مقصود الزعل عليه هو؛ فالحكم يدور معه، هو سواء كان في نجد، أو في الحجاز، أو في أي مكان.  ولكن إذا كان القصد منها الطلاق، وأن لا يكلمها، وأن لا، وأن لا، إذا كان المقصود منع نفسه من زيارتها، وكلامها، وليس المقصود فراق زوجته إن كلمها، فهذا حكمه حكم اليمين، وعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، وإذا عشاهم، أو غداهم؛ كفى، أو أعطى كل واحد نصف الصاع من التمر، أو الرز، أو نحو ذلك، وهو كيلو ونصف؛ كفى، هذا إن كان قصده منعها من الكلام، والزيارة. أما إن كان يقصد من ذلك أنه متى كلمها يقع الطلاق، متى كلمها يفارق زوجته، يقع في الثلاث طلقة واحدة، إذا قال: أنت طالق بالثلاث، إن زارها، أو كلمها؛ يقع فيها واحدة، إذا أراد الطلاق أن يقع، يقع طلقة واحدة، ويراجعها إذا كان ما لها طلاقان، إذا كان ما طلقها طلقتين؛ يكون بهذا طلقة إذا كلم أخته، إذا كان المقصود فراق زوجته إن كلمها.  أما إن كان المقصود ليس ذلك، المقصود منع نفسه من زيارتها، وكلامها، وليس المقصود فراق زوجته؛ فهذا فيه كفارة اليمين، ويكفي، وعليه التوبة إلى الله من هذا. السؤال: والفلوس لا تكفي في الكفارة؟ الجواب: لا، إما طعام، وإما كسوة.","link":"https://binbaz.org.sa/fatwas/1766/حكم-من-حلف-بالطلاق-ثلاثا-ان-لا-يكلم-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_605.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6275,"question":"سمعنا بعض العلماء يقول: إذا قال الرجل لزوجته: أنت طالق طالق طالق؛ فإن هذا يقع طلقة واحدة، وإذا قال: أنت طالق، أنت طالق، أنت طالق ثلاثًا؛ فإنه يقع ثلاث فما ..؟","title":"مسألة تأكيد الطلاق","answer":"الجواب: هكذا قرر أهل العلم، جمهور العلم على هذا، إذا قال: طالق طالق طالق، ولم ينو الثلاث؛ فإن اللفظ الثاني، والثالث يؤكد اللفظ الأول؛ لأنه ما كرر المبتدأ، ما كرر الجملة فقال: أنت طالق طالق طالق، مثل: جاء زيد زيد زيد، للتأكيد.  أما إذا قال: أنت طالق، أنت طالق، أنت طالق، أو هي طالق، هي طالق، هي طالق، ولم ينو تأكيدًا، ولا إسهامًا، وإنما نوى الثلاث، وأطلق؛ تقع الثلاث، بخلاف ما إذا قال: أنت طالق طالق طالق، أو هي مطلقة مطلقة مطلقة،  هذا لا يقع إلا الأولى واحدة، واللفظ الثاني، والثالث مؤكد للفظ الأول، ولا يقع فيه شيء عند أهل العلم، إلا أن تكون له نية في الثلاث، إن كان له نية في الثلاث؛ وقعت الثلاث عند جمهور أهل العلم، بل عند عامتهم، ولا يعرف خلاف في ذلك من المتقدمين.","link":"https://binbaz.org.sa/fatwas/1767/مسالة-تاكيد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_606.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6293,"question":"وأحد الإخوة يسأل سؤالًا خاصًا فيقول: في واحد لما يشرب الدخان، تركه مدة، وعزم أنه لا يشربه، وحلف يمين على أنه إذا شربه؛ صام ثلاث سنين، ورجع إليه مرة ثانية، وشربه، فما حكم صيام الثلاث سنين الذي ألزم نفسه بها؟","title":"حكم من حلف أن يصوم ثلاث سنين إن عاد للدخان","answer":"الجواب:  عليه أن يتوب إلى الله، وعليه كفارة اليمين، لأن الرسول نهى عن صيام الأبد، وهذا صيام مستمر، بل يطعم عشرة مساكين، أو يكسوهم، ويكفي عن يمينه، وعليه التوبة إلى الله، وعدم الرجوع إلى الدخان؛ لأن مضاره كثيرة، وهو خبيث محرم؛ فعليه التوبة إلى الله، وعدم الرجوع إليه، مع كفارة يمين على حلفه أنه لا يشربه، وإن شربه؛ فعليه كفارة يمين.","link":"https://binbaz.org.sa/fatwas/1790/حكم-من-حلف-ان-يصوم-ثلاث-سنين-ان-عاد-للدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_629.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6303,"question":"رجل طلق زوجته دون براءة، طلقها ثاني مرة دون براءة، ثم أرجعها، ومن ثم حرمها مرة أخرى على نفسه مثل أمه، أو أخته، وهو رجل  مقطوع، عمره خمس وستون عامًا، وهو لاجئ، ليس له أحد من الأهل، فما حكم ذلك؟","title":"رجل طلق زوجته مرتين ثم ظاهرها","answer":"الجواب: عليه التوبة إلى الله، وعليه كفارة الظهار، هذا مضى عليه طلقتان، وبقي عليه طلقة واحدة، فعليه أن يكفر كفارة الظهار، مثل ما أمر الله بذلك، وهي: عتق رقبة مؤمنة، فإن لم يستطع؛ صام شهرين متتابعين قبل أن يمسها، فإن لم يستطع؛  أطعم ستين مسكينًا، ستين فقيرًا، ثلاثين صاعًا، كل واحد له نصف صاع، تمر، أو رز من قوت البلد، رز، أو حنطة، أو شعير يعطيه الفقراء، ستين فقيرًا، ثلاثون صاعًا، كل واحد له نصف صاع قبل أن يمسها.","link":"https://binbaz.org.sa/fatwas/1891/رجل-طلق-زوجته-مرتين-ثم-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_674.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6304,"question":"بعض الأسر يأكل بعضهم مع البعض الآخر، مثال ذلك: أهل البيت الواحد، الإخوة كل منهم عنده زوجته، فيأكل بعضهم مع بعض، وإذا قيل لهم: هذا لا يجوز؛ يحتجون بأن الدين يُسر، وليس بعسر، وفصل الزوجات عن الإخوة هذا فيه عُسر، فنرجو بيان الحق بدليله؟","title":"ما حكم اختلاط الأقارب بدعوى أن الدين يُسْر؟","answer":"الجواب: هذا من تزيين الشيطان أيضًا كونهم يدعون أن الدين يُسر، ويبيحون المعاصي، هذا من البلاء، هو يُسر فيما يسَّر الله، لا في إباحة المعاصي، يُسرٌ إذا مرضت؛ تفطر في رمضان، إذا عجزت عن القيام؛ تصلي قاعدًا، إذا عجزت عن الماء؛ تصلي بالتيمم، هذا معنى اليُسر، ما هو معنى اليسر أنك إذا اشتقت إلى النساء تنظر إليهن، وتجلس معهن، وتخلو بهن، لا.  اليُسر في حفظ محارم الله، وترك ما حرم الله، وأداء ما أوجب الله، هذا هو اليسر، وإذا عجز عن شيء؛ أبدله الله شيئًا آخر، أيسر عليه في شريعة الله تيسيرًا من ربنا  وأما أنه يبيح لك المعاصي، ويبيح لك التمتع بزوجة أخيك، بزوجة عمك، بزوجة جارك، هذا منكر، هذا كله من المفاسد، يفضي إلى الزنا، والفواحش، ولكن أكثر الناس لا يشعرون، ولا يعقلون. وليس للرجل أن تأكل معه زوجة أخيه، أو زوجة عمه، وهي ليست مَحْرمًا له، بل يجلس النساء، وحدهن، والرجال وحدهم.","link":"https://binbaz.org.sa/fatwas/1907/ما-حكم-اختلاط-الاقارب-بدعوى-ان-الدين-يسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_690.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":6307,"question":"وآخر يسأل فيقول: لي عيال يشتغلون في القرصان، وهم مشاركون، ويجعلون في الكرتونة خمسة وثلاثين قرصًا، فإذا جاء المشتري قالوا: إن فيها خمسين، وهكذا كل أصحاب القرصان، فما رأي سماحتكم في ذلك؟","title":"حكم الغش في البيع","answer":"الجواب: هذا من الغش، والخيانة، والكذب، الذي حط في الكرتون خمس وثلاثين، ويقول للمشتري: فيه خمسون، أو فيه أربعون، هذا حرام، ومنكر، ويجب عليه أن يتوب إلى الله، وأن يتصدق بما يقابل ذلك، مما أخذ من أموال الناس؛ لأن هذا غش، والواجب أنه يقول: ما في الكرتون سواء، إذا كان في الكرتون عشرة يقول: عشرة، وإذا أربعين يقول: أربعين، لا يزيد، هذا هو الواجب عليه.  فإذا زاد؛ فقد كذب، وأخطأ، وغش المسلمين؛ فعليه التوبة إلى الله، وعليه رد الزيادة إلى صاحبها إن كان يعرفه، وإن كان ما يعرفه؛ يتصدق بالزيادة التي أخذها بغير حق، وفق الله الجميع، وصلى الله وسلم على نبينا محمد، وعلى آله، وأصحابه.","link":"https://binbaz.org.sa/fatwas/1882/حكم-الغش-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_667.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6313,"question":"أحد الإخوة يقول: مسجد بني بالإحساء كلف خمسة وثلاثون مليون ريال، مزين بذهب قيمته ثلاثة ملايين ريال، ما حكم هذا في الإسلام؟ وما هو الموقف الرسمي من هذا العمل؟","title":"حكم المغالاة في بناء المساجد","answer":"الجواب:  سمعتم السؤال هذا يقول: مسجد في الإحساء بني بخمسة وثلاثين مليون، وفيه مقدار ثلاثة ملايين من الذهب، إن صح قول السائل هذا خطأ، ولا شك أنه لا يجوز الإسراف في بناء المساجد، ولا الزخارف التي تضيع الأموال، وتؤذي المصلين، كيف يجعل الذهب؟! لماذا يجعل الذهب؟! بالذهب يبني مساجد أخرى، هذا من الأغلاط إن صح هذا الخبر، وسنبحث في الحقيقة، هذا منكر، ولا يجوز السكوت عليه. ولا شك أن هذا منكر، والناس في حاجة إلى المساجد في حارات كثيرة، يحتاجون إليها كنا، وغيرنا نتعب، ما حصلنا من يبني المساجد؟ متى نحصل الثري الغني الذي يقوم ببناء مسجد؟ فكيف تصرف الأموال هكذا؟! ما يجوز مطلقًا، بل يجب الاقتصاد في بناء المساجد، وأن يعتنى بقوتها، وسلامتها؛ حتى لا تضر المصلين، أما الزخارف فلا. وكان عمر  لما أمر ببناء مسجد النبي ﷺ قال: إياك أن تحمر، أو تصفر وأمره أن يبني بناء شديدًا سليمًا، لا يضر المسلمين، ولكن إذا بني بناء فيه إحكام، وفيه إتقان؛ لا بأس أن يكون فيه حجر، أو سيكون فيه جص، سيكون فيه أسمنت، لكن الزخرفة، والنقوش التي تؤذي المصلين، أو بذهب، أو فضة، أو أشياء من المعادن الأخرى التي لها قيمتها كل هذا لا يجوز، ولا وجه له، فإنما يبنى بالحجر، أو بالأسمنت، أو بالطين، بالخشب لا بأس، أما الزيادة على ذلك كنقوش تؤذي، فهذا أقل أحواله الكراهة. أما وجود الذهب’ والفضة فهذا لا وجه له، بل هو محرم، ومنكر، كل مال يصرف في هذا السبيل بغير وجهه؛ فهو من الإسراف، ومن إضاعة المال، والواجب أن ينزع، وأن يصرف في مساجد أخرى، وفي أعمال شرعية تنفع المسلمين، ولا شك إن كان هذا واقعًا أنه جهل من صاحبه، وغلط من صاحبه، نسأل الله له الهداية وسوف يوجه إن شاء الله إلى الخير.","link":"https://binbaz.org.sa/fatwas/1884/حكم-المغالاة-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_668.mp3","categories":["المساجد ومواضع السجود","الأخلاق المذمومة"]},{"id":6317,"question":"رجل طلق زوجته دون براءة، طلقها ثاني مرة دون براءة، ثم أرجعها، ومن ثم حرمها مرة أخرى على نفسه مثل أمه، أو أخته، وهو رجل  مقطوع، عمره خمس وستون عامًا، وهو لاجئ، ليس له أحد من الأهل، فما حكم ذلك؟","title":"رجل طلق زوجته مرتين ثم ظاهرها","answer":"الجواب: عليه التوبة إلى الله، وعليه كفارة الظهار، هذا مضى عليه طلقتان، وبقي عليه طلقة واحدة، فعليه أن يكفر كفارة الظهار، مثل ما أمر الله بذلك، وهي: عتق رقبة مؤمنة، فإن لم يستطع؛ صام شهرين متتابعين قبل أن يمسها، فإن لم يستطع؛  أطعم ستين مسكينًا، ستين فقيرًا، ثلاثين صاعًا، كل واحد له نصف صاع، تمر، أو رز من قوت البلد، رز، أو حنطة، أو شعير يعطيه الفقراء، ستين فقيرًا، ثلاثون صاعًا، كل واحد له نصف صاع قبل أن يمسها.","link":"https://binbaz.org.sa/fatwas/1891/رجل-طلق-زوجته-مرتين-ثم-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_674.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6318,"question":"بعض الأسر يأكل بعضهم مع البعض الآخر، مثال ذلك: أهل البيت الواحد، الإخوة كل منهم عنده زوجته، فيأكل بعضهم مع بعض، وإذا قيل لهم: هذا لا يجوز؛ يحتجون بأن الدين يُسر، وليس بعسر، وفصل الزوجات عن الإخوة هذا فيه عُسر، فنرجو بيان الحق بدليله؟","title":"ما حكم اختلاط الأقارب بدعوى أن الدين يُسْر؟","answer":"الجواب: هذا من تزيين الشيطان أيضًا كونهم يدعون أن الدين يُسر، ويبيحون المعاصي، هذا من البلاء، هو يُسر فيما يسَّر الله، لا في إباحة المعاصي، يُسرٌ إذا مرضت؛ تفطر في رمضان، إذا عجزت عن القيام؛ تصلي قاعدًا، إذا عجزت عن الماء؛ تصلي بالتيمم، هذا معنى اليُسر، ما هو معنى اليسر أنك إذا اشتقت إلى النساء تنظر إليهن، وتجلس معهن، وتخلو بهن، لا.  اليُسر في حفظ محارم الله، وترك ما حرم الله، وأداء ما أوجب الله، هذا هو اليسر، وإذا عجز عن شيء؛ أبدله الله شيئًا آخر، أيسر عليه في شريعة الله تيسيرًا من ربنا  وأما أنه يبيح لك المعاصي، ويبيح لك التمتع بزوجة أخيك، بزوجة عمك، بزوجة جارك، هذا منكر، هذا كله من المفاسد، يفضي إلى الزنا، والفواحش، ولكن أكثر الناس لا يشعرون، ولا يعقلون. وليس للرجل أن تأكل معه زوجة أخيه، أو زوجة عمه، وهي ليست مَحْرمًا له، بل يجلس النساء، وحدهن، والرجال وحدهم.","link":"https://binbaz.org.sa/fatwas/1907/ما-حكم-اختلاط-الاقارب-بدعوى-ان-الدين-يسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_690.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":6322,"question":"كثير من المبتعثين خارج المملكة لهم أموال في بنوك الكفار، وعند استلامهم لهذه الأموال، يسلمون معها أرباحًا ربوية، فهل تعطى للمسلمين، أم تترك للكفار؟","title":"حكم أخذ الأرباح التي تعطيها البنوك الربوية في بلاد الكفر","answer":"الجواب: هذا فيه خلاف بين علماء الإسلام، يعني كون المسلم يقبض مع أمواله أرباحًا من البنوك، يعطى إياها؛ لأن البنوك اعتادت أنها تعطي أرباحًا على الأموال التي عندها في بنوكها، فهل للمسلم أن يأخذ هذه الأرباح، وينفقها في وجوه البر، وأعمال الخير، أم يتركها لهم، ويأخذ رأس ماله؟ هذا محل نزاع بين أهل العلم، هل يجوز، أم لا يجوز؟  لكن هنا أمر لا بدّ من الانتباه له، وهو أنه لا يجوز للمسلم أن يتفق على الربا، ما يجوز أن يتفق مع البنك، يقول: أنا أعطيك هذا المال على أن  لي 5% أو 10% ربحًا، ما يجوز هذا، فهو من الربا، لكن لو أعطاه المال، وجعل عنده المال من غير مشارطة، من غير شيء بينه وبينه، ولكن معلوم أن هذا عند البنوك معروف عندهم، فإذا ... المال وأعطوه الربح المعتاد، فهل يقبضه، أم لا؟ المشروع عند العلماء: أنه لا يقبضه إذا كان معروفًا؛ لأن الشرط العرفي كالنطقي، كأنه شارطهم على ذلك، وقال بعض أهل العلم: لا بأس أن يؤخذ، لكن لا يدخل في ماله، بل يجعل في جهات أخرى: من صدقة على الفقراء، من إصلاح الطرق، من إصلاح دورات المياه، من أشباهه، مما ينفع المسلمين، ولا يكون في ماله، ولا يأخذه، ولا ينتفع به، هذا قول جماعة من أهل العلم، وهو قول قوي، لكنه يخشى على الإنسان أن تطاوعه نفسه، يخشى عليه أنه إذا أخذه أن يأكله، ويخشى عليه .. في ذلك فالحيطة له أن لا يأخذه، فإن أخذه؛ فليجعله عند غيره من الأمناء، والأخيار؛ حتى يصرف في جهة بر، وفي جهة تنفع المسلمين، وهو يسلم من شره،، ولا يستعين به في شيء من  أموره الخاصة.","link":"https://binbaz.org.sa/fatwas/1880/حكم-اخذ-الارباح-التي-تعطيها-البنوك-الربوية-في-بلاد-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_666.mp3","categories":["الربا والصرف","الأخلاق المذمومة"]},{"id":6328,"question":"وآخر يسأل فيقول: لي عيال يشتغلون في القرصان، وهم مشاركون، ويجعلون في الكرتونة خمسة وثلاثين قرصًا، فإذا جاء المشتري قالوا: إن فيها خمسين، وهكذا كل أصحاب القرصان، فما رأي سماحتكم في ذلك؟","title":"حكم الغش في البيع","answer":"الجواب: هذا من الغش، والخيانة، والكذب، الذي حط في الكرتون خمس وثلاثين، ويقول للمشتري: فيه خمسون، أو فيه أربعون، هذا حرام، ومنكر، ويجب عليه أن يتوب إلى الله، وأن يتصدق بما يقابل ذلك، مما أخذ من أموال الناس؛ لأن هذا غش، والواجب أنه يقول: ما في الكرتون سواء، إذا كان في الكرتون عشرة يقول: عشرة، وإذا أربعين يقول: أربعين، لا يزيد، هذا هو الواجب عليه.  فإذا زاد؛ فقد كذب، وأخطأ، وغش المسلمين؛ فعليه التوبة إلى الله، وعليه رد الزيادة إلى صاحبها إن كان يعرفه، وإن كان ما يعرفه؛ يتصدق بالزيادة التي أخذها بغير حق، وفق الله الجميع، وصلى الله وسلم على نبينا محمد، وعلى آله، وأصحابه.","link":"https://binbaz.org.sa/fatwas/1882/حكم-الغش-في-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_667.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6356,"question":"لي مال في بنك ما، هل يجوز لي أن أتفق مع البنك، أن أجعل هذا المال مضاربة بيني  وبينه؛ ليكون لي نصف الربح، وله نصفه، ولو خسر أيضاً فالخسارة مناصفة، فماذا يكون الحل، والحرفة في ذلك؟","title":"ضوابط المضاربة بين العامل وصاحب المال","answer":"الجواب: المضاربة ما على العامل خسارة، المضاربة العامل شريك في الربح، والخسارة على رب المال؛ لأنه أمانة في يد العامل، إذا كان العامل ما فرط، ولا قصر؛ فالخسارة على رب المال، والربح مشترك بالنصف، أو بالربع، أو بالثلث إذا كان في سلعة معلومة، إذا كان في البنك سلع معلومة يحطها في سيارات خاصة، يحطها في بيوت، في مزارع، بالنصف، بالثلث، بالربع. هذه مضاربة عليه أن يتقي الله فيها، وأن يعتني بها، وأن لا يقصر فيها، وأن يحفظها، فإذا جاء ربح؛ فهو بينهما على الشرط، وإن ما جاء ربح؛ فالخسارة على صاحب المال، هذا إذا كان متحدًا، ولكن أهل البنوك، وأهل الربا لا يؤمنون، قد يخلطونها بغيرها، فينبغي له أن يكون هذا مع غير المرابي، مع غير البنوك المرابية، مع أشخاص سليمين؛ حتى يأمن على ماله أنه لم يعن به من يرابي.  السؤال: طيب لو هو اتفق مع البنك على الخسارة؟ الجواب: لا يصح شرط يخالف.","link":"https://binbaz.org.sa/fatwas/1935/ضوابط-المضاربة-بين-العامل-وصاحب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_720.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6375,"question":"لي ولد عم، وعنده سبعة أولاد، وحالته المادية ضعيفة، وأنا أستطيع مساعدته، ولي زوجة كلما علمت أني أرسلت له شيئًا من المال؛ تغضب علي غضبًا شديدًا، وتترك الطعام، والصلاة لمدة خمس أعوام على هذه الحال، فما رأي سماحتكم؟","title":"نصيحة لزوجة لا تعين زوجها على بر أقاربه","answer":"الجواب: هذه زوجة ظالمة -نسأل الله العافية- هذه لا يطيعها، ويتصدق على ابن عمه، ويحسن إليه، يمكن عنده بنات يتزوج، تخشى أن يتزوج منهن، لعل عنده بنات تخشى أن يتزوج منهن، هذا ظنها السيئ. فالمقصود: أنه يعتني بالأمر، ويتصدق عليه، ويحسن إليه من غير أن يعلمها، لا يخبرها، بالطرق الأخرى؛ حتى يجمع بين المصلحتين، يمكن أن يتصدق من طريق آخر، من طريق خفية، ولا يعلمها بشيء، وينصحها لله، ويخوفها من الله، وإذا كانت لا تصلي؛ يلزمه فراقها، لا خير فيها، ومع هذا تعينه على قطع الرحم، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1960/نصيحة-لزوجة-لا-تعين-زوجها-على-بر-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_747.mp3","categories":["الحقوق الزوجية","الأخلاق المذمومة"]},{"id":6376,"question":"إذا كان النذر للتقرب في طاعة؟","title":"حكم نذر الطاعة","answer":"الجواب: إذا نذر لطاعة يلزمه الوفاء، مثل ما قال النبي ﷺ: من نذر أن يطيع الله؛ فليطعه رواه البخاري في الصحيح، فإذا قال نذر لله علي أن أتصدق بمائة ريال على فلان، أو ألف ريال على فلان، وهو يستطيع؛ يلزمه، أو قال: لله عليه أن يصوم يوم الخميس، أو يصوم يوم الإثنين، أو يصلي ركعتين من الضحى؛ يلزمه. السؤال: طيب كبر في السن ولا يقدر أن يصوم السنتين؟ الجواب:  إذا عجز يصوم .... السنتين مكروهة ، النبي قال: لا صام من صام الأبد، ولما أراد عبدالله بن عمرو أن يصوم السنة؛ نهاه، قال: صوم يومًا، وأفطر يومًا وقال: أطيق أفضل من ذلك، قال: لا أفضل من ذلك ونهاه عن صوم السنة، فصوم السنة مكروهة، لا ينبغي، ولو نذره يكفر كفارة يمين، ويكفي.","link":"https://binbaz.org.sa/fatwas/1950/حكم-نذر-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_737.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6377,"question":"ما هو النمص؟ وما حكمه؟ وأين يتم في جسم الإنسان؟ وهل يشمل الرجال، والنساء؟","title":"حكم النمص","answer":"الجواب: النمص هو أخذ شعر الحاجبين، وألحق به بعض أهل العلم شعر الوجه المعتاد، فلا يجوز نمصه، النبي ﷺ لعن النامصة، والمتنمصة، قال أهل العلم: النمص أخذ شعر الحاجبين بالمنماص، وهو المنقاش، تزين شعر حاجبيها بالمناقيش حتى تأخذ بعض الشعرات، فإذا كان بالمنقاش يحرم، فكيف بأكثر من المنقاش؟!  السؤال: كذلك شعر اليدين، والرجلين؟ الجواب: اليدين، والرجلين ما ورد فيها شيء، ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1955/حكم-النمص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_742.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6381,"question":"أحد الإخوة يقول: نذرت أنني إذا فعلت العادة السرية، أي: الاستمناء باليد أن أصوم سنتين متتابعتين، وذلك لكي أمنع نفسي من هذه العادة، ولكني فعلتها، ولا أستطيع الصيام، فما هو الحل؟","title":"كفارة النذر المكروه","answer":"الجواب: هذا النذر مكروه لا ينبغي، ولأنه نذر ليس للتقرب، إنما هو لمنع نفسه من هذه العادة، مثل الذي يقول: إن كلمت فلانًا؛ صمت سنين، أو إن زرته؛ سأصوم سنتين، هذا معناه حث نفسه على ترك هذا الشيء، ومنع نفسه من هذا الشيء، فهذا حكمه حكم اليمين، وليس عليه صيام، يطعم عشرة مساكين، أو يكسوهم، ويكفي، وليس عليه هذا الصيام؛ لأن هذا ليس مقصوده التقرب، مقصوده أن يمنع نفسه من هذا الشيء. والعادة السرية يجب عليه الحذر منها مطلقًا، ولو ما نذر، هذا النذر يجب عليه أن يحذرها، ويجب أن لا يمد بصره إلى النساء، يغض بصره عن النساء، وعن المردان، وعنده الحذر أن يخاف من الله، والمراقبة، ويكثر من الصوم، وأن يتصل بأهله إذا كان له زوجة، أو يتزوج، وبهذا يزول الشر إن كان مع العلاج، كل داء له دواء، ما أنزل الله داء إلا أنزل له دواء.","link":"https://binbaz.org.sa/fatwas/1948/كفارة-النذر-المكروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_735.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6385,"question":"لي ولد عم، وعنده سبعة أولاد، وحالته المادية ضعيفة، وأنا أستطيع مساعدته، ولي زوجة كلما علمت أني أرسلت له شيئًا من المال؛ تغضب علي غضبًا شديدًا، وتترك الطعام، والصلاة لمدة خمس أعوام على هذه الحال، فما رأي سماحتكم؟","title":"نصيحة لزوجة لا تعين زوجها على بر أقاربه","answer":"الجواب: هذه زوجة ظالمة -نسأل الله العافية- هذه لا يطيعها، ويتصدق على ابن عمه، ويحسن إليه، يمكن عنده بنات يتزوج، تخشى أن يتزوج منهن، لعل عنده بنات تخشى أن يتزوج منهن، هذا ظنها السيئ. فالمقصود: أنه يعتني بالأمر، ويتصدق عليه، ويحسن إليه من غير أن يعلمها، لا يخبرها، بالطرق الأخرى؛ حتى يجمع بين المصلحتين، يمكن أن يتصدق من طريق آخر، من طريق خفية، ولا يعلمها بشيء، وينصحها لله، ويخوفها من الله، وإذا كانت لا تصلي؛ يلزمه فراقها، لا خير فيها، ومع هذا تعينه على قطع الرحم، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1960/نصيحة-لزوجة-لا-تعين-زوجها-على-بر-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_747.mp3","categories":["الحقوق الزوجية","الأخلاق المذمومة"]},{"id":6386,"question":"إذا كان النذر للتقرب في طاعة؟","title":"حكم نذر الطاعة","answer":"الجواب: إذا نذر لطاعة يلزمه الوفاء، مثل ما قال النبي ﷺ: من نذر أن يطيع الله؛ فليطعه رواه البخاري في الصحيح، فإذا قال نذر لله علي أن أتصدق بمائة ريال على فلان، أو ألف ريال على فلان، وهو يستطيع؛ يلزمه، أو قال: لله عليه أن يصوم يوم الخميس، أو يصوم يوم الإثنين، أو يصلي ركعتين من الضحى؛ يلزمه. السؤال: طيب كبر في السن ولا يقدر أن يصوم السنتين؟ الجواب:  إذا عجز يصوم .... السنتين مكروهة ، النبي قال: لا صام من صام الأبد، ولما أراد عبدالله بن عمرو أن يصوم السنة؛ نهاه، قال: صوم يومًا، وأفطر يومًا وقال: أطيق أفضل من ذلك، قال: لا أفضل من ذلك ونهاه عن صوم السنة، فصوم السنة مكروهة، لا ينبغي، ولو نذره يكفر كفارة يمين، ويكفي.","link":"https://binbaz.org.sa/fatwas/1950/حكم-نذر-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_737.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6387,"question":"ما هو النمص؟ وما حكمه؟ وأين يتم في جسم الإنسان؟ وهل يشمل الرجال، والنساء؟","title":"حكم النمص","answer":"الجواب: النمص هو أخذ شعر الحاجبين، وألحق به بعض أهل العلم شعر الوجه المعتاد، فلا يجوز نمصه، النبي ﷺ لعن النامصة، والمتنمصة، قال أهل العلم: النمص أخذ شعر الحاجبين بالمنماص، وهو المنقاش، تزين شعر حاجبيها بالمناقيش حتى تأخذ بعض الشعرات، فإذا كان بالمنقاش يحرم، فكيف بأكثر من المنقاش؟!  السؤال: كذلك شعر اليدين، والرجلين؟ الجواب: اليدين، والرجلين ما ورد فيها شيء، ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1955/حكم-النمص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_742.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6388,"question":"يتردد كثيرًا على ألسنة بعض الدعاة، والشعراء، وغيرهم قولهم: لعمري، وقولهم لعمرك كذا وكذا، فهل يعد ذلك قسمًا، وحلفًا بالعمر، أم لا؟ وما معناه؟","title":"حكم قول أحدهم لعمري","answer":"الجواب: الصواب أنه لا حرج فيه، وقد وقع في بعض الأحاديث الصحيحة عن النبي ﷺ أنه قال: لعمري وقد صح عن ابن عباس وعن جماعة من السلف، والخلف، فليس بيمين بغير الله، ليس من الحلف بغير الله، أو أن هذا مما يتسامح فيه، ويقصد به التأكيد لعمرك كذا، وكذا لعمري كذا وكذا، يؤتى لتأكيد الكلام، وتقويته، وليس من مقام القصد بالحلف.","link":"https://binbaz.org.sa/fatwas/1972/حكم-قول-احدهم-لعمري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_759.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6393,"question":"عندي أولاد، وبنات، وزوجتين، وعندي بنت عندها بعض المرض، هل يحق لي أن أعطيها بعض المال، وهل يجوز ذلك، أرجو إفادتي جزاكم الله خيرًا؟","title":"حكم هبة المال لأحد الأبناء لمرضه","answer":"الجواب: البنت المريضة تعالجها، وتنفق عليها ما دامت فقيرة، ومحتاجة، ولكن لا تخصها بشيء دون أخواتها، إذا كان لها أخوات، وإخوة لا تخصها بشيء، لا بيت، ولا مال يحفظ لها خاصة، الله يقوم برزق الجميع .  ولكن الفقير يعطى الفقير، ينفق عليه، والمريض يعالج، وليس في هذا محاباة، المحاباة أن تعطيه شيئًا سوى ذلك، وتفاضل بينهم، أو تخص بعضهم دون بعض، قال النبي ﷺ: اتقوا الله واعدلوا بين أولادكم أما علاج المريض، والإنفاق على الفقير؛ فهذا ليس بمحاباة، فالغني قد استغنى بما أعطاه الله من المال.","link":"https://binbaz.org.sa/fatwas/1963/حكم-هبة-المال-لاحد-الابناء-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_750.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":6399,"question":"أنا قلت لزوجتي في حال غضب مني عليها: والله إذا ذهبت إلى أهلك لمدة ستة أشهر؛ فأنت طالق بالثلاثة، هل يجب الطلاق، أم يجب عليّ كفارة اليمين؟","title":"حكم طلاق الثلاث بلفظ واحد","answer":"الجواب: ينبغي للعاقل أن لا يعجل في الطلاق، ينبغي للعاقل أن يعالج الأمور بغير الطلاق، يعالج الأمور بالوعد، والوعيد، والتهديد، والتحذير بغير الطلاق،، يعدها بكذا من الكرامات، إذا استقامت؛ يتوعدها بشيء من الإهانة، وعدم إعطائها بعض المطالب، ويدع الطلاق بعيدًا، لكن هذا الذي يتوعدها بالطلاق له حالان: إحداهما: أن يقصد تنفيذ ما أراد، وأنه متى أخلت بما قالت؛ فإن الطلاق يقع بها، فهذا له ما نوى، ويقع عليها الطلاق، فإذا قال: إن مكثت عند أهلك ستة أشهر، أو يومًا، أو يومين، أو كذا، أو كذا؛ فأنت طالق، وهو يقصد طلاقها؛ وقع الطلاق، أو قال: إن كلمت فلانًا؛ فأنت طالق، وهو يقصد الطلاق؛ وقع الطلاق، أو قال: إذا خرجت إلى بيت فلا؛ن فأنت طالق، أو علي الطلاق إذا خرجت من بيتي -وهو يقصد ذلك- وقع الطلاق، يقول المصطفى -عليه الصلاة والسلام-: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. أما الذي يقصد تهديدها، وتحذيرها، ولا يقصد فراقها، لكن يقصد تخويفها، وتحذيرها، كأن يقول: إن كلمت فلانًا؛ فأنت طالق، أو إن زرت فلانة؛ فأنت طالق، أو ذهبت إلى أهلك بغير إذني؛ فأنت طالق، يقصد تخويفها، وتحذيرها، ولم يقصد فراقها، والله يعلم ما في قلبه، وإنما أراد التحذير، فهذا حكمه حكم اليمين، وعليه كفارة ظهار إذا أخلت بالمطلوب، إذا خالفته عليه كفارة يمين، مثل قوله: والله لا تذهبين، والله ما تفعلي كذا، وكذا حكمه حكم اليمين في أصح قولي العلماء، كما أفتى بهذا جمع من أهل العلم، من السلف في عهد الصحابة، وفي عهد التابعين وأفتى بهذا أيضًا أبو العباس ابن تيمية شيخ الإسلام -رحمة الله عليه- والعلامة ابن القيم، وجمع من أهل العلم من القدماء، وغيرهم؛ لأن هذا يقع من الناس كثيرًا بالتخويف، والتحذير لا لأجل إيقاع الطلاق. أما إذا علق الطلاق على شيء ما فيه تخويف، من طبيعته أنه ليس فيه تخويف، يعني إذا دخل رمضان فأنت طالق، إذا ولدت فأنتِ طالق، إذا حملت فأنت طالق، يقع الطلاق بهذا، وما أشبه ذلك. السؤال: إذا قال لزوجته: أنتِ طالق بالثلاث الجواب: إذا قال: أنت طالق بالثلاث؛ تكون واحدة على الصحيح، إذا قال: أنت طالق بالثلاث، بهذا اللفظ، أما إذا قال: أنت طالق، ثم طالق، ثم طالق، تقع الثلاث، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1970/حكم-طلاق-الثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_757.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6415,"question":"جاءنا من أحد الإخوة ملخصه: أهديت لابني الأكبر قطعة أرض مبانٍ، على شرط شفوي على أن خيرها لجميع الأسرة، وكتبت له بذلك، ولكنه عمّر عليها، واستغلها، ولم يعط لأحد منا شيئًا منها، وامتنع، وطلبته بتنفيذ شرع الله، وأن يستغلها طول عمري، ثم تكون ميراثًا لكل حقه، ولكنه هددني، وشتمني، وتطاول عليّ، وسب الدين، ومزق كتاب منهاج المسلم، وطرحه، فهل عليّ وزر فيما حدث؟","title":"وجوب المساواة بين الأبناء في العطية والهدية","answer":"الجواب: عليك أن ترفع أمره إلى المحكمة، وأن توضح للمحكمة بما جرى، والمحكمة فيها الخير -إن شاء الله- والبركة، هذه مسائل خصومة بينك، وبين ولدك، وهذه من عقوبات التخصيص، هذه من عقوباتك لما تخصصه بشيء، الولد ما يخصص بشيء دون .. اتقوا الله، واعدلوا بين أولادكم فلما وقع منك هذا الشيء، والتساهل؛ صار هذا من نوع العقوبات.  فالواجب عليك أن تخاصمه، وأن ترفع أمره إلى ولاة الأمور؛ حتى يخلصوك مما حصل من العقوق، والجحد للحق، وإنكاره، وحتى تعدل بين أولادك.","link":"https://binbaz.org.sa/fatwas/2134/وجوب-المساواة-بين-الابناء-في-العطية-والهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_783.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":6424,"question":"قال في سبل السلام: لو ظاهر الرجل يريد طلاقًا؛ كان ظهارًا، ولو طلق يريد ظهارًا؛ كان طلاقًا، فهل هذا صحيح؟ وكيف يجمع بينه، وبين إنما الأعمال بالنيات؟","title":"حكم اعتبار الظهار طلاقاً","answer":"الجواب: الله جعل الظهار ظهارًا؛ لأن الجاهلية تجعله طلاقًا، فالله حكم بأن الظهار ظهار تحريم، وبين فيه الكفارة  في كتابه الكريم، فلا يجعل الطلاق، فإذا قال: أنت علي كظهر أمي، أو كظهر أختي، أو بنتي؛ فإنه ظهار، ولو نواه طلاقًا، بل هو ظهار كما شرع الله ضد أعمال الجاهلية، قد أبطل الله أعمال الجاهلية؛ فيكون له حكم الظهار، وعليه الكفارة، وهي: عتق رقبة، فإن عجز؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا قبل أن يمسها. أما إذا قال: أنت طالق، ونوى الظهار، ما يصير ظهارًا؛ لأن هذا ما يرد على الظهار، أنت طالق لفظه صريح الطلاق، فلا ينتقل عن صريح الطلاق إلى معنى آخر.","link":"https://binbaz.org.sa/fatwas/2128/حكم-اعتبار-الظهار-طلاقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_776.mp3","categories":["الطلاق","الظهار","الأخلاق المذمومة"]},{"id":6431,"question":"إذا كان الاحتكار في أوقات ليس الناس بحاجة إلى المحتكر، ولكن البائع يتوقع ارتفاع الأسعار، فهل هذا جائز؟","title":"حكم من احتكر سلعة ليس في احتكارها مشقة على الناس","answer":"الجواب: النبي ﷺ قال: لا يحتكر إلا خاطئ ومن احتكر؛ فقد خطئ، فهذا الاحتكار محرم، ولكن بين العلماء محل الاحتكار، وأنه في الأوقات التي فيها مشقة على الناس، الطعام فيها غال مثلًا، فيشتريه ليبيعه بأغلى، هذا لا يجوز، هذا يضر بالناس.  أما في أوقات السعة، ووجود الخير الكثير، والأموال الواسعة، وإذا اشترى ما يؤثر على السوق، ولا يسبب زيادة على الناس، فإذا اشترى شيئًا، وادخره ليبيعه في وقت آخر؛ ليربح فيه؛ فهذا شأن التجارة، يشتري هذا، ويبيع هذا، ويدخر هذا، فإذا كان ما في مشقة؛ لا يسمى احتكارًا. كذلك إذا قبضه من المزارع، حبوبًا من المزارع، وأبقاه عنده إلى وقت يرجو أن يكون بيعها فيه أنفع له، وأغلى؛ لأن الوقت الآن كاسد، والطعام رخيص، فحفظ إنتاج مزرعته من الحبوب، والتمور إلى وقت آخر؛ لا يسمى احتكارًا.","link":"https://binbaz.org.sa/fatwas/2140/حكم-من-احتكر-سلعة-ليس-في-احتكارها-مشقة-على-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_789.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6433,"question":"هل وضع الرجل الذي من البادية سيارته في المعرض سمسرة ليبيعها صاحب المعرض له، هل هذا من بيع الحاضر للبادي، أم أنه من الوكالة؟ وكيف يكون بيع الحاضر للباد محرمًا إذا كان الناس الآن يأتون من البادية، ويضعون سياراتهم في المعارض، وهم مضطرون لذلك؟","title":"حكم وضع صاحب البادية سيارته في المعرض لغرض البيع","answer":"الجواب: ثبت عنه -عليه الصلاة والسلام- أنه نهى أن يبيع حاضر لباد، وهذا ثابت في الصحيحين، وفي غير الصحيحين، في أحاديث كثيرة نهى عن بيع الحاضر للبادي، والحاضر هو الذي يتولى بيع سلعته، والبادي هو الذي يتولى بيع سلعته، ولا يتولاه الحاضر؛ لأن الحاضر قد عرف السلع، وعرف قيمها؛ فيكون بيعه عن البادي فيه مشقة على الناس، والرسول ﷺ يقول: دعوا الناس يرزق الله بعضهم ببعض.  فالذي يجلبه البادي من السلع من الإبل، والبقر، أو الدهن، أو الأقط، أو غير ذلك يترك هو الذي يتولى البيع؛ حتى لا يشدد على الناس، وحتى يتسع الخير للناس، إذا باعه لا يشدد، أما إذا باع حافظ له، ودلال له؛ فقد يشدد، وقد لا يبيع إلا بأغلى الأثمان؛ فيكون في توليه لذلك مشقة على الناس. وهل يدخل حكم السيارة في ذلك؟ هذا محل نظر، هل تدخل فيما ذكره النبي ﷺ أما لا؟ محل نظر، والأقرب -والله أعلم- دخولها إذا جاء أهل البوادي من مكان بعيد، ومعهم سياراتهم، وجلبوها في الأسواق عند المعارض، ووكلوا صاحب المعرض أن يبيعها، هل تدخل في هذا، أو ما تدخل؟ محل نظر.  والأقرب -والله أعلم- دخولها للعموم، وقد يقال: لا تدخل؛ لأنهم عرفوا السلع، وعرفوا الأثمان، ولا بقي فيها إشكال، فهم يبيعون برضاهم، وبمشاورتهم أشياء يعرفونها، وليست مجهولة لهم، بخلاف البوادي أولًا في بعض الأمور التي يجلبونها، لا يعرفون قيمها، أما الأسواق فقد تقاربت الآن، والناس قد عرفوا السلع، والبادية صارت كالحاضرة في معرفة -الآن- السلع، ومعرفة قيم السيارات، اشتروهاـ واستعملوها، وعرفوا قيمها، فقد يقال في هذه الحال: إن العلة التي قالها النبي ﷺ منتفية الآن؛ لأن البادي لو تولى ما يبيع إلا بالأسعار التي يعرفها الناس، ويعرفها الحاضرة؛ فلا يكون في هذا خطر على الناس، قد يقال هذا وهو قريب، وقوي.","link":"https://binbaz.org.sa/fatwas/2141/حكم-وضع-صاحب-البادية-سيارته-في-المعرض-لغرض-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_790.mp3","categories":["الأخلاق المذمومة","البيوع"]},{"id":6442,"question":"فضيلة الشيخ يسأل رجل طلق زوجته ثلاثًا بلفظ واحد، وكتب بذلك ورقة، وأرسلت إلى الزوجة، وأشهد على ذلك، وبعد وقت قصير تأسف، واسترجع زوجته، فهل تحل له، أم ماذا؟ مع العلم أن الزوجة لها ثلاثة أولاد، وأن الطلاق في حالة غضب، أفتونا جزاكم الله خير الجزاء؟","title":"حكم الطلاق ثلاثاً بلفظ واحد","answer":"الجواب: طلاق الثلاث إن كانت بواحدة كأن يقول: فلانة طالقة بالثلاث، أو مطلقة بالثلاث، أو علي الطلاق بالثلاث فيها خلاف بين أهل العلم، أكثر أهل العلم من عهد عمر  وما بعده، أكثرهم يقولون: إنها تمضي، وتنفذ، ولا تحل له إلا بعد زوج، وهكذا قال أكثر أهل العلم.  وذهب بعض أهل العلم، وهو قول أهل العلم في عهد الصديق  وفي أول خلافة عمر، وهو الذي عليه الحال في عهد النبي ﷺ أن الثلاثة باللفظ الواحد تعتبر واحدة، طلقة واحدة رجعية، وهذا هو الذي أفتي به أنها تكون واحدة رجعية، وأفتى به جماعة من أهل العلم من عهد ابن عباس، ومن بعده، وثبت عن ابن عباس في رواية عنه  أنه أفتى بها أيضًا، وأفتى بقول الجمهور، وثبت عن جماعة من أصحابه، أفتوا بأنها واحدة، وأفتى بذلك أبو العباس ابن تيمية شيخ الإسلام -رحمه الله- وتلميذه العلامة ابن القيم رحمه الله، هذا القول أرجح من حيث الدليل أنها واحدة إلا إذا حكم الحاكم بإمضائها، فحكم الحاكم يرفع الخلاف. إذا كان الزوج قد اتصل بالمحكمة، وحكمت المحكمة بأن هذا الطلاق ماض، وأنها بانت، فالحكم يرفع الخلاف، وتكون بائنة إلا إذا رجع الحاكم عن حكمه، ورأى أن يجعلها واحدة، وأذن لغيره في ذلك؛ فلا بأس. المقصود: الصحيح أنها واحدة، لكن إذا حكم أحد الحكام الشرعيين بإمضائها عملًا بقول الجمهور، وأنها لا تحل إلا بعد زوج، فهذا قول له وجهه، وقد ذكر العلماء أن حكم الحاكم يرفع الخلاف، وله نقضه إذا رأى أن الأدلة الشرعية تقتضي ذلك، أو أن لغيره من الحكام، أو المفتيين بنقضه إذا رأى ... فلا بأس، هذا هو الجواب عن هذه المسألة.  والغضب فيه تفصيل، الغضب أنواع ثلاثة: غضب عادي لا يمنع الطلاق، وغضب شديد يغير على الإنسان حاله، وقصده، ولا يتمكن معه من الطلاق الشرعي، بل يعمى عليه قصده، ويعمى عليه طريقه بسبب طول النزاع، وشدة النزاع، والمضاربة بينهما، أو السباب، والمشاتمة بينهما، فهذا إذا اشتد الغضب، لا يقع معه الطلاق على الصحيح أيضًا. والحال الثالث: أن يوقعه الغضب في عدم الشعور، وأن يكون كسائر المجانين، والمعتوهين، قد ألجأه وأوقعه الغضب في زوال العقل، فلا يعقل ما يقول، وهذا لا يقع طلاقه عند جميع أهل العلم، ويلحق في هذه الحالة بالمعتوهين، والمجانين، فلا يقع طلاقه إذا كان غضبه قد أوقعه في هذه الحالة.","link":"https://binbaz.org.sa/fatwas/2195/حكم-الطلاق-ثلاثا-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_820.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6463,"question":"فضيلة الشيخ يسأل رجل طلق زوجته ثلاثًا بلفظ واحد، وكتب بذلك ورقة، وأرسلت إلى الزوجة، وأشهد على ذلك، وبعد وقت قصير تأسف، واسترجع زوجته، فهل تحل له، أم ماذا؟ مع العلم أن الزوجة لها ثلاثة أولاد، وأن الطلاق في حالة غضب، أفتونا جزاكم الله خير الجزاء؟","title":"حكم الطلاق ثلاثاً بلفظ واحد","answer":"الجواب: طلاق الثلاث إن كانت بواحدة كأن يقول: فلانة طالقة بالثلاث، أو مطلقة بالثلاث، أو علي الطلاق بالثلاث فيها خلاف بين أهل العلم، أكثر أهل العلم من عهد عمر  وما بعده، أكثرهم يقولون: إنها تمضي، وتنفذ، ولا تحل له إلا بعد زوج، وهكذا قال أكثر أهل العلم.  وذهب بعض أهل العلم، وهو قول أهل العلم في عهد الصديق  وفي أول خلافة عمر، وهو الذي عليه الحال في عهد النبي ﷺ أن الثلاثة باللفظ الواحد تعتبر واحدة، طلقة واحدة رجعية، وهذا هو الذي أفتي به أنها تكون واحدة رجعية، وأفتى به جماعة من أهل العلم من عهد ابن عباس، ومن بعده، وثبت عن ابن عباس في رواية عنه  أنه أفتى بها أيضًا، وأفتى بقول الجمهور، وثبت عن جماعة من أصحابه، أفتوا بأنها واحدة، وأفتى بذلك أبو العباس ابن تيمية شيخ الإسلام -رحمه الله- وتلميذه العلامة ابن القيم رحمه الله، هذا القول أرجح من حيث الدليل أنها واحدة إلا إذا حكم الحاكم بإمضائها، فحكم الحاكم يرفع الخلاف. إذا كان الزوج قد اتصل بالمحكمة، وحكمت المحكمة بأن هذا الطلاق ماض، وأنها بانت، فالحكم يرفع الخلاف، وتكون بائنة إلا إذا رجع الحاكم عن حكمه، ورأى أن يجعلها واحدة، وأذن لغيره في ذلك؛ فلا بأس. المقصود: الصحيح أنها واحدة، لكن إذا حكم أحد الحكام الشرعيين بإمضائها عملًا بقول الجمهور، وأنها لا تحل إلا بعد زوج، فهذا قول له وجهه، وقد ذكر العلماء أن حكم الحاكم يرفع الخلاف، وله نقضه إذا رأى أن الأدلة الشرعية تقتضي ذلك، أو أن لغيره من الحكام، أو المفتيين بنقضه إذا رأى ... فلا بأس، هذا هو الجواب عن هذه المسألة.  والغضب فيه تفصيل، الغضب أنواع ثلاثة: غضب عادي لا يمنع الطلاق، وغضب شديد يغير على الإنسان حاله، وقصده، ولا يتمكن معه من الطلاق الشرعي، بل يعمى عليه قصده، ويعمى عليه طريقه بسبب طول النزاع، وشدة النزاع، والمضاربة بينهما، أو السباب، والمشاتمة بينهما، فهذا إذا اشتد الغضب، لا يقع معه الطلاق على الصحيح أيضًا. والحال الثالث: أن يوقعه الغضب في عدم الشعور، وأن يكون كسائر المجانين، والمعتوهين، قد ألجأه وأوقعه الغضب في زوال العقل، فلا يعقل ما يقول، وهذا لا يقع طلاقه عند جميع أهل العلم، ويلحق في هذه الحالة بالمعتوهين، والمجانين، فلا يقع طلاقه إذا كان غضبه قد أوقعه في هذه الحالة.","link":"https://binbaz.org.sa/fatwas/2195/حكم-الطلاق-ثلاثا-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_820.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6478,"question":"أستطيع أن أقول بأن الكثير من بائعي الذهب، والنساء اللاتي يشترين الذهب، ويقعون في الربا، وذلك مثل: البدل، يعني ذهب بذهب، وعندما يبقى لصاحب المحل بعض الفلوس؛ فيرضى بأن يصبر على الشخص بموجب المعرفة بينهما، ولقد سألنا كثيرًا من النساء عن البدل، فيقولون: نعم نبدل دائمًا، ولا نعلم عن الربا شيئًا؟","title":"حكم بيع الذهب القديم بالذهب الجديد","answer":"الجواب:  المعاصي تقع، ما يقال: إنها لا تقع، المعاصي تقع بين الناس، تقع في الربا، تقع معاصي الربا، ومعاصي غير الربا،  كلها تقع، لكن المهم العلاج لهذه المعاصي بالحدود الشرعية، والمواعظ، والتذكير، والنصائح، وإلا فالمعاصي تقع، فالربا يقع من النساء، ومن الرجال مع الصاغة، ومع غير الصاغة، فلا يجوز السكوت عنهم، من علم أنه يقع منه المعصية ينصح، ويوجه إلى الخير.  فالذي يشتري من الصاغة القلائد، أو أسورة، أو غير ذلك لا بد أن يشتريها بمال يدًا بيد في الأسورة، في القلائد في .. [ثم] يشتريها بالنقد يدًا بيد، أو بنوع آخر غير النقد، يشتري مثلاً قلادة من الذهب، أو من الفضة، أو خاتم من الذهب، أو أسورة من الذهب، أو غير ذلك، يشتريها بغير النقود، يشتريها مثلًا بطعام، يشتريها بملابس، يشتريها بهيل، بقهوة، بسكر إلى أجل، ما في بأس، لكن بنقود لا، لا بد يدًا بيد، بذهب لا بدّ يدًا بيد.  فإذا باع؛ أعطى الخواتم المستعملة، أو الأشياء المستعملة بشيء جديد، لا بد أن يكون يدًا بيد، مثلًا بمثل، وإلا فلتشتري من الجديد بثمن مستقل، ولتبع عليه المصمت بثمن مستقل، أما أن تعطي هذا بهذا وزيادة، ما يجوز، هذا ربا، تبيع هذا الجديد بهذا المصمت، وزيادة جنيه جنيهين، ما يجوز، فلا بد أن تشتري الجديدة بثمن مستقل، يدًا بيد إن كان من النقود من الورق، وإن كان بغير النقود .. إلى أجل، طعام إلى أجل، بملابس إلى أجل، لا بأس يعني ما هو بربوي إذا باع الذهب بهيل، أو قهوة، أو ملابس، أو خام آخر، أو سلع أخرى غير النقود؛ فلا بأس إلى أجل معلوم، أما بالنقود فلا، لا بدّ يدًا بيد، فإن كان ذهبًا بذهب، لا بد أن يكون مثلًا بمثل، سواء بسواء، وجها لوجه يدًا بيد، لا يتفرقا، وهكذا الفضة.  فإن باع فضة بذهب، لا بأس، لكن يدًا بيد، إن اشترى من الصائغ، أسورة من الذهب بورق يدًا بيد؛ فلا بأس، أما يقول: روح، وبعدين تجيء لي ما يصلح، لا بدّ يدا بيد، وإذا فعلته المرأة، والرجل؛ ينصح، ويبين له أن هذا منكر، وعلى الهيئة، والحسبة أن تقوم بهذا الأمر، وأن تنكر على من فعل هذا الشيء، ومن لم يرتدع؛ يعاقب بالأدب، والسجن، والضرب إذا لم ينزجر عما حرم الله عليه.","link":"https://binbaz.org.sa/fatwas/2226/حكم-بيع-الذهب-القديم-بالذهب-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_846.mp3","categories":["الربا والصرف","الأخلاق المذمومة"]},{"id":6493,"question":"أستطيع أن أقول بأن الكثير من بائعي الذهب، والنساء اللاتي يشترين الذهب، ويقعون في الربا، وذلك مثل: البدل، يعني ذهب بذهب، وعندما يبقى لصاحب المحل بعض الفلوس؛ فيرضى بأن يصبر على الشخص بموجب المعرفة بينهما، ولقد سألنا كثيرًا من النساء عن البدل، فيقولون: نعم نبدل دائمًا، ولا نعلم عن الربا شيئًا؟","title":"حكم بيع الذهب القديم بالذهب الجديد","answer":"الجواب:  المعاصي تقع، ما يقال: إنها لا تقع، المعاصي تقع بين الناس، تقع في الربا، تقع معاصي الربا، ومعاصي غير الربا،  كلها تقع، لكن المهم العلاج لهذه المعاصي بالحدود الشرعية، والمواعظ، والتذكير، والنصائح، وإلا فالمعاصي تقع، فالربا يقع من النساء، ومن الرجال مع الصاغة، ومع غير الصاغة، فلا يجوز السكوت عنهم، من علم أنه يقع منه المعصية ينصح، ويوجه إلى الخير.  فالذي يشتري من الصاغة القلائد، أو أسورة، أو غير ذلك لا بد أن يشتريها بمال يدًا بيد في الأسورة، في القلائد في .. [ثم] يشتريها بالنقد يدًا بيد، أو بنوع آخر غير النقد، يشتري مثلاً قلادة من الذهب، أو من الفضة، أو خاتم من الذهب، أو أسورة من الذهب، أو غير ذلك، يشتريها بغير النقود، يشتريها مثلًا بطعام، يشتريها بملابس، يشتريها بهيل، بقهوة، بسكر إلى أجل، ما في بأس، لكن بنقود لا، لا بد يدًا بيد، بذهب لا بدّ يدًا بيد.  فإذا باع؛ أعطى الخواتم المستعملة، أو الأشياء المستعملة بشيء جديد، لا بد أن يكون يدًا بيد، مثلًا بمثل، وإلا فلتشتري من الجديد بثمن مستقل، ولتبع عليه المصمت بثمن مستقل، أما أن تعطي هذا بهذا وزيادة، ما يجوز، هذا ربا، تبيع هذا الجديد بهذا المصمت، وزيادة جنيه جنيهين، ما يجوز، فلا بد أن تشتري الجديدة بثمن مستقل، يدًا بيد إن كان من النقود من الورق، وإن كان بغير النقود .. إلى أجل، طعام إلى أجل، بملابس إلى أجل، لا بأس يعني ما هو بربوي إذا باع الذهب بهيل، أو قهوة، أو ملابس، أو خام آخر، أو سلع أخرى غير النقود؛ فلا بأس إلى أجل معلوم، أما بالنقود فلا، لا بدّ يدًا بيد، فإن كان ذهبًا بذهب، لا بد أن يكون مثلًا بمثل، سواء بسواء، وجها لوجه يدًا بيد، لا يتفرقا، وهكذا الفضة.  فإن باع فضة بذهب، لا بأس، لكن يدًا بيد، إن اشترى من الصائغ، أسورة من الذهب بورق يدًا بيد؛ فلا بأس، أما يقول: روح، وبعدين تجيء لي ما يصلح، لا بدّ يدا بيد، وإذا فعلته المرأة، والرجل؛ ينصح، ويبين له أن هذا منكر، وعلى الهيئة، والحسبة أن تقوم بهذا الأمر، وأن تنكر على من فعل هذا الشيء، ومن لم يرتدع؛ يعاقب بالأدب، والسجن، والضرب إذا لم ينزجر عما حرم الله عليه.","link":"https://binbaz.org.sa/fatwas/2226/حكم-بيع-الذهب-القديم-بالذهب-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_846.mp3","categories":["الربا والصرف","الأخلاق المذمومة"]},{"id":6500,"question":"بعض زملائي في العمل يجاهرن بجريمة الزنا أثناء السفر إلى الخارج، فما هو الذي يجب علينا إزاء ذلك إذا لم تفد معهم النصيحة؟","title":"حكم المجاهرة بالزنا","answer":"الجواب:  إذا سمعت هذا؛ تنكر عليه، تقول له: اتق الله، لا تفضح نفسك ولا تجاهر بمعصيتك، هذا حرام عليك، والرسول -عليه الصلاة والسلام- يقول: كل أمتي معافى إلا المجاهرين نعوذ بالله، فالإنسان إذا فعل المعصية لا يجوز له أن يجاهر بها، ويقول: فعلت، وفعلت، بل يطلب من ربه الستر، فيسأل ربه العافية، ويبادر بالتوبة، فإذا سمعت من زميلك في المكتب، أو في غيره، هذا الأمر تنكره عليه، وتقول: اتق الله، لا تقل هذا الكلام، ولا تنطق بهذا الكلام، وسل ربك التوبة، تب إلى الله، هذه فضيحة، هذا منكر، تتكلم عليه، وتبين له أن هذا منكر، وأن هذا ما يجوز، ولا يحل له أن يبوح به عند زملائه، ولا عند غيرهم، بل عليه أن يستتر بستر الله، وأن يتوب إلى الله  ولا تسأم من الإنكار عليه، لا تسأم إذا قال لك مرتين، قل له مرتين ثلاث أربع، تشدد عليه، وقل له والذين معك تنكرون عليه، تعاونوا عليه، أعينوه على حرب الشيطان، هذا يزين له الشيطان، وأنتم أعينوه على حرب الشيطان بالإنكار عليه، والتغليظ عليه؛ لعله ينتهي، وإذا لم ينته؛ فاستعينوا بالله على فصله، جاهدوا في إبعاده عنكم مع المسؤولين. السؤال: إقراره منه على نفسه ألا يقام عليه الحد..؟ الجواب: نعم. السؤال: إقراره منه على نفسه بأنه فعل جريمة الزنا؟ الجواب: بلى، إذا شهدوا عند الحاكم؛ يقام عليه، يخوفونه بهذا، يقولون: إما أن تتوب، وإلا سنشهد عند الحاكم؛ حتى يقام عليك الحد، تقدم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2271/حكم-المجاهرة-بالزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_894.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6516,"question":"بعض زملائي في العمل يجاهرن بجريمة الزنا أثناء السفر إلى الخارج، فما هو الذي يجب علينا إزاء ذلك إذا لم تفد معهم النصيحة؟","title":"حكم المجاهرة بالزنا","answer":"الجواب:  إذا سمعت هذا؛ تنكر عليه، تقول له: اتق الله، لا تفضح نفسك ولا تجاهر بمعصيتك، هذا حرام عليك، والرسول -عليه الصلاة والسلام- يقول: كل أمتي معافى إلا المجاهرين نعوذ بالله، فالإنسان إذا فعل المعصية لا يجوز له أن يجاهر بها، ويقول: فعلت، وفعلت، بل يطلب من ربه الستر، فيسأل ربه العافية، ويبادر بالتوبة، فإذا سمعت من زميلك في المكتب، أو في غيره، هذا الأمر تنكره عليه، وتقول: اتق الله، لا تقل هذا الكلام، ولا تنطق بهذا الكلام، وسل ربك التوبة، تب إلى الله، هذه فضيحة، هذا منكر، تتكلم عليه، وتبين له أن هذا منكر، وأن هذا ما يجوز، ولا يحل له أن يبوح به عند زملائه، ولا عند غيرهم، بل عليه أن يستتر بستر الله، وأن يتوب إلى الله  ولا تسأم من الإنكار عليه، لا تسأم إذا قال لك مرتين، قل له مرتين ثلاث أربع، تشدد عليه، وقل له والذين معك تنكرون عليه، تعاونوا عليه، أعينوه على حرب الشيطان، هذا يزين له الشيطان، وأنتم أعينوه على حرب الشيطان بالإنكار عليه، والتغليظ عليه؛ لعله ينتهي، وإذا لم ينته؛ فاستعينوا بالله على فصله، جاهدوا في إبعاده عنكم مع المسؤولين. السؤال: إقراره منه على نفسه ألا يقام عليه الحد..؟ الجواب: نعم. السؤال: إقراره منه على نفسه بأنه فعل جريمة الزنا؟ الجواب: بلى، إذا شهدوا عند الحاكم؛ يقام عليه، يخوفونه بهذا، يقولون: إما أن تتوب، وإلا سنشهد عند الحاكم؛ حتى يقام عليك الحد، تقدم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2271/حكم-المجاهرة-بالزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_894.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6531,"question":"تزوجت، ونذرت لله إذا جاءني بولد أن أصوم من كل شهر ثلاثة أيام، قد حصل لي الآن مرض في بطني، ومنعني الطبيب عن الصوم؛ فتركت صوم الثلاثة أيام، وإنما أصوم رمضان، فما حكم ترك صيام الثلاثة أيام؟","title":"من لم يستطع الوفاء بنذره بسبب المرض","answer":"الجواب: يقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه فالذي نذر أن الله إن رزقه ولدًا أن يصوم ثلاثة أيام من كل شهر، أو إن الله عافاه من مرضه؛ يصوم ثلاثة أيام من كل شهر، أو إن الله رزقه الوظيفة الفلانية يصوم ثلاثة من كل شهر؛  يصوم إذا حصل مقصوده، إذا حصل الشرط؛ يلزمه الصيام، وإذا مرض يقضي، إذا مرض، وعافاه الله يقضي الأيام مثل رمضان، إذا مرض يصوم بعد ذلك، فإذا مرض الإنسان في أي الشهور يصوم بعد ذلك الثلاثة الأيام التي بعد شفائه، وليس له عذر في ترك ذلك، إلا إذا أصابه مرض لا حيلة فيه، لا يرجى برؤه؛ فحينئذ معذور مثل رمضان، يكفر، يطعم عن كل يوم مسكينًا. س: عن كل يوم في كل شهر؟  الجواب: كل شهر. الطالب: كلما يمر عليه شهر؟ الجواب: صاع ونصف عن كل شهر.\n\nالطالب: يتكرر باستمرار الشهور؟ الجواب: نعم مثل رمضان.","link":"https://binbaz.org.sa/fatwas/2386/من-لم-يستطع-الوفاء-بنذره-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_919.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6537,"question":"بالنسبة لقبول الهدايا يجوز قبول الهدايا؟","title":"حكم قبول الهدايا","answer":"الجواب: الهدايا فيها تفصيل، إذا كانت هدية لا يترتب عليها شر، وليست بقشيشًا، ولا رشوة، بل هدية من صاحب،  ومن. السؤال:.. الجواب: هذا فيه تفصيل .....\n\nالسؤال: عيد الميلاد الذي يسمونه عيد الميلاد .. قبول الهدية هذا فيه شيء؟  الجواب:  لا، في عيد النصارى ما يجوز قبول الهدايا فيه؛ لأنها تشجيع لأعيادهم، لا يجوز كذلك، لا يجوز حضورها، ولا مشاركتهم فيها، ولا تشجيعهم عليها، ولا معاونة فيها، ولا إهداؤهم شيئًا لأعيادهم، كل هذا معناه إقرارهم على المنكر وموافقتهم عليه. السؤال: طيب وإن كنت أنا صاحب عمل، وعندي نصارى ..؟ الجواب: الذين معهم .. الطالب: عندهم خمسة وعشرون في العيد بتاعهم ذا ممكن يستأذنوا نصف يوم بحجة إنهم يروحوا يعيدوا عندهم ..؟ الجواب: لا ما جئت بهم للأعياد، أنا جئت بهم لعملي، هذا منكر حتى في دينهم منكر.","link":"https://binbaz.org.sa/fatwas/2382/حكم-قبول-الهدايا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_915.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":6542,"question":"إنسان طلق على أنه لا يقعد عند هذا الشخص، وفي يوم من الأيام ذهب إليه، فما حكم ذلك اليمين؟","title":"حكم من علق طلاقه على شرط","answer":"الجواب: إذا طلق الإنسان لا يقعد عند فلان، أو لا يكلم فلانًا؛ فله حالان: إحداهما: أن يقصد منع نفسه، ولا يقصد إيقاع الطلاق، إنما قصد منع نفسه من هذا الشيء، وشدد على نفسه بالطلاق، ولم يرد إيقاع الطلاق على أهله، وإنما أراد منع نفسه من قعوده عنده، أو الكلام، فهذا حكمه حكم اليمين على الصحيح، وعليه كفارة اليمين ولا يقع الطلاق. أما إذا أراد وقوع الطلاق، وأنه نوى إذا قعد عنده فزوجته طالق، أو كلمه فزوجته طالق؛ فإنه متى كلمه، أو قعد عنده يقع طلقة على زوجته؛ لأنه طلاق معلق على الشرط، مثل لو قال: إذا دخل رمضان فزوجته طالق؛ تطلق، أو قال: إذا نزل المطر فزوجته طالق، أو قال: إذا حاضت فهي طالق، وما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/2372/حكم-من-علق-طلاقه-على-شرط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_906.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6548,"question":"شخص طلق وهو في حالة سكر على ألا يركب السيارة مع أشخاص، ثم ركب معهم، ولكن في مقدمة السيارة، والبقية في المؤخرة؟","title":"حكم طلاق السكران","answer":"الجواب: السيارة كلها واحدة مقدمها، ومؤخرتها، لكن إذا كان عقله معه وقع الطلاق إن كان قصد الطلاق، وإن كان عقله ما هو معه، يتكلم وهو غير عاقل، غائب العقل؛ فهو مثل المجنون، لا يقع طلاقه، إذا تكلم وهو غير عاقل مثل المجنون لا يقع طلاقه. أما إن كان يعقل فيستفصل؛ إن كان أراد منع نفسه من الركوب مثل ما تقدم في الذي طلق ألا يكلم فلاناً، أو لا يقعد عنده إن كان طلق .. وليس قصده فراق زوجته، وإنما قصده منع نفسه من الركوب، والتشديد على نفسه؛ فهذا حكمه حكم اليمين، وعليه كفارتها، فإن كان أراد إيقاع الطلاق، يعني ركب، فيقع الطلاق على زوجته، يقع عليها طلقة في ذلك إذا كان عقله معه، سواء ركب في مقدمها، أو مؤخرها، إلا إذا قال: إنه لا يركب في المقدمة، أو في المؤخرة عيّن فهو على ما عيّن وعلى ما ...","link":"https://binbaz.org.sa/fatwas/2373/حكم-طلاق-السكران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_907.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6555,"question":"امرأة نذرت لله صوم شهر تصومه بدون سحور إن طلقها زوجها، هل توفي بالنذر بدون سحور، أم لا؟","title":"حكم من نذر صياماً بغير سحور","answer":"الجواب: إذا طلقها زوجها؛ تصوم، ولكن تتسحر، لا تترك السحور، السحور سنة، وقربة، والرسول ﷺ يقول: تسحروا فإن في السحور بركة فعليها أن تصوم، وعليها أن تتسحر، عليها السحور، النبي ﷺ قال: من نذر أن يطيع الله؛ فليطعه فالصوم طاعة، وترك السحور ما هو بطاعة، تتسحر ...","link":"https://binbaz.org.sa/fatwas/2413/حكم-من-نذر-صياما-بغير-سحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_940.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6574,"question":"لقد انتشر في قبائلنا الشغار، وغلو المهور، حتى إن الرجل يبلغ من العمر أكثر من ستين عامًا، ويأخذ بكريمته زوجة عن بنت أقل من 18 سنة بطريق الشغار، وهذا أدى إلى توقف الشباب منا من الزواج، وانحرافهم، وذهابهم إلى البلاد المختلفة؛ ليزاولوا هناك المنكرات؟","title":"حكم زواج الشغار وخطورة التكلف في الولائم وغلاء المهور","answer":"الجواب:\n\nهذا الذي قاله السائل أمر واقع في كثير من الجهات من غلاء المهور، ومن التكلف في الولائم، والحرص على الطمع من الأولياء، أو بعض الأولياء، وهذا لا شك أنه غلط كبير، والتنافس في المهور أمر منكر لقصد مصالحهم، الواجب على الأولياء أن يتقوا الله، وأن ينظروا في مصالح النساء، وأن يرضوا -ولو بالمهر القليل- إذا جاء الكفء، أما أن ينافس في طلب المهور حتى يأخذ المال، ولا يبالي؛ فهذا منكر لا يجوز له، ولو كان أباها، ليس له أن يحبسها لأجل المال الكثير، بل متى جاء الكفء -ولو بالقليل- زوجها، وسارع إلى ذلك، إذ المقصود صيانتها، وحفظ عرضها، وإعانتها على الخير، وإعانة المجتمع الإسلامي على الخير أيضًا. \n\nفعلى كل حال قد صدر فيه رسائل كثيرة، ونصائح كثيرة من هيئة كبار العلماء، وكثير من العلماء -ومني أيضًا- صدر في هذا كثير من الوعظ، والتذكير، وبيان ما يجب على المسلمين، وصدر رسائل في الشغار، والتحذير منه، ووزعت في جميع أنحاء البلاد مرات كثيرة، ولكن كما قيل:\n\n\n\t\n\t\t\n\t\t\tما لجرح بميت إيلام\n\t\t\n\t\n\n\nإذا لم يكن في القلب واعظ، ولم يكن في القلب إقبال على الخير، والهدى؛ لا ينتفع الإنسان بما يسمع، ولا يعلم، بل يصر على باطله، ولا يبالي، القرآن أكبر واعظ، القرآن العظيم، وأعظم ذكر، ومع ذلك أكثر الخلق قد خالفه، فلم يمتثل بما في القرآن من الأوامر، والنواهي متابعة للهوى، وإنما يمتنع بالنصائح من يرغب الحق، ويريد الحق، ويعيش بالحق، ويطلبه، متى وُعِظَ؛ قبل، ومتى ذُكِّر؛ تذكر؛ لأن قصده الحق، وهدفه اتباع الحق.\n\nفالواجب على السائل وجماعته أن يتقوا الله، وأن يتعاونوا على البر والتقوى، وأن يتناصحوا فيما بينهم، كبارهم، ويقومون على سفهائهم، وأعيانهم، يقومون على عامتهم حتى يتعاونوا على الخير، ويستعينوا أيضًا بعلمائهم، وقضاتهم، وأمرائهم في هذا الأمر العظيم؛ حتى يزوج الكفء، ولو بالمهر القليل، وحتى لا يتنافسوا في الولائم الكثيرة التي لا ضرورة إليها، بل يكون الشيء القليل الذي لا يضر الزوج، ولا أهل الزوجة، هذا هو الذي ينبغي للمسلمين فيما بينهم التعاون، فإذا علموا شخصًا يتساهل في هذا الأمر، ويحبس بناته، أو أخواته بغير حق؛ قاموا عليه، ونصحوه، ووجهوه إلى الخير، ولو أدى إلى أن يشتكوه إلى ولي الأمر عندهم؛ حتى يأخذ على يده، وحتى يزوج بناته، أو أخواته عن الأكفاء، ولو من طريق المحكمة إذا لم يحصل من الأولياء الخضوع للحق.\n\nنسأل الله للجميع الهداية، هذا إن شاء الله يعتنى به أكثر فيما يستقبل إن شاء الله.\n\nالسؤال: وهذا سؤال سبق أن أرسله إلينا أحد الإخوة قبل ذلك، وهو يستعين بالله، ثم بسماحتكم أن تنصفوه من هذا الرئيس الفلبيني الذي يفصل الذين، يصلون في المؤسسة، ويهددهم، ويضع الكلب مكان صلاتهم؟\n\nالجواب: هذا كذلك أيضًا سبق أن كتبنا إلى وزير الداخلية، ونسأل الله أن يوفقهم.","link":"https://binbaz.org.sa/fatwas/2421/حكم-زواج-الشغار-وخطورة-التكلف-في-الولاىم-وغلاء-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_948.mp3","categories":["الأنكحة المحرمة","الأخلاق المذمومة"]},{"id":6587,"question":"امرأة نذرت لله صوم شهر تصومه بدون سحور إن طلقها زوجها، هل توفي بالنذر بدون سحور، أم لا؟","title":"حكم من نذر صياماً بغير سحور","answer":"الجواب: إذا طلقها زوجها؛ تصوم، ولكن تتسحر، لا تترك السحور، السحور سنة، وقربة، والرسول ﷺ يقول: تسحروا فإن في السحور بركة فعليها أن تصوم، وعليها أن تتسحر، عليها السحور، النبي ﷺ قال: من نذر أن يطيع الله؛ فليطعه فالصوم طاعة، وترك السحور ما هو بطاعة، تتسحر ...","link":"https://binbaz.org.sa/fatwas/2413/حكم-من-نذر-صياما-بغير-سحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_940.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6593,"question":"رجل طلق زوجته في طهر جامعها فيه، ولكن حيل بينه وبين فض بكارتها، فهل يقع الطلاق، أم لا؟ مع أن هذا الأمر تكرر ثلاث مرات، وراجعها في الطلقة الأولى، والثانية، فهل بانت منه، أم لا؟","title":"حكم طلاق الرجل للمرأة في طهر جامعها فيه","answer":"الجواب: هذه المسألة خلاف بين أهل العلم، جمهور أهل العلم يرون أنه إذا طلقها ولو في طهر جامعها فيه؛ يقع الطلاق، لو أنه .. الطلاق في طهر جامعها فيه، أو في الحيض، أو في النفاس. وذهب آخرون من أهل العلم إلى أنه إذا طلقها في الحيض، أو في النفاس، أو في طهر جامعها فيه وهي ليست حاملًا أنه لا يقع؛ لحديث ورد عن ابن عمر في ذلك أنه طلق امرأته وهي حائض، فغضب عليه النبي ﷺ وأنكر عليه، وقال له: ارجعها، وأمسكها حتى تحيض، ثم تطهر، ثم تحيض، ثم تطهر، ثم إن شاء طلق، وإن شاء أمسك فقال رسول الله: فتلك العدة التي أمر الله أن تطلق لها النساء. وهذا يدل على أن الطلاق الذي فعله ابن عمر غير واقع؛ لأن الرسول ﷺ أمره أن يرجعها، ولم يسأله هل واحدة، أو ثنتين، أو ثلاث، بل أمره أن يرجعها، فدل ذلك على أن الطلاق غير واقع؛ لأنه عاصٍ لله في طلاقها في الحيض، أو في النفاس، أو في طهر جامعها فيه، فعليه أن يردها وأن يراجعها، ثم إذا أراد الطلاق يطلقها بعد ذلك إذا طهرت قبل أن يطأها. وأما إذا طلقها وهي حامل؛ فطلاقها ماضٍ، أو طلقها في طهر لم يجامعها فيه؛ فطلاقها ماضٍ، ولكن إذا طلقها في الطهر الذي جامعها فيه، وهي غير حبلى، أو في الحيض، أو في النفاس، فجمع من أهل العلم يقولون: لا يقع الطلاق؛ لأنه معصية. السؤال: يعني فض البكارة ليس شرطًا؟ الجواب: لا ما هو بشرط.","link":"https://binbaz.org.sa/fatwas/2436/حكم-طلاق-الرجل-للمراة-في-طهر-جامعها-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_963.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6595,"question":"وهذه رسالة من أخ رمز لاسمه بالحروف: م. ح. م. د من جيزان يقول: ما رأيكم في الدخان حرام، أم لا؟ والبردقان هي شجرة واحدة، أم لا، وشربها حرام، أم مكروه؛ لأن كثيرًا من الناس يشربونها، أو البردقان، ويقولون: إنه مكروه، وليس حرامًا، أفيدونا عن ذلكم أفادكم الله ؟","title":"حكم الدخان والبردقان","answer":"الجواب: الدخان منكر، ومحرم، ومضاره كثيرة، وهو من الخبائث، والبردقان جزء منه البردقان، نوع من الدخان يسمونه، بردقان، نوع من الدخان، وهو من جنسه، جميع أنواع الدخان وفصائل الدخان كلها محرمة، قال الله -جل وعلا-: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فنص القرآن أن الله أباح لنا الطيبات فقط، ولا يقول عاقل: إن الدخان بأنواعه من الطيبات، بل هو من المنكرات، ومن الشرور، ومن الخبائث، فبيعه حرام، والتجارة فيه حرام، وثمنه حرام، واستعماله حرام، ثم فيه من المضار الكثيرة ما لا يحصى، حتى قال بعض الأطباء: إنه أضر من الخمر من جهة مضاره الكثيرة، نسأل الله العافية. فالحاصل: أنه منكر، ومن الخبائث، وليس من الطيبات التي أباح الله لنا، الله أباح الطيبات، وحرم الخبائث كما قال في وصف نبيه ﷺ وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]، وقال في سورة المائدة: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فالله ما أباح لنا إلا الطيبات، ولا يقول عاقل لا من طبيب، ولا غير طبيب أن الدخان من الطيبات، بل هو من الخبائث الضارة المؤذية.","link":"https://binbaz.org.sa/fatwas/2438/حكم-الدخان-والبردقان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_965.mp3","categories":["الأخلاق المذمومة","الأطعمة والأشربة"]},{"id":6660,"question":"هل يحق للزوجة مطالبة زوجها بالطلاق إذا كان يسكر، لأني قرأت فتوى في إحدى المجلات تجيز ذلك إذا كان الزوج لا يؤذي زوجته، ويلبي كافة حقوقها، ولا يؤذيها، أفيدونا جزاكم الله خيرًا؟","title":"حكم المطالبة بالطلاق إذا كان الزوج يسكر","answer":"الجواب: وهل  هناك أشد من الأذى في السكر، السكران مجنون، قد يقتلها بعض الأحيان -نسأل الله العافية- لها الحق أن تطلب الطلاق إذا كان زوجها سكيرًا، أو يتساهل في الصلاة، أو يفعل جرائم أخرى، كاللواط، أو يأتيها في الدبر، لها الحق أن تطلب الطلاق؛ لأنه -زوجها- مجرم، فلها أن تطلب الطلاق.  في الحديث أيما امرأة طلبت الطلاق من غير ما بأس من غير ما علة يعني لم ترح رائحة الجنة أما هذه لها علة، إذا كان لا يصلي هذا كافر -نعوذ بالله- لا تقم عنده، ولا يجوز لها البقاء عنده: لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]. وإذا كان يسكر، أو يتعاطى الجماع في الدبر، أو ما أشبه ذلك من المعاصي؛ لها طلب الطلاق، وعليها أن تمتنع منه، لا يجوز لها أن تمكنه من دبرها، ليس له الجماع إلا في القبل، أما الدبر فلا، هذا لواط.","link":"https://binbaz.org.sa/fatwas/2549/حكم-المطالبة-بالطلاق-اذا-كان-الزوج-يسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1044.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":6756,"question":"ما حكم كتمان الشهادة لاسيما إن كان ذلك صادرًا من بعض أهل العلم؟ وهل يعتبر كاتمه عدلًا، ثقة، أم لا؟ وماذا يترتب على كاتمها من جرح؟","title":"حكم كتمان الشهادة","answer":"الجواب: يقول الله -جل وعلا-: وَلَا تَكْتُمُوا الشَّهَادَةَ وَمَنْ يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ [البقرة:283] إذا كان عنده شهادة لزيد، أو عمرو بأنه اشترى شيئًا، أو باع شيئًا، أو قتل فلانًا، أو ضرب فلانًا، فلا يجوز له كتمان الشهادة، بل يجب عليه أن يبين الشهادة، ولا يجوز كتمانها، أما ما يتعلق بإثمه عند الله، فهذا عند الله  كونه معذورًا، أو ما هو معذور، هذا إلى الله، والواجب عليه أداء الشهادة.","link":"https://binbaz.org.sa/fatwas/2639/حكم-كتمان-الشهادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1135.mp3","categories":["القضاء والشهادات","الأخلاق المذمومة"]},{"id":6886,"question":"كيف يتخلص الإنسان من الحسد؛ لأنه مرض الإنسان الخطير؟","title":"كيفية التخلص من داء الحسد","answer":"الجواب: الإنسان إذا بلي بالحسد، ومحبة زوال النعمة عن أخيه، ينظر أن الله سبحانه هو المنعم، أي يفكر، وينظر الله، هو الذي أعطى أخاه، وهو أعطى هذا الشخص، وأعطى الآخر، فلينظر أن حسده لا يضر إلا نفسه، لا يضر الآخرين. فالله المعطي المانع -جل وعلا- فحسده لأخيه يضره هو، ويغضب الله عليه  ولا يضر المنعم عليه، بل يضر صاحبه، فالحاسد إنما أضر نفسه؛ فليفكر ولينظر! فإنه اعتراض على الله  بما أعطاه بعض عباده، فليراجع نفسه، وليعلم أنه ظالم لنفسه، وأنه معترض على الله -جل وعلا- في تصرفه، وإحسانه إلى عباده، فليندم وليستغفر ربه  وليشكر الله على ما أعطاه سبحانه، وليدع لأخيه بالتوفيق، والهداية، وأن يهدى لصرف النعم في طاعة المولى -جل وعلا-.  وأما اعتراضه على أخيه، وحسده له، فهو في الحقيقة ظلم منه، وعدوان على نفسه، واعتراض على الله  فلا ينبغي له ذلك، بل ينبغي له أن يبادر بالتوبة من ذلك، والاستغفار من ذلك، وأن يسأل ربه الهداية والتوفيق، وأن يحمد ربه على ما أعطاه، ويسأل .. .","link":"https://binbaz.org.sa/fatwas/2770/كيفية-التخلص-من-داء-الحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1262.mp3","categories":["الأخلاق المذمومة","الرقائق","قضايا المرأة"]},{"id":6898,"question":"أعلنت البلدية أنه سوف توزع أراضي، وشرطت الحلف على عدم ملك عقار، أو أراضي، وأنا ليس لي أي أملاك، هل أحلف على ذلك؟","title":"حكم اليمين بعدم ملكية أي عقار للحصول على أرض","answer":"الجواب: الواجب على الرعية أن يلتزموا ما تقوله الدولة في حدود الشريعة، والاجتهاد، فإذا قالت الدولة: إنها تعطي من الضمان الاجتماعي من صفته كذا وكذا وكذا؛ فعلى الرعية أن يلتزموا بذلك، وليس لهم الكذب، والحيل حتى يقولوا: إن هذه المرأة فقيرة، وهي ليست فقيرة، أو هذا الرجل فقير، وليس بفقير، أو هي مطلقة، وهي غير مطلقة، لا يجوز. فإنه ليس له أن يكذب، وليس له أن .. الزور على أنه ما عنده بيت، ولا عنده أرض، وهو كاذب، ليس له ذلك؛ لأن الدولة لها في هذا اجتهاد، وتبرير، ولا مانع لها من هذا الشرط، فإذا كان عنده بيت، أو أرض؛ لا يفعل، ولا يحلف، وإذا طلبوا منه الحلف؛ لا يجوز له الحلف، لا يجوز أن يحلف فيقول: والله ما عندي أرض، وهو يكذب، والله ما عندي بيت، وهو يكذب، أما إذا كان صادقًا، ما عنده أرض، ولا بيت؛ فلا حرج، يحلف ولا حرج عليه. السؤال: هو تكميلًا للسؤال، يقول: هو عنده أرض واحد، وهبها له من عشر سنوات، ولكن لا يعلم أين هي، ولا موقعها، ولا يستطيع التصرف فيها، فهل ممكن يحلف على هذا الأساس؟","link":"https://binbaz.org.sa/fatwas/2829/حكم-اليمين-بعدم-ملكية-اي-عقار-للحصول-على-ارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1277.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6908,"question":"سمعنا من بعض طلبة العلم أن سماحتكم قلتم إن من زاد في سرعة سيارته عن مائة وعشرين كيلو، وحصل له حادث، وتوفي؛ يعتبر منتحرًا، فما مدى صحة هذا القول؟","title":"حكم زيادة سرعة السيارة عن تحديد أنظمة المرور","answer":"الجواب: ما صدر منا شيء في هذا، لكن الناس يكتبون كلمات لم يصدر مني شيء في هذا، ولكني أوصي بعدم السرعة، يتصلون بي، وأحذرهم من السرعة، وأقول السرعة في الحقيقة طريق لهلاك نفسك، وهلاك غيرك، فالواجب عليك أن تأخذ الطريق السوي، والعادة التي يرشد إليها كلام المرور، ويوجه إليها حتى تكون آخذًا بالحيطة لنفسك، ولمن معك. هذا هو الواجب على أصحاب السيارات: أن يسلكوا الطريق السوي، وألا يزيدوا في السرعة التي تضرهم، وتضر غيرهم؛ ثقة بأنهم سالمون، وأنهم معلمون، وهذا كله من الشيطان، من يقول له: إنك سالم، وإنك لا تقع في الخطأ، هذا لا شك أنه من التساهل الذي لا ينبغي.","link":"https://binbaz.org.sa/fatwas/2835/حكم-زيادة-سرعة-السيارة-عن-تحديد-انظمة-المرور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1283.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":6931,"question":"ما حكم من حلف بالقرآن الكريم وعظمته؟","title":"حكم الحلف بالقرآن وعظمته","answer":"الجواب: القرآن كلام الله، فالحلف بالقرآن حلف بكلام الله، فإذا قال: والقرآن المجيد، أو وكلام الله لا أفعل كذا، فهو حلف بالقرآن، حلف بكلام الله، مثل لو قال: وعلم الله، وعزة الله، أو ورحمة الله، كله لا فرق. السؤال: آخر يقول: مدير العلاقات العامة الإداري بمستشفى الملك فهد يمنع من أراد أن يذَّكر في الصلاة داخل المستشفى، وهذا أمر عظيم، حيث يساعد على ترك الصلاة، فكيف يكون هذا التصرف من رجل مسؤول في بلد مسلم؛ لأنه لمن الغريب المنكر؟ الجواب: ينظر في الأمر -إن شاء الله-.","link":"https://binbaz.org.sa/fatwas/2861/حكم-الحلف-بالقران-وعظمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1309.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6932,"question":"يقسم بآيات الله؟","title":"حكم الحلف بآيات الله","answer":"الجواب: كذلك آيات الله إذا كان أراد بها القرآن؛ فلا بأس، وإن كان أراد بها آيات الله التي هي الليل والنهار، والشمس والقمر؛ ما يجوز؛ لأنها مخلوقات. أما إذا قال: أقسمت بآيات الله، أو أقسم بآيات الله، يعني القرآن؛ فهو كلام الله، وإذا قال: أقسمت بآيات الله، أو أقسم بآيات الله، يعني: الليل والنهار، أو الشمس والقمر، أو السموات والأرض؛ لا ما يجوز؛ لأنها مخلوقات وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ [فصلت:37].","link":"https://binbaz.org.sa/fatwas/2862/حكم-الحلف-بايات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1310.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6978,"question":"امرأة حامل في شهرها الثالث، أصر زوجها على إخراج ابنها، وإلا يطلقها، وهي معها منه ثمانية أولاد، ففعلت ما أراد منها مكرهة، وأخرجت جنينها خوفًا من الطلاق، وسؤالها يتلخص في الأمر الآتي: هل يلزمها شيء من الكفارة؟ وهل عليها إثم؟ وهل الغرة واجبة في هذه الحالة؟","title":"حكم من أجبر زوجته على إسقاط حملها","answer":"الجواب: عليها التوبة إلى الله، وعليه التوبة هو، كلاهما عليه التوبة، ولا عليهما شيء، عليهما التوبة إلى الله؛ لأن هذا عمد، عليهما التوبة إلى الله  الله يهديهم جميعًا، عليهم التوبة إلى الله. ولا يجوز إخراج الطفل بعدما يتجاوز الأربعين، ما يجوز التعرض له، بل يستعين بالله، ولعل الله يجعل فيه البركة، والخير، ما يدرون لعله يكون أبرك من الذي قبله، أما في الأربعين الأولى إذا دعت الحاجة إلى ذلك؛ فالأمر في هذا واسع عند جمع من أهل العلم، أما إذا جاوز الأربعين، وصار إلى العلقة؛ فلا يجوز التعرض له. السؤال: ولي الأمر هل عليه التعزير على ذلك إذا علم ذلك؟ الجواب: نعم لولي الأمر أن يعزر من فعل ذلك، لولي الأمر إذا عرف ذلك.","link":"https://binbaz.org.sa/fatwas/2899/حكم-من-اجبر-زوجته-على-اسقاط-حملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1347.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":7010,"question":"إذا قال الزوج عليه الحرام، ولا يقصد الطلاق، وكذلك لو قال: أنت علي حرام، وأراد الطلاق، فهل يكون طلاقًا؟","title":"حكم من يحرم امرأته على نفسه","answer":"الجواب:\n\nإذا قال: أنت علي حرام، وأراد الطلاق؛ فالصحيح أنه يكون طلاقًا، يكون طلقة واحدة على الصحيح، وإذا قال: عليه الحرام ما يفعل كذا، فله تفسيران:\n\nأحدهما: أن يقصد عليه الطلاق يعني: فعلى نيته إذا قصد الطلاق، وأنه إذا فعل كذا؛ وقع الطلاق، وقع الطلاق.\n\nأما إذا كان يقصد منع نفسه من هذا الشيء، عليه الطلاق ما يكلم فلانًا، عليه الطلاق ما تروحي لها، عليه الطلاق ما تكلمي فلانًا، بقصد منعها -ما قصده الطلاق- فهذا فيه خلاف بين أهل العلم، الصحيح أنه يكون في حكم اليمين، أن عليه كفارة يمين؛ لأن قصده المنع، ليس قصده الطلاق، والرسول ﷺ يقول: الأعمال بالنيات.\n\nفإذا كان قصده المنع، عليه الطلاق ما يكلم فلانُا، عليه الطلاق ما تروحي لأحد، عليه الطلاق ما تكلمي فلانًا، ما قصد إيقاع الطلاق، وإنما قصد تخويفها، ومنعها؛ فهذا الصواب فيه أنه عليه كفارة يمين.\n\nأما إذا قصد إيقاع الطلاق، منعها، وإيقاع الطلاق؛ فإنه يقع الطلاق طلقة واحدة، إلا إذا كرر عليه الطلاق، عليه الطلاق، عليه الطلاق، يقصد ثلاثًا وقعت الثلاث.","link":"https://binbaz.org.sa/fatwas/2941/حكم-من-يحرم-امراته-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1389.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7041,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7047,"question":"وآخر يسأل عن القات، هل هو حرام، أم غير حرام، وهو الذي يؤخذ في اليمن، وغيره؟","title":"حكم تناول القات","answer":"الجواب:\n\nالقات تنازع فيه علماء اليمن، وألفوا فيه من الجانبين، فقوم منهم حرموه، وألفوا فيه، وبينوا مضاره وخبثه، وأنه يعطلهم عن الصلاة، وعن أعمالهم الكثيرة في وقت طويل، وأن فيه مضار كثيرة، وألف آخرون منهم من إخواننا من علماء اليمن في ذلك أيضًا .. أخرى يدافعون عنه، ويزعمون أنه ليس بمحرم.\n\nوالصواب الذي عرفناه من علماء التحقيق، وعرفناه ممن شربه، وتعاطاه: أنه منكر، وأنه لا يجوز، وأنه محرم لما فيه من الضرر العظيم، والتعطيل للناس عند تعاطيهم ذلك، فإذا خزنوا؛ عطلوا مدة طويلة، وربما جمعوا بين الصلاتين من أجل ذلك -نسأل الله العافية-.\n\nوفيه مضار فيما ذكر إخواننا من علماء اليمن، وممن تعاطاه غيرهم فيه مضار كثيرة، وربما أسكر بعض الأحيان، ربما غير العقل بعض الأحيان، فالصواب: قول من قال بتحريمه.\n\nونصيحتي لإخواننا اليمنيين: أن يحذروه، وأن يتقوا الله في ذلك، وأن يحاربوا زراعته وتعاطيه، هذه نصيحتي لهم، وقد كتبنا في هذا بعض الشيء.","link":"https://binbaz.org.sa/fatwas/3051/حكم-تناول-القات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1443.mp3","categories":["الأخلاق المذمومة","الأطعمة والأشربة"]},{"id":7066,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7071,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7078,"question":"أنا أشتغل مدير شركة لتصدير الموكيت من أمريكا، وعندما يتفق مع التاجر يطلب مني أن أعطيه مهلة لتسديد المبلغ، فأعطيه تسعين يومًا، ولكن بضمان بنكي، فعند ذلك البنك يأخذ منه نسبة مقابل الضمان، فما حكم ذلك؟","title":"حكم أخذ البنك نسبة من المال مقابل الضمان","answer":"الجواب:\n\nأما الإمهال فأنت مشكور، إمهاله في قضاء ما عليه؛ حتى يتسهل له القضاء، أما مسألة الضمان البنكي فلا يزال فيه بعض الإشكال، الأصل فيه أنه المنع، هذا هو الأصل في الضمان البنكي؛ لأنه يأخذ هذه الزيادة في مقابل ما قد يسلمه من المال عن المضمون، فقد يكون هذا داخلًا في القرض الذي جر ربًا، جر زيادة، فإنه يسلم عنه مالًا بزيادة، فإذا تيسر أن يكون ضمانًا غير ربوي -يعني ضمان بدون زيادة- بالمعروف، وبالتطوع، لا بالزيادة؛ فلا إشكال فيه. \n\nأما الضمان البنكي بالزيادة التي يعرفها الناس الآن هو معروض على هيئة كبار العلماء، وقد أجل البحث فيه إلى دورة آتية، ولا يزال فيه بعض الإشكال؛ لأن ليس كل ضامن يسلم مالًا، قد يأخذه بمقابل ضمانه واستعداده للقضاء والتسليم، وقد يبذل مالًا، وقد لا يبذل مالًا، ويوفي المضمون، ولا يحتاج إلى البنك.\n\nفالحاصل: أن فيه نظرًا، والأصل فيه المنع، هذا هو الأصل فيما أعلم، الأصل فيه المنع؛ لأن الضامن إنما يطلب الزيادة من أجل ما يسلمه في المستقبل من المال حتى يأخذ الزيادة، يضمن ألفًا، ويأخذ شيئًا معلومًا في هذا الألف عشرة، أو عشرين، أو أكثر، أو أقل في مقابل هذا الذي ضمن، فهو في الحقيقة أخذ للزيادة في مقابل ما يسلمه، فكأنه قال: أسلم عنك ألفًا بألف وعشرة؛ فيقع في الربا، فينبغي تركه مهما أمكن. \n\nالسؤال: ...؟\n\nالجواب: الربا للضامن سواء من القيمة أو من غيرها.\n\nالسؤال: الإثم على البائع، أم على المشتري؟\n\nالجواب: عليهما جميعًا؛ لأنهما اشتركا.","link":"https://binbaz.org.sa/fatwas/3084/حكم-اخذ-البنك-نسبة-من-المال-مقابل-الضمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1466.mp3","categories":["الضمان والكفالة","الأخلاق المذمومة"]},{"id":7105,"question":"الأخ عرض هذا السؤال أكثر من مرة، ويلح علينا في عرضه، جدة زوجتي كانت عند مستشفى الشميس، ورغبت أن تركب تاكسي هي وأختها، وعندما أوقفت صاحب التاكسي؛ اتضح أنه قريب لها، وركبت هي وأختها معه، وأعطوه الأجرة، فرفض أن يأخذها منها، وحلفت بأن عليها صوم سنة كاملة بأن يأخذ الأجرة منها، ولكنه رفض، فما حكم هذا اليمين الذي حلفت على نفسها بأن تصوم سنة كاملة؟","title":"حكم من حلفت أن تصوم سنة كاملة","answer":"الجواب:\n\nعليها كفارة يمين، هذه يمين مكروهة، غير شرعية، وعليها كفارة يمين فقط؛ لأنه ما هو مقصودها الصوم، مقصودها تلزمه، فعليها كفارة يمين، إطعام عشرة مساكين، أو كسوتهم، ويكفي.","link":"https://binbaz.org.sa/fatwas/3134/حكم-من-حلفت-ان-تصوم-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1492.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7111,"question":"ما حكم من أقسم بالطلاق على أن شيئًا ما قد يحدث، وهو يعلم أنه لم يحدث، علمًا بأنه لم يكن يقصد الطلاق، أو ينويه؟","title":"حكم الإقسام بالطلاق من دون قصد الطلاق","answer":"الجواب:\n\nإذا حلف بالطلاق على أن هذا حدث ليصدق، ما قصد إيقاع الطلاق، ولكن قصد ليصدق، فقد أخطأ وكذب، وعليه التوبة إلى الله، وعليه كفارة يمين؛ لأنه ما قصد إيقاعه، إنما قصد أن يصدق، أو قصد أن يفعل هذا الفعل.\n\nقال: عليه الطلاق من امرأته، عليه الطلاق أن تكلمي فلانًا أو فلانًا، عليه الطلاق أن تشتري هذا، عليه الطلاق أن تخرجي لكذا وكذا، قصده أمرها بهذا الشيء، وتكليفها به، وتخويفها، وليس قصده إيقاع الطلاق، هذا حكمه حكم اليمين، فيه كفارة يمين على الصحيح، فيه خلاف بين العلماء، لكن هذا هو المختار.\n\nالسؤال: يعني إذا كذب يكفر كفارة يمين إذا كان كاذبًا في هذا اليمين؟\n\nالجواب: قصده التصديق ليس قصده إيقاع الطلاق.","link":"https://binbaz.org.sa/fatwas/3140/حكم-الاقسام-بالطلاق-من-دون-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1498.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7126,"question":"رجل يعمل في إدارة، فساعد رجلًا لتخليص عمله في تلك الإدارة، وأهدى هذا الرجل للرجل الذي يعمل في الإدارة كتبًا بعد إنجاز العمل، علمًا أن هذه الكتب كتب عليها: وقف لله تعالى، نرجو من سماحتكم الرد على هذا، هل هذه رشوة، أو ما هي؟","title":"حكم الهدية مقابل خدمة معاملة في مكتب إدارة","answer":"الجواب:\n\nالموظف الذي يسعى في تخليص معاملة أخيه لا يأخذ رشوة، ولا يأخذ مالًا، ولا يأخذ عطية؛ لأن هذه في الغالب تكون رشوة باسم الهدية، ولو أنها كتب موقوفة لا يأخذ منها شيئًا أبدًا؛ لأنها في الغالب تكون رشوة، ومساعدة له حتى يعطل عمل غيره، ويقدم هذا الرجل، أو يعطيه أشياء بغير حق، ويعمل له بغير حق، فلا يعطي الموظف شيئًا أبدًا.","link":"https://binbaz.org.sa/fatwas/3164/حكم-الهدية-مقابل-خدمة-معاملة-في-مكتب-ادارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1522.mp3","categories":["الهبة والعطية","الأخلاق المذمومة"]},{"id":7137,"question":"رجل تزوج، وذهبت الزوجة بيت أبيه لقصد وضع الحمل، وبعد وضع الحمل (في السبوع) وقعت مشاجرة بين الزوجات بالتلفون، وطلق الزوج أربعة طلقات وأكثر، وهو في حالة انفعال، ثم بعد يومين قال: أرجعت زوجتي إلى عصمة نكاحي على ما تبقى لي من الطلاق، وأشعرت الزوجة في الرجوع علمًا أن الجميع موافقين للرجوع، وإنما الأب طلب إفتائي من الناحية الدينية، لذا أرجو إفادتي وشكرًا. ملاحظة: الزوج عنده حالة نفسية، وعند الانفعال، يتكلم ولم يشعر بشيء، وقد راجع الأطباء بذلك، ولا فائدة.","title":"حكم الطلاق في الحيض والنفاس","answer":"الجواب:\n\nالطلاق في النفاس، وفي الحيض الصحيح أنه لا يقع؛ لأنه طلاق محرم، فلا يقع، والنبي ﷺ لما طلق ابن عمر في الحيض أنكر عليه، وأمره أن يمسكها حتى تحيض، ثم تطهر، ثم تحيض، ثم تطهر، ثم إذا شاء طلقها قبل أن يمسها، وقال له -عليه الصلاة والسلام-: تلك العدة التي أمر الله أن تطلق لها النساء لقوله : يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1]\n\nالمعنى طلقوهن طاهرات من غير جماع، أو حبالى، فالطلاق المشروع إنما يكون في حال كونها حاملاً، طلاق الحامل طلاق مشروع، أو يطلقها في حال كونها طاهرًا طهرًا لم يجامعها فيه، هذا هو معنى قوله فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] يعني طاهرات من غير جماع، أو في حال الحمل، هذا هو الطلاق الشرعي، أما كونه يطلقها في حال الحيض، أو في حال النفاس فهذا طلاق منكر، فلا يجوز، أما ما يتعلق.. \n\nالسؤال: يعني لا يقع؟ \n\nالجواب: لا يقع، فهي باقية على حالها زوجة له، وعليه أن يتوب إلى الله من عمله، أما ما يتعلق بشدة غضبه، وتغير حاله، هذا له بحث آخر، لكن هذا يكفي ما دام طلقها في هذه الحال؛ فهو طلاق لاغٍ.","link":"https://binbaz.org.sa/fatwas/3166/حكم-الطلاق-في-الحيض-والنفاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1524.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":7149,"question":"قوله: أنت علي حرام كحرمة البنت على أبيها، أرجو من سماحتكم إفادتي ماذا يلزمني في هذا، وما هي كفارة هذا اليمين، جزاكم الله خيراً؟","title":"حكم قول أنت علي حرام","answer":"الجواب:\n\nبسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\n\nفهذه العبارة وأشباهها على الصحيح من أقوال أهل العلم تعتبر ظهارًا، لها حكم الظهار الذي بينه الله في كتابه العظيم في سورة المجادلة، فإذا قال لزوجته أنت علي حرام كبنتي، أو أختي، أو أنت علي حرام، وأطلق، فهذا حكمه حكم الظهار؛ فعليه التوبة إلى الله من ذلك؛ لأن هذا منكر وزور، ما هي عليه حرام، الله أحلها له بالعقد الشرعي.\n\nفقوله إنها عليه حرام غلط منه، ولا يجوز له ذلك، ومنكر، فالواجب عليه التوبة من ذلك، ولهذا يقول سبحانه: وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا [المجادلة:2] وعليه الكفارة التي بينها الله في كتابه العظيم، وهي عتق رقبة مؤمنة، فإن عجز؛ صام شهرين متتابعين، ستين يومًا، فإن عجز؛ أطعم ستين مسكينا لكل مسكين، نصف صاع من قوت البلد، من تمر أو أرز أو بر أو غير ذلك، وإن أطعم أكثر من ذلك؛ فلا بأس.\n\nالمقصود: أنه لا بد أن يطعم ستين مسكينًا، يعشيهم، أو يغديهم، أو يعطيهم نصف صاع من قوت البلد، وإذا كان معه إدام؛ كان أفضل، وهذا كله على الترتيب، هذا على الترتيب ليس على التخيير. \n\nأولًا: العتق إذا تيسر، فإن لم يتيسر؛ فالصيام، فإن عجز عن ذلك لأسباب تقتضي ذلك؛ انتقل إلى الإطعام قبل أن يمسها، لا يقربها لا بقبلة ولا بجماع، لا يستمتع بها بشيء حتى يؤدي هذه الكفارة مع التوبة الصادقة النصوح إلى الله سبحانه من هذا العمل؛ لأن الله قال: مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3].\n\nالسؤال: ولا يغني قيمة المال عن الإطعام؟\n\nالجواب: ولا يغني القيمة لا. الواجب العتق، ثم الصيام، ثم الإطعام.","link":"https://binbaz.org.sa/fatwas/3188/حكم-قول-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1546.mp3","categories":["الظهار","الأخلاق المذمومة"]},{"id":7150,"question":"ذهبت زوجتي بدون إذني لزيارة أختها، فغضبت، وقلت لها: إذا ذهبت بدون إذني؛ فأنت طالق، ثم طالق، ثم طالق، وبعد فترة ذهبت مع أهلها، وأنا غير موجود، فهل يقع الطلاق؟ والآن أريد أن أتحلل، هل علي كفارة، أم ماذا أفعل؟","title":"حكم الطلاق بالثلاث في وقت واحد","answer":"الجواب:\n\nهذا يختلف إذا كنت قلت هذا لمنعها، ما قصدت الطلاق، إنما قصدت منعها، وتخويفها، فهذا يمين، عليك كفارة يمين إذا ذهبت بغير إذنك.\n\nأما إن كنت أردت الطلاق؛ فإنه يقع الطلاق ثلاث طلقات، طالق، ثم طالق، ثم طالق، إذا كنت أردت إيقاع الطلاق، إذا فعلت؛ فقد حرمت عليك حتى تنكح زوجًا غيرك.","link":"https://binbaz.org.sa/fatwas/3183/حكم-الطلاق-بالثلاث-في-وقت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1541.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7151,"question":"أرى في المجتمع نساء أجنبيات يظهرن وجوههن في أجمل زينة، فهل يجوز أن نلعنها لقوله: تخرج المرأة زانية وتعود زانية؟","title":"حكم لعن المرأة المتبرجة","answer":"الجواب:\n\nليس لك أن تلعنها، ولكن تدعو لها بالهداية، وتنكر عليها المنكر، ولا تلعنها، لا تعن عليها الشيطان، لكن تدعوها إلى الخير، وتنكر عليها المنكر، وتقول: يا أمة اتقي الله، تستري، احتجبي، وتدعو لها بالهداية، وإن كان معها زوج، أو ولي تنصحه، هكذا ينبغي للمؤمن. \n\nالسؤال: إذا كانت كافرة؟\n\nالجواب: ولو كافرة، يؤمر وليها بأن يحجبها في بلاد المسلمين، ويطلب من ولاة الأمور كذلك؛ حتى لا تضر المجتمع، وحتى لا يتأسى بها المسلمات.","link":"https://binbaz.org.sa/fatwas/3178/حكم-لعن-المراة-المتبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1536.mp3","categories":["الدعوة والدعاة","الأخلاق المذمومة"]},{"id":7218,"question":"نرجو من سماحتكم بمناسبة هذا الجمع الكريم أن توجهوا كلمة، ونصيحة لمن اتخذ التمثيل، والقصص الخيالية سبيلاً إلى الدعوة إلى الله، لأن كثيرًا من الشباب الصالح -جزاهم الله خيرًا- يفعلون هذا الآن؟","title":"حكم التمثيل والقصص الخيالية لغرض دعوي","answer":"الجواب:\n\nقد سبق منا غير مرة أن التمثيل لا يصلح، وأنه كذب، كون الإنسان يمثل نفسه أنه عمر بن الخطاب، أو أنه أبو جهل، أو أنه أبو لهب، أو أنه فلان، أو أنه فلان، لا يصح، الواجب أن تكون الدعوة والتعليم والتوجيه على الطريقة التي سلكها العلماء، وسلكها أصحاب النبي ﷺ وأتباعهم.\n\nيقوم المعلم، أو المرشد، أو الواعظ فيذكر بالله، وبحقه، ويحذر من غضبه، ولا يحتاج أن يقول: أنا فلان، وأنا فلان، يمثل نفسه بأنه فلان، أو فلان؛ لأن هذا كذب، ولو كان قصد خيرًا.\n\nوكذلك إحداث القصص التي لا أساس لها، يخشى أن تكون من الكذب، ينبغي له أن يوضح للناس ما هو واضح، وما هو بين من أمر الخير، وما هو بين من أمر الشر؛ حتى يحذروا الشر، وحتى يرغبوا في الخير بالآيات والنصوص التي جاءت عن رسول الله -عليه الصلاة والسلام-.\n\nيعني يكفي المؤمن في تعليمه وفي وعظه وتذكيره ما كفى الأولين، مع البعد عن الكذب الذي هو التمثيل، أو القصص التي لا أساس لها .. قصص غير واقعة، جرى كذا، وجرى كذا، فلان صار له كذا، وصار له كذا، وهو ما له حقيقة، فلانة صار لها كذا، وصار لها كذا، وهي ما لها حقيقة. أخشى أن يكون هذا من الكذب الذي نهى الله عنه. \n\nيقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك به القوم، ويل له، ثم ويل له هكذا الذي يحدث ليزجر القوم، أو ليعظ القوم فيكذب، أخشى عليه من هذا، هذا هو الذي ظهر لي.","link":"https://binbaz.org.sa/fatwas/3267/حكم-التمثيل-والقصص-الخيالية-لغرض-دعوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1595.mp3","categories":["الأخلاق المذمومة","الدعوة والدعاة"]},{"id":7222,"question":"عن الاختلاف الطبقي الذي نعيشه في مجتمعنا هنا تحت ما يسمى بقبيلي وخضيري وحر وصانع، فهذه النظرة المريضة هدمت الكثير من البيوت، وأفشلت العديد من الزيجات، كما أنها أدت إلى التنافر والتناحر بين أبناء المجتمع الواحد في بعض المناطق، سماحة الشيخ نرجو أن توضح لأصحاب هذه الاعتقادات خطورة هذه القضية، وتعارضها مع تعاليم ديننا الحنيف؟","title":"موقف الإسلام من التمييز العنصري","answer":"الجواب:\n\nهذه الأمور ينبغي للمجتمع الإسلامي أن يتجاوزها، وأن يرفضها، وأن يتركها، لقوله -جل وعلا-: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\n\nوالنبي ﷺ وأصحابه تجاوزوها، وضربوا للناس أروع الأمثال في هذه المسائل، فزوج -عليه الصلاة والسلام- فاطمة بنت قيس وهي قرشية على أسامة بن زيد وهو عتيق، وتزوج أبوه زينب بنت جحش، وهي أسدية وأمها عمته -عليه الصلاة والسلام- ولما طلقها زيد أخذها النبي ﷺ وزيد مولاه وعتيقه، وكذلك بلال تزوج زهرية أخت عبدالرحمن بن عوف، وهو حبشي عتيق. \n\nفهذه مسائل اعتنى الصحابة -رضي الله عنهم وأرضاهم- ونبينا قبل ذلك -عليه الصلاة والسلام- بما يزيلها؛ لأن العرب كانت تعظم هذه الأمور، وكانت العرب تأبى أن تزوج بناتها على الموالي، وعلى العجم، ولكن جاء الإسلام بأنه لا حرج في ذلك، والحمد لله. \n\nأن يزوج عجميًّا أو مولى عتيقًا، أو ما يسمى بالخضيري، وهو الذي لا تعرف قبيلته في اصطلاح الناس هنا في نجد، وفي بعض الجهات أن الذي لا تعرف قبيلته هل هو تميمي، أو قحطاني، أو قرشي، أو كذا يقال له: خضيري، فإذا عرفت قبيلته؛ قيل له عربي، والمولى هو الذي يعتق، يكون عتيقًا، والعجمي هو الذي ليس من العرب، من الروم، أو من فارس، أو من الأتراك يقال له: عجمي.\n\nوالذي جاء به الإسلام أنه لا فرق بين هؤلاء إذا استقام الدين، فإذا تزوج العربي من التركية، أو من الرومية، أو من الفارسية، أو غير ذلك مع استقامة الدين؛ فلا بأس، أو تزوج عتيقة قد كانت مملوكة، ثم أعتقت، أو تزوج ما يسمى خضيرية، أو الخضيري تزوج قرشية، أو ما أشبه ذلك، كله لا بأس بهذا، إنما المهم التقوى والإيمان كما قال : يَاأَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا [الحجرات:13].\n\nلكن بعض الناس قد يتأذى بهذا؛ لأن جماعته وأقاربه يأبون عليه ذلك، ويقولون: لا، فإذا كان يحصل عليه مضرة؛ فلا مانع من أن يمتنع من ذلك حتى يزوج من العرب إذا كان عربيًا، أو كان من حمولته إن كان روميًّا، أو أعجميًا، إذا كانت جماعته يشقون عليه ويؤذونه، فهو يراعي عدم الأذى وكف الأذى، هذه أمور قد يؤذى فيها الإنسان الولي إذا تساهل من جماعاته، فإذا كان فيه أذى؛ فيتقي الأذى، ويترك الشيء الذي هو الأولى لما يدفعه من الأذى. \n\nالسؤال: ويطلقها إذا كان قد تزوجها يعني؟ \n\nالجواب: التطليق شيء آخر، إن تسامحا، وإلا يرجعا إلى المحكمة، لكن في بادئ الأمر.","link":"https://binbaz.org.sa/fatwas/3285/موقف-الاسلام-من-التمييز-العنصري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1610.mp3","categories":["الأخلاق المذمومة","مسائل متفرقة في العقيدة"]},{"id":7229,"question":"معظم أقاربي من والدي المتوفيين، وكذلك أقارب زوجتي تعودوا على الاختلاط بين الرجال والنساء، واعتبروا ذلك منهاجًا وعرفًا، فالرجال يصافحون النساء، ويجلسون معهم، ولذلك لا أذهب إليهم مع زوجتي أبدًا، حاولت أن أذهب وحدي حتى أصلهم، ولكن أخذت نساؤهم يحاولن مصافحتي من باب المضايقة؛ لعلمهن بأنني لا أصافح النساء، وبدؤوا يعملون أشياء تضايقني، فامتنعت أنا أيضًا عن زيارتهم.والآن هناك بيننا شبه قطيعة، وأخشى على نفسي من أن أدخل ضمن قاطع الرحم، وفي نفس الوقت لا أستطيع التصرف، ماذا أفعل بارك الله فيكم؟","title":"حكم مصافحة النساء الأجنبيات والنظر إليهن","answer":"الجواب:\n\nلست بقاطع يا أخي هم القاطعون، أنت لست بقاطع هم القاطعون، من أدام المنكر، وثبت على المنكر، وأبى أن يقبل؛ فهو القاطع، ما هو أنت.\n\nإن استطعت أن تنصحهم من دون مصافحة للنساء، ومن دون نظر إلى النساء الكاشفات، تغض بصرك، ولا تصافح، وتنصح، وتقول الحق؛ فافعل، واجتهد، فإن لم تستطع؛ فأنت معذور، وهم القاطعون، ولست بقاطع أنت.","link":"https://binbaz.org.sa/fatwas/3305/حكم-مصافحة-النساء-الاجنبيات-والنظر-اليهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1630.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":7242,"question":"أقسمت على زوجتي ألا تحضر فرح بنت خالتي، أو بنت خالتها، وقلت لها: لو حضرت لا تجلسين معي في البيت مرة أخرى، ولكن عندما سافرت من اليمن إلى السعودية علمت أنها حضرت هذا الفرح؛ علمًا بأنه في بلد آخر، فما موقفي جزاكم الله خيرًا؟","title":"حكم من أقسم على زوجته أن لا تحضر عرساً فحضرته","answer":"الجواب:\n\nإذا كنت أردت الطلاق، وأنها تطلق بذلك؛ يقع طلقة، وإن كنت ما أردت الطلاق وإنما أردت تخويفها، وتحذريها؛ فليس عليك شيء، وإنما عليك كفارة يمين.","link":"https://binbaz.org.sa/fatwas/3299/حكم-من-اقسم-على-زوجته-ان-لا-تحضر-عرسا-فحضرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1624.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7276,"question":"من خطر اللسان قول بعضهم: وحياة الله، أو قاتلك الله، فما حكم ذلك؟","title":"حكم الحلف بحياة الله","answer":"الجواب:\n\nهذا الكلام فيه تفصيل: اللسان أخطاؤه كثيرة، وأغلاطه كثيرة، لكن (وحياة الله) ليس من أخطاء اللسان، هذا قسم بالله، إذا قلت: وحياة الله، أو وعلم الله، أو وعزة الله، أو وقدرة الله، فهذا من الأيمان الشرعية؛ لأن الحلف بالله وبصفاته حلف شرعي.\n\nأما قول: قاتلك الله، أو لعنك الله، أو أخزاك الله، هذا منكر، هذه من آفات اللسان -نعوذ بالله- فذكر الله، والحلف بأسمائه، هذا ليس من آفات اللسان، بل هذا من فضائل اللسان، ومن خصاله الطيبة أن يذكر الله، وأن يثني عليه، وأن يشكره سبحانه، وهكذا الحلف به عند الحاجة للحلف يحلف به سبحانه.\n\nلكن من آفات اللسان الحلف بغير الله، هذا من آفاته، كأن يقول: والنبي، والكعبة، والأمانة، وشرف فلان، وحياة فلان، وحياتك، هذا هو المنكر، هذا من آفات اللسان، الحلف بغير الله كائنًا من كان، يقول النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وفي اللفظ الآخر: فلا يحلف إلا بالله أو ليصمت ويقول ﷺ: من حلف بغير الله؛ فقد كفر، أو أشرك الشك من الراوي، هل قال: كفر، أو قال: أشرك؟ هذا يدل على أن الحلف بغير الله من جملة أنواع الكفر، نسأل الله العافية. \n\nفالواجب الحذر من ذلك، وألا تحلف إلا بربك  وقال أيضًا -عليه الصلاة والسلام-: من حلف بالأمانة فليس منا وقال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون.\n\nالسؤال: وحياة الله؟\n\nالجواب: الحياة من صفاته هو الحي القيوم سبحانه.","link":"https://binbaz.org.sa/fatwas/3341/حكم-الحلف-بحياة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1662.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7277,"question":"ما حكم الكذب إذا كان كذبًا بسيطًا مثل: أن أكذب على أحد، دون أن أفقد صداقته؟","title":"خطورة التهاون في الكذب","answer":"الجواب:\n\nتقول أم كلثوم بنت عقبة ابن أبي معيط -رضي الله عنها-: لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: في الإصلاح بين الناس، وفي الحرب، وفي حديث الرجل امرأته، والمرأة زوجها، هذا المستثنى.\n\nفالإصلاح بين الناس، وفي الحرب، والحرب خدعة، وفيما بين الرجل وزوجته، يحدثها وتحدثه بأشياء غير حقيقة لما في هذا من إصلاح الحال بينهما، وتثبيت العشرة بينهما فيما لا يضر أحدًا من الناس، هذه الأشياء التي رخص فيها النبي ﷺ من الكذب.\n\nوأما غير هذه الثلاث فينبغي التحرز من الكذب، والحذر منه، وأن يعتني الإنسان بالصدق في أقواله، وفي أعماله، وأن يكون من ديدنه الصدق، ومن عادته الصدق في أموره، اللهم إلا أن يكون الصدق يجر عليه شرًا، ويسبب فتنًا، فهذا له بحثه، وله شأنه في محله، فإذا كان ظالم يسأل عن إنسان ليقتله، أو ليظلمه؛ فليس له الصدق في هذا، أن يقول: هو في المحل الفلاني، يقول: ما أدري؛ حتى لا يضر أحدًا، وإن كان يدري، إذا كان يعرف أن هذا السائل يضر هذا المسؤول عنه لو علم بمكانه ظلمًا وعدوانًا، فهذا من الكذب الواجب، وكذلك الذي يصلح بين الناس، فيقول خيرًا، أو ينمي خيرًا.\n\nالمقصود: أن الكذب في هذه الثلاثة لا بأس، وهكذا الكذب فيما دل الشرع على جوازه فيه لحماية المسلمين من الشر، ولحمايتهم من عدوهم، أو لحماية المسلم من ظلم من يظلمه، ويتعدى عليه، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/3352/خطورة-التهاون-في-الكذب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1673.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7279,"question":"منذ ثلاثة أيام تقريبًا مضتْ دار بيني وبين زوجتي خلاف لدرجة في هذا اليوم صرت عصبيًّا جدًا لدرجة لا أتخيله، فمسكت الحذاء -أعزكم الله- فضربت زوجتي به، يعني فقدت وعيي بالمرة رغم أنها حامل في الشهر السادس، ومعي ابنة عمرها سنتين في هذه الظروف الصعبة، وقالت لي زوجتي: طلقني -وكنت غضبان- فقلت لها: أنت طالق طالق طالق، قلتها أكثر من مرة، ولا أدري ما العدد بالضبط، ولكنني متأكد تمامًا أنها أكثر من مرة، والآن أنا في حيرة، زوجتي تبكي بالبيت، ولا تريد الفراق بعيدًا عني، كذلك أنا، فأفيدوني ماذا أعمل؛ لأني لا أنام الليل؟","title":"حكم الطلاق بأكثر من مرة في حالة الغضب","answer":"الجواب: \n\nهذا من الشيطان -نسأل الله أن يعيذنا وإياكم من الشيطان- كان الواجب عليك التثبت، وعدم العجلة في الأمور، والاستعاذة بالله من الشيطان، هذا يحتاج إلى أن تأتينا في البيت، إن شاء الله غدًا ننظر في الأمر، أو يوم السبت، كذلك لا بأس، ننظر في الموضوع معك، أو مع المرأة ووليها، لا بد من النظر في الموضوع، إن شاء الله ولا يحصل إلا الخير.","link":"https://binbaz.org.sa/fatwas/3342/حكم-الطلاق-باكثر-من-مرة-في-حالة-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1663.mp3","categories":["الطلاق","الأخلاق المذمومة","قضايا المرأة"]},{"id":7280,"question":"هل يعد التقليد بالحركات، أو بالصوت، أو بالكلام من الغيبة؟ وإذا كان من الغيبة فإن المغتاب إذا قيل له: لا تغتاب قال: هذا ما يفعله أو يقوله فلان؟","title":"حكم الغيبة بالحركات أو بالصوت","answer":"الجواب:\n\nنعم الغيبة تكون بالكلام، وتكون بالفعال، بالكلام إذا قال فلان كذا ما يكره، وتكون الغيبة بالفعل إذا أشار إليه، وعرف الناس أنه يريده، إذا كان يمشي مشيته، أو يتكلم بكلام على سبيل العيب له، والاستهزاء به، أو ما أشبه ذلك من الإشارات التي يراد منها تحقيره، ويراد منها ذمه، فهذا غيبه بالفعل، -نسأل الله العافية- وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","link":"https://binbaz.org.sa/fatwas/3353/حكم-الغيبة-بالحركات-او-بالصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1674.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7281,"question":"هل يعد التقليد بالحركات، أو بالصوت، أو بالكلام من الغيبة؟ وإذا كان من الغيبة فإن المغتاب إذا قيل له: لا تغتاب قال: هذا ما يفعله أو يقوله فلان؟","title":"حكم الغيبة بالحركات أو بالصوت","answer":"الجواب:\n\nنعم الغيبة تكون بالكلام، وتكون بالفعال، بالكلام إذا قال فلان كذا ما يكره، وتكون الغيبة بالفعل إذا أشار إليه، وعرف الناس أنه يريده، إذا كان يمشي مشيته، أو يتكلم بكلام على سبيل العيب له، والاستهزاء به، أو ما أشبه ذلك من الإشارات التي يراد منها تحقيره، ويراد منها ذمه، فهذا غيبه بالفعل، -نسأل الله العافية- وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","link":"https://binbaz.org.sa/fatwas/3353/حكم-الغيبة-بالحركات-او-بالصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1674.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7288,"question":"إذا كان الشخص في جماعة -يعني مع ناس- وعلق على شخص منهم، علق يعني معناه: تكلم بشيء ليس بصحيح، يريد إضحاك الجماعة، والشخص عن ذلك لم يرض، فما حكم ذلك؟","title":"حكم الكذب على شخص لإضحاك الناس","answer":"الجواب:\n\nليس له أن يعلق شيئًا يؤذي بعض الحاضرين، أو يكون كذبًا، أو يكون مغضبًا لله  ولو أراد الإضحاك.\n\nيقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك القوم، ويل له، ثم ويل له ما يجوز للإنسان أن يتكلم بالباطل ليضحك الناس، عليه أن يصون لسانه، وألا يعلق شيئًا يضحك الناس، وهو لا يجوز في نفسه إما كذب، وإما سب لأحد، وإما استهزاء بأحد، كل هذا منكر.","link":"https://binbaz.org.sa/fatwas/3345/حكم-الكذب-على-شخص-لاضحاك-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1666.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7395,"question":"بعد صلاة العصر يأتي أشخاص، ويحجزون أماكن في المسجد الجامع للمحاضرة، ثم يذهبون إلى السوق، إلى خارج المسجد قبل أذان المغرب، فيأتون في أماكنهم المحجوزة، هل هذا العمل صحيح منهم؟","title":"حكم حجز مكان في الصف الأول","answer":"الجواب:  لا يجوز هذا العمل، الحجز في الصف الأول وهو يذهب لا، هذا ما يجوز، الصف الأول لمن تقدم بنفسه، لا لمن قدم نعليه، أو عصاه، أو ظرف، أو كذا أو كذا، لا، الواجب أن يتقدم بنفسه، ويجلس هو، فإذا تقدم بعصاه الذي يأتي يزيلها، ويجلس مكانه، ليس له أن يتقدم بغير جسمه، المسابقة تكون بالجسم، يتقدم ويجلس في الصف، ويسبح الله، ويذكره، أو يقرأ القرآن وينتظر الصلاة، أما أن يضع شيئًا ويذهب إلى السوق، فإذا جاء الأذان جاء، هذا منكر لا يجوز.  فالواجب على المسلم ترك ذلك، وأن يدع الصف الأول لمن تقدم بنفسه ليجلس في الصف، وينتظر الصلاة، ولا يتقدم بمجرد عصا، أو غيرها من الأشياء التي يضعها في مكانه -نسأل الله الهداية للجميع-. السؤال: وإذا ذهب للوضوء؟ الجواب: هذا فتح باب، يروح يتوضأ وإذا عاد الحمد لله يجلس في المكان الثاني؛ لأن هذا فتح باب، كل واحد يتعذر بهذا، العذر أنا رحت أتوضأ، وأنا رحت أسوي كذا، الحمد لله هو على نيته الطيبة، والحمد لله، وإلا هو أحق به إذا قام يتوضأ ولا جلس، ولكن عرض له عارض، أما أن يأتي وهو ليس متوضئًا، ويحط، ويذهب يتوضأ، لا، يتوضأ قبل ما يأتي. أما إذا كان جالسًا، ولكن عرض له عارض، وذهب يتوضأ؛ فهو أحق بمكانه، من قام من موضعه، ثم عاد إليه؛ فهو أحق به، لكن بعض الناس قد يفعل هذا وهو ما جاء متوضئَا، إنما جاء ناويًا أن يحط هذه العصا، ويذهب، فهذا ما يصلح. السؤال: إذا كان جالسًا في المسجد، ويتقدم، أو يتأخر وهو حاجز مكانًا؟ الجواب: لماذا يتأخر عن مكانه؟ السؤال: يريد يذكر، أو كذا. الجواب: كل هذا تركه أولى؛ لأنه يفتح باب للآخرين، لو ترك ذلك والحمد لله، ولو كان في طرف الصف إذا جاء أولى من وضعه، وإلا هو ما يكون متحجرًا؛ لأنه متقدم، لكن كونه يبتعد عن الصف؛ قد يفتح بابًا لغيره، كل واحد يدعي هذه الدعوى يقول: أنا ما ذهبت، أنا ما رحت، أنا ما فعلت، يختلط الحابل بالنابل، وتقع المشكلة، وتبقى هذه البدعة. السؤال: لو قدر الله أصابه ريح، أو حاجة، وذهب، ورجع في محله ما في بأس؟ الجواب: لا مانع نعم، إذا كان جلس أولًا، جاء متطهرًا، هو ناوي الجلوس، ولكن عرض له هذا العارض، أما واحد يأتي من بيته، ما عنده نية إلا يذهب، يعني ما توضأ ويحط هذا، ويقول: أروح أتوضأ.","link":"https://binbaz.org.sa/fatwas/3483/حكم-حجز-مكان-في-الصف-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1787.mp3","categories":["المساجد ومواضع السجود","الأخلاق المذمومة"]},{"id":7404,"question":"نذرت بهذا اللفظ، وخاطبت مجموعة من الناس كانوا جلوسًا عندي قلت لهم: إن لكم علي أربع من الغنم، وكان في النية أن أذبحها لهم، ولكن هؤلاء الناس تفرقوا، ولم يبق منهم إلا القليل، فهل يجوز لي أن أصرفه إلى الفقراء، وهل يجوز أن آكل منه، مع أنه كان في النية أن أعزم هؤلاء، والغالب عندي أن آكل من هذا النذر، فما رأي سماحتكم؟","title":"الوفاء بالنذر وما يتعلق به","answer":"الجواب:  إذا نذرت أن تذبحها لهم وأبوا؛ عليك كفارة يمين؛ لأن المقصود إكرام الضيف، المقصود من هذا إكرام الضيف، إذا قلت: والله نذر لوجه الله أن أذبحها لكم، أو والله لأذبحها لكم، أو علي الحرام أن أذبحها لكم، وأبوا؛ عليك كفارة يمين في هذا؛ لأن هذا ما هو مقصودك التقرب إلى الله، مقصودك إكرامهم هم، فإذا أبوا وعاندوك؛ فعليك كفارة يمين، بخلاف ما لو قلت: لله علي أن أتصدق بناقة، أو أتصدق بخروف، أو أتصدق ببقرة، فهذا نذر لله، عليك أن تؤده لقول النبي ﷺ: من نذر أن يطيع الله فليطعه.  وأما قولك: نذر عليَّ أن أذبح لكم، أو والله أذبح لكم، أو عليَّ الحرام أن أذبح لكم، مقصودك إكرامهم، وتلزيمهم، فأبوا؛ فعليك كفارة يمين، ويبقى مالك لك، فإن ذبحتها وتصدقت بها فلا بأس. ولا بأس أن تأكل منها إذا ذبحتها؛ لأن قصدك أن تأكل أنت وأهل بيتك مع الضيوف، إذا ذبحتها، وتصدقت منها، وأكلت منها أنت وأهل بيتك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3476/الوفاء-بالنذر-وما-يتعلق-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1780.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7414,"question":"بعد صلاة العصر يأتي أشخاص، ويحجزون أماكن في المسجد الجامع للمحاضرة، ثم يذهبون إلى السوق، إلى خارج المسجد قبل أذان المغرب، فيأتون في أماكنهم المحجوزة، هل هذا العمل صحيح منهم؟","title":"حكم حجز مكان في الصف الأول","answer":"الجواب:  لا يجوز هذا العمل، الحجز في الصف الأول وهو يذهب لا، هذا ما يجوز، الصف الأول لمن تقدم بنفسه، لا لمن قدم نعليه، أو عصاه، أو ظرف، أو كذا أو كذا، لا، الواجب أن يتقدم بنفسه، ويجلس هو، فإذا تقدم بعصاه الذي يأتي يزيلها، ويجلس مكانه، ليس له أن يتقدم بغير جسمه، المسابقة تكون بالجسم، يتقدم ويجلس في الصف، ويسبح الله، ويذكره، أو يقرأ القرآن وينتظر الصلاة، أما أن يضع شيئًا ويذهب إلى السوق، فإذا جاء الأذان جاء، هذا منكر لا يجوز.  فالواجب على المسلم ترك ذلك، وأن يدع الصف الأول لمن تقدم بنفسه ليجلس في الصف، وينتظر الصلاة، ولا يتقدم بمجرد عصا، أو غيرها من الأشياء التي يضعها في مكانه -نسأل الله الهداية للجميع-. السؤال: وإذا ذهب للوضوء؟ الجواب: هذا فتح باب، يروح يتوضأ وإذا عاد الحمد لله يجلس في المكان الثاني؛ لأن هذا فتح باب، كل واحد يتعذر بهذا، العذر أنا رحت أتوضأ، وأنا رحت أسوي كذا، الحمد لله هو على نيته الطيبة، والحمد لله، وإلا هو أحق به إذا قام يتوضأ ولا جلس، ولكن عرض له عارض، أما أن يأتي وهو ليس متوضئًا، ويحط، ويذهب يتوضأ، لا، يتوضأ قبل ما يأتي. أما إذا كان جالسًا، ولكن عرض له عارض، وذهب يتوضأ؛ فهو أحق بمكانه، من قام من موضعه، ثم عاد إليه؛ فهو أحق به، لكن بعض الناس قد يفعل هذا وهو ما جاء متوضئَا، إنما جاء ناويًا أن يحط هذه العصا، ويذهب، فهذا ما يصلح. السؤال: إذا كان جالسًا في المسجد، ويتقدم، أو يتأخر وهو حاجز مكانًا؟ الجواب: لماذا يتأخر عن مكانه؟ السؤال: يريد يذكر، أو كذا. الجواب: كل هذا تركه أولى؛ لأنه يفتح باب للآخرين، لو ترك ذلك والحمد لله، ولو كان في طرف الصف إذا جاء أولى من وضعه، وإلا هو ما يكون متحجرًا؛ لأنه متقدم، لكن كونه يبتعد عن الصف؛ قد يفتح بابًا لغيره، كل واحد يدعي هذه الدعوى يقول: أنا ما ذهبت، أنا ما رحت، أنا ما فعلت، يختلط الحابل بالنابل، وتقع المشكلة، وتبقى هذه البدعة. السؤال: لو قدر الله أصابه ريح، أو حاجة، وذهب، ورجع في محله ما في بأس؟ الجواب: لا مانع نعم، إذا كان جلس أولًا، جاء متطهرًا، هو ناوي الجلوس، ولكن عرض له هذا العارض، أما واحد يأتي من بيته، ما عنده نية إلا يذهب، يعني ما توضأ ويحط هذا، ويقول: أروح أتوضأ.","link":"https://binbaz.org.sa/fatwas/3483/حكم-حجز-مكان-في-الصف-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1787.mp3","categories":["المساجد ومواضع السجود","الأخلاق المذمومة"]},{"id":7419,"question":"نذرت بهذا اللفظ، وخاطبت مجموعة من الناس كانوا جلوسًا عندي قلت لهم: إن لكم علي أربع من الغنم، وكان في النية أن أذبحها لهم، ولكن هؤلاء الناس تفرقوا، ولم يبق منهم إلا القليل، فهل يجوز لي أن أصرفه إلى الفقراء، وهل يجوز أن آكل منه، مع أنه كان في النية أن أعزم هؤلاء، والغالب عندي أن آكل من هذا النذر، فما رأي سماحتكم؟","title":"الوفاء بالنذر وما يتعلق به","answer":"الجواب:  إذا نذرت أن تذبحها لهم وأبوا؛ عليك كفارة يمين؛ لأن المقصود إكرام الضيف، المقصود من هذا إكرام الضيف، إذا قلت: والله نذر لوجه الله أن أذبحها لكم، أو والله لأذبحها لكم، أو علي الحرام أن أذبحها لكم، وأبوا؛ عليك كفارة يمين في هذا؛ لأن هذا ما هو مقصودك التقرب إلى الله، مقصودك إكرامهم هم، فإذا أبوا وعاندوك؛ فعليك كفارة يمين، بخلاف ما لو قلت: لله علي أن أتصدق بناقة، أو أتصدق بخروف، أو أتصدق ببقرة، فهذا نذر لله، عليك أن تؤده لقول النبي ﷺ: من نذر أن يطيع الله فليطعه.  وأما قولك: نذر عليَّ أن أذبح لكم، أو والله أذبح لكم، أو عليَّ الحرام أن أذبح لكم، مقصودك إكرامهم، وتلزيمهم، فأبوا؛ فعليك كفارة يمين، ويبقى مالك لك، فإن ذبحتها وتصدقت بها فلا بأس. ولا بأس أن تأكل منها إذا ذبحتها؛ لأن قصدك أن تأكل أنت وأهل بيتك مع الضيوف، إذا ذبحتها، وتصدقت منها، وأكلت منها أنت وأهل بيتك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3476/الوفاء-بالنذر-وما-يتعلق-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1780.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7426,"question":"أنا رجل متزوج، ولدي ولد، وزوجتي حامل في شهرها الأول، ولقد خرجت زوجتي مع أخي إلى المستشفى، وذلك دون إذن مني، أو من والدي، فأثار ذلك غضبي، وليس بالغضب الذي يفقدني عقلي، ولكني أعي ما أقول، وأستطيع ان أمنع نفسي من أي كلمة لا أريد النطق بها، فحلفت على زوجتي بالطلاق بقصد التهديد، لا بقصد الفراق؛ لأنني سبق أن حلفت عليها بالله، وفجرتني وكفرت عن حلفي، فحلفت بالطلاق؛ لعلها تنتهي عن مخالفتي، وهذا نص الحلف:علي الطلاق بالثلاث المحرمات، أو الحارمات أنك لو تخرجين من المنزل من غير إذني أن أذهب بك إلى أهلك، وبعد تداول الكلام بيننا بعد ذلك قال: إذا خرجت من فتحة الباب شبرًا واحدًا بدون إذن مني؛ فأنت طالق، وبعد ذلك بيومين خرجت مع والدي إلى المستشفى بدون إذن مني مع العلم أني موجود، ولكنها تقول: إنها لم تسمع الطلاق، والآن أود استرجاعها من أجل ابني ومن أجل الجنين الذي في بطنها، أفيدونا أفادكم الله، وأنني أقصد التهديد في كلا الحالتين، وإذا كانت حاملًا في الشهر الأول فمتى تنتهي عدتها؟ أي متى آخر موعد لاسترجاعها، وهل تلزم علي نفقتها وهي الآن في منزل والدها؟","title":"حكم من حلف على زوجته بالطلاق بقصد التهديد لا الفراق","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل؛ فإن هذا الكلام يكون حكمه حكم اليمين؛ لأن المقصود تهديدها، وتخويفها، وليس المقصود إيقاع الطلاق، فمثل ما فعلت في المرة الأولى عليك كفارة يمين، وهي: إطعام عشرة مساكين، أو كسوتهم بسبب خروجها لو كانت متعمدة، ولو كانت عالمة، أما ما دامت لم تسمع الكلام؛ فليس عليك شيء؛ لأنها جاهلة أو ناسية، لو كانت فعلت ناسية كذلك؛ لأن الله يقول: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وصح عن رسول الله ﷺ أنه قال: قال الله: قد فعلت فإذا خرجت جاهلة، ما درت عن يمينه، ما سمعت أو ناسية؛ فليس عليه كفارة، أما لو تعمدت وهي ذاكرة لو تعمدت فعليك كفارة يمين، ما دام القصد التهديد، والمنع، وليس القصد فراقها، لعلك فهمت.","link":"https://binbaz.org.sa/fatwas/3517/حكم-من-حلف-على-زوجته-بالطلاق-بقصد-التهديد-لا-الفراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1821.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7429,"question":"ما الحكم على من تستر على الذين يتركون الصلاة، ويقضون وقتهم مع لعب الورق؟","title":"حكم التستر على تارك الصلاة","answer":"الجواب: الواجب على المؤمنين التعاون، مثلما سمعت في الكلام، التعاون على الخير، وأن ينصحوا من تخلف عن الصلاة، وأن لا يتركوهم في باطلهم، ومع الشياطين، بل ينصحونهم ويوجهونهم إلى الخير، فإن استقاموا وإلا رفع الأمر إلى المسؤول عنهم حتى يقيم في حقهم ما يلزم، وحتى يبلغ عنهم ما يلزم، المقصود أن ترك الناس على باطلهم أمر منكر، والله -جل وعلا- يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ويقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110].  ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان فإذا علم أن أهل المكتب الفلاني، أو البيت الفلاني يضيعون الصلوات، ولا يبالون بهم؛ نصحهم الإخوان، واتصل بهم الإخوان، ووجهوهم إلى الخير وحذروهم من مغبة عملهم، فإن استقاموا؛ وإلا رفع بأمرهم إن كانوا في دائرة يرفع إلى رئيس الدائرة، أو إلى الهيئة، أو إلى أمير القرية، أو ما أشبه ذلك ممن يرجو أنه ينفع في هذا المقام، من باب التعاون على البر والتقوى، بعدما ينصح لهم، ويجتهد، وإذا تيسر أن يكون الناصح معه غيره لا يكون فردًا؛ يذهب معه بعض إخوانه؛ لأن كلمة الجماعة أشد أثرًا، إذا كان الناصحون اثنين، أو ثلاثة، أو نحو ذلك كان هذا أشد أثرًا في نفس المنصوح، وأقرب إلى النتيجة الصالحة.","link":"https://binbaz.org.sa/fatwas/3514/حكم-التستر-على-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1818.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7497,"question":"سؤاله الثاني يقول: تناقشت مع مجموعة من الزملاء عن حكم ما يسمى بالعادة السرية، وحكم الفعل في بعض أنواع الحيوانات، أفيدونا ولا حياء في الدين وفقكم الله؟","title":"حكم العادة السرية والفعل في بعض الحيوانات","answer":"الجواب: لا شك أن الاستمناء باليد، لا شك أنه من المحرمات؛ لأن الاستمناء يخالف قوله جل وعلا: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] وهذا ابتغى أمراً آخر غير الاستمتاع بالزوجة والسرية، فيكون عادياً، يعني: ظالماً؛ ولأن الأطباء قد قرروا أن الاستمناء باليد فيه مضار كثيرة، فالواجب ترك ذلك والحذر من ذلك، وأن يستعين على تخفيف حدة الشهوة بالأشياء الأخرى كالصوم الشرعي، فإن الله شرع الصوم لمن عجز عن النكاح، كما قال النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء فجعل الصوم وجاء، أي: قاطعاً للشهوة كالخصاء، لمن لم يجد قدرة على النكاح، وبهذا يعلم أن الواجب على الشباب المبادرة بالنكاح والإسراع إليه لما فيه من المصالح الكثيرة التي من جملتها العفة عن المحرمات، وتحصيل الأولاد، وإعفاف النساء، وتحقيق مكاثرة النبي ﷺ الأمم يوم القيامة بأمته عليه الصلاة والسلام، فينبغي في هذا التعاون على البر والتقوى، والتخفيف في المهور، وهكذا التخفيف من الولائم حتى يتسنى للشباب حصول المطلوب من النكاح.\nولا شك أن المغالاة في المهور من أعظم الأسباب في تعويق النكاح، وهكذا المغالاة في الولائم وكثرة ما يذبح من البهائم وما يصنع من الطعام، كل هذا مما ينبغي تخفيفه وتقليله حتى لا يتكلف المتزوج، وهكذا الفتاة ينبغي لها أن تسارع إلى ذلك، وأن ترضى بما يسر الله من المهر، وأن لا تشدد في المهور ولا في الولائم، وهكذا أمها وأخواتها وأولياؤها، ينبغي في هذا التخفيف والتيسير حتى يحصل التعاون على البر والتقوى، وإذا اجتمع رأي الجميع على مهر قليل وعلى وليمة قليلة فهذا أحسن، تحقيقاً للمصلحة العامة، وليكونوا بذلك قدوة لغيرهم في التخفيف والتيسير.\nومن ذلك أيضاً: أن يتعاطى بعض الأدوية التي تخفف شر الشهوة ولا تقطعها؛ لأن هذا يعينه على ترك الاستمناء والعافية من شر هذه العادة السرية، نعم.\nأما ما يتعلق باتصال الإنسان بالحيوان، فهذا لا شك أنه منكر وكبيرة من الكبائر، وقد جاء في الحديث عنه عليه الصلاة والسلام أنه قال: من وجدتموه يعمل عمل قوم لوط فاقتلوا الفاعل والمفعول به، ومن وقع على بهيمة فاقتلوه واقتلوا البهيمة، هذا وعيد شديد، وقد ذهب بعض أهل العلم إلى أنه يقتل، كما لو زنى وهو محصن، ولكن ذهب آخرون من أهل العلم؛ منهم ابن عباس رضي الله عنهما إلى أنه لا يقتل بل يعزر ويؤدب؛ لأن الحديث في سنده مقال وليس بذاك في الصحة، بل اختلف العلماء في صحته فلهذا: الصواب أنه يعزر ولا يقتل، الذي يأتي البهيمة الصواب أنه يعزر ويجلد ويؤدب بما يراه ولي الأمر من الأدب والسجن ردعاً له ولأمثاله عن هذه الفاحشة الكبيرة.\nأما البهيمة فتقتل، ولعل الحكمة في ذلك والله أعلم لئلا يتحدث الناس أن هذه البهيمة فعل فيها فلان، فيكون في هذا نشر للفاحشة وإظهار لها وإعلان لها، ولكن عليه مع ذلك غرامتها، إن كانت مأكولة تذبح وتؤكل، وإن كانت غير مأكولة كالحمار والبغل فإنها تذبح وتطرح للكلاب أو للسباع وما أشبه ذلك، ولا تؤكل؛ لأنها محرمة، وعليه غرامتها لأهلها؛ لأنه السبب في إتلافها، فتلزمه قيمتها لأهلها. نعم.","link":"https://binbaz.org.sa/fatwas/4458/حكم-العادة-السرية-والفعل-في-بعض-الحيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00702.mp3","categories":["الأخلاق المذمومة"]},{"id":7569,"question":"طيب وبالنسبة للملابس الشفافة؟","title":"حكم لبس الملابس الشفافة أمام المحارم","answer":"الجواب: لا ما تجوز الشفافة، الشفافة خطيرة قد تبدي العورة، لكن إذا كان يعني شفافة في الذراع فهذا سهل، إذا كان البدن مستورا، فينبغي أن تكون الملابس ساترة صفيقة، لا تبين ما وراءها من حسن اللحم، وظهور اللحم من حمرة وبياض ونحو ذلك، بل تكون ساترة لهذا الشيء، تكون تحت الثوب الخفيف مثل الفنيلة التي تعين على ذلك وأشباه ذلك، المقصود أن الشفافة كالعارية، الشفافة من جنس العارية، فينبغي التحرز من هذا الشيء وعدم التساهل في هذا الشيء.","link":"https://binbaz.org.sa/fatwas/4575/حكم-لبس-الملابس-الشفافة-امام-المحارم ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01605.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":7681,"question":"هذا حمد مسعود فضل السيد من السودان يقول: ما حكم تقبيل يد الرجل الصالح والانحناء له هل يجوز أم لا؟","title":"حكم تقبيل يد الرجل الصالح والانحناء له","answer":"الجواب: أما تقبيله اليد فذهب جمع من أهل العلم إلى كراهته، ولا سيما إذا كان عادةً، أما إذا فعل بعض الأحيان عند بعض اللقاءات فلا حرج في ذلك مع الرجل الصالح مع الأمير الصالح، مع الوالد، أو شبه ذلك لا حرج في ذلك، لكن اعتياده يكره، وبعض أهل العلم حرم ذلك إذا كان معتاداً دائماً عند اللقاء، أما فعله بعض الأحيان فلا حرج في ذلك، أما السجود على اليد كونه يسجد على اليد يضع جبهته على اليد هذا السجود محرم، ويسميه بعض أهل العلم السجدة الصغرى، هذا لا يجوز، كونه يضع جبهته على يد إنسان سجوداً عليها لا، لكن تقبيلها بفمه إذا كان غير معتاد إنما نادر أو قليل فلا بأس؛ لأنه ورد عن النبي صلى الله عليه وسلم أنه قبل بعض الصحابة يده وقدمه، وفعله بعض الصحابة فالأمر في هذا سهل إذا كان قليلاً، أما اعتياده دائماً فيكره أو يحرم، وأما الانحناء فهو لا يجوز، كونه ينحني كالراكع هذا لا يجوز لأن الركوع عبادة ولا يجوز أن ينحني، أما إذا كان انحناؤه ما هو من أجل التعظيم، انحنى له لأنه قصير والمسلم طويل فانحنى له حتى يصافحه، لا لأجل التعظيم بل لأجل أن المسلم عليه قصير، أو مقعد، أو جالس فلا بأس بهذا، أما أنه ينحني لتعظيمه هذا لا يجوز، ويخشى أن يكون من الشرك إذا قصد تعظيمه بذلك، وقد روي عن النبي ﷺ أنه سئل قيل: يا رسول الله! ألقى الرجل فهل أنحني له؟ قال: لا، قال: فهل ألتزمه وأقبله؟ قال: لا، قال: فهل آخذ بيده وأصافحه؟ قال: نعم، وإن كان في سنده ضعف.. الحديث ضعيف الإسناد، لكن ينبغي العمل به؛ لأن الشواهد الكثيرة تشهد له في المعنى، والأدلة كذلك تدل على أن الانحناء والركوع للناس لا يجوز.\nفالحاصل أنه لا يجوز الانحناء أبداً لأي شخص لا للملك ولا لغير الملوك، ولكن إذا كان الانحناء لا لأجل التعظيم بل لأجل أن المسلَّم عليه قصير، أو مقعد، أو جالس، فانحنى ليسلم عليه؛ فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4878/حكم-تقبيل-يد-الرجل-الصالح-والانحناء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04006.mp3","categories":["الأخلاق المذمومة"]},{"id":7800,"question":"سؤاله الثاني والأخير يقول: ما حكم اللعن في رمضان؟","title":"حكم لعن المسلم وهل يكون أشد في رمضان؟","answer":"الجواب: اللعن في رمضان وفي غيره محرم، والواجب ......... الله جل وعلا أوجب على عباده حفظ ألسنتهم مما حرم عليهم، قال سبحانه: مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ [ق:18] وقال: وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ ۝ كِرَامًا كَاتِبِينَ ۝ يَعْلَمُونَ مَا تَفْعَلُونَ [الانفطار:10-12]، فالإنسان مأمور بالحفظ بحفظ لسانه وصيانة جوارحه عما حرم الله عليه، والرسول ﷺ قال: لعن المؤمن كقتله فشبه اللعن بالقتل وقال: إن اللعانين لا يكونون شهداء ولا شفعاء يوم القيامة قال: ليس المؤمن بالطعان ولا اللعان ولا الفاحش ولا البذيء، فالسب واللعان أمر منكر، وقال عليه الصلاة والسلام: سباب المسلم فسوق وقتاله كفر.\nفالواجب على المؤمن حفظ اللسان وهكذا المؤمنة يجب عليهما حفظ اللسان عما حرم الله من السباب والكذب وقول الزور سواء في رمضان أو في غيره، لكن في رمضان يكون الإثم أشد، إذا كان السب في رمضان أو في أيام ذي الحجة تسع ذي الحجة يكون التحريم أشد والإثم أكثر، وإلا فاللعن محرم في جميع الأوقات وجميع الأماكن، على المؤمن أن يحذر ما حرم الله وهذا في كل وقت من شتم ولعن وقول زور وغير ذلك، لكن في مثل رمضان وفي أيام ذي الحجة يكون الإثم أكثر وأشد، نسأل الله السلامة والعفو. نعم.","link":"https://binbaz.org.sa/fatwas/5154/حكم-لعن-المسلم-وهل-يكون-اشد-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05004.mp3","categories":["الأخلاق المذمومة"]},{"id":7813,"question":"هذا سائل يقول: المستمع من الأردن يقول: هل يجوز لي أن أجلس مع أقربائي وكان حديثهم في غيبة ونميمة واستهزاء على الناس، علماً بأن زيارتي كانت بهدف صلة الرحم، فما العمل أرشدوني مأجورين؟","title":"حكم الجلوس مع قوم يخوضون في أعراض الناس","answer":"الجواب: ليس لك الجلوس مع قوم يغتابون الناس أو يأتون منكرات أخرى لا تجالسهم، إذا خاضوا في هذا أنكر عليهم وانصحهم، فإن قبلوا منك فالحمد لله وإلا فارقهم، لا تجلس معهم، كما قال تعالى: وَإِذَا رَأَيْتَ الَّذِينَ يَخُوضُونَ فِي آيَاتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ [الأنعام:68]، وقال جل وعلا: فَلا تَقْعُدْ بَعْدَ الذِّكْرَى مَعَ الْقَوْمِ الظَّالِمِينَ [الأنعام:68].\nفالمؤمن لا يجالس أهل الشر، لكن ينصحهم ويوجههم إلى الخير، فإن قبلوا منه فالحمد لله وإلا غادر المكان ولم يجلس معهم؛ لأن الله يقول: فَلا تَقْعُدْ بَعْدَ الذِّكْرَى مَعَ الْقَوْمِ الظَّالِمِينَ [الأنعام:68]. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/5193/حكم-الجلوس-مع-قوم-يخوضون-في-اعراض-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05111.mp3","categories":["الأخلاق المذمومة"]},{"id":7955,"question":"بعث بهذه الرسالة محمد أحمد عبد الله شمراني بجدة يقول فيها: إن لي أخو وهو الأكبر فينا وعددنا سبعة أشخاص وأصغر واحد فينا عمره خمسة وثلاثين سنة، وهو عمره تسع وأربعين سنة -الذي هو الأكبر- وقد توفي الوالد والوالدة وهو يعمل فيهم الأذية حتى الضرب لولا يخاف منها لكان ضربهم، توفي الوالد والوالدة وهما زعلانين عليه ونحن زعلانين عليه وحتى قطعناه من المزاورة، واليوم لنا حوالي سبع سنوات من مزاورته علماً أنه صائم ومصلي ولكن فيه بذخ كلام علينا يا إخوته أو يا أخواته، اليوم هل علينا إثم أم لا، هذا وسلام الله عليكم وبركاته؟","title":"حكم الهجر بين الإخوة","answer":"الجواب: لاشك أنه بهذا العمل قد أساء إلى والديه وإلى إخوته، والواجب عليه حسن الخلق وترك الترفع على إخوته والإيذاء لإخوته والكلام القبيح، وأما ما فعله مع والديه فلا شك أنه عمل قبيح وعليه التوبة إلى الله من ذلك والاستغفار والدعاء لوالديه لعل الله يتوب عليه ولعل الله يرحمه.\nأما أنتم -أيها الإخوة- فينبغي لكم أن تجتهدوا في صلته والدعاء له بالتوفيق والهداية حتى تكونوا أنتم خيراً منه؛ لأن النبي عليه السلام يقول: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها فأنتم تحضون بالأجر تصلونه وتزورونه وتسلمون عليه تدعون له بالتوفيق والهداية، وتنصحونه أنه يتوب إلى الله ويدعو لوالديه ويستغفر لما جرى على والديه هذا هو الذي ينبغي منكم، فإن ردكم وأبى أن يسلم عليكم فأنتم معذورون والإثم عليه، أما أنتم فالذي ينبغي أن تصلوه، وأن تزوروه وتسلموا عليه، وتدعوه للزيارة لكم والوليمة عندكم؛ حتى يلين قلبه، وحتى تزول الوحشة إن شاء الله بينكم وبينه، فإن أبى ولم يوافق وأصر على هجركم أو على سبكم فأنتم معذورون والإثم عليه، وليس عليكم بعد ذلك زيارته، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5481/حكم-الهجر-بين-الاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06902.mp3","categories":["الأخلاق المذمومة"]},{"id":7998,"question":"أيضاً يقول: المستمع إقليل علي: إن عمي أخو والدي من عمه بينه وبين والدي نزاع وزعلت أنا من أجل أنني رأيت عمي يخطئ على والدي وبقيت لا أسلم على عمي أكثر من ثلاث سنوات، وحيث أن والدي حذرني من السلام على عمي أخو والدي من عمه، فهل علي إثم أفيدوني أفادكم الله هذا وجزاكم الله عنا خير الجزاء؟","title":"حكم قطع صلة الرحم","answer":"الجواب: صلة الرحم من أهم الواجبات، والعم من أقرب الأرحام فهو صنو الأب، فيجب أن يوصل بالكلام الطيب والفعل الطيب، وبر الوالدين من أهم الواجبات وأعظم الواجبات، وحق الوالد أكثر من حق العم.\nولكن الهجر لا يجوز إلا بعلة شرعية، الهجر فوق ثلاثة أيام لا يجوز، إلا إذا كان المهجور قد أظهر المعاصي والبدع، فيستحق الهجر الذي يمنعه عن البدعة والمعصية حتى يتوب، أما الهجر لحق الوالد أو لحق زيد أو عمرو في أمور الدنيا والخصومات فهذا لا يزيد على ثلاثة أيام، هكذا أمر النبي ﷺ، ونهى عن الزيادة على ثلاثة أيام.\nفالواجب عليك أن تصل عمك وأن تزيل الهجر وأن تعتذر إليه، وتطلبه المسامحة وأن تستسمح أباك في هذا وتقول: هذا أمر يلزمني من جهة الله والحديث الصحيح: إنما الطاعة في المعروف يوجب عليك ذلك، في اللفظ الآخر: لا طاعة لمخلوق في معصية الخالق فإذا أمرك أبوك بقطيعة الرحم، لا، ولكن تعامل أباك بالحكمة والكلام الطيب والصفة الحميدة، وتستسمحه في هذه الأمور، وتخاطبه بالتي هي أحسن، وتقوم بصلة الرحم ولو بطريقة خفية عن والدك إذا كان لم يسمح، تقوم بالواجب من جهة صلة الرحم والكلام الطيب مع عمك وغيره، ولو ما أطلعت أباك على ذلك إذا لم يسمح، أما أنك تهجر بغير حق من أجل كلام والدك فهذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/5553/حكم-قطع-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07402.mp3","categories":["الأخلاق المذمومة"]},{"id":8188,"question":"هذه رسالة وردتنا من شلوي محمد العلي من الرياض، يقول في رسالته: أرجو عرض رسالتي هذه على سماحة الشيخ عبد العزيز بن باز حفظه الله خاصة، ونرجو أن يعالج هذه الرسالة معالجة وافية، يقول: بعض المبتعثين إلى الخارج يذهبون بزوجاتهم معهم، فمنهم من يجبر زوجته على التكشف؛ خشية الضحك عليهم والتندر بهم من الغرب، حتى إن الزوجات يجتمعن مع أزواجهم جميعاً، ويأكلون ويشربون ويتندرون، بل إن بعضهم يقبل زوجة صديقه أو زميله وهو ينظر، ولا بأس عندهم في ذلك، نرجو معالجة ذلك عبر برنامجكم نور على الدرب، وفقكم الله؟","title":"حكم إجبار المبتعثين لزوجاتهم على التكشف والاختلاط في الخارج","answer":"الجواب: لاشك أن هذا الأمر الذي ذكره السائل منكر ولا يجوز، فإن الواجب على الرجل أن يكون عنده غيرة، وأن يكون عنده حرص على عفة زوجته، وبعدها عن مواضع الخطر، وأن تكون بعيدة عن التبذل وعدم الحجاب، بل يلزمه أن يقوم عليها وأن يوجهها إلى الخير، وأن تحتجب أينما كانت، سواء كانت في بلاد المسلمين، أو في بلاد الكافرين مع زوجها، الواجب على الجميع التأدب بالآداب الشرعية، والتقيد بها في كل مكان، ومن ذلك الحجاب، وعدم الاختلاط بالأجناب من أزواج الزملاء، وإذا وقع التقبيل من الشخص لزوجة زميله هذا منكر عظيم.\nالمقصود أن هذه الأشياء التي ذكرها السائل منكر، فلا يجوز كشف الوجه أو الشعر عند زملاء الزوج، ولا يجوز لزيد أو عمرو من الزملاء أن يقبل زوجة صديقه أو زميله، أو ينظر إليها، بل يجب غض البصر، ويجب الامتناع من التقبيل، ويجب الامتناع أيضاً من الاختلاط الذي يفضي إلى ذلك، بل يجلس النساء وحدهن في أكلهن وشربهن، والرجال وحدهم في أكلهم وشربهم، وتحافظ المرأة على الحجاب، والرجل على غض البصر أينما كان، هذا هو الواجب على المسلمين، ويجب على الدول الإسلامية التي تخاف الله أن تمنع هذا، وأن تقوم على من يفعله حتى يزول هذا البلاء.\nوالابتعاث إلى بلاد الكفر فيه خطر عظيم، فيجب منعه مهما أمكن، وأن تكون الدراسة في الداخل، وأن يسلم الناس من شر هذا الابتعاث، الذي يفضي إلى فساد كثير، إلى فساد العقيدة، وإلى إفساد الأخلاق، وإلى اختلاط الرجال بالنساء، وإلى قلة الغيرة، وإلى تمتع الرجال بأزواج غيرهم ونساء غيرهم، وربما أفضى إلى الفاحشة والملامسة والتقبيل بغير حق، وهذا كله بلاء عظيم، وهو خطر، هذا الابتعاث خطر في العقيدة والأخلاق جميعاً على الرجال والنساء، فالواجب منعه منعاً باتاً من دولتنا وفقها الله، ومن جميع الدول الإسلامية، وعلى آباء المبتعثين نصيحتهم لهذا، وألا يوافقوا على ابتعاثهم مهما أمكن، ولو على حساب الآباء، أو حساب المؤسسات، أو ما أشبه ذلك، بل يجب التقيد بالتعلم في بلاد الإسلام، وفي المدارس الإسلامية، والجامعات الإسلامية التي فيها الخير وفيها الكفاية، وإذا كان هناك ضرورة للابتعاث ليس هناك ما يغني عنه، فليبتعث الرجل العاقل الدين، المعروف بالاستقامة والعقل الرزين، والغيرة الإسلامية، والبعد عن أسباب الشر، فيبتعث هذا وحده أو مع زوجته المستقيمة عند الضرورة، هذا لا حرج فيه إن شاء الله عند الضرورة، يكون داعية إلى الله، وموجهاً إلى الخير، ويتعلم الشيء الذي تدعو الضرورة إلى تعلمه، وزوجته معه تعينه على العفة والسلامة، ويتحدث معها وتتحدث معه، ويعلمها ويفيدها ويوجهها إلى الخير، وإذا سافر بدون الزوجة فلا بأس.\nالمقصود أن هذا ينبغي أن يعالج بأمرين: الأمر الأول: منع الابتعاث بالكلية، فإذا دعت الضرورة إليه؛ لعدم وجود الحاجة التي يبتعث لأجلها، فلابد أن ينظر في الشخص المبتعث، ولا يبتعث كل أحد، بل لا يبتعث إلا الرجل المعروف بالاستقامة، والعقل الجيد والأخلاق الفاضلة، والاتزان والعلم والفضل، حتى لا يخشى عليه الوقوع في الباطل بإذن الله، وإذا كان معه زوجة فلينظر أيضاً فإن كانت جيدة صينة، فلا بأس باصطحابها مع نصيحتها ومع ملاحظتها حتى لا تقع في باطل، وإن كانت ليست جيدة لم يذهب بها وتركها عند أهله خوفاً عليها من وقوع ما لا تحمد عقباه؛ فإنه ليس دائماً عندها. نعم.","link":"https://binbaz.org.sa/fatwas/5998/حكم-اجبار-المبتعثين-لزوجاتهم-على-التكشف-والاختلاط-في-الخارج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09204.mp3","categories":["النظر والخلوة والاختلاط","الأخلاق المذمومة"]},{"id":8192,"question":"نبدأ أولاً برسالة المستمع (س. ع) من أبها، يقول: امرأة لعنت زوجها بسبب شجار بينهم، وحيث أن هذه يوجد لديها نوع الحمق، فهل تحرم على زوجها أم لا؟","title":"حكم لعن الزوجة لزوجها ولعن الزوج لزوجته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه.\nأما بعد: لا، لعنها له لا يحرمها عليه، ولعنه لها لا يحرمها عليه أيضاً، إذا لعن أحدهما الآخر فقد أخطأ وأساء وظلم، فعليه التوبة إلى الله ، واستسماح صاحبه، الزوج يستسمح زوجته إذا لعنها، وهي بالعكس كذلك تستسمحه وتتوب إلى الله مما فعلت والزوجية باقية، لا يفسد النكاح بذلك، فاللعن لا يبطل النكاح ولا يفسده، ولا يكون طلاقاً لها، سواء كان اللعن منه لها أو منها له، إلا أنه منكر ولا يجوز، وكبيرة من الكبائر، جاء في الحديث الصحيح أن النبي عليه الصلاة والسلام قال: لعن المؤمن كقتله، وقال: ليس المؤمن بالطعان ولا اللعان ولا الفاحش ولا البذيء، فاللعن ليس من صفة المؤمنين، بل هو منكر، فلا يجوز أن يقع من الزوج، ولا من الزوجة، وإذا وقع من أحدهما وجب عليه أن يستسمح الآخر؛ لأنه تعدى عليه وظلمه، مع التوبة إلى الله ، نعم.","link":"https://binbaz.org.sa/fatwas/6000/حكم-لعن-الزوجة-لزوجها-ولعن-الزوج-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09301.mp3","categories":["الحقوق الزوجية","الأخلاق المذمومة"]},{"id":8260,"question":"قضية الحاجة إلى عمل المرأة في مكان معين سماحة الشيخ، وقضية محرمها قضية لعل لسماحتكم فيها وجهة نظر ونصيحة، ماذا تقولون لو تكرمتم؟","title":"التحذير من سفر المرأة بغير محرم والاختلاط في العمل","answer":"الجواب: لا ريب أن هذا عمل خطير، وأن مجيء النساء بدون محارم فيه خطر وفتنة، فالذي ننصح أخواتنا في الله الحذر من ذلك وأن لا يقدمن إلا بمحارم، وننصحهن أيضاً بالحذر من الاختلاط مع الرجال والعمل مع الرجال ، أو الخلوة بالرجال، كونها تخلو برجل ليس محرماً لها، كل هذا مما يجب الحذر منه، سواء كان في المستشفيات أو في غير المستشفيات.\nفنصيحتي للجميع ألا تقدم امرأة إلا بمحرم، وألا تسافر إلا بمحرم وألا تعمل بين الرجال، وألا تخلو بأي رجل من غير محارمها؛ لأنه طريق للفتنة، والرسول ﷺ منع ذلك وحرمه، وقال: لا يخلون رجل بامرأة فإن ثالثهما الشيطان.\nفالمقصود من هذا: أن الواجب على المرأة وعلى أوليائها الحرص على سلامة العرض، والبعد عن أسباب الفتنة، وأما العمل فلا بأس أن تعمل بين النساء ممرضة أو خياطة أو خادمة أو غير ذلك في عمل مباح لا يضر دينها ولا يسبب فتنة مع الرجال، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6070/التحذير-من-سفر-المراة-بغير-محرم-والاختلاط-في-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09810.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":8320,"question":"من تهامة عسير رسالة بعث بها الأخ حمود علي محمد عسيري ، أخونا كتب رسالته بأسلوبه وبلهجته -باللهجة العامية- مفهوم الرسالة سماحة الشيخ: أنه شهد مع أناس عدة مرات أن لهم أراضي وأن في تلك الأراضي غرف ومساكن بينما هي أراضٍ بيضاء ليس فيها مساكن -كما يقول- فيسأل عن الحكم والحالة هذه ولا سيما وقد تكرر منه ذلك؟","title":"حكم شهادة الزور وكيفية التوبة منها","answer":"الجواب: نعوذ بالله من ذلك، هذه شهادة الزور التي شدد فيه الرب عز وجل وشدد فيها النبي ﷺ، قال الله جل وعلا: فَاجْتَنِبُوا الرِّجْسَ مِنَ الأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ [الحج:30] فالواجب على المؤمن أن يحذر ذلك غاية الحذر، وقال النبي ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين، وكان متكئاً فجلس، فقال: ألا وقول الزور ألا وشهادة الزور فشهادة الزور من أكبر الكبائر، وقال أيضاً عليه الصلاة والسلام: الكبائر: الشرك بالله، وعقوق الوالدين، وقتل النفس، وشهادةة الزور فهذه الكبيرة العظيمة عليه إثمها، وعليه أن يغرم للمشهود عليهم ما فوتها بشهادته، إذا كانت شهادته فوتت عليهم مالاً أو غرمتهم مالاً فإن الواجب عليه أن يغرم لهم ما حصل تفويته عليهم بشهادته، أما إذا كانت لم تقبل أو لم يترتب عليها شيء فإنما عليه التوبة فقط، الرجوع إلى الله والإنابة إليه والندم على ما مضى والعزم الصادق أن لا يعود في ذلك ويكفيه ذلك، من تاب تاب الله عليه.\nأما إن كان ترتب على شهادته شيء من الظلم للناس فإن عليه أن يغرم لهم ما ظلموه بأسباب شهادته، مع التوبة والاستغفار والندم العظيم والإقلاع من هذا الشيء وعدم فعله في المستقبل، مع الندم على الماضي والأسف على ما مضى، ومع العزم الصادق أن لا يعود في ذلك خوفاً من الله وتعظيماً له سبحانه وتعالى، وإذا تحللهم وسمحوا عنه فلا بأس، إما أن يعطيهم حقهم وإما أن يتحللهم. نعم.\nالمقدم: جزاكم الله خيراً، يبدو سماحة الشيخ من رسالته أن الشهادة كانت من أجل مقاضاة بينهم وبين البلدية.\nالشيخ: ما هو ببعيد، نعم. ظاهر هذا.. ظاهر من أنه شهد لأنه ورث في الأرض وهو كاذب نسأل الله العافية، على كل ما يتغير الحكم.\nالمقدم: لا يتغير الحكم، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6133/حكم-شهادة-الزور-وكيفية-التوبة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_110/11003.mp3","categories":["القضاء والشهادات","الأخلاق المذمومة"]},{"id":8341,"question":"هنا رسالة وصلت إلى البرنامج من الجمهورية العربية اليمنية لواء إب، وباعثها أخونا محمد عبد الحميد محمد حاتم الحذيفي أخونا يقول: وجدت أناساً من إخواننا المسلمين يستخدمون الكلاب المعادية غير المعلمة، وذلك في مأكلهم ومشربهم، وأيضاً يركب الرجل في السيارة ويضع الكلب أمامه ويداعبه بيديه، فوقفت أمامهم وقلت لهم: إن هذا الكلب لا يجوز استخدامه؛ لما فيه من النجاسة المغلظة، فأجابوا قائلين: إنه يوم ولد هذا الكلب أخذوه وغسلوه بالصابون والماء بعدما كان نجساً وقد أصبح اليوم طاهراً، وقد استدلوا بأصحاب الكهف وكلبهم الباسط ذراعيه بوصيدهم، كما وصفهم الله بقوله: وَكَلْبُهُمْ بَاسِطٌ ذِرَاعَيْهِ بِالْوَصِيدِ [الكهف:18] فما هو الحكم في هؤلاء؟ وهل يطهر الكلب بعد نجاسته، أفيدونا بارك الله فيكم؟","title":"حكم اقتناء الكلاب وادعاء طهارتها بالتغسيل","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من اقتنى كلباً إلا كلب صيد أو ماشية أو زرع فإنه ينقص من أجره كل يوم قيراطان يعني: من الأجر، وهذا يدل على أنه ما ينبغي اقتناء الكلب، ولا يشرع اقتناءه، بل ظاهر الحديث منع ذلك، ما دام ينقص الأجر يحصل له في أجره أن ينقص قيراطان هذا أمر خطير، وهو يدل على كراهة ذلك أو تحريمه، ومعلوم أن المؤمن ينبغي له أن يبتعد عن كل ما ينقص أجره، فلا يقتنى كلب إلا لهذه الثلاث: إما لصيد، وإما لماشية، وإما لزرع، أما يقتنيه لأجل الصيد، وإما ليحرس الماشية يكون مع الماشية يطرد عنها الذئاب إذا سمعه أهل الماشية قاموا وطردوا الذئاب أيضاً، والذئاب تهاب صوته إذا سمعت صوته تهاب؛ لأنها تعلم أنه ينبه أهل الماشية، وهكذا الزرع يكون في المزارع للتنبيه على ما قد يرد عليها من سراق أو بهائم تعثوا فيها أو ما أشبه ذلك، وما زاد على ذلك لا يقتنى الكلب فيه، هذا الذي اقتناه وصار يحمله معه في السيارة هذا قد غلط وهو على خطر من نجاسته، وعلى خطر من نقص أجره الذي بينه النبي ﷺ: أنه ينقص كل يوم من أجره قيراطان فلا ينبغي أبداً اقتناؤه لغير هذه الثلاث؛ للمصالح التي بينها النبي عليه الصلاة والسلام.\nوتغسيله لا يطهره، تغسيل الكلب ولو غسله كل يوم لا يطهره، نجس، نجس الذات مثل: لو غسل الخنزير لا يطهر، الخنزير لا يطهر، والكلب لا يطهر بالتغسيل، هو نجس ولو غسل، ولو غسل بالصابون كل يوم، هو نجس، فلو ولغ في الإناء وجب أن يغسل الإناء منه سبع مرات إحداهن بالتراب، كما قال النبي ﷺ: إذا ولغ الكلب في إناء أحدكم فليغسله سبع مرات أولاهن بالتراب فالمقصود أن الكلب نجس، ولهذا قال عليه الصلاة والسلام: طهور إناء أحدكم إذا ولغ فيه الكلب أن يغسله سبع مرات أولاهن بالتراب فجعلها طهوراً، فدل ذلك على أنه نجس، وأن هذا الماء إذا غسل سبع مرات يطهر الإناء.\nوكذلك ما يتعلق بكلب أهل الكهف، هذا لا يدل على جواز اقتناء الكلاب، فلعلهم اقتنوه للصيد أو لماشية عندهم، والأغلب أنهم اقتنوه للصيد يصيدون به ما يتقوتون به، فلا حرج في ذلك إذا حبسوا عندهم الكلب وربوه وعلموه حتى يصيدوا به، أو حتى يحمي المزرعة أو الماشية لا بأس بهذا كما تقدم، فلا يجوز حمله على أنهم اقتنوه للعب أو لحاجات أخرى، لا، يحمل على محمل حسن؛ لأنهم أهل خير وأهل استقامة وأهل طاعة.\nثم هذا شرع لمن قبلنا ليس شرعاً لنا، هؤلاء قبلنا، قبل بعث محمد عليه الصلاة والسلام، فلو قدر أن الرسول صلى الله عليه وسلم نهى عن الكلب لكان وجود كلبهم عندهم لا يكون شرعاً لنا، لكن ما دام شرعنا أجاز الكلب للماشية والصيد والزراعة، فنحمل كلبهم على أنه كان عندهم لواحدة من هذه الأنواع، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6159/حكم-اقتناء-الكلاب-وادعاء-طهارتها-بالتغسيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11205.mp3","categories":["الأخلاق المذمومة"]},{"id":8344,"question":"شيخ عبد العزيز ! نعود في بداية هذا اللقاء إلى رسالة الأخت (د. م. ع) من القصيم العين، أختنا أثارت خمسة أسئلة في حلقةٍ مضت، وها نحن نعود إلى بقية أسئلتها في هذا اللقاء، فتقول في سؤال لها: لقد تمادى الناس وتساهلوا في ذهاب بناتهم مع أصحاب النقل إلى مدارس خارج بلدتهم، وذلك بدون محرم مع السائق، ولا يرى الجميع من بد في ذلك، فحبذا لو عالجتم هذه المشكلة أنتم يا رجال الدين ويا أهل العلم، جزاكم الله عنها وعن المسلمين خير الجزاء، وجعل لما تقولون أذناً واعية وقلوباً صاغية؟","title":"حكم ركوب الطالبات مع سائق المدرسة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفقد ثبت في السنة عن رسول الله عليه الصلاة والسلام بالنهي عن سفر المرأة بدون محرم، فإذا كان سفر البنات الطالبات في المدارس يبلغ السفر الشرعي حرم على البنت أن تذهب إلا بمحرم، أما ما دام في أرجاء البلد وأطراف البلد وما لا يعد سفراً فإن هذا لا حرج فيه، أن تذهب في سيارات النقل مع البنات إلى المدارس لا حرج في ذلك، ما دام ذلك في أرجاء البلد وفي أطراف البلد، كل ذلك لا حرج فيه ولا يسمى سفراً، وليس له أن يخلو بواحدةٍ منهن، بل يكن جميعات، يكن معهن جماعة يكون معه جماعة، ينقلهن إلى المدارس، كل هذا لا حرج فيه.\nوإذا كان هناك انفراد بواحدة حرم عليه ذلك، بل عليه أن يتحرى أن ينزل آخر شيء ثنتين أو أكثر حتى لا يحصل خلوة بشيءٍ منهن، على السائق أن يلاحظ ذلك، إلا إذا كانت معه زوجته أو أمه أو أخته أو نحو ذلك فإنه لا يحصل بذلك خلوة، ولو كان الباقي واحدة. نعم.","link":"https://binbaz.org.sa/fatwas/6162/حكم-ركوب-الطالبات-مع-ساىق-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11301.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":8349,"question":"لقد قيل لي: إن النوم على البطن محرم، فهل هذا صحيح؟ وإذا كان صحيحاً فماذا أفعل، لأني لا أرتاح إلا إذا نمت على هذا الموضع، وأن النوم على البطن مريح بالنسبة لي؟","title":"هل النوم على البطن حرام؟","answer":"الجواب: قد جاء عن النبي ﷺ: أنه رأى بعض أصحابه قد نام على بطنه، فحركه برجله، وقال له: إن هذا ضجعة يبغضها الله وفي رواية: إنها ضجعة أهل النار فهي مكروهة، ضجعة مكروهة، ينبغي تركها إلا من ضرورة كالوجع الذي يحتاج معه صاحبه إلى هذه الضجعة، وإلا فينبغي تركها، وأقل أحوالها الكراهة؛ لقول النبي ﷺ: إن هذه الضجعة يبغضها الله فينبغي تركها، وعلى الأقل الكراهة في ذلك، مع أن ظاهر الحديث التحريم، فينبغي للمؤمن والمؤمنة ترك هذه الضجعة، إلا من ضرورةٍ لا حيلة فيها. نعم.","link":"https://binbaz.org.sa/fatwas/6167/هل-النوم-على-البطن-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11306.mp3","categories":["الأخلاق المذمومة"]},{"id":8432,"question":"أيضاً من العراق بغداد (م. م. ن) يسأل سؤالين: في سؤاله الأول: يصور نفسه سماحة الشيخ بأنه سيئ الظن بكثير من الناس، بم تنصحونه؟","title":"سوء الظن حكمه وعلاجه وضابطه","answer":"الجواب: يقول الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12].\nويقول النبي ﷺ: إياكم والظن فإن الظن أكذب الحديث متفق على صحته.\nفالواجب عليك أيها السائل! أن تتقي الله، وأن لا تسيء الظن بالناس إلا بشروط بأسباب، أما سوء الظن مطلقاً فهذا غلط، وليس لك ذلك: إياكم والظن فإن الظن أكذب الحديث، لكن من ثبت لديك بالبينة العادلة أو بالمشاهدة أنه يقف موقف التهم، ويجلس مجالس التهم فهذا هو محل سوء الظن، وإلا فاتق الله واحذر سوء الظن في الناس، وعليك بحملهم على أحسن المحامل ما لم تجد خلاف ذلك، ما لم تعلم خلاف ذلك، وعليك أيضاً أن تبتعد عن مخالطة من تتهمهم وتسيء بهم الظن، لفسادهم وإعراضهم عن دين الله، ابتعد عنهم واختلط بأهل الخير والاستقامة، والتمس لك الجلساء الصالحين، فإذا لم تجد فالزم بيتك، إلا وقت الصلاة تخرج وتصلي مع المسلمين، وابتعد عن مخالطة الأشرار، واتق الله حتى تجد الصاحب الطيب والجليس الصالح، أما سوء الظن بالناس من غير علة ومن غير سبب هذا لا يجوز؛ بل هو مخالف لقوله سبحانه: اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12]؛ ولقول النبي ﷺ: إياكم والظن فإن الظن أكذب الحديث. نعم.","link":"https://binbaz.org.sa/fatwas/6316/سوء-الظن-حكمه-وعلاجه-وضابطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11909.mp3","categories":["الأخلاق المذمومة"]},{"id":8433,"question":"يسأل هل هناك كفارة لمن أساء به الظن وأصبح مخطئاً؟","title":"واجب من أساء الظن بالناس","answer":"الجواب: الكفارة التوبة إلى الله والاستغفار والندم على ما مضى منك، وإحسان الظن به على حسب ما ظهر من الخير. نعم.","link":"https://binbaz.org.sa/fatwas/6317/واجب-من-اساء-الظن-بالناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11910.mp3","categories":["الأخلاق المذمومة","الرقائق","قضايا المرأة"]},{"id":8528,"question":"الأخ (ح. ص. الأحمدي ) من المدينة له سؤال في هذه الرسالة آخر يقول فيه: ما حكم استعمال الشمة؟ هذا هو سؤاله، يسأل عن استعمال الشمة؟ نعم.","title":"حكم استعمال الشمة","answer":"الجواب: جميع مشتقات الدخان كلها محرمة، والدخان أضراره عظيمة، قد ألف فيه جمع من العلماء والأطباء، وبينوا أضراره الكثيرة، وهو من أسباب أمراض كثيرة من السرطان وغيره، وهو من أسباب موت السكتة، ومضاره كثيرة، حتى قال بعض الأطباء أنها تربو على مضار الخمر، فالواجب تركه بجميع مشتقاته، فالشمة والشيشة وغير ذلك مما يستعمله المدخنون كله ممنوع، فبيعه حرام، وشراؤه حرام، واستعماله حرام، شمة وغيرها، فالواجب على المسلم أن يحذره ويحذره غيره. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6597/حكم-استعمال-الشمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_204/20402.mp3","categories":["الأخلاق المذمومة","الأطعمة والأشربة"]},{"id":8649,"question":"يسأل أيضاً ويقول: ما حكم لعن الرجل لزوجته، وهل تحرم عليه بذلك أم لا؟","title":"حكم لعن الرجل لزوجته","answer":"الجواب: لعن الرجل لامرأته أمر منكر ومن كبائر الذنوب، وهكذا لعنه للناس، فاللعن من الكبائر ولا يجوز للمسلم أن يتعاطى ذلك مع إخوانه المسلمين، وقد صح عن رسول الله ﷺ أنه قال: لعن المؤمن كقتله وهذا يدل على عظم الخطر حتى شبهه بالقتل، فدل ذلك على أنه من كبائر الذنوب، وقال عليه الصلاة والسلام: سباب المسلم فسوق وقتاله كفر متفق على صحته، فدل على أن السباب -وهو اللعن والشتم- من الفسوق يعني: من المعاصي، فوجب تركه والحذر منه، وقال عليه الصلاة والسلام: إن اللعانين لا يكونون شهداء ولا شفعاء يوم القيامة وجاء عنه عليه الصلاة والسلام أنه قال: ليس المؤمن بالطعان، ولا اللعان، ولا الفاحش، ولا البذيء فلا يجوز للمسلم أن يلعن زوجته، وليس لها أن تلعن زوجها، وليس له أن يلعن أولاده، وليس لها أن تلعن أولادها، وهكذا غيرهم من المسلمين لا يجوز سبهم ولعنهم، ولا تحرم عليه زوجته بذلك، لو أنه لعنها لم تحرم بذلك فزوجته باقية على حلها له، لكنه قد أساء وعليه التوبة إلى الله وعليه استسماح زوجته مما حصل من لعنها، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6787/حكم-لعن-الرجل-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21302.mp3","categories":["الأخلاق المذمومة","الحقوق الزوجية"]},{"id":8851,"question":"عندي جدتي تعيش مع خالي وعائلته ويكرهونها، وخالي لا يشتري لها لباس ولا يتركها تذهب إلى بناتها إلا مرة في كل خمسة أشهر، وكل بناتها وأزواجهن يتمنون لها أن تحج إلى بيت الله الحرام وهو لا يبالي، هل يجوز له كل هذا، أفيدونا جزاكم الله خيرًا؟","title":"حكم من يمنع أمه من زيارة بناتها دون وجه حق","answer":"الجواب: الواجب على أخيها وهو خالك أن لا يمنعها من بناتها، وأن لا يمنعها من الحج، هذا لا يجوز له، بل يجب عليه أن يساعد في الخير، وأن يعين على الخير، كما قال النبي عليه الصلاة والسلام في الحديث الصحيح: من كان في حاجة أخيه كان الله في حاجته وقال عليه الصلاة والسلام: والله في عون العبد ما كان العبد في عون أخيه فإذا كانت بناتها وأزواج بناتها لا شر فيهم، ولا يخشى عليها منهم فلا يجوز له منعها، أما إن كان منعها لأمر شرعي؛ لأن بناتها لا خير فيهن يضرونها وهكذا أزواجهن يضرونها لضلالهم أو فجورهم وإظهار معاصيهم أو أذاهم لها بشيء، هذا له شأن آخر.\nوإذا كان بناتها يردن زيارتها فليتصلن بخالهن ويبحثن معه الموضوع حتى يعرفن الأسباب التي من أجلها منع.\nالمقصود: أنه ليس له منعها إلا بسبب شرعي. نعم.","link":"https://binbaz.org.sa/fatwas/7006/حكم-من-يمنع-امه-من-زيارة-بناتها-دون-وجه-حق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16608.mp3","categories":["الأخلاق المذمومة"]},{"id":9114,"question":"والدي حلف يمين على عدم إدخال الفيديو في البيت، ونظرًا لحالتي فقد أدخلت الفيديو دون علمه، ما الحكم، انصحوني جزاكم الله خيرًا؟","title":"حكم مخالفة الابن لأبيه في عدم إدخال الفيديو البيت","answer":"الجواب: أولًا: أنت عاصٍ في هذا الحال؛ لأن الواجب عليك طاعة والدك في المعروف، وهذا من المعروف والفيديو لا يأتي بخير لا يأتي إلا بالشر؛ لأن الغالب على الفيديو أن يكون فيه الصور الخليعة والأغاني والملاهي، فليس لك أن تدخله حتى ولو كان سليمًا عليك أن تطيع والدك، من باب سد الذريعة، فأنت عاصٍ بهذا وعليك التوبة إلى الله وإخراج الفيديو، والوالد ليس عليه كفارة؛ لأنه لم يعلم، لكن أنت العاصي وأنت الذي عليك التوبة إلى الله وإخراج الفيديو من البيت طاعة لأبيك وحذرًا من شر الفيديو؛ لأنه في الغالب لا يسلم من أن يكون فيه ما يغضب الله من الصور الخليعة والكلام المحرم والأغاني المنكرة ونحو ذلك، نسأل الله لنا ولك الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7274/حكم-مخالفة-الابن-لابيه-في-عدم-ادخال-الفيديو-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17908.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9126,"question":"هذه الرسالة التي وردت إلى البرنامج من طالب علم كنا قد وعدنا مرسلها بإتمام أسئلته في هذه الحلقة، السؤال الثاني في رسالة الأخ طالب علم يقول فيه: قال ﷺ: خالفوا المشركين وفروا اللحى وأحفوا الشوارب، وقال في والد أبي بكر: غيروا شعره وجنبوه السواد، ما حكم صبغ الشعر للنساء والرجال إذا صح هذا الحديث أفيدونا أفادكم الله؟","title":"حكم حلق اللحى وصبغ الشعر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذان الحديثان صحيحان ثابتان عن النبي عليه الصلاة والسلام، فالأول: من حديث ابن عمر ، يقول النبي ﷺ: أحفوا الشوارب ووفروا اللحى، وفي لفظ آخر: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، متفق على صحته من حديث ابن عمر رضي الله تعالى عنهما، وروى مسلم في الصحيح عن أبي هريرة  أن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، فهذا يدل على وجوب إكرام اللحى وتوفيرها وإعفائها وإرخائها وأنه لا يجوز للمسلم قصها ولا حلقها، أما ما وقع فيه الكثير من الناس اليوم فهو مؤلم ومحزن ولا ينبغي للمسلم أن يتأسى بأحد في ذلك، فإن الأسوة هو رسول الله عليه الصلاة والسلام ومن سار على نهجه من أهل الخير، أما من خالف نهج الرسول ﷺ وخالف أمره بحلق اللحية أو قصها فليس بقدوة، بل ينبغي أن ينصح بل يجب أن ينصح وأن ينكر عليه ويوجه إلى الخير ولا يقتدى به.\nأما الشوارب فالواجب قصها وإحفاؤها وعدم إطالتها؛ لأن إطالتها مشابهة للمشركين ولا سيما المجوس ، فإنهم يطيلون شواربهم، فالرسول ﷺ أمر بقصها وأمر بجزها، قال أبو محمد بن حزم -وهو من الكبار المعروفين بمعرفة مقالات العلماء- قال: اتفق العلماء على أن إعفاء اللحى وتوفيرها وقص الشوارب أمر مفترض، فحكى الإجماع على أن قص الشوارب مفترض، وعلى أن إعفاء اللحية وتوفيرها أمر مفترض فلا يجوز للمسلم أن يخالف سنة الرسول ﷺ وإجماع أهل العلم في ذلك.\nأما الحديث الثاني: وهو قوله ﷺ في قصة والد أبي بكر: غيروا هذا الشعر وجنبوه السواد، فليس لفظ الحديث هكذا، لفظ الحديث: غيروا هذا الشيب، يقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد رواه مسلم في الصحيح وغيره، ومعنى هذا الحديث الدلالة على أن الشيب يغير وأن السنة تغييره ومن هذا قوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم، فالسنة للمسلم أن يغير شيبه وهكذا المرأة تغير شيبها، لكن بغير السواد، ولهذا قال: اجتنبوا السواد، فيغير الشيب بالحمرة والصفرة والسواد المخلوط بالحمرة لا بأس، كان أبو بكر وعمر يخضبان بالحناء والكتم، وروي عن النبي ﷺ أنه خضب بالحناء والكتم، يعني: بالسواد المخلوط بالكتم يصبغ سواداً والحناء حمرة فإذا اجتمعا صارا سواداً بحمرة فإذا خضب بالسواد المخلوط بالحمرة فلا بأس، أما السواد الخالص فلا يجوز لهذا الحديث ولأحاديث أخرى جاءت في المعنى تدل على تحريم الصبغ بالسواد، ومن هذا ما رواه أبو داود والنسائي وجماعة بإسناد صحيح عن ابن عباس رضي الله عنهما عن النبي ﷺ أنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة، وهذا وعيد عظيم يوجب الحذر. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7285/حكم-حلق-اللحى-وصبغ-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22901.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":9314,"question":"له سؤال آخر السائل (س. ع. م) من مصر، يقول: طلب مني أحد أقاربي أن أحضر له شيئاً من مكة أو المدينة، وعندما ذهبت لشراء ذلك الشيء قال لي التاجر: هو بعشرين ريالاً فقلت له: لا، بل بخمسة عشر، فاشتريته على ذلك، فهل يجوز لي أن أبيعه على صاحبي بعشرين ريالاً كما قال التاجر أول مرة أم لا؟","title":"التحذير من الكذب عند البيع","answer":"الجواب: هذا إليك، لا تكذب، لكن إذا بعته بعشرين أو بأقل أو بأكثر فهذا إليك لا بأس به؛ لأن هذه سلعة ليس لها عندكم سعر معروف، أما إذا كان لها سعر معروف عندكم فلا تغير السعر، بين له أنها تباع بكذا وكذا، وأنك لا تبيعها إلا بكذا وكذا، أما إذا كان ليس لها سعر عندكم معروف، فأنت بالخيار إن شئت بعتها بخمسة عشر الذي اشتريت به، وإن شئت بعتها بأكثر من ذلك أو بأقل من ذلك، وإن شئت وهبتها إياه، فالأمر في هذا واسع والحمد لله، نعم ولكن لا تكذب لا تقل: إنها علي بعشرين وأنت تكذب، ولا تقل: إنها بستة عشر، بسبعة عشر، قل الواقع إنها بخمسة عشر ولكن لا تبيعها إلا بعشرين، أو لا تخبره بشيء، ولكن تحده عليه بهذه القيمة. نعم.\nالمقدم: بارك الله فيكم، المهم أنه لا يقول: إنني اشتريتها بعشرين؟\nالشيخ: نعم، لا يكذب.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7485/التحذير-من-الكذب-عند-البيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23704.mp3","categories":["الأخلاق المذمومة"]},{"id":9380,"question":"قضية تثيرها أختنا هي قضية كثير من النساء المسلمات تقول: كثير من إخواتي في الله يدرسن في الجامعات، وبعض الجامعات مختلطة، تجد الشباب الشيوعي -كما تصفهم سماحة الشيخ- والنصراني والذي ينتمي للأحزاب غير الإسلامية -أيضًا هذا هو قولها- فهل يحق للمرأة السلفية، أي: التي تنتهج منهج السلف هل يحق لها الدراسة في هذا المجال، وهل دراستهن ضرورة للقانون والأحياء والرياضيات، هل هذا ضرورة تبيح للمرأة المسلمة الدراسة مع الشباب سالفي الذكر، مع العلم بأن الدارسات يقلن إنهن سلفيات ويدرسن في هذا الجو المختلط، وأيضًا بحجة الضرورة، فهل يبيح لهن الشرع ذلك، مع أنهن لا يلتزمن أيضًا بلبس النقاب ذلك بأنه ليس بضرورة كما يقلن، وترجو التوضيح في هذه القضايا جزاكم الله خيرا؟","title":"حكم دراسة المرأة في الجامعات التي فيها اختلاط","answer":"الجواب: هذه قضية عظيمة وأمر خطير وليس للنساء أن يدرسن في المدارس والمعاهد والكليات المختلطة؛ لما فيه من الفتنة العظيمة والفساد الكبير؛ ولأنه وسيلة قريبة إلى وقوع ما حرم الله ، فليس لهن أن يدرسن في هذه المدارس أو الكليات أو المعاهد بل يلتمسن الدراسة في جو آخر من المدارس السليمة التي ليس فيها اختلاط، أو بالمكاتبة بينها وبين أهل العلم حتى تسأل عن دينها أو بحضور حلقات العلم في المساجد وهن متحجبات مستورات كما كان في عهد النبي ﷺ، كان النساء في عهد النبي ﷺ يصلين معه ﷺ وهن متحجبات، فإذا صلين خرجن، يسمعن الخطبة ويسمعن العلم، أما دراستهن مع الرجال مختلطات فهذا لا يجوز أبدًا حتى ولو تحجبن، فكيف إذا كن غير متحجبات؟! يكون الشر أكبر وأعظم.\nثم ليس هناك ضرورة إلى أن تدرس ما لا حاجة لها في دينها دراسة الجيولوجيا أو الحساب أو الرياضيات أو غير ذلك، إنما تدرس ما تحتاج إليه في دينها، صلاتها وصومها والمعاملات .. النكاح .. الطلاق، إلى غير هذا مما تحتاج إليه في دينها، وأهم شيء العقيدة، ودرس القرآن الكريم، ومعرفة ما حرم الله وما أوجب الله هذا هو المطلوب، وما زاد على ذلك فالرجال يقومون بذلك وليست في حاجة إلى أن تدرس ذلك.\nلا مانع من دراسة الطب حتى تطب أخواتها النساء، فالشيء الذي هناك للمجتمع حاجة فيه لا بأس في المرأة من جنس تعلم الطب لتطب أخواتها هذا لا حرج فيه وطيب ونافع لكن بشرط عدم الاختلاط، أما إذا كان اختلاط فلا.\nوهذا هو الواجب على المؤمنة أن تتقي الله وأن تبتعد عن أسباب الفتنة، وأن لا تتخذ رأيها وهواها سبيلًا إلى ما حرم الله ، بل تسأل أهل العلم وتستفيد مما عندهم من العلم، والله جل وعلا قال: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] وقال: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] وقال سبحانه: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] فالمرأة مأمورة بأن تبقى في بيتها إلا إذا ظهرت المصلحة في خروجها، ومنهية عن التبرج، ومنهية عن الخلطة بالرجال، والخلوة بالرجال، والخضوع للرجال بالقول كل هذا مما يضرها في دينها وأخلاقها، وقد قال عليه الصلاة والسلام: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات رءوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها وإن ريحها ليوجد من مسيرة كذا وكذا فبين ﷺ أن هذا الصنف من النساء وهن الكاسيات العاريات المائلات عن الحق والمميلات إلى الباطل، هم من أهل النار من المتوعدين بالنار لعدم قيامهن بواجب الستر والحجاب، ولتساهلهن بما يجر الفتنة عليهن ويسبب وقوعهن في الفاحشة ولا حول ولا قوة إلا بالله، فنسأل الله لأخواتنا في الله الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/7544/حكم-دراسة-المراة-في-الجامعات-التي-فيها-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18703.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":9451,"question":"السؤال الثالث والأخير في رسالة الأخت السائلة من العراق تقول: في الأفراح كفرح الزفاف مثلاً هل يجوز الغناء والتزين له؟ وهناك رقصة أحياناً عندنا تسمى: بالدبكة كانت تجري سابقاً للرجال فقط بمعزل عن النساء، لكن في الوقت الحاضر تطور الأمر فأصبحت هذه الرقصة يختلط فيها الرجال والنساء في مناسبات الزواج، فما حكم الشرع في ذلك بارك الله فيكم؟","title":"حكم الغناء للنساء ورقصة الدبكة للرجال مع النساء","answer":"الجواب: أما الغناء المعروف الذي ليس فيه تعد لحرمات الله، بل الغناء في مدح أهل الزوجة أو أهل الزوج مع الدف فلا بأس مثل ما جاء في حديث عائشة لما زاروهم قالوا:\n\n\t\n\t\t\n\t\t\tأتيناكم أتيناكم\n\t\t\tفحيانا وحياكم\n\t\t\n\t\n\n\n\n\t\n\t\t\n\t\t\tولولا الذهب الأحمـر\n\t\t\tما حلت بواديكم\n\t\t\n\t\n\n\n\n\t\n\t\t\n\t\t\tولولا الحنطة الحمـراء\n\t\t\tما سمنت عذاريكم\n\t\t\n\t\n\nوما أشبه ذلك من الأشعار والغناء يتعلق بمدح الزوج مدح الزوجة مدح أهلهم، أهل الزوج أو أهل الزوجة، أو أشياء نحو هذا ليس فيها ظلم لأحد، وليس فيها غيبة لأحد، فهذا لا بأس به مع الدف بين النساء خاصة، هذا مشروع من باب إعلان النكاح، كما أمر النبي بإعلان النكاح عليه الصلاة والسلام، وأمر بضرب الدف فيه؛ لأن إعلانه أمر مطلوب حتى يعرف أن فلانة تزوجت فلاناً، وحتى لا يظن بهم السوء، فإن السفاح والزنا يكون بالسر، أما الزواج الشرعي فيكون بالعلن.\nأما الدبكة التي يفعلها الرجال فلا يجوز، وإذا فعلوها مع النساء كان أشر وأقبح، فلا يجوز فعل ذلك من الرجال مع النساء مختلطين؛ لما فيه من الفتنة والفساد الكبير، أما الرجال فليس لهم دخل في هذا إنما هذا للنساء، وإذا فعل الرجال شيئاً يوافق الشرع مثل التدرب على السلاح، وحمل الأثقال، مثل اللعب بالحراب، والتروس، والرمي هذا هو شأن الرجال وحدهم، في أي مناسبة.\nأما اختلاط الرجال بالنساء في الأعراس أو في غير الأعراس هذا منكر لا يجوز؛ لما فيه من الفتنة، قد قال عليه الصلاة والسلام: ما تركت بعدي فتنة أضر على الرجال من النساء، واختلاط الرجال بالنساء في كل مناسبة ينبني عليه شر كثير، ويفضي إلى فتنة عظيمة، فيجب الحذر من ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7630/حكم-الغناء-للنساء-ورقصة-الدبكة-للرجال-مع-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24007.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":9473,"question":"تقول في آخر رسالتها: وليت سماحة الشيخ يوضح للمستمعات ويبين لهن من من الرجال يجوز أن تخرج معهم المرأة، خاصة أن كثيراً من النساء في هذه الأيام يخرجن مع الرجال الأجانب من سائق وغيره وحدهن؟","title":"حكم خروج المرأة مع السائق الأجنبي لوحدهما","answer":"الجواب: نعم، لا يجوز للمرأة أن تخرج مع السائق وحدها ولا مع أخي زوجها وحده، ولا مع عم زوجها وحده، ولا مع غيرهما من الأجانب، أما مع محرمها كأبيها وعمها وخالها وأبي زوجها وابن زوجها وجد زوجها وابن بنت زوجها وابن ابن زوجها لا بأس به، هؤلاء محارم، أما الخروج مع أجنبي سواء كان السائق أو غير السائق فلا يجوز؛ لأن هذا خلوة، وجوده معها في السيارة خلوة ويخشى منها شر كثير، فلا يجوز لها أن تذهب مع السائق الأجنبي وحدها، بل لابد أن يكون معهما ثالث ممن يؤمن به ضرر هذا الركوب، ويحصل به عدم الخلوة من زوجة السائق، أم السائق، امرأة أخرى، رجل آخر ممن يوثق به لا بأس بذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7640/حكم-خروج-المراة-مع-الساىق-الاجنبي-لوحدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24104.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":9489,"question":"الأخ إبراهيم بعث برسالة من الطائف يقول فيها: حصل بين والدي وشخص منازعات في أرض لا يعرف من هو صاحبها الأحق، أهو والدي أم الشخص الآخر؟! فحضر المشكلة أهل الخير فأرادوا الإصلاح بينهما ولم يستطيعوا ذلك، فأصر والدي أن الأرض هي له، وهي ليست له حقًا كلها، فحاولت إقناع والدي بأن يرضى بالصلح أو يأخذ من خصمه اليمين، فرفض كل المحاولات فطلعت مني كلمة مع الزعل فقلت لوالدي: أنت كاذب، فما هو الحكم في ذلك، وما هي كفارتها، والله يحفظكم، والسلام عليكم ورحمة الله وبركاته؟","title":"إساءة الولد الأدب مع والده","answer":"الجواب: عليك التوبة إلى الله من ذلك واستسماح والدك، عليك أن تستغفر الله وتتوب إليه من هذه المجابهة، وعليك أن تستبيح والدك وتستحله، تقول: سامحني يا والدي فهي زلة مني، والله يسامحك.\nوعليك أن تنصحه إذا كنت تعلم أن بعض الأرض ليس له عليك أن تنصحه، وتبين له الأسباب التي جعلت هذا الشيء ليس له وأنه لخصمه فإن هذا حق، والمؤمن يقول بالحق على نفسه وعلى أبيه وعلى غيره، كما قال سبحانه في كتابه العظيم: يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَى أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالأَقْرَبِينَ إِنْ يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللَّهُ أَوْلَى بِهِمَا [النساء:135] الآية.\nفالمؤمن يقول الحق على نفسه وعلى أبيه وعلى أمه لكن بطريقة حسنة وبأسلوب حسن، لا بالمجابهة القبيحة، تقول: يا والدي! أنا عندي علم، أشهد ...... أو قال لي فلان، أو علمت كذا وكذا، تنصح بينك وبينه، حتى يهتدي إن شاء الله وحتى يقنع بالحق، وحتى يعطي الحق لصاحبه من دون أن تجابهه مجابهة تسيء الأدب معه وتكدر حالك معه فإن هذا لا يليق من الولد مع الوالد.\nفتستغفر الله جل وعلا، وتتوب إليه وتستسمح أباك، ولا يمنعك هذا من نصحه والشهادة بالحق ولو عليه، والله المستعان وهو ولي التوفيق ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7651/اساءة-الولد-الادب-مع-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19208.mp3","categories":["الأخلاق المذمومة"]},{"id":9506,"question":"يسأل أيضاً ويقول: هل يجوز للكاتب أن يؤلف قصصاً وحكايات، ويرتب عليها أحداث إنشاءً من عنده، أي: أنها لم تقع أصلاً؟","title":"حكم تأليف القصص والحكايات","answer":"","link":"https://binbaz.org.sa/fatwas/7674/حكم-تاليف-القصص-والحكايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24308.mp3","categories":["الأخلاق المذمومة"]},{"id":9508,"question":"هذه رسالة وردتنا من سليمان مبارك عمر مخاش من الرياض، يقول: ما حكم الشرع في حالة تعرض أحد من المسلمين للانتهاك في عرضه عندما يكون الشخص في رحلة برية أو بحرية أو جوية وقد يناديك للاستغاثة بك، وفي حالة تلبيتي ذلك بدافع ديني وأخوي وإنساني قد تقوم في أثناء دفاعك عنه بقتل أحد الأفراد المعتدين الغاصبين، علماً أنك لم تبخل بأي وسيلة لعدم التعرض لقتله، ولكن اضطررت إلى ذلك لأجل دفعه عن عرض أخيك المستنجد بك الذي معه نساء، أو يعتدى عليه هو في عرضه أو ماله أو نحو ذلك، أفيدونا ما الحال إذا كان هناك فيه قتل، وهل ينطبق على ذلك قول الرسول صلى الله عليه وسلم: «القاتل والمقتول في النار» أفيدونا أفادكم الله؟","title":"حكم قتل الصائل","answer":"الجواب: الواجب على المسلمين التآمر بالمعروف والتناهي عن المنكر أينما كانوا في الطائرة أو في غيرها، وعلى المسلم أن يعين أخاه في الحق وليس له أن يعينه في الباطل، وعليه أن يذب عن عرضه، فلا ينبغي له أن يجلس مع المغتابين بل ينكر عليهم ويعظهم ويذكرهم حتى لا يغتابوا إخوانهم؛ لأن الله سبحانه يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] فالغيبة منكرة ومن الكبائر.\nفإذا جلست مع قوم يغتابون الناس فأنت شريك لهم في الإثم، إلا أن تنكر عليهم أو تفارقهم، فعليك أن تنكر فإن أجابوا فالحمد لله، وإلا فعليك أن تفارقهم ولا تجلس معهم على ما حرم الله عز وجل، وإذا تعدى زيد على أخيك، فالرسول ﷺ قال: انصر أخاك ظالماً أو مظلوماً، قالوا: يا رسول الله! نصرته مظلوماً فكيف أنصره ظالماً؟ قال: تمنعه من الظلم.\nوفي لفظ: تأخذ على يديه أي تحجزه عن الظلم، هذا نصر الظالم منعه من الظلم، فإذا تعدى أحد على أخيك توسط بينهم بالإحسان، في منعه العدوان، تحول بينهم أنت وإخوانك جميعاً، توسطون بينهم، تفكوا مشكلهم، تمنع هذا من هذا، وإذا كان لهم دعوى أو خصومة بعد ذلك يتصلوا بالمحكمة، لكن لا تتركونهم في الطائرة أو في السيارة أو في الباخرة أو في أي مكان يتقاتلان ويظلم أحدهما الآخر لا، بل توسطوا بينهم وحلوا مشكلهم، وامنعوا هذا من هذا، وكونوا جلساء خير وأعواناً في الخير، فانصروا المظلوم وامنعوا الظالم، هذا هو الواجب عليكم بدون قتل، أما القتل لا، لا يقتل هذا ولا هذا، بل عليكم أن تحولوا بينهم من التعدي، وأما القتل فلا يجوز الإقدام على القتل، بل هذا يؤجل إلى أن تنظر المحكمة في أمرهما، ومن كان يستحق قتلاً لأنه فعل ما يوجب القتل هذا له شأن آخر.\nفالحاصل أن عليك أن تساعد أخاك في رد ظلامته وفي منع الظلم عنه بغير قتل، أما القتل فلا؛ لأن القتل يحتاج إلى عناية ويحتاج إلى نظر في أسباب القتل، وإنما تحجز بينهما، تمنع هذا من التعدي على هذا، أنت وإخوانك الحاضرون، تتعاونون على منع هذا من ظلم أخيه، وإذا كانت لهم دعوات تؤجل حتى يصلوا إلى محلهم أو إلى بلد أخرى فيه القضاء، فيتحاكمون إلى القضاة فيما أشكل بينهم.\nلكن موضوع القتل موضوع كبير وعظيم فليس لأحد أن يقتل الآخر بل عليهم أن يتوقفا، وعلى أنصارهما أن يحولا بينهم وبين ذلك حتى لا يقع قتال. نعم.\nالمقدم: بارك الله فيكم، لو كان مع الشخص نساء وهو في البر واعتدي على عرضه واستغاث بأحد الناس، واضطر صاحب النساء والمساعد له في أن يدافعا عن عرضهما ووصل الأمر.. القتل.\nالشيخ: عليه أن يدافع، فإن قتل فهو شهيد، وإن قتل الظالم فلا شيء عليه.\nالمقدم: ربما هذا هو مقصود السائل يا شيخ.\nالشيخ: المقصود أنه إذا اعتدي على عرضه أو أراد قتله أحد فهذا له أن يدافع، من قتل دون ماله فهو شهيد، من قتل دون دمه فهو شهيد، من قتل دون دينه فهو شهيد، من قتل دون أهله فهو شهيد ثبت في الصحيح أن رجلاً قال: يا رسول الله! الرجل يأتيني يريد مالي؟ قال: لا تعطه مالك. قال: أرأيت إن قاتلني؟ قال: قاتله. قال: فإن قتلني؟ قال: فأنت شهيد. قال: فإن قتلته؟ قال: فهو في النار هذا رخص النبي في الدفاع عليه الصلاة والسلام يدافع عن ماله، فالعرض أكبر والدين أكبر، فإذا أراد الظالم أن يتعدى على زوجته أو بنته أو أمه فله أن يمنع ذلك بما استطاع، إن امتنع بالكلام أو بالعصا منعه، فإن لم يمتنع إلا بالقتل كالسيف والسكين ونحو ذلك فله ذلك، فإن صدق من جهة ولاة الأمور فلا قصاص عليه إذا ثبت ما يدل على صدقه، وإن لم يثبت هذا يرجع إلى المحكمة في تحري الحقائق والنظر في الواقعة، فإن ثبت ما يدل على صدقه وإلا فعليه قصاص. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7680/حكم-قتل-الصاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24314.mp3","categories":["الجنايات والحدود","الأخلاق المذمومة"]},{"id":9554,"question":"هذه رسالة وردتنا من (م. أ. ع) مصري ويعمل في المنطقة الشرقية يقول: أسافر عن زوجتي لمدة عام ولا أذهب إليها إلا في الإجازة فقط ومدة غيابي عنها تطول وأخشى على نفسي من أن يذهب بي الشيطان لارتكاب الفواحش فأتجرأ على استعمال العادة السرية مضطراً، فما حكم ذلك؟ بارك الله فيكم.","title":"حكم العادة السرية عند الضرورة","answer":"الجواب: العادة السرية لا تجوز وهي الاستمناء باليد أو بغيرها من الآلات لا يجوز؛ لأن الله يقول سبحانه: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] هذا غير ما أباح الله فيكون عدواناً وظلماً، وقد ذكر الأطباء العارفون أن العادة السرية فيها مضار كثيرة، وتعقب عواقب وخيمة، وربما أفضت بالإنسان إلى أن يحرم من النسل بعد ذلك. فالمقصود أنها فيها أضرار كثيرة ولا يجوز تعاطيها للمؤمن، وفي إمكانك أن تأتي بزوجتك معك، تطلب مجيئها إذا تيسر ذلك أو تسافر إليها بين وقت وآخر، تأخذ إذن من صاحبك أو تشرط على من تعاقدت معه ذلك حتى تذهب إلى زوجتك في أثناء السنة أو تستعين بالله ثم بالصوم أو تتزوج زوجة ثانية في محل عملك ولو غضبت الغائبة لا يضرك؛ لأن هذا لدفع الشر ودفع الفساد، فإذا لم يتيسر حضورها وأنت قادر لك عذر شرعي تزوج ثانية فالزواج مباح والحمد لله، لك أربع في الشرع، والله يقول: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ [النساء:3] من احتاج أن يتزوج أو عنده قدرة على الزواج أخذ ثنتين أو ثلاثاً أو أربعاً فلا حرج عليه وقد ينفع الله بذلك حتى يعفهم وحتى يحصل لهن منه أولاد فيكون له في هذا خير عظيم ولهن جميعاً، وطبيعة النساء يكرهون الجار طبيعة النساء كراهة الجارات ولكن قد تكره المرأة الجارة ويكون لها فيها خير من أسباب عفة زوجها، ومن أسباب وجود أولاد صالحين، ومن أسباب العدل بينها وبين ضرتها، فلا ينبغي للمرأة أن تكره الضرة الجارة إذا دعت الحاجة إليها وكان زوجها قادراً يستطيع العدل فالحمد لله، أما العادة السرية فلا. نعم.\nالمقدم: بارك الله فيكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/7719/حكم-العادة-السرية-عند-الضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27003.mp3","categories":["الأخلاق المذمومة"]},{"id":9633,"question":"ويسأل أيضاً ويقول: هل الكلام في عرض الشخص الذي يزني أو يترك الصلاة أو يفطر في رمضان يكون من الغيبة أم لا؟","title":"حكم غيبة المجاهر بالمعاصي وهجره","answer":"الجواب: من أظهر المعاصي لا غيبة له، من لا يصلي يجب أن ينكر عليه ويذكر بعيبه ويحذر منه ويهجر ولا تجاب دعوته، ولا يزار، ولا يعاد إذا مرض حتى يتوب إلى الله عز وجل، وهكذا من أظهر الفواحش بين الناس كالزنا جهرةً بين الناس أو شرب الخمر كل هذه المعاصي الظاهرة يستحق صاحبها الهجر والإنكار والتأديب، وأعظمها ترك الصلاة فإنه كفر، كفر أكبر، وإن لم يجحد وجوبها فهو كفر أكبر في أصح قولي العلماء؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر أما من جحد الوجوب كفر بإجماع المسلمين.\nوقد بين أهل العلم أن من تجاهر بالمعاصي يستحق الهجر، وقد هجر النبي ﷺ ثلاثةً من الصحابة تخلفوا عن الغزو بغير عذر شرعي فهجرهم النبي ﷺ وهجرهم الصحابة خمسين ليلة حتى تابوا وتاب الله عليهم.\nفلا يجوز للمسلمين أن يتساهلوا مع تارك الصلاة، بل يجب أن يهجروه ويجتهدوا في أسباب هدايته، فإن اهتدى وإلا وجب على ولي الأمر أن يستتيبه، فإن تاب وإلا قتل عن طريق المحكمة الشرعية وما يقوم مقامها، استتابته لعله يرجع لعله يتوب، ولا يجدوا إيمان الناس إذا عرفوا بأنهم قد تركوا الصلاة وهم يدعون الإسلام، وهكذا من تظاهر بالمعاصي بشرب الخمر أو الربا أو القمار أو ما أشبه هذا من المعاصي الظاهرة يجب أن يمنع من ذلك وأن يقام عليه الحد إذا كانت المعصية فيها حد كالخمر، أو يؤدب ويعزر بما يردعه إذا كانت المعصية لا حد فيها كالقمار والربا ونحو ذلك؛ لأن هذا من أسباب صلاح المسلمين، ومن أسباب صلاح المجتمع، ومن أسباب اختفاء الرذائل وظهور الفضائل، وإذا ترك الناس من غير ردع انتشرت المنكرات، وظهرت الشرور، وفسد المجتمع ولا حول ولا قوة إلا بالله، نسأل الله السلامة والعافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7797/حكم-غيبة-المجاهر-بالمعاصي-وهجره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25007.mp3","categories":["الأخلاق المذمومة"]},{"id":9644,"question":"السؤال الخامس والأخير في رسالة الأخ (ح. ع. س) من الأردن يقول فيه: هل الديوث الذي يتكلم عما يجري بينه وبين زوجته في الخلوة الصحيحة، أم من هو الديوث بالشكل الصحيح في نظر الدين الإسلامي الحنيف جزاكم الله خيرًا؟","title":"حقيقة الديوث","answer":"الجواب: الديوث: الذي يرضى بالفاحشة في أهله، يرضى أن تؤتى زوجته يرضى بأن تروح زوجته للزنا هذا هو الديوث اللي يرضى أن تؤتى زوجته وأن يزنى بها لقلة غيرته ولفساد غيرته ولضعف إيمانه أو عدم إيمانه هذا يقال له: ديوث.\nأما الذي يتحدث عن حاله مع زوجته فهذا ماجن، وقد يكون فاسقًا بذلك ولكن لا يكون ديوثًا إنما الديوث الذي يرضى بالفاحشة في أهله نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/7810/حقيقة-الديوث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19407.mp3","categories":["الأخلاق المذمومة"]},{"id":9742,"question":"أولى رسائل هذه الحلقة وردت من المستمع (ف. ع. م. ص) يقول في رسالته: أنا رجل متزوج وبعد زواجي بحوالي ست سنوات، سافرت إلى بلد أخرى من أجل السعي والبحث عن الرزق، وكنت أصلي وأصوم ولله الحمد، ولكن لعب بي الشيطان ومارست العادة السرية؛ لأنني بعيد عن زوجتي، وبعد هذا قلت: هذا عمل حرام ولا بد أن أتركه، فبدأت أصلي وأصوم وقلت: حلفت علي الطلاق بالثلاث لا أفعل هذا العمل مرة ثانية، وكانت نيتي الطلاق، وبعد فترة لعب بي الشيطان مرة ثانية فوقعت في هذا الأمر، ثم رجعت عنه، ف هل هذا الطلاق واقع علي أم لا، مع العلم أن زوجتي لم تسمعه، أفيدوني أفادكم الله؟","title":"حكم الحلف بالطلاق مع قصد الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن العادة السرية التي يعتادها بعض الناس محرمة، وفيها أضرار كثيرة وهي الاستمناء، وقد قال الله عز وجل في وصف المؤمنين: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7].\nوهذه العادة الخبيثة هي غير ما أباح الله من إتيان الزوجة والسرية، فتكون محرمة وتكون من العدوان الذي بينه الله سبحانه في هذه الآية، قد بين الأطباء العارفون بهذه العادة مضرتها العظيمة وشرها الكثير.\nفالواجب على كل مؤمن أن يحذرها غاية الحذر.\nأما ما ذكره السائل من تعليقه الطلاق على العودة، فإذا كان يقصد مثل ما قال: إيقاع الطلاق، فإنه يقع طلقة واحدة؛ لعوده إليها؛ لأنه طلاق معلق على شرط يقصد منه الوقوع فوقعت بذلك طلقة واحدة على الصحيح؛ لأنه ثبت من حديث ابن عباس رضي الله عنهما عن النبي ﷺ ما يدل أن إيقاع الثلاث بلفظ واحد يعتبر طلقة واحدة.\nولك أيها السائل! مراجعتها بعدما عاودت هذه العادة الخبيثة؛ لأنه طلاق رجعي.\nأما إذا كنت لم تطلقها قبل هذا طلقتين، أما إن كنت طلقتها قبلها طلقتين فهذه تكون الثالثة ولا رجعة، نسأل الله للجميع الهداية.\nالمقدم: وبالنسبة سماحة الشيخ لما قاله: بأن زوجته لم تسمع هذا الطلاق؟\nالشيخ: ولو ما سمعت، ماله تعلق، سماعها وعدم سماعها سواء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7908/حكم-الحلف-بالطلاق-مع-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25601.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9764,"question":"إذا اشترى لنا والدي بعض الأشياء للبيت، ووالدتي وَلِيَّة ذلك، فأخذنا منه دون أن نستأذن من الوالدة، أخذت أنا وإخوتي فما الحكم.الشيخ: أعد.المقدم: تقول: إذا اشترى لنا والدي بعض الأشياء للبيت، ووالدتي ولية ذلك، فأخذنا منه أنا وإخوتي بدون علم منها فما حكم ذلك؟","title":"حكم أخذ الولد مما يشتريه الأب للبيت بدون إذنه","answer":"الجواب: إذا كنتم في بيوت مستقلة فليس لكم الأخذ إلا بإذن الوالد؛ لأنه اشتراه لبيته، والوالدة لا تعطيكم شيء إلا بإذنه، إلا إذا كنتم تعلمون أنه يسمح وليس عنده في هذا مانع فلا بأس، فإذا اشترى لحمة لبيته لا تأخذوا منها شيء، أو فاكهة للبيت لا تأخذوا إلا بإذنه، الإذن النطقي أو العرفي إذا كان من عرفه عرفكم المعروف بينكم أنه يتسامح وأنه لا يهمه هذا الأمر فلا بأس، وإلا فليس لكم الإقدام على هذا الشيء، الذي اشتراه لبيته وعند زوجته وعائلته الصغار، وأنتم في بيوت مستقلة لا تأخذوا منه شيء إلا بإذن، والوالدة كذلك لا تعطيكم إلا بإذن، إلا إذا كان هناك إذن معروف من والدكم، إذن صريح أو تدل عليه شواهد الحال وما عرف من حالته وسماحه وأنه لا يأبى أن يؤخذ من هذا الشيء إذا عرف هذا فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7937/حكم-اخذ-الولد-مما-يشتريه-الاب-للبيت-بدون-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25711.mp3","categories":["الأخلاق المذمومة"]},{"id":9770,"question":"إذا اشترى لنا والدي بعض الأشياء للبيت، ووالدتي وَلِيَّة ذلك، فأخذنا منه دون أن نستأذن من الوالدة، أخذت أنا وإخوتي فما الحكم.الشيخ: أعد.المقدم: تقول: إذا اشترى لنا والدي بعض الأشياء للبيت، ووالدتي ولية ذلك، فأخذنا منه أنا وإخوتي بدون علم منها فما حكم ذلك؟","title":"حكم أخذ الولد مما يشتريه الأب للبيت بدون إذنه","answer":"الجواب: إذا كنتم في بيوت مستقلة فليس لكم الأخذ إلا بإذن الوالد؛ لأنه اشتراه لبيته، والوالدة لا تعطيكم شيء إلا بإذنه، إلا إذا كنتم تعلمون أنه يسمح وليس عنده في هذا مانع فلا بأس، فإذا اشترى لحمة لبيته لا تأخذوا منها شيء، أو فاكهة للبيت لا تأخذوا إلا بإذنه، الإذن النطقي أو العرفي إذا كان من عرفه عرفكم المعروف بينكم أنه يتسامح وأنه لا يهمه هذا الأمر فلا بأس، وإلا فليس لكم الإقدام على هذا الشيء، الذي اشتراه لبيته وعند زوجته وعائلته الصغار، وأنتم في بيوت مستقلة لا تأخذوا منه شيء إلا بإذن، والوالدة كذلك لا تعطيكم إلا بإذن، إلا إذا كان هناك إذن معروف من والدكم، إذن صريح أو تدل عليه شواهد الحال وما عرف من حالته وسماحه وأنه لا يأبى أن يؤخذ من هذا الشيء إذا عرف هذا فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7937/حكم-اخذ-الولد-مما-يشتريه-الاب-للبيت-بدون-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25711.mp3","categories":["الأخلاق المذمومة"]},{"id":9798,"question":"وهذه رسالة من الأخ أحمد حسن زيد من الجمهورية العربية اليمنية في رسالته عدة أسئلة من بينها: أنه يقول: رجل له ثلاثة أولاد لا يقصرون في طاعته وبره وهو يدعو عليهم، هل يضرهم دعاؤه؟","title":"دعاء الآباء على الأبناء","answer":"الجواب: لا ينبغي للمؤمن أن يدعو على أولاده بل ينبغي له أن يحذر ذلك؛ لأنه قد يوافق ساعة إجابة فينبغي له أن لا يدعو عليهم وإذا كانوا صالحين كان الأمر أشد في تحريم الدعاء عليهم، أما إذا كانوا مقصرين فينبغي له أيضًا أن لا يدعو عليهم بل يدعو لهم بالهداية والصلاح والتوفيق، هكذا ينبغي للمؤمن، وقد جاءت النصوص عن النبي ﷺ تحذر من دعاء الإنسان على ولده أو على أهله أو على ماله؛ لئلا يصادف ساعة إجابة فيضر نفسه ويضر أهله ويضر ولده.\nفينبغي لك يا أيها السائل أن تحفظ لسانك وأن تؤكد على من تعلمه يتعاطى هذا الأمر بأن يحفظ لسانه وبأن يتقي الله في ذلك حتى لا يدعو على ولده ولا على غيره من المسلمين بل يدعو لهم بالخير ويدعو لهم بالسداد والاستقامة لا بالدعاء عليهم بما يضرهم، والله المستعان. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7965/دعاء-الاباء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19614.mp3","categories":["الأخلاق المذمومة"]},{"id":9810,"question":"له استفسار ثانٍ يقول: إذا أراق الرجل الأعزب منيه مع نفسه فهل يعتبر هذا زنا، وما حكم ذلك؟","title":"مضار العادة السرية وحكمها","answer":"الجواب: هذا يسمى عند بعض الناس: العادة السرية، ويسمى: الاستمناء، والذي عليه جمهور أهل العلم تحريمه، وهو الصواب؛ لأن الله جل وعلا قال لما ذكر المؤمنين وصفاتهم، قال: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7] والعادي هو الظالم المتعدي لحدود الله، فأخبر سبحانه أن من تجاوز جماع الزوجة وجماع السرية فإنه عادي، ولا شك أن الاستمناء خارج عن ذلك، ولهذا استنبط العلماء من هذه الآية الكريمة تحريم هذه العادة السرية وهي الاستمناء باليد، يعني: إخراج المني بيده عند تحرك الشهوة، فلا يجوز له هذا العمل، وفيه مضار كثيرة قالها الأطباء، وقد ألف بعض أهل العلم في ذلك مؤلفًا جمع فيه مضار هذه العادة السرية، فينبغي لك أيها السائل أن تحذر ذلك وأن تبتعد عن هذه العادة، ففيها من المضار الكثيرة ما لا يحصى، ولأنها عادة تخالف ظاهر كتاب الله العزيز وتخالف ما أباح الله لعباده، فيجب اجتنابها والحذر منها، وينبغي لمن اشتدت به الشهوة وخاف على نفسه أن يبادر بالزواج ويسارع إلى الزواج، فإن لم يتيسر ذلك فليصم، قال النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم -ولم يقل ومن لم يستطع فليخرجها بيده أو فليستمني، بل قال- ومن لم يستطع فعليه بالصوم فإنه له وجاء فالنبي ﷺ ذكر أمرين:\nأحدهما: المبادرة بالزواج لمن قدر.\nالثاني: الاستعانة بالصوم لمن عجز عن النكاح؛ لأن الصوم يضعف مجاري الشيطان، والشيطان يجري من ابن آدم مجرى الدم، والصائم بسبب تركه الأكل والشرب يضيق على الشيطان مجاريه، فينبغي لك يا عبد الله أن تتأدب بالآداب الشرعية، وأن تجتهد في إحصان نفسك بالزواج الشرعي حتى ولو بالاستدانة والقرض، فإن الله يوفي عنك ، فإن التزوج عمل صالح وصاحبه ممن يعان، والحديث: ثلاثة حق على الله عونهم -ذكر منهم- المتزوج يريد العفاف فبادر إلى الزواج ولو بالاستدانة والقرض وليوف الله عنك جل وعلا، فمن أخذ أموال الناس يريد أداءها أدى الله عنه، واحذر هذه العادة القبيحة، واحذر سائر الفواحش، فإن أعظم من ذلك الزنا، فإنه من الكبائر العظيمة، والذي يتساهل في الزواج قد يفضي به ذلك إلى الزنا أو إلى الاستمناء المحرم، فينبغي لك يا عبد الله أن تحذر أسباب الشر وأن تبتعد عن وسائله، وأن تحرص على المبادرة بالزواج الشرعي إذا استطعت ذلك، وأبشر بالعون من الله والتيسير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7977/مضار-العادة-السرية-وحكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19709.mp3","categories":["الأخلاق المذمومة"]},{"id":9898,"question":"هذه سائلة لم تذكر الاسم في هذه الرسالة، تقول: كنت عاقة لوالدتي ، والآن تبت إلى الله ، وكانت تدعو علي بعدم التوفيق، ففشلت في دراستي وتذكر بأنها الآن هي عانس، فهل هذا بسبب أن الله عاقبها وما نصيحتكم لها يا سماحة الشيخ؟!","title":"عقوبة عقوق الوالدين","answer":"الجواب: قد يكون ذلك عقوبة فعليها التوبة إلى الله وعليها بر والدتها ، والحرص على استرضائها، قد يكون هذا الفشل بسبب عقوقها، فإن المعاصي شرها عظيم والله يقول: وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30] ويقول سبحانه: وَمَا أَصَابَكََ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ [النساء:79] فقد يكون فشلها بأسباب عقوقها، أو بأسباب معاصٍ أخرى أو بأسباب الجميع، فالواجب التوبة والندم والإقلاع وأسأل الله التوفيق والإعانة. نعم.","link":"https://binbaz.org.sa/fatwas/8066/عقوبة-عقوق-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27310.mp3","categories":["الأخلاق المذمومة"]},{"id":9935,"question":"وهذه رسالة من الجمهورية العراقية محافظة بغداد من السائل (ع. ك. ج) يقول في رسالته: توجد امرأة متزوجة ومطلقة ومتزوجة من شخص آخر، ولديها بنات من زوجها السابق وتدخل على بيت زوجها السابق وتراه ويراها، ونفس الحالة مع ابنتها الكبيرة، فهي متزوجة ومطلقة ولها ولد من زوجها السابق وزوجها السابق يراها وتراه، ما الحكم في ذلك؟الشيخ: مع الأسف فإنه ..!المقدم: أعيد السؤال؟الشيخ: نعم.المقدم: السؤال مرة أخرى امرأة مطلقة ومتزوجة من شخص آخر، ولها بنات منه وهو يدخل عليها وتراها ويراه زوجها السابق، وكذلك ابنتها الكبرى نفس الحالة مطلقة ومتزوجة بشخص آخر وزوجها السابق يراها وتراه؟","title":"حكم ظهور المرأة المطلقة على زوجها السابق","answer":"الجواب: هذا فيه التفصيل، إن كان دخوله عليها لرؤية بناته وهكذا المرأة الأخرى يدخل الرجل عليها لأجل بنته بحضور أبيها بحضور أخيها بحضور زوجها الثاني على وجه لا شبهة فيه ولا فتنة فلا بأس بهذا ولا ريبة في هذه الحال، إذا كان الدخول دخولًا واضحًا شريفًا ليس فيه شيء ليرى بناته ولو سلمت عليه لا بأس مع الحجاب مع التحجب عنه، تسلم عليه لابد أن يكون حاضرًا من تزول معه التهمة.\nأما دخوله على زوجته السابقة من أجل بناته مطلقًا من دون حضور أحد هذا لا يجوز؛ لأنه قد يفضي إلى فتنة وقد يفضي إلى تهمة ولاسيما إذا كانت بنات صغارًا فإن الفتنة تكون أكبر.\nفالحاصل أنه لا يدخل عليها إلا إذا كان معه من تزول معه التهمة من زوجها الجديد أو أبيها المأمون أو أخيها المأمون الذي لا يتهم فلا بأس بهذا.\nأما الدخول الذي تكون معه التهمة فيمنع ؛ لأن الشيطان يجري من ابن آدم مجرى الدم، وقد تتفق معه على شيء قد تقول لبناتها: اذهبوا إلى كذا واذهبوا إلى كذا، فالشيطان موجود وتلبيسه كثير وتزيينه كثير للفساد والشر، فالواجب على المؤمن التحرز من هذا الشيء وأن لا يقدم عليه إلا بطريقة سليمة ليس فيها تهمة، هذا هو الواجب في هذه المسائل. نعم.\nالمقدم: طيب جزاكم الله خيرا إذًا نفهم من هذا أنه إذا أراد أن يراها وتراه لابد من وجود محرم حتى لا يكون هناك خلوة ولابد أن تحتجب منه؟\nالشيخ: الحجاب لابد منه، أما المحرم ما هو بلزوم لابد من وجود أناس لا يتهم معهم في الدخول.\nالمقدم: يعني حتى تنتفي الخلوة؟\nالشيخ: مثلًا إذا دخل ومعه ناس معروفون أو عندها يعني نساء معروفات مثل أخواتها مثل أمها وجدتها مثل ناس يعني تزول معهم التهمة ولكن إذا كان محرم فهو أكمل كأخيها وأبيها وعمها المأمون، يكون أكمل ولو دخل عليها وعندها النساء المأمونات من أم أو أخوات ونحو ذلك المقصود نساء تزول معهن التهمة، على طريقة لا تهمة فيها، هذا الضابط أن تكون الطريقة لا تهمة فيها. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8099/حكم-ظهور-المراة-المطلقة-على-زوجها-السابق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19909.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":10029,"question":"تقول: في قاعة الامتحان يكون معي في القاعة زميلاتي لا يعرفن الإجابة، وأقوم بمساعدتهن فهل يعتبر هذا العمل نوع من الغش، وبالرغم من أن القصد مساعدة زميلاتي جزاكم الله خيراً.","title":"حكم إعانة الطالبات في قاعة الاختبار","answer":"الجواب: هذا يرجع إلى النظام والتعليمات المتبعة لديكم، فإذا كان النظام والتعليمات تسمح لك بمساعدة الزميلة فلا بأس وإلا فلا تساعديها، لأن المقصود معرفة فهمها وحفظها للمواد التي تدرسها، فإذا كانت التعليمات لديكن تمنع من ذلك فلا تعلميها حتى يتبين فهمها وعلمها، أما إذا كانت التعليمات لديكن أن الزميلة تساعد زميلتها فيما قد يخفى عليها فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8202/حكم-اعانة-الطالبات-في-قاعة-الاختبار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30106.mp3","categories":["الأخلاق المذمومة"]},{"id":10069,"question":"أحفظ قولاً هو: لا تسرفوا في الماء ولو كنتم على نهر جارٍ، هل هذا حديث؟","title":"الإسراف بالماء","answer":"الجواب: نعم، يروى عن سعد بن أبي وقاص عن النبي ﷺ أنه نهى عن الإسراف ولو كان على نهر جاري والآية تعم ذلك، الله قال: وَلا تُسْرِفُوا [الأعراف:31]، فالآية تعم ذلك، وقال النبي ﷺ: كل واشرب والبس وتصدق في غير سرف ولا مخيلة، فالمؤمن مأمور بالاقتصاد في كل شيء منهي عن الإسراف في كل شيء، حتى الماء حتى في الوضوء والغسل يقتصد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8250/الاسراف-بالماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30413.mp3","categories":["الأخلاق المذمومة"]},{"id":10276,"question":"مشكلة بينه وبين أخيه، يقول: لي أخ أصغر مني، إنما بيني وبينه جفوة، والخصام مستمر بيننا، وهو دائم السب والشتم، انصحوني كيف أصاحب أخي، وأكون أنا وهو على وفاق؟","title":"حكم هجر ومقاطعة الأخ لأخيه","answer":"الجواب: ننصحكما جميعاً بمراقبة الله، والحذر من أسباب التهاجر، يقول النبي ﷺ : لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام ويقول ﷺ: ترفع الأعمال إلى الله في كل إثنين وخميس، فيغفر الله لكل مسلم لا يشرك بالله شيئاً، إلا رجلاً كانت بينه وبين أخيه شحناء، فيقول الله: دعوا هذين حتى يصطلحا فالشحناء والتهاجر من أسباب حرمان المغفرة، فالواجب عليكما عدم التهاجر، وأن تصطلحا فيما بينكما، وأن تتوبا إلى الله مما سلف، وعليك أن تنصح أخاك عن السب والشتم، وعلى من يعلم ذلك من أقاربك وإخوانك أن ينصحوه، حتى يدع السب والشتم، وإذا سمحت عنه وعفوت عنه فلك أجر عظيم، تعفو وتصفح، وتسأل الله له الهداية، ولا تهجره من أجل حقك، ويجوز هجره ثلاثة أيام فأقل، لا زيادة، مع النصيحة والتوجيه لعل الله يهديه بأسبابك أو بأسباب بعض إخوانك الطيبين الذين ينصحونه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8456/حكم-هجر-ومقاطعة-الاخ-لاخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31112.mp3","categories":["الأخلاق المذمومة"]},{"id":10282,"question":"من قرية الكامل المستمع مبارك السلمي بعث يسأل ويقول: أنا رجل راعي أغنام، ولي والدة طاعنة في السن كبيرة، لا تستطيع التمييز في بعض الأمور، هذه الوالدة تقوم باللعن لجميع الحيوانات والأغنام التي أملكها ومصروفي منها، سمعت أن رسول الله ﷺ أمر بترك ناقة لعنت في إحدى الأسفار ما رأيكم في حالتي، وشرح الحديث المذكور، جزاكم الله خيراً؟","title":"حكم لعن الحيوانات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد:\nفقد دلت الأدلة الشرعية على أنه لا يجوز للمسلم أن يلعن الحيوانات، لا إبلاً ولا بقراً ولا غيرهما، ليس للمسلم أن يلعن حيواناً مأكول أو غير مأكول، والتي لعنت ناقتها وأمر النبي ﷺ بأن يخلى سبيلها، ذكر العلماء أن هذا من باب التعزير، حتى لا تعود إلى مثل ذلك، مع أنها باقية في ملك صاحبتها لا تخرج عن ملكها عند أهل العلم، لكن من باب التعزير، وهذا اللعن الذي حصل من والدتك إذا كانت قد تغير شعورها ليس عليها شيء؛ لأنها خرجت عن حد التكليف بزوال شعورها، بسبب كبر سنها، وصارت في عداد من لا عقل له، وقد قال عليه الصلاة والسلام: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن المجنون حتى يفيق -وفي اللفظ الآخر: وعن المعتوه حتى يفيق- وعن الصغير حتى يبلغ فإذا كان عقلها قد تغير فلا إثم عليها، أما إن كان عقلها معها حين اللعن تدرك وتعلم أن هذا لا يجوز، عندها عقل، فالواجب نصيحتها، وأن يبين لها أن هذا لا يجوز، وأن عليها التوبة من ذلك.\nأما أنت فلا يضرك، غنمك ومالك لا يضره لعنها، ولا حرج عليك في استعمالها والأكل منها والشرب من لبنها، لا حرج عليك؛ لأنك مظلوم، والإثم على من لعن، الإثم عليها هي إن كانت تعقل، أما إن كانت قد ذهب عقلها بسبب كبر السن، فليس عليها شيء، ليس عليها إثم وكلامها لاغي لا قيمة له، نسأل الله للجميع التوفيق.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8444/حكم-لعن-الحيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31101.mp3","categories":["الأخلاق المذمومة"]},{"id":10286,"question":"مشكلة بينه وبين أخيه، يقول: لي أخ أصغر مني، إنما بيني وبينه جفوة، والخصام مستمر بيننا، وهو دائم السب والشتم، انصحوني كيف أصاحب أخي، وأكون أنا وهو على وفاق؟","title":"حكم هجر ومقاطعة الأخ لأخيه","answer":"الجواب: ننصحكما جميعاً بمراقبة الله، والحذر من أسباب التهاجر، يقول النبي ﷺ : لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام ويقول ﷺ: ترفع الأعمال إلى الله في كل إثنين وخميس، فيغفر الله لكل مسلم لا يشرك بالله شيئاً، إلا رجلاً كانت بينه وبين أخيه شحناء، فيقول الله: دعوا هذين حتى يصطلحا فالشحناء والتهاجر من أسباب حرمان المغفرة، فالواجب عليكما عدم التهاجر، وأن تصطلحا فيما بينكما، وأن تتوبا إلى الله مما سلف، وعليك أن تنصح أخاك عن السب والشتم، وعلى من يعلم ذلك من أقاربك وإخوانك أن ينصحوه، حتى يدع السب والشتم، وإذا سمحت عنه وعفوت عنه فلك أجر عظيم، تعفو وتصفح، وتسأل الله له الهداية، ولا تهجره من أجل حقك، ويجوز هجره ثلاثة أيام فأقل، لا زيادة، مع النصيحة والتوجيه لعل الله يهديه بأسبابك أو بأسباب بعض إخوانك الطيبين الذين ينصحونه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8456/حكم-هجر-ومقاطعة-الاخ-لاخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31112.mp3","categories":["الأخلاق المذمومة"]},{"id":10365,"question":"من شقرة رسالة بعث بها مستمع رمز إلى اسمه بالحروف (ن. م. م) يقول: أنا طالب في إحدى المدارس، وأرى زملائي هدانا الله وإياهم يقومون بالغش في الاختبار، وحينئذ هل يلزمني إنكار هذا المنكر أو بماذا توجهونني علمًا بأني أخشى منهم؟","title":"حكم الغش في الامتحانات المدرسية وكيفية إنكار ذلك","answer":"الجواب: لا يجوز الغش في الاختبار، هذا من الخيانة والواجب نصيحتهم، وتحذيرهم من هذا العمل؛ لأن المؤمن أخو المؤمن والمسلم أخو المسلم والله جل وعلا يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]، ويقول سبحانه: إِنََّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58]، ويقول  في وصف المؤمنين: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونََ [المؤمنون:8] ، وعليك أن تلاحظ ذلك حسب الطاقة مع المسئول؛ لأجل أداء الأمانة. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8537/حكم-الغش-في-الامتحانات-المدرسية-وكيفية-انكار-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27914.mp3","categories":["الأخلاق المذمومة"]},{"id":10387,"question":"قد يغتابني بعض الناس فأغتابهم، علمًا بأن الذي يغتابونني فيه غير صحيح بل إنه شيء مفترى، فأقوم بصرف الكذب عني والافتراء ولا أزيد على ذلك، مع أن قلبي يكون كارهًا وكثيرًا ما أبكي على ما فعلت، كيف توجهونني؟","title":"حكم غيبة المغتاب","answer":"","link":"https://binbaz.org.sa/fatwas/8559/حكم-غيبة-المغتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33908.mp3","categories":["الأخلاق المذمومة"]},{"id":10517,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، رمزت إلى اسمها بحروف (م. م) أختنا لها رسالة مطولة كلها شكوى وملاحظات على زوجها فهي تقول: أنا فتاة في الثامنة عشرة من عمري ملتزمة والحمد لله، وقد زوجني أبي وأنا عمري في السادسة عشرة من رجل عنده امرأتان ولديه خمسة عشر ولداً، أكبرهم في سني، وأنا أشكو من زوجي الذي آمره بأن يعفي لحيته طاعة لله ورسوله، ولكنه لم يفعل بل يقصرها على آخر شيء، ولولا كثرة الشيب لكان يحلقها بالموس، ولأنه يقول: إن الموس تكثر الشيب فاتخذ القص بدلًا من الحلق، وكلما أردت أن أكرر النصيحة قال: لا تتدخلين في شأني، علماً بأنني لم أنجب أبناء منه حتى الآن، فأخبرني يا سماحة الشيخ هل أطلب الطلاق من ذلكم الرجل أم أعيش وأصبر؟ وكيف تنصحونني جزاكم الله خيرًا، علماً بأنني أعتبره عاصٍ لله ولرسوله؟","title":"حكم طلب المرأة للطلاق لامتناع الزوج من إعفاء اللحية","answer":"الجواب: لقد أحسنت في إنكار المنكر جزاك الله خيراً، وفعلت ما يجب من إنكار المنكر، والله جل وعلا هو الذي يهدي من يشاء كما قال سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْْ يَشَاءُ [القصص:56]، والواجب عليه أن يتقي الله، وأن يطيع الرسول ﷺ، فالرسول عليه السلام يقول: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين، ويقول ﷺ: قصوا الشوارب ووفروا اللحى، خالفوا المشركين، فالواجب عليه أن يتقي الله وأن يطيع الرسول ﷺ، وأن يعفي لحيته ويكرمها ويوفرها طاعة لله ولرسوله، وحذرًا من غضب الله، فالواجب عليه أن يسمع ويطيع لأمر الله ورسوله، وأن يشكرك على ما فعلت من الخير، وأن يقبل منك النصيحة؛ لأنك فعلت ما ينبغي وما يجب.\nأما ما يتعلق بطلب الطلاق فهذا شيء يرجع إليك إذا رأيت المصلحة في طلب الطلاق فلا بأس، إذا كان استمر على حاله ولم تنجبي منه فلا مانع من طلب الطلاق لعل الله يرزقك من هو خير منه، ويرزقك أيضاً ذرية، فهذا عذر شرعي، لا بأس أن تطلبي الطلاق إذا سمح أن يطلق فهذا طيب، ولعل الله يرزقك بما هو أصلح منه. نعم.","link":"https://binbaz.org.sa/fatwas/8692/حكم-طلب-المراة-للطلاق-لامتناع-الزوج-من-اعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28306.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":10801,"question":"ما هي نصيحتكم لمن يلعن في المسجد؟","title":"حكم اللعن في المسجد وخارجه","answer":"الجواب:  اللعن محرم في المسجد، وغير المسجد، اللعن من كبائر الذنوب، في المساجد وفي البيوت وفي الطرقات وفي السيارات وفي القطارات وفي الطائرات في كل مكان، يقول النبي ﷺ: لعن المؤمن كقتله شبهه بالقتل لعظم الجريمة، ولأنه من أعظم الأسباب في الشحناء والعداوات والفتن، ويقول ﷺ: إن اللعانين لا يكونوا شهداء ولا شفعاء يوم القيامة ويقول أيضًا ﷺ: ليس المؤمن بالطعان ولا اللعان ولا الفاحش ولا البذيء. فالواجب على كل مؤمن ومؤمنة حفظ اللسان، وصيانتها مما لا ينبغي، ومن أقبح الكلام اللعن والشتم، أن يلعن أخاه، أو صاحبه ولو مازحًا، ولو لاعبًا، ما يجوز.  فالمؤمن من شأنه حفظ لسانه، وصيانته حتى لا يتكلم إلا بالخير، وهكذا المؤمنة عليها حفظ لسانها، وصيانته، وألا تقول إلا خيرًا، كما ثبت في الصحيحين عن النبي ﷺ أنه قال: من كان يؤمن بالله واليوم الآخر فليقل خيرًا، أو ليصمت وهذا حديث عظيم: من كان يؤمن بالله واليوم الآخر فليقل خيرًا، أو ليصمت والله يقول سبحانه: لا خَيْرَ فِي كَثِيرٍ مِنْ نَجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلاحٍ بَيْنَ النَّاسِ [النساء:114]. ويقول أيضًا -عليه الصلاة والسلام-: إن العبد ليتكلم بالكلمة ما يتثبت فيها يعني: ما يتبين فيها يزل بها في النار أبعد مما بين المشرق والمغرب ويقول أيضًا -عليه الصلاة والسلام-: إن العبد ليتكلم بالكلمة من سخط الله ما يلقي لها بالًا يكتب الله له بها سخطه إلى يوم يلقاه فالأمر عظيم وخطير، ولا حول ولا قوة إلا بالله. فالواجب حفظ اللسان، وصيانته عن جميع الكلام الذي يضر العبد، كاللعن والشتم والغيبة والنميمة والكذب وشهادة الزور والدعاوى الباطلة وغير هذا مما حرم الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8975/حكم-اللعن-في-المسجد-وخارجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35205.mp3","categories":["الأخلاق المذمومة"]},{"id":10830,"question":"تقول في سؤال آخر: فتاة متدينة، وتجاوزت العشرين من عمرها والحمد لله تؤدي كل واجباتها الدينية، إلا أنها تكشف وجهها أمام أزواج أخواتها، وذلك لأنها ليس لها رغبة في الزواج؛ لأن بها عاهة خلقية منذ الولادة، فهل عليها إثم في ذلك؟","title":"ما حكم كشف الوجه بالنسبة لامرأة بها عاهة خلقية؟","answer":"الجواب:  عليها التوبة إلى الله من ذلك؛ لأن كشفها لأزواج أخواتها لا يجوز، فينبغي لها في مثل هذا الندم والاستغفار والحمد لله، إلا إذا كانت العاهة في الوجه، فتكون مثل القاعدة، مثل العجوز الكبيرة التي لا تشتهى، ولا شيء عليها، إن شاء الله.  أما إذا كان وجهها سليمًا والعاهة داخلية، والوجه سليم فعليها التوبة والاستغفار؛ لأنه ليس لها الكشف، بل عليها أن تحتجب عن أزواج أخواتها، وعن كل أجنبي لقول الله  في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، والوجه من أعظم الزينة، بل هو أبرز الزينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8994/ما-حكم-كشف-الوجه-بالنسبة-لامراة-بها-عاهة-خلقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35405.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":10879,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية من المستمعين (أ. ن. ط) و (م. ع. ص) يقول أحدهما في سؤال له: أحضرت معي مياه من زمزم، وأخلط معه مياه عادية لكي تكفي عددًا كبيرًا من الناس، هل يعتبر هذا من الغش، أم لا؟","title":"حكم خلط ماء زمزم مع غيره لتكثيره","answer":"الجواب:  إذا قلت لهم: إنها كلها من زمزم، فهذا غلط كذب، أما إذا قلت: إني خلطت معها ماء من غير زمزم فلا بأس، وإلا فلا حاجة إلى هذا كله، الماء الذي معك تعطيه من تشاء، أو تشربه أنت، أو تستعمله أنت على بصيرة، ولا تكذب، والأمر في هذا سهل -إن شاء الله- لكن ينبغي لك أن تكون على بصيرة في هذه الأمور، وأن لا تتعاطى الكذب، لا ينبغي للمؤمن أن يتعاطى الكذب أبدًا، ينبغي له أن يكون حريصًا على الصدق في أقواله وأعماله، فإذا كنت تحب أن تهدي تهدي شيئًا تعلم أنه زمزم، وتقول: إنه زمزم، تصدق وإلا فلا حاجة إلى ذلك والحمد لله أنت غير ملزوم بالهدية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9064/حكم-خلط-ماء-زمزم-مع-غيره-لتكثيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_359/35910.mp3","categories":["الأخلاق المذمومة"]},{"id":10899,"question":"تسأل أختنا وتقول: هل يحاسب الإنسان على سوء ظنه، وعدم ثقته بالناس؟ لأننا في زمن لا نستطيع أن نثق كثيرًا بمن حولنا، وكذلك الظروف المحيطة بنا تجعلنا نسيء الظن بالجميع، فهل يؤاخذنا الله على سوء الظن؟","title":"حكم سوء الظن بالآخرين","answer":"الجواب:  يقول الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12]، فأمر سبحانه باجتناب الكثير لا كل الظن، وقال: إن بعض الظن إثم ولم يقل: إن كل الظن إثم، فدل ذلك على جواز الظن السيء إذا ظهرت أماراته، رؤيت دلائله، فالذي يقف مواقف التهم يظن به السوء، والمرأة التي تخلو بالرجل يظن بها السوء، والتي تغازل الرجال فيما يتعلق بالزنا والزيارات بينها وبين الرجل متهمة بالسوء، وهكذا من أظهر أعمالًا تدل على قبح عمله يتهم. أما إساءة الظن بدون سبب فلا تجوز، لا يجوز للمسلم أن يسيء الظن بأخيه بدون علة، وبدون سبب، ولا بأخته في الله بدون سبب، وهذا معنى اجتنبوا كثيراً من الظن وهو الظن الذي لا سبب له، ولا موجب له، هذا حرام لا يجوز، وعلى هذا المعنى يحمل الحديث الصحيح وهو قوله ﷺ: إياكم والظن فإن الظن أكذب الحديث يعني: الظن الذي لا سبب له، ولا موجب له، بل يظن بغير تهمة، وبغير سبب، هذا ظالم مخطي لا يجوز، أما إذا كان ظنًا له أسباب فلا حرج فيه. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9078/حكم-سوء-الظن-بالاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36005.mp3","categories":["الأخلاق المذمومة"]},{"id":10932,"question":"يقلن: ما رأيكم فيما يجري في حفلات الزواج من إسراف وتبذير، حيث تستمر هذه الحفلات عدة ليال؟","title":"حكم التبذير والإسراف في الولائم","answer":"الجواب:  الواجب الحذر من الإسراف والتبذير، أما الوليمة فهي سنة، سنة العرس، الوليمة سنة قال النبي ﷺ لـعبدالرحمن بن عوف: أولم ولو بشاة، وقد أولم النبي ﷺ على زينب وليمةً عظيمة، ودعا إليها الناس من الخبز واللحم -عليه الصلاة والسلام- وأولم على صفية بحيس من التمر والسمن والأقط، والوليمة سنة، تارةً تكون باللحم والطعام مثل الخبز والرز وغير ذلك، وتارة تكون بالحيس ونحوه من غير لحم كالتمر والسمن والأقط يقال له: حيس، أو بالثريد، أو بغير هذا مما ... على حسب حال الناس وقدرتهم، لكن لا يجوز الإسراف والتبذير، بل يجب الاقتصاد، حتى لا يضيع الطعام، ولا يصرف في غير محله، أما إذا صنع طعامًا للناس، وبقي شيء فإنه يتصدق به على الفقراء والمحاويج، ولا يلقى في القمائم، ولكن يتصدق به على المحتاجين، وإذا لم يوجد محتاج يوضع في محل نظيف طيب حتى تأكله السباع، أو الدواب، أو يأخذه الناس لحاجة بهائمهم، ولا يلقى في القمامة، ولا في محل ممتهن، بل يوضع في محل نظيف، ومحل بعيد عن الامتهان، حتى يأخذه من يحتاج إليه، أو تأكله الدواب، إذا بقي شيء من الوليمة، مع تحري الاقتصاد، وتحري عدم إضاعة المال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9108/حكم-التبذير-والاسراف-في-الولاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36205.mp3","categories":["الأخلاق المذمومة"]},{"id":11109,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من جمهورية مصر العربية، باعثها المستمع: (ع. أ. م) أخونا عرضنا له قضية في حلقة مضت، وفي هذه الحلقة له قضية مطولة بعض الشيء يقول فيها: تزوج رجل بامرأة، وأنجب منها أولادًا، وكان له صديق يتردد عليه في منزله، وكان هذا الصديق يغري زوجة صاحبه بالمال، ثم اتفق معها على أن تطلب الطلاق من زوجها الأول، وتتنازل له عن حقوقها وحقوق أولادها، وفعلاً تم الطلاق وتزوجها هذا الصديق، فرجاءً الإفادة عن هذا الزواج هل هو حلال أم حرام؟ والأولاد الآن في حيرة، ومشاكل بين الأم والأب، هل على الزوجة ذنب، أم على الزوج؟  لأنه سمح لهذا الصديق بدخول بيته وإغراء زوجته، وهذا بدون علمه، جزاكم الله خيرًا.","title":"حكم من خبب امرأة على زوجها ليتزوجها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  هذا العمل من الصديق في إغراء الزوجة وتخبيبها لا يجوز، بل هو منكر، وقد نهى عنه النبي -عليه الصلاة والسلام- وحذر منه، فعليه التوبة إلى الله من ذلك، والزواج صحيح، لكنه آثم، وعليه التوبة إلى الله مما فعل، فإذا كان تزوجها بعد خروجها من العدة فلا حرج، لكنه يأثم، وهي تأثم، وعليها التوبة إلى الله من ذلك كلاهما يأثم. أما الزوج فلا إثم عليه إذا كان لا يعلم، ليس عليه حرج لكونه لا يعلم عمل هذا الرجل، وهذا الرجل قد خانه في أهله بالتخبيب، والحث على الفراق، فهو قد أتى جريمة، فعليه التوبة إلى الله من ذلك، والندم على ما مضى، والعزم أن لا يعود في ذلك، وإذا تيسر أن يستسمح أخاه، ويطلب منه العفو عما جرى إذا لم يترتب على هذا شر فهذا حسن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9283/حكم-من-خبب-امراة-على-زوجها-ليتزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36801.mp3","categories":["الأخلاق المذمومة"]},{"id":11114,"question":"أيضًا تسأل عن حكم قطيعة الرحم، لأسباب مثل الغيبة والنميمة، وما أشبه ذلك؟","title":"حكم قطع الرحم بسبب الغيبة والنميمة وغيرها من المعاصي","answer":"الجواب:  لا تجوز القطيعة، قطيعة الرحم من الكبائر، يقول النبي ﷺ: لا يدخل الجنة قاطع رحم، فالواجب صلة الرحم بالكلام، أو بالزيارة، أو بالمال على حسب المستطاع، ولا يجوز للمؤمن أن يقطع الرحم، ولا للمؤمنة، من أجل الغيبة، أو النميمة، لا تجوز قطيعة الرحم، فالذي يقع في الغيبة ينصح، أو في النميمة ينصح ويوجه إلى الخير: الدين النصيحة، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. فالذي يغتاب الناس، وينم عليهم من أقاربك تنصحه، لا تقطعه، تنصحه، وتنكر عليه عمله، وتوجهه إلى الخير، وتستعين بأقاربه الآخرين، أو أصدقائه أن ينصحوه حتى تكون الكلمة واحدة، وحتى يحصل التعاون على الخير، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9295/حكم-قطع-الرحم-بسبب-الغيبة-والنميمة-وغيرها-من-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36813.mp3","categories":["الدعوة والدعاة","الأخلاق المذمومة"]},{"id":11127,"question":"ما كفارة الرياء؟ وما هو الرد على من أثنى علي بالمدح، كمن يقول: فلان يصلي ويذكر الله، حتى لا يدخل في عملي الرياء؟ وقانا الله وإياكم شر هذا المرض.","title":"كفارة الرياء والرد على المداحين","answer":"الجواب:  كفارة الرياء التوبة إلى الله، وهكذا كل معصية وكل شرك، توبته ودواؤه التوبة إلى الله، التوبة النصوح بالندم على الماضي، والإقلاع من الرياء ونحوه، والعزم الصادق أن لا يعود فيه، وإذا مدحك تقول: يا أخي! اتق الله، لا ينبغي المدح فالرسول ﷺ قال: إذا رأيتم المداحين فاحثوا في وجوههم التراب لأن المدح قد يفضي إلى العجب والكبر، فينبغي للأخ إذا دعت الحاجة أن لا يستطيل في المدح، تكون كلمات قليلة إذا دعت إليها الحاجة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9316/كفارة-الرياء-والرد-على-المداحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36916.mp3","categories":["الأخلاق المذمومة"]},{"id":11130,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول المرسل: (ر. س) من جازان، أخونا يقول: لنا عم نقاطعه لأسباب متعددة، منها ما هو معصية لله، ومنها أشياء أخرى تتعلق بصلة الرحم وتتعلق بقسمة الميراث، وما أشبه ذلك، ويرجو من سماحتكم التوجيه بصدد موقفهم هذا مع عمهم كيف يكون على الطريقة الصحيحة؟ جزاكم الله خيرًا.","title":"حكم قطيعة العم","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فالواجب على المؤمن صلة الرحم مع أقاربه، أبيه وأجداده وأولاده، وإخوته وأعمامه وغيرهم، الأقرب فالأقرب، يقول النبي ﷺ في الحديث الصحيح: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها، ويقول -عليه الصلاة والسلام: لا يدخل الجنة قاطع رحم، ويقول -عليه الصلاة والسلام-: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله فليصل رحمه، فإذا كان عمكم قد قطع الرحم، فلا تقطعوه؛ لأن العم بمنزلة الأب. فالمشروع لكم، بل الواجب عليكم صلة الرحم والإحسان إليه، بالكلام الطيب، والسلام، ومواساته إن كان فقيرًا، وأنتم قادرون، وإذا كان عنده معصية انصحوه، ووجهوه إلى الخير، وعلموه ما ينفعه فـ الدين النصيحة انصحوه، وبينوا له تحريم ما فعل إذا كنتم على بصيرة، وتعاونوا مع إخوانكم الطيبين من جيرانه أو بأحبابه أو إخوانه في نصيحته لعله يستجيب لكم، ويدع ما حرم الله عليه، ولكم مثل أجره.  يقول النبي ﷺ: من دعا إلى هدى كان له من الأجر مثل أجور من تبعه، ويقول -عليه الصلاة والسلام-: من دل على خير فله مثل أجر فاعله، فأنتم على خير انصحوه ووجهوه وصلوا الرحم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9301/حكم-قطيعة-العم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36901.mp3","categories":["الأخلاق المذمومة"]},{"id":11202,"question":"السائل (ع. ع. ط) مقيم بالرياض يقول: ما حكم المرأة التي تعطي أهلها من بيت زوجها الشيء الكثير دون سابق علمه أرجو منكم الإفادة؟","title":"حكم إعطاء المرأة من مال زوجها لأهلها بغير إذنه","answer":"الجواب:  ليس لها أن تعطي أهلها من مال زوجها إلا بإذنه، هذه خيانة لابد من إذنه، لا تتصرف في ماله إلا بإذنه، إلا ما جرت العادة بإخراجه من الصدقة للفقراء والمساكين فلا بأس، الشيء المعتاد، أما أن تعطي أهلها أو غير أهلها شيئًا لم تجر العادة به ولم يأذن فيه فلا. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9383/حكم-اعطاء-المراة-من-مال-زوجها-لاهلها-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29102.mp3","categories":["الأخلاق المذمومة"]},{"id":11203,"question":"السائل يقول: ما حكم المرأة أيضًا التي تسب أهل الزوج وخاصة والديه أمامه هل يقوم بتطليقها، نرجو منكم الإفادة؟","title":"حكم المرأة التي تسب أهل زوجها أمامه","answer":"الجواب:  يلزمه أن ينصحها ويحذرها من هذا العمل وله أن يؤدبها بشيء لا يضر حتى ترجع عن هذا العمل وتدع هذا العمل، فإن هذا منكر وظلم فليس لها سبهم، ولا يعجل بالطلاق، لا يعجل بالطلاق لكن يعالج الموضوع بالحكمة، بالنصيحة والتوجيه والتأديب المناسب، لعلها ترتدع. نعم.","link":"https://binbaz.org.sa/fatwas/9384/حكم-المراة-التي-تسب-اهل-زوجها-امامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29103.mp3","categories":["الأخلاق المذمومة"]},{"id":11250,"question":"يقول: والدي مغترب ويرسل مبلغًا شهريًا لي ولإخواني، لأنفق ذلك المبلغ على المنزل، لكني أخذته وتصرفت فيه بعض الأشهر وأنا الآن نادم، فما الذي يجب علي عمله جزاكم الله خيرًا؟","title":"أخذ من مال والده دون إذنه ثم ندم فماذا يفعل؟","answer":"الجواب:  عليك أن تنفق المبلغ في حاجات البيت، الذي تصرفت فيه، عليك أن تعيده، أن تنفقه في البيت، أو تعيده إلى أبيك، أو تستسمحه، تقول: جرى كذا وجرى كذا سامحني، حتى إذا كان هناك حاجة لك تخبره بها، وإلا فعليك أن تنفقه في أهل البيت كما أمرك أبوك، أو تعيده إليه إن كان قد وصل تعيده إليه وتقول: هذا بقي عندي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9435/اخذ-من-مال-والده-دون-اذنه-ثم-ندم-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37408.mp3","categories":["الأخلاق المذمومة"]},{"id":11262,"question":"يقول: والدي مغترب ويرسل مبلغًا شهريًا لي ولإخواني، لأنفق ذلك المبلغ على المنزل، لكني أخذته وتصرفت فيه بعض الأشهر وأنا الآن نادم، فما الذي يجب علي عمله جزاكم الله خيرًا؟","title":"أخذ من مال والده دون إذنه ثم ندم فماذا يفعل؟","answer":"الجواب:  عليك أن تنفق المبلغ في حاجات البيت، الذي تصرفت فيه، عليك أن تعيده، أن تنفقه في البيت، أو تعيده إلى أبيك، أو تستسمحه، تقول: جرى كذا وجرى كذا سامحني، حتى إذا كان هناك حاجة لك تخبره بها، وإلا فعليك أن تنفقه في أهل البيت كما أمرك أبوك، أو تعيده إليه إن كان قد وصل تعيده إليه وتقول: هذا بقي عندي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9435/اخذ-من-مال-والده-دون-اذنه-ثم-ندم-فماذا-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37408.mp3","categories":["الأخلاق المذمومة"]},{"id":11293,"question":"القضية الثانية التي يود من سماحتكم توجيهه بخصوصها هي الحديث عن ذوي العيوب في غيابهم، يقول: هل يجوز هذا أو لا، جزاكم الله خيرا، وما الفرق بين ذلك والغيبة؟","title":"حكم ذكر عيوب الناس في غيابهم","answer":"الجواب:  التحدث عن الناس بعيوبهم إذا كانوا غير مسمين لا بأس، ... بعض الناس يكثرون من الغيبة، بعض الناس يتعاطى النميمة، للتحذير هذا لا بأس به، بعض الناس يكذب، بعض الناس يظلم ما فيه شيء، لكن كونه يسمي فلان بن فلان يسميه أنه فعل كذا وكذا من الشيء الردي هذه الغيبة، وهي ذكرك أخاك بما يكره، فلان بن فلان بخيل، فلان جبان، فلان قاطع للرحم وما أشبه ذلك لا، هذه غيبة، والنميمة كونه ينقل الكلام الردي، ينقل لزيد يقول: ترى أخوك يقول فيك كذا، ترى أمك تقول كذا، ترى عمك يقول كذا حتى يثير الشحناء بينهما، هذا لا يجوز هذه النميمة وأشباه ذلك. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9470/حكم-ذكر-عيوب-الناس-في-غيابهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37602.mp3","categories":["الأخلاق المذمومة"]},{"id":11328,"question":"سماحة الشيخ، له سؤال أخير هذا السائل من السودان يقول سماحة الشيخ: يقتصر بعض الإخوة على قول: صباح الخير مساء الخير، بدل السلام عليكم ورحمة الله وبركاته تحية الإسلام، فهل من توجيه حول هذا؟ جزاكم الله خيرًا.","title":"حكم التحية بـ (صباح الخير ومساء الخير)","answer":"الجواب: نعم. لا يجوز هذا، الواجب أن يبدأ بالسلام، السلام عليكم ما هو صباح الخير مساء الخير، أقول: السلام عليكم، وإذا قال: ورحمة الله وبركاته أكمل وأفضل، ثم بعد ذلك يقول: صباح الخير، صبحكم الله بالخير، مساكم الله بالخير، كيف حالكم، كيف أولادكم، كيف أهلكم، ... شيء زيادة احتفاء طيب، لكن يبدأ بقوله: السلام عليكم، هذا أقل شيء، وإن زاد: ورحمة الله وبركاته؛ كان أكمل، وهكذا كان النبي ﷺ مع أصحابه، ودخل مرة عليه رجل فقال: السلام عليكم، قال: عشر -يعني: عشر حسنات- ثم دخل آخر فقال: السلام عليكم ورحمة الله، فقال: عشرون -يعني: عشرون حسنة، يعني: حصل له عشرون- ثم دخل آخر فقال: السلام عليكم ورحمة الله وبركاته، فقال: ثلاثون يعني: ثلاثون حسنة، فالفضل في هذه الصيغة بدءًا وردًّا. نعم.","link":"https://binbaz.org.sa/fatwas/9510/حكم-التحية-بـ-صباح-الخير-ومساء-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29207.mp3","categories":["الأخلاق المذمومة"]},{"id":11566,"question":"أحد الإخوة من السودان رمز إلى اسمه بالحروف (ع. م. م) يسأل عن ذلكم الابن الذي يرفع صوته على أحد والديه، هل يعتبر هذا من العقوق؟","title":"حكم رفع الابن صوته على والديه","answer":"الجواب: نعم، الله يقول -جل وعلا-: وَلا تَنْهَرْهُمَا [الإسراء:23]، والنهر: رفع الصوت عليهما، فلا يجوز له نهرهما، ولا ضربهما، ولا إيذاؤهما بأي نوع من الأذى حتى التأفيف، حتى كونه يظهر كراهة لرائحتهما، بل عليه أن يعاملهما بلطف، وأن يخفض جناحه لهما، وأن يقول لهما قولًا كريمًا، كما قال الله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا  ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24]. والله -جل وعلا- في مواضع كثيرة أمر بالإحسان إلى الوالدين، وقال -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] والنبي ﷺ يقول -عليه الصلاة والسلام-: لما سئل أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي يا رسول الله؟ قال: بر الوالدين قيل: ثم أي يا رسول الله؟ قال: الجهاد في سبيل الله فبر الوالدين من أهم المهمات، وعقوقهما من أقبح السيئات والكبائر، ورفع الصوت عليهما من العقوق ومن الكبائر، سواءً كان رفع الصوت لطلب شيء، أو منعهما من شيء، أو لأسباب أخرى. فالواجب عليه التأدب معهما، وعدم رفع الصوت على أي سبب كان، حتى ولو كان في الإنكار عليهما، لو رأى منهما منكرًا لا يرفع الصوت، يخاطبهما بالتي هي أحسن، قال الله -جل وعلا- في حق الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] هكذا أمر الولد مع والديه الكافرين، فكيف بالمسلمين؟! فإذا رأى منهما ما ينكر كالدخان، أو الخمر، أو ما أشبه ذلك يرفق بهما، وينصحهما، لكن من دون رفع الصوت. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9749/حكم-رفع-الابن-صوته-على-والديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29715.mp3","categories":["الأخلاق المذمومة"]},{"id":11568,"question":"يقول: إن لي صديق لا يصلي، هل أمشي معه، أم أتركه في حال سبيله، وأبقى في سبيلي؟ جزاكم الله خيرًا.","title":"حكم معاشرة ومصادقة تارك الصلاة","answer":"الجواب:  الرفيق الذي لا يصلي لا تجوز مرافقته، بل يجب الحذر منه، وهجره مع نصيحته، وحثه على تقوى الله، وإرشاده إلى الخير، وإعلامه أن الصلاة عمود الإسلام، وأنها أحد أركان الإسلام الخمسة، بل هي أعظم الأركان، وأكبر الأركان بعد الشهادتين، فعليك أن تنصحه، وأن تبلغه أمر الله، وأن تجتهد في دعوته إلى الخير؛ لعله يهتدي بأسبابك؛ حتى يكون لك مثل أجره، فإن أبى وأصر؛ فارفض رفقته، ولا تزره، ولا يزرك، ولا تتخذه صاحبًا، بل اتخذه عدوًا، وفارقه واهجره حتى يتوب إلى الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9751/حكم-معاشرة-ومصادقة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29717.mp3","categories":["الأخلاق المذمومة"]},{"id":11571,"question":"تسأل أختنا هل نوم الإنسان على بطنه حرام، أم لا، وهل يجوز للإنسان أن يستند وهو جالس على يديه، أو على إحداهما؟","title":"حكم النوم على البطن، والاستناد على اليدين أثناء الجلوس","answer":"الجواب:  لا بأس أن يستند على يديه، أو إحداهما، لكن لا ينام على بطنه الرسول ﷺ نهى عن ذلك؛ النوم لا يصلح على البطن أقل أحواله الكراهة الشديدة قال النبي ﷺ: إنها ضجعة أهل النار فلا ينام على بطنه، ولكن على جنبيه على جنبه، أو على ظهره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9754/حكم-النوم-على-البطن-والاستناد-على-اليدين-اثناء-الجلوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38604.mp3","categories":["الأخلاق المذمومة"]},{"id":11636,"question":"رسالة بتوقيع إحدى الأخوات المستمعات تقول المرسلة أم عبدالله ، أم عبدالله تقول: أعيش مع أناس أشبه ما يكونون بالمنافقين، وأنا غير متزوجة، وأعيش معهم، وأضطر لأن أشاركهم وجبات الطعام، غير أنهم لا يبالون بالكذب والغيبة والنميمة، وأثناء الجلسة على الطعام تراهم يخوضون في أعراض الناس بين الحين والآخر، وجهوني سماحة الشيخ، ولا سيما وأنني في بعض الأحيان لا أستطيع إنكار المنكر.","title":"حكم الجلوس مع من يخوضون في أعراض الناس","answer":"الجواب:  الواجب عليك إنكار المنكر بالنصيحة والكلام الطيب عليهم إذا خاضوا في المنكرات والغيبة، عليك أن تنكري حسب الطاقة، وإذا تيسر لك أن تكوني وحدك بعدهم، أو قبلهم، تأخذين طعامك وحدك قبلهم أو بعدهم، فافعلي، وإذا لم يتيسر هذا الشيء؛ فاتقي الله ما استطعت، كلي وأنكري المنكر، وقومي بعد قضاء حاجتك، لكن إذا تيسر لك الخروج من المحل الذي هم فيه، وأن تكوني في معزل عنهم فافعلي، هذا هو الواجب عليك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9830/حكم-الجلوس-مع-من-يخوضون-في-اعراض-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38917.mp3","categories":["الأخلاق المذمومة"]},{"id":11692,"question":"الأخت المستمعة (ف. م) بعثت تسأل وتقول: ما حكم الغش في الامتحانات، فأنا لا أدخل البراشيم، وإنما الذي أفعله أن أنقل من زميلاتي، وعند نهاية الامتحان أشعر بالذنب، وهل قول الرسول ﷺ: من غشنا فليس منا داخل ضمن هذا العمل، أم أن المقصود في الحديث شيء آخر؟ جزاكم الله خيرًا.","title":"الغش في الامتحانات محرم وينافي الأمانة","answer":"الجواب:  الغش في الامتحان لا يجوز، الواجب على الطالب والطالبة أداء الأمانة في الامتحان، والحذر من الغش، وأن يجتهد الطالب، وتجتهد الطالبة حتى يعرف ما يجيب به بأدلته من الكتاب والسنة، ويستعين في ذلك بكلام أهل العلم، حتى يؤدي الجواب جيدًا واضحًا بأدلته، والله سبحانه يقول: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58] ويقول سبحانه في صفة أهل الإيمان: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8] ويقول النبي ﷺ: من غشنا فليس منا سواء كانت المادة دينية، أو لغة عربية، أو لغة أجنبية، جميع المواد، يجب على الطالب والطالبة أداء الأمانة فيها، وعدم الغش. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9872/الغش-في-الامتحانات-محرم-وينافي-الامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39102.mp3","categories":["الأخلاق المذمومة"]},{"id":11832,"question":"يسأل سماحتكم يحفظكم الله عن عقوبة من يبخل على بنيه، أو زوجته، أو أولاده من ناحية الملبس؟","title":"عقوبة البخيل على أولاده","answer":"الجواب:  الواجب عليه تقوى الله، وأن ينفق على زوجته وأولاده النفقة اللازمة لأمثالهم لا إسراف، ولا تقتير، عليه أن ينفق على الرجل، أن ينفق على زوجته وأولاده النفقة العرفية، ويلبسهم الملابس العرفية لأمثالهم، فلا إسراف ولا تبذير، فإذا قصر في ذلك؛ فعليه التوبة إلى الله، والإنابة إليه، وعدم العودة. نعم.","link":"https://binbaz.org.sa/fatwas/10020/عقوبة-البخيل-على-اولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39523.mp3","categories":["الأخلاق المذمومة"]},{"id":11867,"question":"درج النساء على لبس ما يسمى دبلة الخطوبة، فما هو توجيه سماحتكم؟","title":"حكم لبس دبلة الخطوبة","answer":"الجواب:  لا أعلم لها أصلًا، فإن كانت من عمل الكفار فالذي ينبغي تركها، وإن كانت ليست عملًا للكفار، بل اعتادها الناس؛ فالأمر فيها واسع سهل، لكن تركها أفضل بكل حال. نعم. المقدم: جزاكم الله خيرًا. نعم.","link":"https://binbaz.org.sa/fatwas/10045/حكم-لبس-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39708.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":11900,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع (س. ع. س. ع) أخونا عرضنا له بعض الأسئلة في حلقة مضت، وفي هذه الحلقة يقول في هذا  أنا ولله الحمد أصلي وأصوم وقد أديت العمرة، ولكن مشكلتي أنني في خصام دائم مع أناس كثيرين، ومنهم أقرب الناس إلي، فهل هذا الخصام يحبط أعمالي؟ وهل لا تقبل أعمالي الصالحة عند الله؟ وهل الدعاء الذي أدعو به لا يستجاب بسبب ذلكم الخصام؟ وجهوني جزاكم الله خيرا.","title":"أثر المخاصمات مع الناس على قبول الأعمال الصالحة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الخصام والمنازعات التي بينك وبين الناس لا تحبط أعمالك، والحمد لله، أعمالك على حالها، أعمالك الطيبة إذا قبلها الله، فالخصام مع الناس والدعاوى لا تبطلها، ولكن نوصيك بالحذر من المخاصمة بغير حق، والنزاع بغير حق، أما إذا ظلمت وتعدي عليك؛ فلك أن تخاصم، وتطلب الحق عند المحكمة، بشرط أن تتحرى الحق، ولا تقل إلا خيرًا. أما أن تتعمد الباطل، أو تأتي بشهود الزور؛ هذا حرام عليك ومعصية، ولكن لا يبطل أعمالك، لكن نقصًا في إيمانك، وضعفًا في إيمانك، وعليك أن تتحرى الحق، وأن لا تخاصم في الباطل، ولا تنازع في الباطل، وأن تجتهد في ترك الخصومات، والتوبة إلى الله من ذلك، إلا إذا ابتليت، وادَّعَى عليك ناس بغير حق؛ فلك أن تخاصمهم عند المحكمة، حتى تُبَرِّئ نفسك مما ادَّعَوْه من الباطل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10084/اثر-المخاصمات-مع-الناس-على-قبول-الاعمال-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42601.mp3","categories":["الأخلاق المذمومة"]},{"id":11921,"question":"رسالة بعث بها مستمع رمز إلى اسمه بالحروف (م) و (ظ) يقول: سمعت أن قاطع الرحم لا يدخل الجنة، سؤالي: يوجد لي قرابة، ولكن هؤلاء القرابة يسعون لي بالمضرة، وقد سعوا لي عدة مرات بالأذية، حتى إنهم عملوا لي السحر، هل أقاطعهم، أم أصلهم. جزاكم الله خيرًا.","title":"حكم قطيعة الرحم بسبب الشحناء والعداوة","answer":"الجواب:  أما قول النبي ﷺ: لا يدخل الجنة قاطع رحم، قطيعة الرحم من الكبائر، كبائر الذنوب، من أسباب حرمان دخول الجنة، إلا إذا عفا الله عن صاحبها، فالقطيعة من المنكرات والمعاصي الكبيرة، فاتق الله ولا تقطعهم، وتصالح معهم، ودعوى أنهم يسحرونك قد تكون هذه دعوى باطلة، لا أساس لها، قد تكون أوهامًا لا دليل عليها، فاتق الله، وحاسب نفسك، وإذا تعدوا عليك؛ فلك أن تسمح، ولك أن تخاصمهم، وتدعي عليهم عند المحكمة، ولا تقطع الرحم بمجرد الهوى، أو الوساوس، أو دعاوى لا أساس لها، فاتق الله وصل رحمك إلا إذا قطعوك، وأبوا أن تأتيهم، ولم يسمحوا لك، فأنت معذور حينئذ، أما ما داموا لم يمنعوك؛ فإنك تصلهم، وتحسن إليهم ولو أساؤوا إليك، يقول النبي ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها وجاءه رجل وقال: يا رسول الله! إن لي قرابة أصلهم ويقطعونني، وأحسن إليهم ويسيؤون إلي، وأحلم عنهم ويجهلون علي فقال له ﷺ: لئن كنت كما قلت فكأنما تسفهم المل -المل يعني: الرماد الحامي- ولا يزال معك من الله ظهير عليهم ما دمت على ذلك. فالمؤمن يصل أرحامه، وإن قطعوه يحسن إليهم، ويعالج الأمور إذا كانت من شحناء يعالجها بالحكمة، أو بتوسيط الأخيار الطيبين، ولا يستمر على القطيعة، يعالج الأمور ..... إلا إذا كانوا على بدع، أو معاصي ظاهرة، ولم يتوبوا، فلك أن تتركهم، ولك أن تهجرهم، أما من أجل الشحناء بينك وبينهم، فعليك أن تعالجها بالحكمة، بالأسلوب الحسن، وبتوسيط الأخيار؛ حتى تزول الشحناء، وحتى تحل محلها المحبة والصلة. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10105/حكم-قطيعة-الرحم-بسبب-الشحناء-والعداوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42622.mp3","categories":["الأخلاق المذمومة"]},{"id":12105,"question":"رسالة مطولة بتوقيع إحدى الأخوات المستمعات تقول المرسلة (ح. س. د) أختنا لها مشكلة في كتابة مطولة، ملخص هذه القضية أنها ابتليت بزوج سكير، وقد اكتشفت أنه كذلك بعد سنتين من الزواج، لكنه غير مدمن كما تصفه، بل يشربه بين فترة وأخرى، وحينئذٍ أنكرت عليه؛ فحلف لها بالطلاق ثلاث مرات أنه لا يسكر، لكنه عاد، ما هو توجيهكم؟","title":"حكم من حلف بالطلاق ألا يشرب الخمر ثم عاد","answer":"الجواب:  الواجب نصيحته، وتحذيره من مغبة هذا العمل السيئ، فإن الخمر من أقبح السيئات، ومن أقبح الكبائر، فالواجب على هذا الرجل أن يتقي الله، وأن يدع هذا الشراب الخبيث، والرسول ﷺ: لعن الخمر وشاربها وساقيها وحاملها والمحمولة إليه وعاصرها ومعتصرها وبائعها ومشتريها وآكل ثمنها وقال ﷺ: لا يشرب الخمر حين يشربها وهو مؤمن وهذا من باب الوعيد الشديد؛ لأنها تنافي كمال الإيمان الواجب، فالواجب عليه أن يتقي الله، وأن يتوب إلى الله، وعليك أن تنصحيه، وتحذريه من شؤمها. وأما طلاقه ألا يشرب؛ فهذا فيه تفصيل: إن كان طلق ألا يشرب وقصده الامتناع، وليس قصده وقوع الطلاق، ولكن قصده أن يمتنع منه، وأن يشدد على نفسه، وليس قصده إيقاع الطلاق، فعليه كفارة يمين، ولا يقع، أما إن كان قصده إيقاع الطلاق؛ فإنه يقع الطلاق، نسأل الله لنا وله الهداية. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا هل تنصحونه بالبقاء معه، أم تتصرف تصرفًا آخر سماحة الشيخ؟ الشيخ: نوصيها بالبقاء معه والنصيحة، فإذا لم يقبل النصيحة نوصيها بالفراق، ولو بإعطائه ماله، نعم. إذا لم يطلقها بدون مال، أو ترفع أمرها للمحكمة، نعم. المقدم: جزاكم الله خيرًا. وتلك الأيمان بالطلاق ثلاث مرات على ألا يعود ثم يعود؟ \nالشيخ: أخبرناها أن هذا فيه التفصيل: إن كان أراد الامتناع، ولم يرد إيقاع الطلاق؛ فإن عليه كفارة يمين عن كل واحدة، أما إن كان أراد الامتناع مع إيقاع الطلاق إن شرب؛ فإنه يقع الطلاق، وإذا تكرر ثلاثًا؛ حرمت عليه، نعم. حتى تنكح زوجًا غيره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10290/حكم-من-حلف-بالطلاق-الا-يشرب-الخمر-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43708.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":12264,"question":"أولى هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد محمود أبو الخير من مصر، الأخ محمد عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة بقي له جمع من الأسئلة من بينها سؤال يقول: ما هو ذنب آكل حق المرأة بالباطل؟","title":"التحذير من ظلم المرأة في مالها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإن الواجب على المسلم أن يتقي الله في كل شيء، وأن يحذر مال أخيه المسلم، وأخته المسلمة، فلا يأكله إلا بحق، وقد خطب النبي ﷺ في حجة الوداع، فقال: إن دماءكم وأموالكم وأعراضكم عليكم حرام، كحرمة يومكم هذا يعني: يوم النحر في شهركم هذا يعني: شهر ذي الحجة في بلدكم هذا يعني: مكة. هذا الحديث معناه: التشديد في ظلم الناس في مال أو نفس أو عرض، وإذا كان المال للمرأة، وظلمها كان أشد؛ لأنها ضعيفة، وقد قال -عليه الصلاة والسلام-: إني أحرج حق الضعيفين اليتيم والمرأة فإن الغالب أنها لا تستطيع أن تنتصف ممن ظلمها، ولا سيما في البلاد التي ليس فيها حكم شرعي.  فالواجب على المسلم أن يحذر ظلم أخته في الله، سواء كانت زوجة، أو أختًا، أو بنتًا، أو غير ذلك، يجب الحذر، وأن ينصف من نفسه، ويعطي الحق من نفسه، هذا هو الواجب على كل مسلم، وعلى كل مسلمة، والظلم شره عظيم، وعاقبته وخيمة، يقول الله سبحانه: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19] ويقول النبي ﷺ: اتقوا الظلم؛ فإن الظلم ظلمات يوم القيامة ويقول الرب  فيما رواه عنه نبيه -عليه الصلاة والسلام-: يا عبادي! إني حرمت الظلم على نفسي، وجعلته بينكمم محرمًا؛ فلا تظالموا. فعلى كل مسلم، وعلى كل مسلمة الحذر من الظلم، في نفس، أو مال، أو عرض، ولا يجوز للرجل أن يظلم الزوجة، أو الأخت، أو البنت، أو غير ذلك، بل يجب الحذر من ذلك، وأن يتقي الله في ذلك، هذا هو الواجب على جميع المكلفين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10464/التحذير-من-ظلم-المراة-في-مالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45001.mp3","categories":["الأخلاق المذمومة"]},{"id":12444,"question":"ننتقل بعد هذا إلى رسائل أخرى من السادة المستمعين، هذه رسالة من الجمهورية العربية السورية، بعث بها أحد الإخوة من هناك، يقول: ما رأي سماحتكم فيمن يلعب الورق؟ هل يؤثر ذلك على عبادته، علمًا بأنه لا يترك الصلاة، ولا يتخذها وسيلة للتأخر عن العبادة، بل هي للاستجمام كما يقول؟","title":"نصيحة لمن يلعب بالورق","answer":"الجواب:  الحمد لله الذي لم تعقه عن الصلاة، ولا عما أوجب الله، ولكن الواجب عليه تركها؛ لأنها من آلات الملاهي، فالواجب تركها، والاعتياض عنها بشيء مما ينفع، من قراءة القرآن، قراءة الأحاديث المذاكرة مع إخوانه فيما ينفعهم في دينهم ودنياهم، العمل الذي لا حرج فيه، من المسابقة على الأقدام، من التحدث فيما ينفعهم في دينهم ودنياهم. أما لعب الورق، وغير ذلك من آلات الملاهي؛ الواجب تركها، والصلاة صحيحة، لا تؤثر فيها هذه اللعبة، لكن المعاصي تنقص الإيمان، كل المعاصي تنقص الإيمان، وتنقص فضل الصلاة وثوابها، وتنقص الأعمال الأخرى، عند أهل السنة والجماعة الإيمان يزداد بالطاعات، وينقص بالمعاصي، وقد دلت الأدلة الشرعية على ذلك. فإذا أطاع ربه، واستقام على دينه؛ زاد إيمانه، وكمل إيمانه، وإذا تعاطى بعض المعاصي من غيبة، أو نميمة، أو تعاطيه بعض الملاهي، أو غير هذا من المعاصي؛ صار نقصًا في الإيمان، كل معصية تنقص الإيمان، وتضعف الإيمان. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10648/نصيحة-لمن-يلعب-بالورق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45605.mp3","categories":["الأخلاق المذمومة"]},{"id":12517,"question":"يقول: عندما ننصح المدخنين فإنهم يقولون: إنه من أخف الذنوب! فما هو تعليق سماحة الشيخ؟","title":"حكم التدخين وأضراره","answer":"الجواب:  الذنوب كلها محرمة صغيرها وكبيرها، الذنوب كلها محرمة صغيرها وكبيرها، فالواجب الحذر مما حرم الله -جل وعلا- الله -جل وعلا- نهى عباده عما فيه مضرتهم، وأمرهم بمصلحتهم، والنبي  يقول: ما نهيتكم عنه فاجتنبوه والله يقول سبحانه: وََمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] يعم الصغائر والكبائر، والدخان شره عظيم، وفساده كبير على الصحة والدين والمال والعرض. فالواجب الحذر منه، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10737/حكم-التدخين-واضراره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40816.mp3","categories":["الأخلاق المذمومة"]},{"id":12752,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، باعثتها إحدى الأخوات تقول: المرسلة (م. ص. ع) من الأردن، أختنا تقول: هل يجوز أن أقول: قال فلان، أو فلانة كذا وكذا، دون ذكر اسمه، هل يعتبر ذلك غيبة، وما هي حدود الغيبة، جزاكم الله خيرًا؟","title":"ضابط الغيبة ودور من علم في أخيه عيباً","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد سئل النبي ﷺ عن الغيبة فقال -عليه الصلاة والسلام-: ذكرك أخاك بما يكره هذه الغيبة: ذكرك أخاك بما يكره، وهكذا أختي في الله، فإذا قال: فلان بخيل، فلان جبان، فلان رديء في الصلاة، فلانة فيها كيت وكيت من العيوب؛ هذه غيبة ذكرك أخاك بما يكره قيل: يا رسول الله! إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول؛ فقد اغتبته، وإن لم يكن فيه؛ فقد بهته فهو بين أمرين، إما داخل في الكاذب، وإما مغتاب. فالواجب الحذر، والله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] وإذا كنت تعلم من أخيك نقصًا، وهكذا المؤمنة إذا علمت من أخيها، أو أختها في الله نقصًا؛ فالنصيحة النصيحة، والمشافهة المكاتبة، بالتلفون الحمد لله، الله -جل وعلا- يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَتَوَاصَوْا بِالْحَقِّ [العصر:3] وَالْعَصْرِ  ۝  إِنَّ الإِنسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] ويقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين وعامتهم وقال جرير بن عبدالله البجلي  الصحابي الجليل: بايعت النبي ﷺ على إقام الصلاة، وإيتاء الزكاة، والنصح لكل مسلم. فالوصية لجميع إخواني في الله، وأخواتي في الله الحذر من الغيبة والنميمة، وسائر المعاصي، والذي عنده انتقاد على أخيه في الله، أو أخته في الله النصيحة، يبدي له النصيحة، بلغني عنك كذا، أنك عاق لوالديك، أنك تتكاسل عن الصلاة، أنك كذا وكذا؛ فاتق الله يا أخي، وإن كانت امرأة اتقي الله يا أختي في الله، اجتهدي في الصلاة في وقتها، اجتهدي في بر والديك، احذري شر لسانك وهكذا، الرجل ينصح والمرأة تنصح بالمكاتبة، أو بالمشافهة التي ليس فيها إظهار عيب الأخ عند الناس، أو عيب الأخت عند الناس، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10966/ضابط-الغيبة-ودور-من-علم-في-اخيه-عيبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41901.mp3","categories":["الأخلاق المذمومة"]},{"id":12763,"question":"هل يجوز أن أكتب لأختي بحثًا، وتقدمه باسمها؛ لأنها مشغولة، وهل يعتبر هذا من الغش، والسؤال لأختنا (م. ص. ع) من الأردن؟","title":"حكم كتابة بحث لطالب ليقدمه على أنه من جهده","answer":"الجواب:  نعم هذا من الغش؛ عليها أن تعد البحث، تعمل وتجتهد؛ لأن المقصود معرفة علمها، وبصيرتها حتى تعطى الشهادة على ضوء ذلك، أما أن يعده غيرها؛ فلا، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ الذي يكتب لأبنائه، أو لبناته موضوعًا في الإنشاء مثلًا للمدرسة، هل يعتبر أيضًا هذا من الغش؟ الشيخ: عليه أن يعلمهم حتى يتعلموا، ما هو بس كتابة مجردة، عليه أن يعلمهم، ويفقههم حتى يتعلموا ويستفيدوا، نعم.  المقدم: إذا قصد التعليم مع الكتابة؟ الشيخ: أما كتابة مجردة فأخشى أن يكون هذا غشًا؛ لأنهم سوف ينسبون ذلك إلى أنفسهم يقولون أعددناه ... كتبناه نحن، وهذا كذب، لكن يعلمهم، ويعدونه هم، هو يعلمهم، ويوجههم، وعليهم أن يعدوا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10977/حكم-كتابة-بحث-لطالب-ليقدمه-على-انه-من-جهده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41912.mp3","categories":["الأخلاق المذمومة"]},{"id":12801,"question":"يسأل ويقول: القول الكذب من غير قصد هل هو حرام؟","title":"حكم الكذب غير المتعمد","answer":"الجواب:  إذا كنت تظن أنك صادق؛ فلا شيء عليك، أما التعمد فلا يجوز لك، لكن لو قلت: قدم فلان، أو سافر فلان، تعتقد أنه هو الواقع، ثم بان لك أنك غلطان؛ فلا حرج عليك، لكن عليك التثبت في الأمور، وعدم العجلة في الأمور، حتى تكون أخبارك صادقة وثابتة، حتى لا ترمى بأنك متساهل، وأنك لا تبالي بالكلام، فالمؤمن هكذا يتحرى، ولا يعجل في الأمور، حتى إذا حدث حدث عن يقين، وعن صدق، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11015/حكم-الكذب-غير-المتعمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46206.mp3","categories":["الأخلاق المذمومة"]},{"id":12951,"question":"السائلة من أسئلتها تقول: هل يجوز للمرأة أن تعمل في مكان قريب من المنزل، وهذا المكان يوجد فيه رجل، أو أكثر، وليس معها محرم، فهل هذا الاختلاط وهذا العمل للضرورة جائز؟","title":"حكم عمل المرأة في مكان فيه اختلاط","answer":"الجواب:  إذا كانت تعمل مع النساء؛ فلا يضرها وجود رجل في البيت، أما تختلط بالرجال، لا، لكن إذا كانت تعمل مع النساء في محل ليس فيه اختلاط بالرجال، ولا فتنة؛ فلا حرج، ولو كان في البيت، أو في القصر، أو في المبسط ... إذا كانت في محل بعيد عنهم، ما فيه اختلاط بالرجل، النساء في جهة، والرجال في جهة، أو الرجل في جهة، أما تعمل معه جنبًا إلى جنب، وليس محرمًا لها؛ لا يجوز؛ لأن هذا من أسباب الفتنة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11168/حكم-عمل-المراة-في-مكان-فيه-اختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50210.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":12994,"question":"هذه السائلة تقول في هذا  كيف يستطيع الإنسان إزالة الحقد والكراهية لبعض الناس من قلبه؛ علمًا بأنني أشعر أحيانًا بأنه يبتعد عني هذا الحقد والكراهية، ويرجع أحيانًا أخرى، فهل هذا من الشيطان، أفيدونا مأجورين؟","title":"علاج الحقد والحسد","answer":"الجواب:  يمكن استبعاد الحقد والحسد بالنظر في أعمال الشخص الطيبة، وأن الله سبحانه هو الذي تفضل عليه بالتوفيق، وأن هذا من الله، فيتوب الإنسان من حقده وحسده، ويعلم أن هذا من فضل الله، وجوده وكرمه، حتى يزول ما في قلبه، يتأمل، يتبصر، وأن هذه الأشياء التي رزقها الله العبد من صحة واستقامة، أو جاه طيب، أو أعمال صالحة، أو ما أشبهه هذا كله من الله  فليعلم أن الله هو مقسم الأرزاق، وهو الذي بيده كل شيء، فيسأله -جل وعلا- التوفيق والهداية، وأن يزيل ما في قلبه من الكراهة لأخيه، أو الحسد لأخيه، كل شيء بيد الله . فعليك أن تسأل الله أن يعينك على الخير، وأن يصلح قلبك وأن يعيذك من شر الحسد، والبغضاء، والحقد على إخوانك، كل هذا بيده سبحانه هو الذي يصرف الأمور -جل وعلا- يقول ﷺ: إن القلوب بين أصبعين من أصابع الله يقلبها كيف يشاء  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11211/علاج-الحقد-والحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50407.mp3","categories":["الأخلاق المذمومة"]},{"id":13110,"question":"تقول السائلة من دمشق: ابتليت بعادة الإسراف، ولست أدري كيف أتخلص منها، أرشدوني أرشدكم الله؟","title":"نصيحة إلى من ابتلي بالإسراف","answer":"الجواب:  الواجب على المرأة والرجل الحذر من الإسراف، وأن تكون جميع أعماله على الاقتصاد، وعدم الإسراف؛ لأن الله -جل وعلا- قال: وَلا تُسْرِفُوا إِنَّهُ لا يُحِبُّ الْمُسْرِفِينَ [الأنعام:141] والنبي  قال: كل واشرب، والبس وتصدق في غير إسراف ولا مخيلة. فالواجب عليك المجاهدة حتى تعملي ما هو المطلوب من غير إسراف؛ لأن هذا يضرك، ويضر زوجك إن كان لك زوج، فالواجب عليك تقوى الله، وأن تعملي ما هو المناسب من الاقتصاد، وعدم إضاعة المال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11327/نصيحة-الى-من-ابتلي-بالاسراف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50817.mp3","categories":["الأخلاق المذمومة"]},{"id":13304,"question":"على بركة الله نبدأ هذا اللقاء بسؤال لأحد الإخوة (ع. أ. أ) يقول: ما معنى القنوط من رحمة الله، وذلك من الكتاب والسنة؟ جزاكم الله خيرًا يا سماحة الشيخ.","title":"معنى القنوط من رحمة الله","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالقنوط من رحمة الله هو اليأس، كونه لا يرجو الله يقنط أن الله يغفر له، وأن الله يرحمه، هذا من الكبائر، من كبائر الذنوب، ربنا -جل وعلا- نهى عن هذا، قال -جل وعلا-: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53]، وقال تعالى: إِنَّهُ لا يَيْئَسُ مِنْ رَوْحِ اللَّهِ إِلَّا الْقَوْمُ الكَافِرُونَ [يوسف:87] فلا يجوز لأحد أن يقنط من رحمة الله، يعني: ييئس لكفره أو لمعاصيه، بل عليه التوبة، والرجوع إلى الله، والإنابة إليه، وله البشرى بأن الله يقبل توبته، ويعظم أجره، ويجازيه على ما فعل من الخير. أما اليأس والقنوط لأجل سوء العمل فهذا من تزيين الشيطان، ولا يجوز، بل يجب على العبد الحذر من ذلك، وأن لا يقنط ولا ييئس، بل يرجو رحمة ربه، يرجو أن الله يتوب عليه، يرجو أن الله يتقبل عمله، فلا ييئس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11590/معنى-القنوط-من-رحمة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52201.mp3","categories":["التفسير","الأخلاق المذمومة"]},{"id":13385,"question":"السائل أبو هيثم يقول في هذا  أنا شاب ملتزم، ولي إخوة في الله نجتمع جميعًا، ونناقش أمور الشرع، وأثناء مناقشتنا لموضوع معين أغضب كثيرًا، وأكون عصبيًا جدًا لرأيي، وأتعصب كثيرًا لرأيي، وهذا يجعل إخواني في الله ينفرون مني، هل هذا من الشيطان؟","title":"هل التعصب والغضب عند النقاش من الشيطان؟","answer":"الجواب: لاشك أن هذا من الشيطان، التعصب للرأي، وسوء الخلق، والصياح عند الكلام لاشك أن هذا من تزيين الشيطان، ومن سوء الأدب، فالواجب على المؤمن أن يقول رأيه برفق وحكمة وتواضع، ولا يتعصب، بل يجتهد في إقامة الدليل، يوضح الدليل. وهكذا أصحابه كل منهم يجتهد في إيضاح الدليل من القرآن والسنة، ومن الأصول المعتبرة، مع الرفق، ومع الحلم، ومع طيب الكلام، هذا هو الواجب، أما الغضب، وسوء الخلق؛ فهذا من الشيطان، وهذا منكر لا يجوز، بل الواجب تركه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11674/هل-التعصب-والغضب-عند-النقاش-من-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52507.mp3","categories":["الأخلاق المذمومة"]},{"id":13398,"question":"السؤال الأخير في رسالة هذا السائل الذي لم يذكر الاسم في هذه الرسالة يقول: إذا كان الإنسان على خصام مع إنسان آخر، وهذا الخصام قد يستمر فترة طويلة، هل في ذلك إثم عليه، مع العلم بأن بعض الأشخاص تركهم أفضل من التحدث معهم؟ وجهونا في ذلك.","title":"حكم الاستمرار في الخصومة","answer":"الجواب: الخصام فيه تفصيل: إن كان خصامًا بحق، خصامًا بينهم في دعاوى يعتقد أنه مصيب؛ فلا حرج عليه إذا خاصمه، يقول: إنه مطلني حقي. عليه دين ومطله وهو مليء، خاصمه في أنه باع عليه سلعة ولا أعطاه إياها، خاصمه بأنه ضربه، بأنه سبه، خاصمه بأنه أخذ ماله.. إلى غير ذلك. يعني: إذا خاصمه بحق؛ فعليه أن يعدل، وعليه أن يتقي الله، ويخاصم بحق من غير ظلم، يطلب الحق من دون ظلم له، يطلب حقه لدى المحكمة، أو لدى الإخوان الطيبين يصلحون بينهم، ولا حرج عليه في ذلك. أما إذا خاصم بغير حق يعلم أنه مبطل، فهذا منكر، وعليه خطر في ذلك؛ لأنه مؤذ لأخيه بغير حق. فالواجب على المسلم ألا يخاصم إلا بحق، ويقول النبي ﷺ: أبغض الرجال إلى الله الألد الخصم فالخصومة بغير حق إيذاء وظلم، أما إذا كان يخاصم بحق يعلم أنه محق، وأن هذا الرجل أخذ ماله، أو مطله حقه وهو مليء، أو قتل ولده، أو قتل أخاه، أو غير هذا من الحقوق؛ فلا بأس، يطالب بحقه، ويقول النبي ﷺ: لو يعطى الناس بدعواهم؛ لادعى ناس دماء رجال وأموالهم، ولكن البينة على المدعي، واليمين على من أنكر نعم.","link":"https://binbaz.org.sa/fatwas/11689/حكم-الاستمرار-في-الخصومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52516.mp3","categories":["الأخلاق المذمومة"]},{"id":13569,"question":"بعد ذلك ننتقل إلى سؤال من أحد الإخوة من سائلة للبرنامج أختكم في الله (م. م. أ) تقول: كيف يستطيع الإنسان عندما يغتاب شخصًا أن يخلص نفسه من هذا الذنب؟","title":"كيفية تكفير ذنب الغيبة","answer":"الجواب: يستغفر الله، ويذكره بالمحاسن التي يعلمها منه في المجالس التي اغتابه فيها، فيكون هذا بهذا، إذا كان قال: إنه بخيل وإنه كذا وإنه كذا، فعليه التوبة إلى الله، وعليه أن يذكره في المجالس الأخرى بخصال طيبة إنه كذا وإنه كذا، إنه يحافظ على الصلوات، وإن عمله طيب، وإنه حريص على الخيرات، الشيء الذي يعلمه منه حتى تكون هذه بهذه. وإذا تيسر أن يستحله ويقول: سامحني، هذا طيب إذا تيسر ذلك، أما إذا كان يخاف أنه إذا علمه تشتد البغضاء لا يعلمه، لكن يذكره بالمحاسن، والأخلاق الطيبة التي يعرفها منه في المجالس التي اغتابه فيها، ويستغفر الله، ويتوب إلى الله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11907/كيفية-تكفير-ذنب-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53222.mp3","categories":["الأخلاق المذمومة"]},{"id":13576,"question":"هذه السائلة تقول: امرأة ربت طفلًا صغيرًا، وكبر هذا الطفل حتى تزوج، تقول المرأة بأنها تفتش له وتقبله، فهل يعتبر لها محرمًا؟","title":"هل من ربت طفلًا يكون محرمًا لها؟","answer":"الجواب: إذا ربت المرأة صبيًا حتى بلغ الحلم، ولم ترضعه، وإنما أحسنت إليه بالتربية، والكفالة؛ فإنها لا تكون محرمًا له، ولا أمًا له، بل هو أجنبي منها، لا يجوز لها الخلوة به، ولا يجوز له تقبيلها، ولا مصافحتها، ولا كشفها له، بل عليها أن تحتجب، وتعتبره أجنبيًا. لكن السلام والكلام الطيب: كيف حالك؟ كيف أنت؟ والسلام منه عليها، ومكافأتها بالكلام الطيب، والهدية الطيبة والمال، كل هذا طيب، لكن ما تكون محرمًا له، هي أجنبية منه كسائر النساء، وكونها أحسنت إليه، وربته لا يجعلها محرمًا له، المحرمية تكون إما بالنسب كأخته، وعمته وخالته، أو بالرضاعة الشرعية خمس رضعات في الحولين، أو بالمصاهرة كونها أم زوجته، أو بنت زوجته المدخول بها، أو جدتها، هذه أسباب تحريمها عليه. أما كونها ربته فإنها لا تحرم بذلك، ولا تكون محرمًا له، ولا يكون محرمًا لها، وعليها أن تحتجب منه، وليس لها أن تخلو به، وليس له أن يقبلها، ولا أن يصافحها كسائر الأجنبيات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11913/هل-من-ربت-طفلا-يكون-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53303.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":13584,"question":"هذه السائلة تقول: امرأة ربت طفلًا صغيرًا، وكبر هذا الطفل حتى تزوج، تقول المرأة بأنها تفتش له وتقبله، فهل يعتبر لها محرمًا؟","title":"هل من ربت طفلًا يكون محرمًا لها؟","answer":"الجواب: إذا ربت المرأة صبيًا حتى بلغ الحلم، ولم ترضعه، وإنما أحسنت إليه بالتربية، والكفالة؛ فإنها لا تكون محرمًا له، ولا أمًا له، بل هو أجنبي منها، لا يجوز لها الخلوة به، ولا يجوز له تقبيلها، ولا مصافحتها، ولا كشفها له، بل عليها أن تحتجب، وتعتبره أجنبيًا. لكن السلام والكلام الطيب: كيف حالك؟ كيف أنت؟ والسلام منه عليها، ومكافأتها بالكلام الطيب، والهدية الطيبة والمال، كل هذا طيب، لكن ما تكون محرمًا له، هي أجنبية منه كسائر النساء، وكونها أحسنت إليه، وربته لا يجعلها محرمًا له، المحرمية تكون إما بالنسب كأخته، وعمته وخالته، أو بالرضاعة الشرعية خمس رضعات في الحولين، أو بالمصاهرة كونها أم زوجته، أو بنت زوجته المدخول بها، أو جدتها، هذه أسباب تحريمها عليه. أما كونها ربته فإنها لا تحرم بذلك، ولا تكون محرمًا له، ولا يكون محرمًا لها، وعليها أن تحتجب منه، وليس لها أن تخلو به، وليس له أن يقبلها، ولا أن يصافحها كسائر الأجنبيات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11913/هل-من-ربت-طفلا-يكون-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53303.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":13908,"question":"ما حكم كشف زوجة العم على ابن أخي الزوج حتى ولو كان بينهما تفاوت في السن؟","title":"حكم كشف المرأة وجهها لأقارب زوجها","answer":"الجواب: ليس لها الكشف لأخي زوجها ولا عم زوجها ولا ابن عم زوجها ولا ابن أخيه كلهم أجناب، ليس لها أن تكشف إلا للزوج أو أبيه أو جده أو أولاده، أما أخوه وأعمامه وأخواله وأبناء أخيه كلهم أجناب لا تكشف لهم، ولا تخلو بواحد منهم أيضًا هذا لا يجوز، قال الله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] البعولة: الأزواج، أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31]، أما أخو الزوج لا ليس منهم ولا ابن أخيه ولا عمه ليسوا من هؤلاء، أما أبو الزوج نعم؛ لأنه قال: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] آباء البعولة: أي: آباء الأزواج، والجد أب فأب الزوج وجد الزوج كلهم محارم من الرضاعة أو من النسب.. سواء من الرضاعة أو من النسب، وهكذا أبناء الزوج من الرضاع أو من النسب محارم أيضًا، وهكذا أبناء بناته محارم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12295/حكم-كشف-المراة-وجهها-لاقارب-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48203.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":13911,"question":"ما حكم كشف زوجة العم على ابن أخي الزوج حتى ولو كان بينهما تفاوت في السن؟","title":"حكم كشف المرأة وجهها لأقارب زوجها","answer":"الجواب: ليس لها الكشف لأخي زوجها ولا عم زوجها ولا ابن عم زوجها ولا ابن أخيه كلهم أجناب، ليس لها أن تكشف إلا للزوج أو أبيه أو جده أو أولاده، أما أخوه وأعمامه وأخواله وأبناء أخيه كلهم أجناب لا تكشف لهم، ولا تخلو بواحد منهم أيضًا هذا لا يجوز، قال الله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] البعولة: الأزواج، أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31]، أما أخو الزوج لا ليس منهم ولا ابن أخيه ولا عمه ليسوا من هؤلاء، أما أبو الزوج نعم؛ لأنه قال: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] آباء البعولة: أي: آباء الأزواج، والجد أب فأب الزوج وجد الزوج كلهم محارم من الرضاعة أو من النسب.. سواء من الرضاعة أو من النسب، وهكذا أبناء الزوج من الرضاع أو من النسب محارم أيضًا، وهكذا أبناء بناته محارم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12295/حكم-كشف-المراة-وجهها-لاقارب-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48203.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":14047,"question":"يسأل سؤال آخر ويقول: لقد حدث في يوم من الأيام أن عاهدت أحد الإخوان على القرآن الكريم، على أن يكون السر الذي بيننا لا نخبر به أحدًا لا أنا ولا هو، ولكن اضطررت إلى أن أخبر به أحد الأقارب فماذا يجب علي؟","title":"ما يجب على من عاهد على كتم سر ثم أفشاه؟","answer":"الجواب: عليك التوبة إلى الله سبحانه؛ لأن السر أمانة، فالواجب عليك في هذا عليك التوبة إلى الله لأنك خنت السر، خنت الأمانة، فعليك التوبة إلى الله ، وإن ترتب على ذلك ضرر على هذا الإفشاء ضرر على أخيك الذي ائتمنك، فهذا المرجع فيه إلى المحكمة إن لم تصطلحا، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12472/ما-يجب-على-من-عاهد-على-كتم-سر-ثم-افشاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48402.mp3","categories":["الأخلاق المذمومة"]},{"id":14084,"question":"عند المزح مع الأصدقاء والضحك يدخل في ذلك كذب ليس إلا للضحك والمزح، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم الكذب للضحك والمزاح","answer":"الجواب: لا يجوز للمسلم ولا للمسلمة الكذب ولو في المزح، يقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك به القوم، ويل له ثم ويل له هذا وعيد، الويل: شدة العذاب، فهذا النبي ﷺ يقول: ويل للذي يحدث فيكذب ليضحك به القوم، ويل له ثم ويل له، فالواجب عليك يا أخي الحذر من ذلك، وعلى كل مسلم وعلى كل مسلمة الحذر من ذلك، فالكذب شر والواجب الحذر منه في الجد والمزح جميعًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12513/حكم-الكذب-للضحك-والمزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61403.mp3","categories":["الأخلاق المذمومة"]},{"id":14122,"question":"هذا السائل سلطان العمر من المدينة النبوية يقول: زوجة صالحة ذات صلاة وعبادة، ولكنها ذات خلق سيئ حيث ترفع كثيرًا من صوتها على زوجها وأبنائها، تنظر إلى الأمور نظرة سوداوية متشائمة، وتحمل الأمور ما لم تتحمل، هل من كلمة توجهونها إلى مثل ذلك عبر الأثير؟ فلعلها تستمع إلى ما تقولون يا سماحة الشيخ، وحيث أنها أيضًا تستمع إلى برامج إذاعة القرآن الكريم.","title":"وجوب الحذر من سوء الظن","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فنوصي المرأة المذكورة وأشباهها بتقوى الله جل وعلا، والعناية بحسن الظن، ومراعاة الأساليب الحسنة، والبعد عن سوء الظن لا بأولادها ولا بغيرهم، يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12]، ويقول النبي ﷺ: إياكم والظن فإن الظن أكذب الحديث.\nفالواجب على كل مسلم -رجل أو امرأة- الواجب الحذر من سوء الظن إلا بأسباب واضحة، وإلا فالواجب ترك الظن السيئ، لا بالمرأة ولا بالزوج ولا بالأولاد ولا بأخي الزوج ولا بأبيه.. ولا بغير ذلك، الواجب حسن الظن بالله، وحسن الظن بأخيك المسلم أو بأختك المسلمة، وأن لا تسيء الظن إلا بأسباب واضحة توجب التهمة، وإلا فالأصل البراءة والسلامة، وسوء الظن يسبب الفرقة والاختلاف والشحناء والعداوة، حتى الرجل مع أولاده إذا ساء ظنه بهم والمرأة مع أولادها إذا ساء ظنها بهم ساءت الحال بينهم، فالواجب الحذر من ذلك، والواجب العناية بحسن الظن مادام هناك مجال لحسن الظن، أما إذا وجد، وجدت أسباب تقتضي سوء الظن فلا بأس، كاجتماعه بمن يساء بهم الظن، وكوقوفه مواقف التهم.\nالمقصود متى وجدت أمور واضحة تقتضي سوء الظن فلا بأس، ولهذا إذا قامت البينة عمل بها وأسيء الظن بمن قامت عليه البينة بأنه سرق أو بأنه زنى أو بأنه شرب الخمر، فإذا قامت البينة الشرعية أقيم عليه الحد وأسيء به الظن بسبب البينة، أما عند عدم البينات فالواجب ترك سوء الظن والاعتماد على البراءة الأصلية والسلامة الأصلية والحذر من سوء الظن بالمسلم بغير حق، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12559/وجوب-الحذر-من-سوء-الظن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52501.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات"]},{"id":14124,"question":"السؤال الأخير في رسالة هذا السائل الذي لم يذكر الاسم في هذه الرسالة يقول: إذا كان الإنسان على خصام مع إنسان آخر، وهذا الخصام قد يستمر فترة طويلة، هل في ذلك إثم عليه، مع العلم بأن بعض الأشخاص تركهم أفضل من التحدث معهم؟ وجهونا في ذلك.","title":"حكم الخصام لفترة طويلة","answer":"الجواب: الخصام فيه تفصيل: إن كان خصام بحق خصام بينهم في دعاوى يعتقد أنه مصيب فلا حرج عليه إذا خاصمه يقول: إنه مطلني حقي. عليه دين ومطله وهو مليء، خاصمه في أنه باع عليه سلعة ولا أعطاه إياها، خاصمه بأنه ضربه، بأنه سبه، خاصمه بأنه أخذ ماله.. إلى غير ذلك. يعني: إذا خاصمه بحق، فعليه أن يعدل وعليه أن يتقي الله ويخاصم بحق من غير ظلم، يطلب الحق من دون ظلم له، يطلب حقه لدى المحكمة أو لدى الإخوان الطيبين يصلحون بينهم ولا حرج عليه في ذلك، أما إذا خاصم بغير حق يعلم أنه مبطل فهذا منكر وعليه خطر في ذلك لأنه مؤذ لأخيه بغير حق.\nفالواجب على المسلم أن لا يخاصم إلا بحق، ويقول النبي ﷺ: أبغض الرجال إلى الله الألد الخصم، فالخصومة بغير حق إيذاء وظلم، أما إذا كان يخاصم بحق يعلم أنه محق وأن هذا الرجل أخذ ماله أو مطله حقه وهو مليء، أو قتل ولده أو قتل أخاه، أو غير هذا من الحقوق فلا بأس يطالب بحقه، ويقول النبي ﷺ: لو يعطى الناس بدعواهم لادعى ناس دماء رجال وأموالهم ولكن البينة على المدعي واليمين على من أنكر. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12562/حكم-الخصام-لفترة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52516.mp3","categories":["الأخلاق المذمومة"]},{"id":14220,"question":"نختم هذا اللقاء الطيب المبارك معكم بهذا السؤال للسائل (ل. ع. ع) من جازان يقول سماحة الشيخ: ما حكم النكت أو الطرائف المضحكة التي يقولها الشخص لكنها ترمي إلى الاستهزاء وقد لا يكون لها أساس من الصحة بحيث تكون افتراء وزورًا وبهتان؟ نرجو منكم التعليق على هذا الأمر، جزاكم الله خيرًا.","title":"حكم المزاح بالكذب","answer":"الجواب: هذه الأمور يجب الحذر منها وتركها، إلا إذا كان مزاحًا بحق قليل، مزاحًا بحق وهو قليل لا بأس، كما فعله النبي ﷺ، وقال: ... من يشتري العبد؟ وأراد يعني أنه عبد لله، وقال: لا يدخل الجنة عجوز يعني: أن النساء يدخلن شابات لا عجائز وإن كانت ماتت عجوزًا يجعلها الله في الجنة شابة لا عجوزًا، وهكذا الشيوخ في الجنة شبان، كل أهل الجنة شباب، ... إذا كان مزحًا بحق وهو قليل لا بأس.\nأما المزح بالكذب أو الإكثار من المزح، أو من باب الاستهزاء هذا لا يجوز، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/12674/حكم-المزاح-بالكذب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54821.mp3","categories":["الأخلاق المذمومة"]},{"id":14328,"question":"السائلة تقول في سؤالها: إذا قالت المرأة في أخت لي كلام سيئ، فهل يجوز لي نقل هذا الكلام لأختي، أم يعتبر هذا من النميمة؟ وما هو الضابط لمعرفة الكلام هل هو من النميمة أم لا مأجورين؟","title":"ضابط النميمة ونصيحة النمام","answer":"الجواب: ينبغي بل يجب الإنكار على من قال في عرض أخيه وأنت تسمع، تقول: اتق الله هذا لا يجوز، هذه غيبة، اتق الله لا يجوز لك هذا الكلام، الله يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] ولا تنقل الكلام، لا تنقل الكلام إلى زيد ولا عمرو؛ لأن نقل الكلام من النميمة، ولكن تنكر على صاحب الغيبة وتنصحه ألا يعود إلى ذلك وأن يحذر غيبة الناس، هذا هو الواجب عليك؛ لأن الله جل وعلا يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول النبي ﷺ: من رأى منكم منكرًا رأى يعني: علم أو شاهد فليغيره بيده فإن لم يستطع فبلسانه وهذا من اللسان فإن لم يستطع فبقلبه وذلك أضعف الإيمان.\nوهكذا إذا رأيته يسب.. يشتم.. تنصحه تقول: اتق الله هذا لا يجوز، احفظ لسانك، وهكذا إذا رأيته يتعاطى بعض المنكرات كالتدخين وشرب المسكر واستعمال الملاهي تنصحه تقول: اتق الله هذا لا يجوز لك، احذر احذر نقمة الله، احذر غضب الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12801/ضابط-النميمة-ونصيحة-النمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55011.mp3","categories":["الأخلاق المذمومة"]},{"id":14329,"question":"في آخر أسئلة السائلة أم تماضر تقول: دائمًا أسمع عن الاقتصاد في المال وعدم التبذير، فما هو الضابط لمعرفة الإسراف من عدمه؟","title":"الضابط في معرفة الإسراف والتبذير","answer":"الجواب: الله جل وعلا بين هذا، قال سبحانه: وَلا تُبَذِّرْ تَبْذِيرًا [الإسراء:26] والتبذير: وضع الأموال في غير محلها، صرفها في غير جهة النفع، وقال تعالى في صفة النفقة المضبوطة المستقيمة: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا [الفرقان:67] يعني: لم يزيدوا في النفقة ولم يقصروا بل أنفقوا وسطًا، فهذا هو المشروع.\nأما من زاد وأنفق في غير محل الإنفاق فهذا يقال له: إسراف وتبذير، ما زاد على الحاجة يسمى إسرافًا، وصرف المال في غير وجهه يسمى تبذيرًا، وصرف المال في وجهه هذا طيب وقصد.\nفالمؤمن يتحرى صرف الأموال في وجوهها، وإذا أنفق في بيته أو على ضيوفه أو على خدامه ينفق وسطًا لا إسراف ولا تبذير: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا [الفرقان:67] ويقول سبحانه: وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا [الإسراء:29] ولكن بين ذلك.\nفكونه يضع طعامًا زائدًا ولحومًا زائدة ما لها حد ليس هذا من القصد هذا من الإسراف، إلا إذا كان قصد أنه يعطيها الفقراء الزائد يعطيه الفقراء والمساكين فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12803/الضابط-في-معرفة-الاسراف-والتبذير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55012.mp3","categories":["الأخلاق المذمومة"]},{"id":14374,"question":"السائلة تقول: هل بغض الإنسان لبعض الناس بسبب أو بدون سبب يكون معذور فيه؟وهل يدخل هذا في قوله -عليه الصلاة والسلام-: \"إن محبة القلب ليست بيده\"؟","title":"حكم بغض الناس بغير سبب","answer":"الجواب: لا نعرف هذا الحديث، لا نعرف هذا الحديث، لكن الواجب على المسلم أن يحب أخاه في الله، ولا يبغضه، وليس له بغضه إلا إذا كان يتعاطى منكرات أبغضه على قدرها، أو كافر أبغضه في الله، أما يبغضه لغير سبب فلا يجوز، الواجب حبه لأخيه في الله، أن يحبه في الله، ويبغضه في الله، وليس بغض أخيه بغير حق، أما إذا أبغضه؛ لأنه ظلمه؛ لأنه أخذ إرثه؛ لأن رفع أمره إلى السلطان بغير حق حتى أوذي، أو ما أشبه ذلك، يبغضه على قدر حاله، ويحبه على قدر ما عنده من الإسلام والإيمان.","link":"https://binbaz.org.sa/fatwas/12855/حكم-بغض-الناس-بغير-سبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55117.mp3","categories":["الحكم على الأحاديث","الأخلاق المذمومة"]},{"id":14420,"question":"تقول هذه السائلة: هل يكفي كراهية الغيبة بالقلب فقط دون اللسان؟","title":"هل يكفي كراهية الغيبة بالقلب؟","answer":"الجواب: ما يكفي، لا بد من التنبيه، إذا وجد من يغتاب ينكر عليه، الإنسان يكرهه بالقلب وينكر على من فعل الغيبة، يقول: ترى ما يجوز، اتق الله لا تغتب الناس؛ لأن الله أمر بإنكار المنكر قال -جل وعلا-: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104] قال تعالى: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] قال سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71]. فالغيبة منكر، الذي يتكلم في الناس فلان طويل، فلان بخيل، فلان كذا فلان كذا، يتكلم فيما يكرهون يتكلم فيهم بما يكرهون هذه الغيبة، كما قال ﷺ: الغيبة ذكرك أخاك بما يكره قيل: يا رسول الله، وإن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهته. فالواجب على المسلم أن يحذر الغيبة، وإذا رأى من يغتاب يقول له: يا أخي، اتق الله، ما يجوز لك الغيبة، دع الناس اترك هذا، لا تغتب الناس احذر؛ لأن الله يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12].","link":"https://binbaz.org.sa/fatwas/12902/هل-يكفي-كراهية-الغيبة-بالقلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55316.mp3","categories":["الأخلاق المذمومة"]},{"id":14443,"question":"هذا السائل (ع. ع. م) معهد البريد يقول في هذا  سماحة الشيخ، أنا شخص متزوج وحدث أن ارتكب أحد الأبناء خطأ أثناء تكليفه من قبل والدته بحمل بعض الأغراض للمنزل، وحين تدخلي لمعالجة الموقف حدث بيني وبين والدته شجار، مما جعلني أغضب من تصرفها، فقلت أثناء غضبي ما نصه: لعن الله من أعطاكِ، أو لعن الله من أعطاكْ، وقد ندمت على ذلك ندمًا شديدًا، وأنا لست ممن يستعمل هذه الكلمة الخاطئة والخاصة بالشيطان، ولا حتى مع أولادي ولا مع زوجتي، ولكن لحظة أفقدتني فيها غضبي، فقلت هذا الكلام، فهل علي إثم في علاقتي الزوجية بزوجتي من الناحية الشرعية؟جزاكم الله خيرًا.","title":"حكم نكاح من قال لزوجته: لعن الله من أعطاك","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذا الكلام منكر من القول ومعصية كبيرة، فالواجب عليك التوبة إلى الله منها؛ لأنها سب وشتم لا يليق منك، وقولك: لعن الله من أعطاك هذا خطره عظيم؛ لأن هذا قد يعود إلى الله الذي أعطى، هذا منكر شنيع، وإذا قصدت بذلك الرب فهذه ردة عن الإسلام، فالواجب عليك التوبة إلى الله، ومن تاب تاب الله عليه، عليك التوبة والندم والإقلاع والعزم ألا تعود في ذلك، وعليك الاستكثار من العمل الصالح وأبشر بالخير -إن شاء الله- من تاب تاب الله عليه، يقول الله سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] ويقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فمن تاب أفلح، فعليك التوبة إلى الله والندم والإقلاع والاستكثار من العمل الصالح وأبشر بالخير -إن شاء الله-. وزوجتك معك ولا يضر ذلك من جهة النكاح، فقد قال الله سبحانه فيمن أشرك وفيمن قتل ولده أو زنى، قال -جل وعلا-: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا [الفرقان:68-69] يعني: المشرك والقاتل والزاني، ثم قال: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الفرقان:70] فنسأل الله أن يمن عليك وعلى كل مسلم بالتوبة، ونسأل الله أن يعيذك من العود إلى مثله، نعم.\nالمقدم: سماحة الشيخ، هذا السائل يقول: عندما قلت: لعن الله من أعطاك، يعني: ابنه، يعني الزوجة؟\nالشيخ: على كل حال هو منكر سواء قصد الزوجة أو ما قصد الزوجة، هو منكر، فعليه التوبة إلى الله من ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12907/حكم-نكاح-من-قال-لزوجته-لعن-الله-من-اعطاك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55401.mp3","categories":["الأخلاق المذمومة","الحقوق الزوجية"]},{"id":14478,"question":"هذه السائلة أم عبدالله تقول في سؤال لها: هل الغيبة تنتفي إذا كانت المرأة تتكلم عن ابنها وزوجته مع بناتها في غيبتهما؟ وهي تقول: بأن هذا ليس من الغيبة؟","title":"هل كلام الأم في ابنها وزوجته من الغيبة؟","answer":"الجواب: إذا ذكرت ابنها بما يكره أو زوجته بما يكره فهي غيبة عند بناتها أو غيرهم، إذا ذكرت ابنها بما يكره أو زوجته بما يكره فهي غيبة، والله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] ويقول النبي ﷺ: «لما سئل عن الغيبة؟ قال ﷺ: الغيبة ذكرك أخاك بما يكره قيل: يا رسول الله، إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهته. فالواجب الحذر، فليس للمرأة أن تغتاب ابنها ولا أباها ولا أخاها ولا زوجة ابنها ولا زوجة أبيها ولا زوجة أخيها، والواجب على الجميع الحذر مما نهى الله عنه، نعم.","link":"https://binbaz.org.sa/fatwas/12958/هل-كلام-الام-في-ابنها-وزوجته-من-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55421.mp3","categories":["الأخلاق المذمومة"]},{"id":14480,"question":"هذه السائلة أم عبدالله تقول في سؤال لها: هل الغيبة تنتفي إذا كانت المرأة تتكلم عن ابنها وزوجته مع بناتها في غيبتهما؟ وهي تقول: بأن هذا ليس من الغيبة؟","title":"هل كلام الأم في ابنها وزوجته من الغيبة؟","answer":"الجواب: إذا ذكرت ابنها بما يكره أو زوجته بما يكره فهي غيبة عند بناتها أو غيرهم، إذا ذكرت ابنها بما يكره أو زوجته بما يكره فهي غيبة، والله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] ويقول النبي ﷺ: «لما سئل عن الغيبة؟ قال ﷺ: الغيبة ذكرك أخاك بما يكره قيل: يا رسول الله، إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهته. فالواجب الحذر، فليس للمرأة أن تغتاب ابنها ولا أباها ولا أخاها ولا زوجة ابنها ولا زوجة أبيها ولا زوجة أخيها، والواجب على الجميع الحذر مما نهى الله عنه، نعم.","link":"https://binbaz.org.sa/fatwas/12958/هل-كلام-الام-في-ابنها-وزوجته-من-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55421.mp3","categories":["الأخلاق المذمومة"]},{"id":14530,"question":"تسأل أيضًا وتقول: هل عملي في المؤسسة حرام أم حلال؟ مع العلم بأني متزوجة ولدي ثلاثة أطفال، ولكن راتب زوجي لا يكفي لسد حاجتنا الضرورية.","title":"ما حكم عمل المرأة في مكان مختلط؟","answer":"الجواب: أما عملك في المؤسسة بين الرجال فلا يجوز؛ لأن ذلك يعرضك للفتنة، والخطر العظيم، وقد قال -عليه الصلاة والسلام-: ما تركت بعدي فتنة أضر على الرجال من النساء وقال -عليه الصلاة والسلام-: لا يخلون رجل بامرأة، فإن الشيطان ثالثهما فالواجب عليك البعد عن المؤسسة التي فيها الاختلاط، أما في مكان وحدك أو مع النساء فلا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13031/ما-حكم-عمل-المراة-في-مكان-مختلط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63413.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":14614,"question":"من الجماهيرية، ومن مدينة المرز، المستمع (ح. ح. ح. ع) بعث برسالة ضمنها تسعة أسئلة، في أحد أسئلته يقول: لا تقوموا كما تقوم الأعاجم هل هذا الحديث ينطبق على الطلبة في المدرسة عند دخول المدرس، أم لا؟","title":"حكم قيام الطلاب للمدرس","answer":"الجواب: النبي ﷺ لما كان أصابه بعض الأثر بسقوطه عن الفرس صلى جالسًا، وجحش شقه، يعني: أصابه شيء في شقه -عليه الصلاة والسلام- شق عليه معه القيام، فصلى جالسًا، فلما وقف الصحابة يصلون خلفه قيامًا أمرهم بالجلوس، وقال: لا تقوموا علي كما تفعل الأعاجم لملوكها. أما الطلبة فلا يجوز لهم الوقوف على رؤوس المدرسين تعظيمًا، أما إذا قام لأمر آخر ليسمع الأستاذ جواب مسألة أو سأله عن مسألة، فأراد أن يسمع الطلبة جوابه، أو لأسباب أخرى فهذا ليس من هذا الباب، إذا قام الطالب من أجل جواب عن مسألة، أو من أجل تلاوة حديث أو تلاوة كلام مطلوب من الأستاذ حتى يسمعه الطلبة، أو حتى يسمعه الأستاذ، فهذا ليس من هذا الباب.  أما قيامهم له إذا دخل وقوفًا هذا لا ينبغي، بل إذا دخل يجلسون ويردون السلام، وهم جالسون هذا هو السنة، ولا ينبغي أن يأمرهم بالقيام من أجل تعظيمه، كان الصحابة  وأرضاهم لا يقومون للنبي ﷺ إذا دخل عليهم، وهو أعظم الناس، وأفضل الناس لما يعلموا من كراهته لذلك -عليه الصلاة والسلام-، ولكن يسلمون وهم على مجالسهم جالسون، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13111/حكم-قيام-الطلاب-للمدرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63607.mp3","categories":["الأخلاق المذمومة"]},{"id":14649,"question":"في حديث الرسول ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا عاهد أخلف، وإذا خاصم فجر هل تتفضلون بتوضيح هذا الحديث وخصوصًا: إذا خاصم فجر فهل يعني الرسول ﷺ سرعة الغضب، أم ماذا يعني؟","title":"شرح حديث \"آية المنافق ثلاث...\"","answer":"الجواب: الرسول ﷺ أخبر عن المنافقين بخصال ليحذرنا منها، حتى نبتعد عنها، يقول ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان يحذرنا من إخلاف الوعد، ومن الكذب في الحديث والأخبار، ومن الخيانة في الأمانة، وأنها من خصال أهل النفاق نعوذ بالله فيجب الحذر منها. ويقول ﷺ: أربع من كن فيه كان منافقًا خالصًا، ومن كانت فيه خصلة منهن كانت فيه خصلة من النفاق، حتى يدعها: إذا حدث كذب، وإذا وعد أخلف، وإذا خاصم فجر، وإذا عاهد غدر رواه الشيخان من حديث عبدالله بن عمر -رضي الله عنهما-، فهذا يدل على أن المنافق من خصاله إخلاف الوعد، والكذب في الحديث، والخيانة في الأمانة، وأنه إذا خاصم فجر، وفجوره التوسع في المعصية والكذب. وإذا عاهد غدر إذا عاهد إخوانه، أو عاهد الكفار غدر بهم، ولم يوف بالعهد لضعف إيمانه، أو عدم إيمانه. وإذا خاصم كذب في خصومته وتوسع في الكذب والفجور وظلم؛ لعدم إيمانه، أو لضعف إيمانه، فالفجور هو التوسع في المعصية وإظهارها -نسأل الله العافية- كانفجار الماء.  فالحاصل: أنه يتوسع في الكذب والعدوان على الخصم واللدد في الخصومة لضعف إيمانه، أو عدم إيمانه، نعوذ بالله، هكذا شأن المنافقين لعدم إيمانهم، ولهم صفات بيَّنها الله في القرآن غير هذه الصفات، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا ۝ مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ[النساء:142-143] هذه من صفاتهم، كالخداع والمكر والعدوان على الناس. ومن خصالهم: التكاسل عن الصلاة، والتثاقل عنها، وقلة الذكر، يعني: يغلب عليهم الغفلة.  ومن خصالهم: الرياء في أعمالهم، يصلون رياءً، يتصدقون رياءً، يذكرون الله رياءً.  ومن خصالهم الخبيثة: أنهم ما لهم ثبات عندهم تردد تارة مع المؤمنين، وتارة مع الكافرين، قد ترددوا في دينهم وتذبذبوا؛ ولهذا قال: مذبذبين ليس لهم ثبات، لا مع أهل الحق، ولا مع أهل الباطل، هم مع من رأوا المصلحة أن يكونوا معه في دنياهم، فإن نصر الكفار صاروا معهم، وإن نصر المؤمنون صاروا معهم لطلب الدنيا والأمان، ونحو ذلك، نسأل الله العافية، هذه حالهم عدم الثبات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13138/شرح-حديث-اية-المنافق-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63611.mp3","categories":["الأخلاق المذمومة","شروح الحديث"]},{"id":14689,"question":"السائلة (ن. ش. ح) من مكة المكرمة، تذكر في سؤالها سماحة الشيخ وتقول: بأنها دائمًا تقاطع صلتها مع أخواتها، حيث تقول: لا أكلمهم، وقد تستمر تلك المقاطعة لأكثر من شهر، بسبب سوء أخلاقهن، والتلفظ بألفاظ تقول: لا أقبلها، ماذا علي؟ وهل أعمالي لا تصعد إلى السماء في تلك المدة؟ وماذا أفعل مع أنهن أخواتي؟","title":"حكم قطع الرحم بسبب سوء أخلاقه","answer":"الجواب: الواجب صلة الرحم، والتسامح من الأشياء اليسيرة التي ليست معاصي، مع النصيحة والتوجيه إلى الخير، ولا تجوز قطيعة الرحم؛ لأن الله -جل وعلا- يقول: فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ۝ أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23] ويقول النبي ﷺ: لا يدخل الجنة قاطع رحم فالواجب الحذر. عليك أن تزوريهن، وعليهن أن يزرنك، وعليكن أيضًا بالتسامح بينكن، ومن طريق الهاتف بالكلام الطيب -من طريق التلفون- إذا ما تيسرت الزيارة من طريق الهاتف، يعني: التلفون بالكلام الطيب، وإذا كان عندهن بذاءة في اللسان، عليك النصيحة حتى يعتدن الكلام الطيب، وعلى من يعرف ذلك من الأقارب أن ينصحوا هؤلاء الأخوات حتى تستقيم الحال بينكن -إن شاء الله-. المقصود: المشروع الصبر مع النصيحة والتوجيه والزيارة المناسبة، أو من طريق التلفون، حتى لا تقع القطيعة، وعليهن أن يتقين الله، وأن يسمعن ويطعن فيما ينتقد عليهن. وإذا كان الواقع شيئًا يسيرًا من سوء الكلام، فالنصيحة تكفي -إن شاء الله-، وليس لك قطيعتهن، أما إذا كان معاصٍ، ومجاهرة بالمعاصي، هذا يوجب هجرهن، كأن يلعن ويسببنك أو يجاهرن بالمعاصي بالاختلاط مع الرجال، أو شرب الخمر، أو التلاعب واستعمال الملاهي والأغاني الخبيثة، هذه منكرات عليك أن تهجريهن حتى يتبن ويستقمن على طاعة الله ورسوله. أما إذا كان أشياء بسيطة من سوء الكلام بينكما، أو المزح بينكن، أو ما أشبه ذلك، فعليك النصيحة والتوجيه، ولعل الله يهديهن بأسبابك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13181/حكم-قطع-الرحم-بسبب-سوء-اخلاقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56015.mp3","categories":["الأخلاق المذمومة"]},{"id":14693,"question":"الآية الكريمة سماحة الشيخ: وَأُحْضِرَتِ الأَنفُسُ الشُّحَّ [النساء:128] تريد تفسيرًا لها أيضًا؟","title":"تفسير قوله تعالى: {وَأُحْضِرَتِ الأَنفُسُ الشُّحَّ}","answer":"الجواب: هذا مثلما ظاهر القرآن، الأنفس من صفاتها الشح والبخل، إلا من رحم الله، فالواجب على المؤمن أن يتقي ذلك، ويحذر الشح والبخل، ويعتاد الجود والسخاء، وعدم البخل والشح.  يقول النبي ﷺ: اتقوا الشح، فإنه أهلك من كان قبلكم والله يقول سبحانه في كتابه العظيم: وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الحشر:9] من صفات العباد الشح والبخل إلا من عصم الله، إلا من رحم الله، والشح: الحرص على المال بكل وسيلة من حلال وحرام، ثم إذا وجده بخل به، فالشحيح حريص على طلب المال بكل طريق، ثم إذا وجده بخل به أيضًا، والشح شره عظيم؛ ولهذا قال سبحانه: وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الحشر:9] ويقول النبي ﷺ: اتقوا الشح، فإنه أهلك من كان قبلكم واتقوا الظلم، فإن الظلم ظلمات يوم القيامة الله المستعان. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13188/تفسير-قوله-تعالى-واحضرت-الانفس-الشح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56018.mp3","categories":["الأخلاق المذمومة","التفسير"]},{"id":14937,"question":"من جنوب المملكة وردتنا هذه الرسالة من (ع. ص) الغامدي يقول في رسالته: استمعت في إحدى الليالي إلى برنامجكم المحبوب -برنامج نور على الدرب- وكان يجيب عليها أحد المشائخ الأفاضل -وفقهم الله- وذلك حول التحجب، ويقول: أنه محرم على أخ الزوج أن يكشف على زوجة أخيه، ولكن هذه الظاهرة منتشرة في بلادنا الجنوب، ولا يقدر الأخ أن يمنع أخيه من مطالعة زوجته؛ لأنها عادة. أما أن يكون المنزل يسكنه هو وإخوانه ووالده ووالدته، وهذه عادة متصلة من الآباء والأجداد، وعادة قبلية، والرجاء من سماحتكم أن تدلونا إلى الطريق الصحيح. وفقكم الله. والسلام عليكم ورحمة الله وبركاته.","title":"حكم عادة كشف المرأة وجهها لأخي الزوج","answer":"الجواب: العادات التي تخالف الشرع يجب تركها، الرسل -عليهم الصلاة والسلام- إنما عاداهم الناس بالعوائد، عادة الجاهلية يعبدون الأصنام، ويعبدون الأوثان، ويعبدون الأشجار والأحجار، عادوا الرسل بهذا، فالعادات التي تخالف الشرع يجب تركها، ولو كانت قديمة. وليس للزوج أن يسمح لزوجته أن تكشف لأخيه، أو لعمه، أو لابن عمه، لا بل عليها التستر والحجاب؛ لأنه فتنة والوجه من أعظم الفتنة، فعليها التستر ولو كانت عادة، يجب الحجاب، ويجب على أخي الزوج أن لا يرضى بهذا، ما يرضى بالمعصية، يجب عليه غض البصر، وأن يساعد أخاه على تحجب المرأة، وأن تتحجب عن أخيه، وعن عمه وعن ابن عمه وعن خاله وابن خاله. وهكذا زوج الأخت، لا تكشف له أخت زوجته، بل تحجب عنه، وهو لا ينظر إليها، بل يغض البصر، ولا يرضى بأن تكشف له؛ لأن المسلمين مأمورون بالتعاون على البر والتقوى، مأمورون بالأمر بالمعروف والنهي عن المنكر، فالرجل ينهى زوجة أخيه أن تكشف له، ويغض بصره، والرجل ينهى أخت زوجته أن تكشف له، ويغض بصره، ويتعاون معهم على البر والتقوى، لا يفرح بالمعاصي، ولا يطالب بأن تكشف له؛ لأن هذا من أسباب الفتن، ولو كان عادات قديمة، فالعادات يعالجها الشرع، والشرع يحكمها، ولا تحكم الشرع هي، بل الشرع هو الحاكم على الجميع في العادات وغير العادات، نسأل الله للجميع الهداية والتوفيق، نعم.","link":"https://binbaz.org.sa/fatwas/13443/حكم-عادة-كشف-المراة-وجهها-لاخي-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64708.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":14962,"question":"لديه سؤال آخر يقول: أفيدكم أنني أشاهد بعضًا من الناس تكون عنده مناسبة ويذبح للضيوف ذبائح، ويتوفر من هذه العزيمة والذبائح التي ذبحت لهم شحم وعيش، ثم يكبونه في الأرض، فهل عليهم إثم في ذلك؟أفيدونا، وفقكم الله.","title":"ما حكم وضع بقايا أطعمة الولائم في القمامة؟","answer":"الجواب: هذا شيء واقع من الناس، وهو نقل ما يفضل من الولائم من اللحوم والأطعمة إلى القمامات، أو وضعه في كراتين، ثم توضع في القمامات، كل هذا واقع من الناس، وفيه خطر عظيم.  والواجب مع القدرة أن يوزع هذا الباقي من اللحوم والأطعمة على الفقراء والمساكين في أي مكان، فإن لم يوجد؛ يوضع في مكان نظيف في البرية، صحراء، حتى ينتفع به من شاء الله من حيوانات، ومن بني آدم، ولا يطرح مع القمامة ومع النجاسات، هذا لا يجوز. وقد نبهنا على هذا غير مرة، وكتبنا في الصحف غير مرة للتنبيه على هذا، وعلى البلديات أن تلاحظ هذا، وأن تجعل ما يوضع من الأطعمة واللحوم في كراتين نظيفة، أو في براميل نظيفة خاصة ينقل إلى محلات مناسبة حتى ييبس أو تأكله الدواب أو ييبس ويعطاه أهل الدواب فينتفعون به، نعم.","link":"https://binbaz.org.sa/fatwas/13465/ما-حكم-وضع-بقايا-اطعمة-الولاىم-في-القمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65004.mp3","categories":["الأخلاق المذمومة"]},{"id":15018,"question":"يقول السائل من سوريا، عدنان، ومقيم في الأردن: هل يجوز أن نرمي الطعام المتبقي منذ فترة يومين -مثلًا- أم نأكله كرهًا؟","title":"هل يجوز رمي الطعام المتبقي؟","answer":"الجواب: أنتم بالخيار، إن أكلتموه فلا بأس، وإن رميتموه في محل طيب تأكله الدواب والطيور؛ فلا بأس، يجعل في مكان طيب، في محل طيب نظيف؛ حتى تأكله الطيور أو القطط، أو في الخارج تأكله الكلاب وغيرها في محل طيب، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13514/هل-يجوز-رمي-الطعام-المتبقي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56304.mp3","categories":["الأخلاق المذمومة"]},{"id":15094,"question":"يقول: ما هي نصيحتكم لرجل بلغ الستين من عمره، وهو لا يدع قول الكذب، وأيضًا يغتاب الناس؟","title":"نصيحة لمن ابتلي بالكذب وغيبة المسلمين","answer":"الجواب: يجب عليه أن يتقي الله، ويحذر الكذب والغيبة، سواءً كان ابن ستين أو أقل أو أكثر، الكذب محرم على جميع الناس، فليس له أن يكذب، ولو كان في الشباب، وليس له أن يكذب ولو كان ابن مائة سنة.\nوعليه أن يحذر الغيبة أيضًا، الله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12].\nوالكذب من أقبح الخصال، وهو من خصال المنافقين، فيجب الحذر منه، وإذا كان كبير السن كان أشد في الإثم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13592/نصيحة-لمن-ابتلي-بالكذب-وغيبة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49405.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":15144,"question":"السؤال الآن الذي بين أيدينا، وردنا من المستمع المرسل (أ. م. س) يقول فيه: هل يجوز الغش في الامتحان؛ نظرًا لأننا بدأنا سنةً دراسية جديدة؟وفقكم الله، وأثابكم.","title":"ما حكم الغش في الامتحانات؟","answer":"الجواب: الغش في الامتحان لا يجوز، هذا غلط؛ لأنه يتظاهر بأنه ناجح وهو غير ناجح؛ فيضر المسلمين.  ثم أيضًا هو خيانة للأمانة، ثم قد يفوق غيره بالكذب، فهذا كله لا يجوز، الغش في الامتحان مطلقًا لا يجوز، لا في مادة أساسية، ولا في مادة أخرى فرعية، ولا في مادة اللغة، ولا في مادة الدين، ولا في مادة اللغة الإنجليزية، ولا غير ذلك، لا يجوز الغش أبدًا، بل يجب أن يجتهد، ويحرص حتى ينجح، وليس له أن يغش.  وليس للأساتذة أن يتساهلوا معه في هذا، أو يسمحوا له بالغش، كما يفعل بعض الناس فيما بلغنا، ليس للأستاذ ذلك، بل يجب أن ينصح الطالب بأن يجتهد حتى ينجح في الاختبار نجاحًا صحيحًا لا مغشوشًا، والله المستعان.","link":"https://binbaz.org.sa/fatwas/13654/ما-حكم-الغش-في-الامتحانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65807.mp3","categories":["الأخلاق المذمومة","العالم والمتعلم"]},{"id":15219,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الخبر، أختنا عرضنا لها سؤال في حلقة مضت، وفي هذه الحلقة تسأل وتقول: ما حكم كشف الوجه على بعض أبناء العمومة؛ وذلك بسبب أننا نعيش جميعًا في منزل واحد؛ إذ من الصعب تغطية الوجه، أما باقي الأعضاء فالحمد لله مغطاة، وأنا لا أضع أي نوع من المساحيق في وجهي. مع العلم أننا لا نأكل جميعًا على مائدة واحدة، بل النساء منعزلات عن الرجال، كذلك لا نتخالط كثيرًا، بل مجرد الصعود والنزول من الطابق العلوي إلى السفلي، وبالعكس، نرجو توجيهنا. جزاكم الله خيرًا.","title":"حكم كشف الوجه على أبناء العمومة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دلت الأدلة الشرعية من الكتاب والسنة على أن المرأة عورة، يجب عليها الحجاب عن غير محارمها، ولا يجوز لها إبداء الزينة لغير محارمها، سواء كانوا من بني العم، أو بني الخال، أو من غيرهم، يجب الحجاب عنهم، وإن كانوا أقرباء إذا لم يكونوا محارم؛ لقول الله -جل وعلا- في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هذه الآية عامة، تعم جميع النساء، وإن كان الخطاب لأزواج النبي -رضي الله عنهن- وﷺ، ولكن غيرهن من باب أولى، فإذا أمر أتقى النساء بذلك فغيرهن من باب أولى. ثم بين العلة التي تعم الجميع قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ فإذا كان أطهر لقلوب الصحابة، وهم الأخيار خير هذه الأمة بعد الأنبياء، وأطهر لقلوب الصحابيات من أمهات المؤمنين وغيرهن، فغيرهن في حاجة إلى هذه الطهارة، بل في أشد الضرورة إلى هذه الطهارة. ويقول -جل وعلا- في آية أخرى من سورة النور : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ [النور:31] الآية. والزينة هي الزينة الظاهرة والباطنة، وأعظمها الزينة الخلقية، زينة الوجه والشعور والذراع واليد والساق والقدم، ونحو ذلك، هذه الزينة التي تفتن الناس، أما زينة الملابس فقد تفتن لكنها دون هذه الأشياء. وإذا ظهرت إلى غير محارمها يكون عليها ملابس غير فاتنة، وهكذا في الأسواق تكون ملابس عادية، ليس فيها فتنة، ولكن أعظم من ذلك ظهور الزينة الخلقية زينة الوجه، أو اليد، أو الشعور، أو الساق أو الذراع أو القدم كل هذه تحتاج إلى ستر؛ لأن الآية عامة: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ الآية. وفي الصحيحين عن عائشة -رضي الله عنها- أنها قالت -رضي الله عنها- لما سمعت صفوان يسترجع لما رآها في السفر حين تخلفت -خلفها الغزو- يحسبوا أنها في الهودج، قالت: \"فلما سمعت صوته خمرت وجهي، وكان قد رآني قبل الحجاب، فعرفني، فلما سمعت صوته خمرت وجهي\" فدل ذلك على أن نزول الحجاب يقتضي تخمير الوجه، وأنه يخمر. وفي السنن عنها -رضي الله عنها- أنهن كن في حجة الوداع إذا دنا منهن الرجال سدلت إحداهن جلبابها على وجهها، فإذا بعدوا كشفت. هذا يدل على أن الوجه مما يستر ومن الزينة التي يجب أن تستر، وهي أعظم زينة المرأة تعرف بوجهها، إن كانت دميمة قيل: دميمة، وإن كانت جميلة قيل: جميلة من وجهها، فهو أعظم الزينة وأعظم من اليد، وأعظم من الرجل، وأعظم من الساق، وأعظم من الشعر، فإذا وجب ستر الشعر فستر الوجه من باب أولى. أما الحديث الذي يحتج به بعض دعاة السفور، وهو حديث عائشة في قصة أسماء بنت أبي بكر -رضي الله عنها- أنها دخلت على النبي ﷺ في بيت عائشة، وعليها ثياب رقاق، فأعرض عنها النبي ﷺ ثم قال: يا أسماء، إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه، رواه أبو داود، وفي بعض الروايات عند غير أبي داود: \"وأشار إلى نصف الساعد\" هذا حديث ضعيف لا يصح عن النبي ﷺ، بل هو ضعيف وباطل من عدة أوجه: الوجه الأول: أن الراوي له عن عائشة هو خالد بن دريك، وهو منقطع، لم يسمع منها، كما قال أبو داود -رحمه الله- وغيره، والمنقطع لا حجة فيه. الثاني: أنه من رواية سعيد بن بشير، وهو ضعيف لا يحتج بروايته. الثالث: أنه من رواية قتادة بالعنعنة، وقتادة مدلس، ولا تقبل روايته إذا دلس إلا إذا صرح بالسماع، إلا فيما جاء في الصحيحين، فروايته في الصحيحين معروفة ومنتقاة. الرابع: لو صح لكان محمولًا على حال النساء قبل الحجاب، كن يبدين وجوههن وأيديهن قبل نزول الحجاب، ثم أنزل الله الحجاب، فمنعن من ذلك. خامسًا: في متنه ما يدل على نكارته؛ لأن في الحديث: أن عليها ثيابًا رقاقًا، فهل يليق بـأسماء أن تدخل على النبي ﷺ في ثياب رقاق، زوج أختها، وهي امرأة من أصلح النساء، زوجة الزبير بن العوام، هذا لا يمكن أن يقع من أسماء، بل دينها وخلقها وعفتها وإيمانها يمنعها من هذا، أن تدخل على النبي ﷺ في ثياب رقاق لا تسترها، فلا يجوز أن يظن هذا بـأسماء -رضي الله عنها وأرضاها-. فهذه وجوه خمسة، كلها تدل على عدم صحة الاحتجاج بهذا الحديث، وتدل أربعة منها على عدم صحته، وأنه غير صحيح، والخامس لو صح لكان محمولاً على ما قبل الحجاب، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13711/حكم-كشف-الوجه-على-ابناء-العمومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49701.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15222,"question":"سؤاله الأخير يقول: إذا كنت قد حذرت بعض الناس من أشخاص الذين يقولون: نحن أبناء مشايخ، أو أبناء أولياء، ويعتقدون أن أبناء الصالحين وهم أحياء، هل أكون مغتابًا أو نمامًا؛ لأن الآية تقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا[الحجرات:12]؟الشيخ: أعد.المقدم: يقول: إذا كان قد حذرت الناس من أشخاص الذين يقولون: نحن أبناء مشايخ، أو أبناء أولياء، ويعتقدون أبناء الصالحين وهم أحياء، هل أكون مغتابًا أو نمامًا؛ لأن الآية تقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا[الحجرات:12]؟","title":"هل التحذير ممن يعتقدون في أبناء الصالحين من الغيبة؟","answer":"الجواب: ويعتقدون أبناء الصالحين؟\nالمقدم: إي: نعم، يعتقدون في أبناء أنهم من أبناء الصالحين، وأنهم....\nالشيخ: على كل حال الدين النصيحة، يقول النبي ﷺ: الدين النصيحة فإذا رأيت من بعض الناس ميلًا عن الحق، ودعوة إلى الباطل، سواء كانوا يسمون مشايخ، أو يسمون أولياء، أو كانوا ينسبون إلى مشايخ وأولياء، فإنك تحذر إخوانك من هؤلاء؛ لئلا يضلوهم، وهذا ليس من باب الغيبة، ولا من باب النميمة، ولكنه من باب النصيحة لله ولعباده، فالناصح لا يسمى مغتابًا، والنبي ﷺ لما جاءته فاطمة بنت قيس تقول: «يا رسول الله، إنه خطبني فلان، وخطبني فلان، نصحها، وقال لها: أما فلان فلا يضع عصاه عن عاتقه يعني: ضرابًا للنساء وأما فلان فصعلوك لا مال له فنصحها، ولم يكن هذا غيبة، مع أنه سماهم، قال: فلان وفلان، معاوية وأبو جهم. فالمقصود: أن الرسول ﷺ نصحها، وبيَّن لها أن هذين الرجلين لا يصلحان لها، وأشار عليها بأسامة بن زيد، فدل ذلك على أن الناصح لا يسمى مغتابًا ولا نمامًا، يقول لك: لا تقرب فلانًا، لا تجالس فلانًا؛ لأنه يفعل كيت وكيت، وأخشى عليك منه، فلا حرج في هذا إذا كان المقصود النصيحة والخوف عليه من الشر، نعم.","link":"https://binbaz.org.sa/fatwas/13723/هل-التحذير-ممن-يعتقدون-في-ابناء-الصالحين-من-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_668/nour_66805.mp3","categories":["الأخلاق المذمومة"]},{"id":15341,"question":"في ثاني أسئلة هذا السائل يقول: سماحة الشيخ، هل يجوز أن نجالس قرناء السوء، وإن كان البعض يصلي منهم، ولكنهم لن ينتهوا عن بعض الأمور المخالفة كالسب والكذب والضحك الذي يكون سببه الافتراءات؟ هل يجوز أن نخالط مثل هؤلاء؟","title":"ما حكم مجالسة قرناء السوء؟","answer":"الجواب: لا يجوز أن تخالط مثل هؤلاء، هؤلاء مجالستهم داء عظيم، شر كبير، لا تجوز لك مخالطتهم، بل احذرهم، إلا إذا أردت أن تنصحهم، تمر عليهم تنصحهم، تحذرهم من هذا، ثم تغادر، أما الجلوس معهم وصحبتهم لا، لا تجوز؛ لأن هذا يضرك كثيرًا في دينك، نسأل الله العافية، نعم.","link":"https://binbaz.org.sa/fatwas/13843/ما-حكم-مجالسة-قرناء-السوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56617.mp3","categories":["الأخلاق المذمومة"]},{"id":15427,"question":"تقول هذه السائلة: امرأة علمت بمصيبة لي وذهبت تنشرها بين النساء وبين الناس، فهل يجوز أن أنتقم لنفسي بفضحي ونشر عيوبها وتخريب بيتها؟ وهل يجوز لي ذلك؟","title":"حكم مقابلة السيئة بسيئة مثلها","answer":"الجواب: لا يجوز لك ذلك، لكن تنصح، ويبين لها أن هذا لا يجوز، وإذا ظلمك لا تظلمها، وإذا اغتابت لا تغتبها، وهكذا، ولكن تنصحها، وتنظر من ينصحها، ويوجهها إلى الخير، ويعلمها أن هذا منكر، وأنه لا يجوز، ولكن لا تعاقبها بنشر بعض مساويها؛ لأن نشر المساوي من الغيبة، والله حرم الغيبة ، ومن أسباب الفتنة والشر العظيم، والعداوة الكثيرة، فإذا ظلمتك فلا تظلمها أنت، ولكن تدعو الله لها بالهداية، وتنصحها، وتدعو بعض إخوانك الذين يؤثرون عليها إلى نصيحتها، وكف لسانها، نعم.  وإن أردت العقوبة فلا بأس، إن أردت أن تطلب العقوبة من المحكمة بأن تجازى على فعلها، فلا بأس. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13940/حكم-مقابلة-السيىة-بسيىة-مثلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50008.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":15439,"question":"له سؤال آخر يقول: عندي فتاة لم تتزوج، وقد استغل أخ لي اسم هذه الفتاة في عمل عقد زواج مزور، وقد شهد في العقد شاهدا زور، بأن الفتاة قد عقد قرانها على ابنه؛ وذلك لاستغلال هذا العقد المزور في رفع راتب ابنه، وقد تم هذا العمل المزور، وقد طلبت من أخي والشهود الزور الاحتكام إلى شرع الله، ولكنهم رفضوا ذلك، فما حكم الشرع في هذه المسألة؟جزاكم الله خيرًا.","title":"حكم تزوير عقد نكاح لرفع الراتب","answer":"الجواب: هؤلاء يرفع أمرهم إلى ولاة الأمر، إلى ولي الأمر في البلد؛ ليعاقبهم بما يستحقون، يرفع أمرهم إلى ولي الأمر؛ لأن هذه جريمة عظيمة.  فالواجب رفع أمرهم إلى ولي الأمر إلى المحكمة أو الأمير حتى يعاقبوا بما يستحقون، والنكاح باطل، هذا العقد باطل وفاسد لا يعول عليه ما دام زورًا، كذبوا عليها وعلى وليها فهو باطل، لكن يرفع أمرهم إلى ولي الأمر في البلد، حتى يعاقب الرجل بما يستحق، ويعاقب الشهود الذين كانوا يعلمون بما يستحقون، يعني: يعاقب هؤلاء، يعني: يعاقب المزور الرجل والشهود الزور يعاقبهم ولي الأمر بما يستحقون من الأدب الرادع، والنكاح باطل الذي صدر عن التزوير باطل، نعم. المقدم: نعم لا عبرة به؟ الشيخ: لاغٍ، والكسب حرام الذي أخذه لرفع الراتب بأسباب دعوى أن ولده تأهل، هذا حرام؛ لأنه أخذه بطريق حرام، نسأل الله العافية. المقدم: جزاكم الله خير الجزاء، ونفع بكم.","link":"https://binbaz.org.sa/fatwas/13971/حكم-تزوير-عقد-نكاح-لرفع-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68606.mp3","categories":["الأخلاق المذمومة"]},{"id":15449,"question":"سماحة الشيخ، يقول السائل محمد عبد الله: البعض من الناس يغضب ويزعل إذا قلت له: ارجع. مع أن الله تعالى يقول: وَإِنْ قِيلَ لَكُمُ ارْجِعُوا فَارْجِعُوا هُوَ أَزْكَى لَكُمْ [النور:28]؟","title":"نصيحة لمن يغضب عند عدم الإذن له بالدخول","answer":"الجواب: ينبغي له أن لا يغضب؛ لأن أهل البيت قد يكونون مشغولين، فإذا لم يأذنوا، أو قالوا: ارجع في وقت آخر، فلا يغضب، هم أعلم بأنفسهم، وإذا سكتوا ولم يجيبوا بعد الاستئذان ثلاثًا يرجع أيضًا؛ لأنهم قد يكونون مشغولين وهو لا يعرف حالهم.  فينبغي له أن يحسن الظن بإخوانه، ولا يكلفهم، وإن صرحوا قالوا: ارجع في وقت آخر، فلا بأس. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13966/نصيحة-لمن-يغضب-عند-عدم-الاذن-له-بالدخول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56808.mp3","categories":["الأخلاق المذمومة"]},{"id":15561,"question":"هذه رسالة من المستمع صالح بن عبد الله بن حمود الضبعان، سؤاله يقول: ما الحكم في رجل مسلم استخرج لزوجته صك ترمل باسم رجل آخر؛ ليصرف لها راتب من الضمان الاجتماعي؟ وما الحكم في الشهود الذين شهدوا في هذا الصك؟","title":"حكم استخراج صك للمتزوجة بأنها مطلقة لأجل الضمان الاجتماعي","answer":"الجواب: إذا كان الواقع هو ما ذكر؛ فهذا منكر، وهو آثم والشهود آثمون، وإن كان أخبر عن طلاق سابق من شخص سابق طلقها ثم تزوجها بعده؛ فهو وإن كان صدق أنها قد طلقت، لكنهم عموا المسألة وأخفوا الحقيقة، فهي طلقت ثم تزوجت، وهي زوجة للذي أخذ لها الصك، فعلى كل حال هو زور ومنكر: إما في الحقيقة وإما في ظاهر الأمر بالنسبة إلى المقصود، فهو تدليس وكذب على المحكمة؛ حتى يحصل لهم مرادهم من المال بغير حق، فعلى كل حال يستحقون عليه العقوبة؛ لأنه منكر وتدليس وتلبيس على المحاكم والدولة، وهذا المال لا يجوز؛ لأنه أخذ بغير حق بطريق غير شرعي. نعم.\nالمقدم: أيضًا له سؤال آخر يقول: ما الحكم في رجل مسلم يقدم على استخراج صك طلاق لزوجته باسم رجل آخر وهي في ذمته؛ ليصرف لها معاش أيضًا من الضمان الاجتماعي شبيه بالأول ..؟\nالشيخ: مثلما تقدم كله منكر، كله منكر والمال حرام الذي صرف لها بهذا الصك المزور. نعم.\nالمقدم: أيضًا له بقية أسئلة شبيهة به يقول: ما حكم امرأة طلقت وتزوجت رجلًا آخر وبعد مدة طويلة طلبت من زوجها الأول صك طلاق لتحصل على معاش من الضمان الاجتماعي، رغم أنها لا زالت في ذمة الرجل الحالي مع العلم..\nالشيخ: مثلما تقدم، وإن كان حقًا في نفس الواقع أنها مطلقة، لكنها أخفت الحقيقة من كونها مزوجة بعد ذلك، فهذا منكر ملبس فيه، فيه حيلة وخداع. نعم، نسأل الله العافية، لا حول ولا قوة إلا بالله، نعوذ بالله، أخذ المال بغير حق أمر منكر وسحت، فنسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/14101/حكم-استخراج-صك-للمتزوجة-بانها-مطلقة-لاجل-الضمان-الاجتماعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70308.mp3","categories":["الطلاق","الأخلاق المذمومة"]},{"id":15576,"question":"سؤالها الآخر تقول: هل تحتجب المرأة عن خال زوجها وعمه، حيث سمعت من بعض العلماء أن معنى قوله تعالى في آية الحجاب: أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] أن آباء المرأة تشمل الأب والجد وعمها وخالها، فهل آباء بعولتهن تشمل أيضًا أبا البعل وجده وعمه وخاله؟","title":"هل تحتجب المرأة عن خال زوجها وعمه؟","answer":"الجواب: لا، الخال والعم ليسا محرمين، بل ليس لها أن تكشف لعم الزوج، ولا لخال الزوج، ولا لأخي الزوج، وهو أقرب أيضًا، وإنما قوله : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ[النور:31] هذا يعم الآباء والأجداد، ولا يدخل فيه الأعمام ولا الأخوال، والذي قال: إنهما داخلان غلط، قد غلط في ذلك، وإنما الآباء هم الأب والجد وإن علا، هؤلاء هم الآباء، فأما العم عم الزوج وخاله وأخوه فهم أجانب، وليسوا بمحارم، فليس لها أن تكشف لهم، بل عليها أن تحتجب وليسوا محارم لها، لا الخال ولا العم ولا أخو الزوج جميعًا، نعم.\nالمقدم: جزاكم الله خيرًا.\nالشيخ: وإنما محرمها أبو الزوج وجد الزوج وابن الزوج وابن ابنه وابن بنته هؤلاء محارم، أبو الزوج وأجداده من جهة الأب ومن جهة الأم هؤلاء محارم، وكذلك أولاد الزوج وأولاد أولاده وأولاد بناته كلهم محارم لزوجته. نعم.","link":"https://binbaz.org.sa/fatwas/14117/هل-تحتجب-المراة-عن-خال-زوجها-وعمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69202.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15680,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض، وباعثتها مجموعة من الأخوات هن: (ن. م. صالح ) الأخوات يسألن هذا  يقول  متى تحتجب المرأة عن الصبيان؟ أي: كم هو عمر الصبي الذي يجب على المرأة أن تحتجب منه؟جزاكم الله خيرًا.","title":"كم عمر الصبي الذي تحتجب منه المرأة؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد قال الله -جل وعلا-: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ [النور:59]. ويقول النبي ﷺ: إنما جعل الاستئذان من أجل النظر.\nفالاحتجاب يكون بعد البلوغ، متى بلغ الصبي خمسة عشر سنة، أو عرف أنه احتلم، أو أنبت الشعر الخشن الذي حول الفرج، صار بهذا محتلمًا، ووجب عليه الاستئذان، ووجب التحجب عنه. ولكن ينبغي للمرأة أن تحتاط، فإذا كان مراهقًا قد قارب سن الاحتلام فلتحتط، ولتحتجب منه، وليس لها الخلوة به؛ بعدًا عن الشبهة، وحذرًا من الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14229/كم-عمر-الصبي-الذي-تحتجب-منه-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57201.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15706,"question":"هذه السائلة: أم سليمان تقول في هذا  أرجو إجابتي على هذا السؤال إجابة واضحة، من سماحة الشيخ، وهو يتعلق بمٍسألة الركوب مع السائق بدون محرم، بغرض إيصالي إلى مقر عملي، مع أن عملي داخل المدينة التي أسكن فيها، ولا تعتبر المسافة بين منزلي ومقر عملي سفر؛ ولقد اجتهدت في إيجاد سائق بمحرم، ولكنني لم أجد إلا بمبالغ كبيرة من الصعب أن أدفعها، مع العلم بأنني بحاجة للوظيفة، حيث أنني أصرف على أولادي، هل يجوز ذلك يا سماحة الشيخ؟","title":"حكم ركوب المرأة مع السائق الأجنبي","answer":"الجواب: يقول النبي ﷺ: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما وركوب المرأة مع السائق وحده فيه خطر عظيم مع الخلوة، خطر عظيم مع الخلوة فلا يجوز، فعليها أن يكون معها زوجة السائق، أو امرأة أخرى ثقة تكون معها تذهب معها، وترجع معها، تذهب معها، وتبقى معها في المدرسة حتى ترجع معها، أو ثنتين يذهبن معها، ثم يرجعان، ثم يأتيان مع السائق، ثنتان، أو واحدة تبقى معها في المدرسة، أو في محل عملها، ثم ترجع معها، ولا تخل بالسائق؛ لأن الرسول ﷺ نهى عن ذلك، وحذر من ذلك؛ ولما فيه من الخطورة، الرسول ﷺ قال: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما وفق الله الجميع، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14264/حكم-ركوب-المراة-مع-الساىق-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57315.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15756,"question":"تسأل سماحتكم وتقول: هل يجوز لي أن أسلم مع أقاربي، وأتكلم معهم، وأنا محتجبة، وكاشفة لوجهي، وكفي فقط، بحضور زوجي، أو بحضور عدة نساء كحماتي أو عمتي أو حماي وغير ذلك؟أفيدونا مأجورين.","title":"حكم اختلاط المرأة بأقاربها مع وجود المحرم","answer":"الجواب: لا مانع من التحدث معهم، وسماع أقوالهم، والمشاركة في الخير، والحديث المباح؛ لكن مع الحجاب للوجه والكفين، وجميع البدن، عليك بالحجاب، ولا بأس بالجلوس معهم، والاستماع لحديثهم، والمشاركة في الحديث، والسلام، والكلام كله لا بأس به، لكن من دون (ترك) حجاب، ومن دون مصافحة لغير المحرم، والله يقول -جل وعلا-: قُلْ أَطِيعُوا اللَّهَ وَالرَّسُولَ[آل عمران:32] فالواجب طاعة الله ورسوله في جميع الأحوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14350/حكم-اختلاط-المراة-باقاربها-مع-وجود-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74109.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15761,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الإمارات العربية المتحدة، تقول: أختكم زبيدة باكستانية، مقيمة في الإمارات، أختنا لها رسالة تقول فيها: سماحة الشيخ عبدالعزيز بن عبدالله بن باز! السلام عليكم ورحمة الله وبركاته، وبعد:سماحة الشيخ، باسمي وباسم المسلمين أشكر سماحتكم على ما تبذلونه من جهود في خدمة الإسلام، وتبصير المسلمين بأمور دينهم ودنياهم، وأحيطكم علمًا بأنني أقرأ كتبكم بكثرة، حيث أن مكتبة والدي تزخر بكتبكم القيمة، نفعنا الله بها، آمين.والآن أعرض على سماحتكم السؤال التالي: تعلمون سماحتكم أنه من الصعب جدًا أن يتخلى المرء عن عاداته وتقاليد بلده، وإنه توجد في بلدنا عادات، وهي أن المرأة في بيت زوجها تجد الحمو ووالد زوجها، وبقية إخوان الزوج ووالدته وأخواته، وكما تعلمون سماحتكم أن الحمو لا يجوز كشف الوجه له، وسؤالي هو: ماذا أفعل في مثل هذه الحالة؟ وهل عليّ أن لا أضع كحلاً، ولا ألبس إلا الملابس التي لا تكون زينة في حد ذاتها، علمًا بأن زوجي لا يستطيع أن يبني بيتًا آخر، ولأن أهله لا يرضون بذلك، وهو أيضًا لا يريد أن يعيش إلا مع إخوانه ووالده ووالدته؟أفيدونا، جزيتم عنا وعن الإسلام خيرًا.","title":"توجيه للمرأة التي تعيش مع إخوة زوجها","answer":"الجواب: الواجب عليك تقوى الله، وأن تحتجبي عن حميك، وعن جميع الأحماء، وأن تصبري في ذلك، وتتقي الله -جل وعلا-، ولا حرج عليك في ذلك، والحمد لله، على زوجك وعلى أهل زوجك أن يعذرك؛ لأنك عملت الأمر المشروع، والله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53]. فالواجب عليك الحجاب والتستر عن الأحماء عند الاجتماع بهم، مع الكلام الطيب، والسلام عليهم بالكلام، لكن مع الحجاب والتستر، وعدم المصافحة إلا لمحرم، ومن استعان بالله، وصدق أعانه الله، ويسر أمره وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا[الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا[الطلاق:4]. والواجب على زوجك وعلى أبيه وعلى جميع الحمو أن يعذروك في الحجاب؛ لأنك أطعت الله، وابتعدت عن الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14349/توجيه-للمراة-التي-تعيش-مع-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74108.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15783,"question":"تقول: هل أحتجب عن أبناء أخت زوجي؟","title":"هل تحتجب المرأة عن أبناء أخت زوجها؟","answer":"الجواب: نعم، أبناء أخت الزوج أجانب، وهكذا إخوانه أيضًا، إخوانه وأعمامه كلهم أجانب، عليك الاحتجاب، وأن لا تخلي، ولا يحصل خلوة بأحد منهم، المحرم أبو الزوج وجده وأولاده، أما أبناء أخي الزوج، أو إخوان الزوج، أو أعمام الزوج، هؤلاء أجانب، ليسوا محارم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14372/هل-تحتجب-المراة-عن-ابناء-اخت-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74209.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":15894,"question":"يسأل سماحتكم عمن يسب المواشي إذا كان راع لها هل يكون آثمًا؟","title":"حكم سب المواشي","answer":"الجواب: نعم، لا يجوز سب المواشي، لا الإبل ولا البقر ولا الغنم ولا غيرها، لا يجوز سبها، الرسول ﷺ لما سمع امرأة سبت ناقة لها قال: لا تصحبنا ناقة ملعونة. فالمقصود: أن سب المواشي لا يجوز، والرسول  يقول: إن اللعانين لا يكونوا شهداء ولا شفعاء يوم القيامة فالواجب الحذر من سب المواشي، كما يجب الحذر من سب بني آدم بغير حق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14487/حكم-سب-المواشي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74514.mp3","categories":["الأخلاق المذمومة"]},{"id":15911,"question":"من أسئلة هذا السائل يقول -يا سماحة الشيخ-: أنا وأخي بيننا خصام من عدة سنوات، وعندما أمشي في الطريق أقول لأخي: السلام عليكم، ولم يرد علي السلام، وهذه عدة مرات، وقد تصالحنا عدة مرات، ولم ينفع هذا الصلح معه، وأنا أقول: بأن هذا السلام من قلبي وليس مجاملة أمام الناس، وأخي لا يصلي في المسجد، ويعمل بعض المنكرات، ماذا يجب علي تجاهه؟","title":"حكم قطعية الأخ لأخيه","answer":"الجواب: الواجب عليك نصيحته، وأمره بالمعروف، ونهيه عن المنكر؛ لعل الله يهديه بأسبابك، وإذا تيسر أن يكون معك شخص آخر أو اثنان من الأقارب أو الأصدقاء تذهبون جميعًا إليه، وتنصحونه وتوجهونه إلى الخير، فهذا خير؛ لأنه قد ينتفع بذلك إذا كان معك غيرك ممن يعينك على نصيحته؛ لأن الله يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. فالمؤمنون أولياء، ومن ولايتهم فيما بينهم أنهم يأمرون بالمعروف، وينهون عن المنكر، فلا تهجره، بل اجتهد في نصيحته وتوجيهه إلى الخير ولو هجرك، يقول النبي ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها. فأنت اجتهد في وصله، والإحسان إليه ونصيحته وتوجيهه إلى الخير؛ لعل الله يهديه، لعل الله يرده إلى الصواب، ولعل الله يهديه لترك المنكرات، وليكن معك من يعينك على ذلك ويساعدك لعله يقبل منكم جميعًا، ولعله يتعظ، فإذا لم تجد الموعظة، واستمر على المجاهرة بالمنكرات استحق الهجر، استحق أن يهجر. أما إذا كانت معصية خفية فيما بينه وبين نفسه، وأهل بيته داخل، وليست معصية ظاهرة، فلا تهجره، واجتهد في نصيحته وتوجيهه إلى الخير جزاك الله خيرًا، وأبشر بالخير، وادع له بظهر الغيب أن الله يهديه، وأن الله يعيذه من شر نفسه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14503/حكم-قطعية-الاخ-لاخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57710.mp3","categories":["الأخلاق المذمومة"]},{"id":15912,"question":"من اليمن السائل في آخر أسئلته يقول: سماحة الشيخ، ما معنى هذا الحديث في رواية لـأبي داود قال النبي ﷺ: لا يحل لمؤمن أن يهجر أخاه فوق ثلاث، فإن مرت به ثلاث فليلقه فليسلم عليه، فإن رد عليه السلام فقد اشتركا في الأجر، وإن لم يرد عليه فقد باء بالإثم؟","title":"معنى حديث: «لا يحل لمؤمن أن يهجر...»","answer":"الجواب:   ثبت في الصحيحين عن النبي ﷺ أنه قال: لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا، ويعرض هذا، وخيرهما الذي يبدأ بالسلام هكذا ثبت في الصحيحين خيرهما الذي يبدأ بالسلام فليس له أن يهجر أخاه فوق ثلاث لا يزوره ولا يكلمه، إلا إذا كان هجره له من أجل إظهاره المعاصي، فمن أظهر المعاصي يستحق الهجر، نسأل الله السلامة، نعم. \nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14504/معنى-حديث-لا-يحل-لمومن-ان-يهجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57711.mp3","categories":["شروح الحديث","الأخلاق المذمومة"]},{"id":16043,"question":"تقول: لي زميلة متزوجة، وتأتي إلينا هي وزوجها، ونجلس سويًا مع أنني ألتزم باللباس الشرعي، فهل علي إثم في ذلك؟","title":"شروط جلوس المرأة مع الأجنبي","answer":"الجواب: لا حرج إذا جلست مع أهلك، وبعض جيرانك وزوج جارتك، وأنت مستورة متحجبة في الوجه وغيره للحديث، وسماع الحديث؛ فلا بأس، لكن لا يخلو بك، لا تجلسي معه وحدك مع غير محرمك، لا مع الجار، ولا مع غير الجار. أما إذا كانوا جماعة؛ جلست معهم؛ جلسوا يتقهوون معكم، يتحدثون معكم؛ فلا حرج في ذلك، المحرم الخلوة، أو التكشف، أما إذا كان الحجاب موجودًا، والتستر موجودًا، وليس هناك خلوة؛ فلا حرج لسماع الصوت، والكلام، والتحية، والسلام، ونحو ذلك من دون مصافحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! بعض الناس يعتبرون أن غطاء ما عدا الوجه والكفين يعتبر حجابًا شرعيًا، فما هو توجيهكم لهم؟ الشيخ: لابد، مثلما تقدم، لا يكون حجابًا إلا بالوجه والكفين، لا بد من الكمال، تستر الرأس، والأيدي، والأرجل، كل شيء، تكون المرأة مستورة إلا العينين؛ فلا بأس أن تلبس النقاب الذي فيه خرق للعين، أو العينين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14675/شروط-جلوس-المراة-مع-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74807.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16074,"question":"من سلطنة عمان رسالة بعثت بها إحدى الأخوات من هناك تقول المرسلة (م. م)، لها سؤالان.في سؤالها الأول تقول: سمعت بعض الناس يقولون: إنه عند الانتهاء من قص الأظافر لابد من أخذها، ودفنها في مكان، وقراءة بعض السور عليها مثل الإخلاص، والمعوذتين، وعدم رميها، فما حكم ذلك؟ جزاكم الله خيرًا.","title":"حكم دفن الأظافر بعد قراءة القرآن عليها","answer":"الجواب: هذا شيء لا أصل له، إذا قص الإنسان أظفاره يرميها، ولا بأس، ولا حاجة إلى دفنها، ولا قراءة قرآن عليها، كل هذا خرافة لا أصل لها، ولا أساس لها، متى قص الإنسان أظفاره رجل، أو امرأة؛ فلا حرج في إلقائها في أي مكان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14707/حكم-دفن-الاظافر-بعد-قراءة-القران-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80302.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":16076,"question":"يقول: ما حكم سب البهائم، حيث أني شاهدت من يفعل ذلك، وخاصة عندما ينهمك، ويتعب معها وهو يسبها من غير شعور كما يقول، وبعضهم يسب في الحلال باللعن وغيره؟ جزاكم الله خيرًا.","title":"هل يجوز سب البهائم ولعنها؟","answer":"الجواب: سب البهائم لا يجوز، وهكذا سب الجمادات النبي ﷺ يقول: إن اللعانين لا يكونون شهداء، ولا شفعاء يوم القيامة وفي الحديث يقول ﷺ: ليس المسلم بالطعان، ولا اللعان، ولا الفاحش، ولا البذيء وثبت عنه ﷺ أنه سمع امرأة تسب ناقة -تلعنها- فأمر أن يقام عليها، وقال: لا تصحبنا ناقة ملعونة. فالواجب على المسلم أن يحفظ لسانه عن السب للبهائم، أو لأولاده، أو لغيرهم. أما سب الكفار على العموم، أو الظالمين، أو الفساق؛ فلا حرج، إذا قال: لعن الله الظالمين، لعن الله الكافرين، لعن الله الفاسقين، لعن الله السارق، لعن الله شارب الخمر عمومًا؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14708/هل-يجوز-سب-البهاىم-ولعنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74906.mp3","categories":["الأخلاق المذمومة"]},{"id":16079,"question":"يقول: هناك أناس يتكلمون بالكلام الفاحش، وأنا نصحتهم بتركه، ولكنهم يقولون: هذا مزح، فماذا نقول لهم؟ جزاكم الله خيرًا.","title":"النهي عن المزاح بالكلام المحرم","answer":"الجواب: تقول لهم: إنه لا يجوز المزح بالكلام المحرم، والواجب أن يكون المزح بالكلام المباح، والشيء المباح مع القلة، مع قلة المزح. أما أن يمزح باللعن، أو بالشتم والسب، أو بالكذب؛ فلا يجوز، يقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك به القوم، ويل له، ثم ويل له ويقول ﷺ: لعن المؤمن كقتله وهذا وعيد شديد، ويقول ﷺ: سباب المسلم فسوق، وقتاله كفر فالسب، والشتم، واللعن من الكبائر في أخيه الذي لا يستحق ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14712/النهي-عن-المزاح-بالكلام-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74909.mp3","categories":["الأخلاق المذمومة"]},{"id":16307,"question":"ومع مطلع هذه الحلقة نعود إلى رسالة الأخ عبدالله الصالح من القصيم بريدة، أخونا عبدالله عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له بعض الأسئلة في أحدها يقول: هل يجوز للمرأة أن تركب مع رجل أجنبي في السيارة بدون محرم؛ لقضاء حاجة في السوق، أو الذهاب إلى المدرسة؛ لأن بعض الناس يتهاون في هذا الموضوع، ثم هل ولي أمرها يأثم والحال ما ذكر؟ جزاكم الله خيرًا.","title":"حكم ركوب المرأة مع السائق وحدها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا شك أن ركوب المرأة في السيارة مع السائق من دون ثالث لا يجوز، فهو فيما أعتقد معتبر من الخلوة، ويخشى من عاقبته ما لا تحمد عقباه، فالواجب عليها أن لا تخرج مع السائق إلا ومعها ثالث، امرأة ثالثة، أو رجل ممن يطمأن إليه، ليس فيه ريبة، يكون معها إذا ذهبت إلى بعض حاجاتها، أو إلى المدرسة، هذا هو الواجب، والواجب على الولي ألا يتساهل في هذا، بل يهتم بهذا، ويعتني بهذا، ويلزم موليته بذلك؛ احتياطًا للدين، وحذرًا من سوء العاقبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14996/حكم-ركوب-المراة-مع-الساىق-وحدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81001.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16315,"question":"يقول: يا سماحة الشيخ! أنا أشكو من سرعة الغضب، وعدم التصرف في وقت الغضب، فأرجو من الله، ثم من سماحتكم توجيهي في هذا الأمر، جزاكم الله خيرًا.","title":"كيفية التغلب على الغضب","answer":"الجواب: الرسول ﷺ لما رأى رجلًا قد اشتد غضبه، قال: إني لأعلم كلمة لو قالها لذهب عنه ما يجد: أعوذ بالله من الشيطان الرجيم فإذا غضبت؛ فاجتهد في تكرار: أعوذ بالله من الشيطان الرجيم، كررها واذكر الله، وأبشر بالخير -إن شاء الله- يزول، ولا تعجل في تنفيذ الغضب، واحذر أسبابه قبل ذلك: بالقيام من المجلس الذي فيه اللغط، وأسباب الغضب... بالاشتغال، بالوضوء الشرعي... بقراءة القرآن... بالكلام مع الآخرين في أمور أخرى تشغلك عن هذا الغضب.. إلى غير ذلك. عليك أن تجتهد في العلاج بما تستطيع؛ حتى يهدأ الغضب، وأهم ذلك: التعوذ بالله من الشيطان الرجيم، والإكثار من ذكر الله  وهو سوف يزول الغضب، وإذا تيسر الوضوء، القيام بالوضوء أيضًا الوضوء يطفئ الغضب؛ لأن الغضب من الشيطان، والوضوء يطفئ النار، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15012/كيفية-التغلب-على-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753014.mp3","categories":["الأخلاق المذمومة"]},{"id":16364,"question":"أولى رسائل هذه الحلقة رسالة وصلت من أحد الإخوة المستمعين وقع في نهايتها بقوله: ابنكم مصطفى بابكر حمد، يسأل جمعًا من الأسئلة في أحدها يقول: هل تجوز مصافحة المرأة المسنة من غير المحارم؟","title":"حكم مصافحة الأجنبية الكبيرة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإن الله -جل وعلا- شرع لعباده ما فيه الخير لهم، والعاقبة الحميدة، ونهاهم عما يضرهم، وعما يخشى منه سوء العاقبة، ومن ذلك أنه  نهى عن مصافحة النساء على يد نبيه ﷺ فلا يجوز للرجل أن يصافح المرأة التي ليست محرمًا له، وإن كانت كبيرة السن؛ لأن المصافحة قد تجر إلى ما لا تحمد عقباه، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: إني لا أصافح النساء وهذا يعم العجائز والشباب، وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط -يعني: عند البيعة- ما كان يبايعهن إلا بالكلام\" عليه الصلاة والسلام. قال بعض أهل العلم: إن المصافحة أشد من النظر، وأخطر، فالواجب ترك ذلك مطلقًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15078/حكم-مصافحة-الاجنبية-الكبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81101.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16381,"question":"تقول: هناك عادة عند بعض الناس وهي الغيبة والنميمة، ولا يوجد من ينهى عن هذا المنكر، وأنا أحيانًا أسمعهم وهم يتكلمون في الناس، وأحيانًا أتكلم معهم، لكن أشعر أن ذلك حرام، ثم أندم على عملي هذا، وأتجنبهم، ولكن قد تجمعني بهم بعض الظروف، فماذا أفعل؟ جزاكم الله خيرًا.","title":"التحذير من الغيبة والنميمة","answer":"الجواب:  الغيبة والنميمة كبيرتان من كبائر الذنوب، فالواجب الحذر من ذلك، يقول الله سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] ويقول النبي ﷺ: رأيت -حين أسري بي- رجالًا لهم أظفار من نحاس، يخمشون بها وجوههم، وصدورهم، فقلت: من هؤلاء؟ قيل له: هؤلاء الذين يأكلون لحوم الناس، ويقعون في أعراضهم هم أهل الغيبة، والغيبة يقول ﷺ: ذكرك أخاك بما يكره هذه الغيبة، ذكرك أخاك بما يكره، وهكذا ذكر الأخت في الله بما تكره للرجال والنساء، قيل: يا رسول الله! إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول؛ فقد اغتبته، وإن لم يكن فيه؛ فقد بهته. فالغيبة منكرة، وكبيرة من كبائر الذنوب، والنميمة كذلك، يقول الله -جل وعلا-: وَلا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ ۝ هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ [القلم:10-11] ويقول النبي ﷺ: لا يدخل الجنة نمام ويقول ﷺ: إنه رأى شخصين يعذبان في قبورهما، أما أحدهما فكان لا يستتر من البول، وأما الآخر فكان يمشي بالنميمة. فالواجب عليك أيها الأخت في الله! الحذر من مجالسة هؤلاء الذين يغتابون الناس، ويعملون بالنميمة، وإذا جلست معهم؛ فأنكري عليهم ذلك، وحذريهم من مغبة ذلك، وأخبريهم أن هذا لا يجوز، وأنه منكر، فإن تركوا وإلا فقومي عنهم لا تجلسي معهم، ولا تشاركيهم في الغيبة، ولا في النميمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15087/التحذير-من-الغيبة-والنميمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81105.mp3","categories":["الأخلاق المذمومة"]},{"id":16392,"question":"رسالة من أحد الإخوة المستمعين يسأل فيها عن قضية وقع فيها يقول: حاولت المجيء إلى المملكة، ولكني لم أجد إلا بعد تغيير اسمي إلى اسم شخص آخر، وحينئذ حصلت على التأشيرة؛ وأتيت إلى المملكة بهذا الاسم، وتزوجت، ورزقني الله بطفل على إثر ذلكم المجيء، ما حكم ما فعلت؟ وجهوني جزاكم الله خيرًا.","title":"حكم تغيير الشخص اسمه للحصول على أمر ما","answer":"الجواب: الكذب لا يجوز، وهذا العمل من الكذب، وانتحال شخصية أخرى، والانتساب إلى غير أب الإنسان محرم، ومن الكبائر، فليس لك هذا العمل، ولا يجوز لك هذا العمل، والواجب أن تخبر أهل الزوجة بالحقيقة؛ حتى يكونوا على بينة، وعلى بصيرة، وأن تغير الذي معك من جواز، أو من إقامة، أو غيرها على الحقيقة، وليس لك أن تعمل هذا العمل مستقبلًا.  يقول النبي ﷺ في الحديث الصحيح.. تقول أم كلثوم -رضي الله عنها- عن النبي ﷺ في الحديث الصحيح: ليس الكذاب الذي يكذب فيصلح بين الناس، فينمي خيرًا، ويقول خيرًا ليس الكذاب الذي يصلح بين الناس، فيقول خيرًا، وينمي خيرًا ثم قالت: \"ولم أعلمه يرخص، أو قالت: ولم أره يرخص في شيء من الكذب إلا في ثلاث: الإصلاح بين الناس، وحديث الرجل امرأته، والمرأة زوجها، وفي الحرب\". فالمقصود: أن الكذب منكر محرم، الرسول ﷺ يقول: إياكم والكذب، فإن الكذب يهدي إلى الفجور، والفجور يهدي إلى النار، وعملك هذا ليس من الثلاث التي رخص فيها النبي، عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15103/حكم-تغيير-الشخص-اسمه-للحصول-على-امر-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75419.mp3","categories":["الأخلاق المذمومة"]},{"id":16557,"question":"من جمهورية مصر العربية المستمع (ح. س.م) رسالة وضمنها جمعًا من الأسئلة في أحدها يقول: ما حكم من يعد ويخلف، ويستغل الناس؟","title":"التحذير من إخلاف الوعد","answer":"الجواب: هذه الخصلة من خصال أهل النفاق، فالواجب الحذر منها، يقول النبي ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا أؤتمن خان فالواجب على المسلم أن يحذر هذه الصفات الذميمة، وأن يبتعد عنها، وأن يتوب إلى الله مما سلف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15301/التحذير-من-اخلاف-الوعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81613.mp3","categories":["الأخلاق المذمومة"]},{"id":16559,"question":"من جازان المرسلة حليمة بعثت برسالة، وضمنتها سؤالين، في سؤالها الأول تقول: أنا -ولله الحمد- امرأة ملتزمة، ومحافظة، ولكن لي ولد عم قد بلغ من الكبر كثيرًا، وهو رجل أعمى، حيث أن عمره يناهز السبعين، فهل في الكلام معه، والسلام عليه إثم علي؟ جزاكم الله خيرًا.","title":"ما حكم سلام المرأة وكلامها مع غير المحارم؟","answer":"الجواب: ليس في الكلام معه، والسلام عليه إثم، بل هذا من صلة الرحم، ولا بأس أيضًا بالكلام مع غيره حتى لو كان أجنبيًا إذا لم يكن هناك شر، ولا فتنة، ولا خلوة، فالمسلمة تسلم على أقاربها، وإن كانوا ليسوا محارمًا، تسلم على جيرانها، وأخي زوجها، ونحوهم، من دون خلوة، ومن دون تعاطي أمور توجب التهمة.  فإذا كانت الأمور واضحة، ليس فيها تهمة، فالسلام حق على ابن عمك وعلى غيره من دون خلوة، ولكن من دون مصافحة بالكلام، كيف حالك، السلام عليكم، وعليكم السلام، كيف حالكم، كيف الأهل والأولاد، كل هذا لا بأس به، من دون مصافحة، ولا تقبيل كما يفعل بعض الجهلة، لا.  المصافحة تكون مع النساء، أو مع المحارم كالأخ والعم، أما مع الأجنبي سلام بدون مصافحة، بدون تقبيل رأس، ولا غيره، بدون خلوة، فإذا سلمت عليه بحضرة من يزيل الخلوة أمك، أو أختك، أو أخيك، أو غير ذلك، المقصود بدون خلوة يكون معكم ثالث، وبدون ريبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15291/ما-حكم-سلام-المراة-وكلامها-مع-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81606.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16562,"question":"ما جزاء الراشي، والمرتشي؟","title":"عقوبة الراشي والمرتشي","answer":"الجواب: الراشي، والمرتشي قد أتيا كبيرة عظيمة، في الحديث الصحيح أن الرسول ﷺ: لعن الراشي والمرتشي. والرشوة: بذل المال لمن يعمل لك ما يخالف الأمر الشرعي، ما يخل بالأمانة، والقابل للرشوة هو الذي يفعل ما حرم الله عليه من أجل الرشوة، كأن يعطيك ما ليس بحق لك، أو يقدمك على من هو أولى منك من أجل الرشوة، أو يخبر بأنك مواظب على العمل، وأنت لست مواظبًا على العمل من أجل الرشوة، ونحو ذلك، فالمال الذي يبذل في خلاف الحق آخذه ظالم، وباذله كذلك، ويعتبران متعاونين على الإثم والعدوان. نسأل الله العافية.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15302/عقوبة-الراشي-والمرتشي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81614.mp3","categories":["الأخلاق المذمومة","الكسب المحرم"]},{"id":16566,"question":"يسأل عن جزاء من يحقد على الناس، ويكره الخير للغير؟","title":"التحذير من الحقد والحسد","answer":"الجواب: عليه التوبة إلى الله، عليه التوبة إلى الله، الواجب على المسلم أن يحب الخير لإخوانه، ويكره لهم الشر، ولا يجوز له أن يحقد على أحد بغير الحق، ولا أن يحسده، ولا أن يحب له السوء، يقول النبي ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه. الواجب على المسلم أن يحب لإخوانه الخير، والهدى، والصلاح، وأن يكره لهم كل شر، وألا يحقد عليهم، ومن وجد من نفسه أنه يكره الخير لإخوانه فهذا مرض في قلبه، فعليه التوبة إلى الله من ذلك.","link":"https://binbaz.org.sa/fatwas/15304/التحذير-من-الحقد-والحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81615.mp3","categories":["الأخلاق المذمومة"]},{"id":16575,"question":"من جمهورية مصر العربية المستمع (ح. س.م) رسالة وضمنها جمعًا من الأسئلة في أحدها يقول: ما حكم من يعد ويخلف، ويستغل الناس؟","title":"التحذير من إخلاف الوعد","answer":"الجواب: هذه الخصلة من خصال أهل النفاق، فالواجب الحذر منها، يقول النبي ﷺ: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا أؤتمن خان فالواجب على المسلم أن يحذر هذه الصفات الذميمة، وأن يبتعد عنها، وأن يتوب إلى الله مما سلف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15301/التحذير-من-اخلاف-الوعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81613.mp3","categories":["الأخلاق المذمومة"]},{"id":16660,"question":"مجموعة من الأخوات بعثن بمجموعة من الأسئلة يقلن: السلام عليكم ورحمة الله وبركاته، سماحة الشيخ: هل يجوز الكذب؛ خوفًا من العين، كأن تقول الفتاة: بأن تقديرها جيد جدًا في نتائج الامتحانات، وتقديرها ممتاز في الشهادة، خوفًا من العين؟","title":"حكم الكذب خوفًا من العين","answer":"الجواب: لا تكذب، هذا كذب، تبين الواقع ولا حرج، والحمد لله، تعتمد على الله، ولا يضرها، تعتمد على الله، وتقول: أعوذ بكلمات الله التامات من شر ما خلق وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ [الطلاق:3] لا يضرها، تترك الهواجس من عين، وما العين، الإنسان يسأل ربه، يقول: أعوذ بكلمات الله التامات من شر ما خلق صباحًا ومساءً ثلاث مرات، ولا يضره شيء والحمد لله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15393/حكم-الكذب-خوفا-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58317.mp3","categories":["الأخلاق المذمومة"]},{"id":16664,"question":"سماحة الشيخ هذه سائلة رمزت لاسمها بـ (ر. ب. ك. العرفجي) تقول: ما حكم ركوب امرأتين، أو أكثر مع سائق النقل بدون محرم، وذلك للضرورة، مع كونهن متحجبات، ومتسترات بالحجاب الشرعي، وذلك مثل نقل مدرسات أو طالبات، مأجورين؟","title":"حكم ركوب أكثر من امرأة مع سائق أجنبي","answer":"الجواب: إذا كان الركوب مع السائق في غير سفر، في البلد، فلا بأس، إذا كن ثنتين، أو أكثر لا حرج، المحرم الخلوة إذا كان وحدها، أما إذا كانوا ثنتين، أو ثلاثًا، أو أكثر، وليس هناك تهمة؛ فلا حرج في ذلك.  أما السفر لا، لا تسافر إلا مع محرم، والواحدة لا تركب مع السائق الأجنبي، ولو في البلد، لأن هذه خلوة، والرسول ﷺ يقول: لا يخلون رجل بامرأة فإن الشيطان ثالثهما. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/15397/حكم-ركوب-اكثر-من-امراة-مع-ساىق-اجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58321.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16665,"question":"من أسئلتها تقول: هل يجوز للمرأة أن تجلس مع حماها إذا اضطرت إلى ذلك، وتكون هذه المرأة متغطية، وعليها الحجاب الذي يغطي الرأس، وجميع جسمها؟","title":"حكم جلوس المرأة مع عم أو أخي زوجها","answer":"الجواب: نعم، لها أن تجلس مع أخي زوجها، وعم زوجها إذا كان معهما ثالث بدون شبهة، أما أن تخلو بعم زوجها، أو بأخي زوجها لا، ما يجوز لها الخلوة، الرسول ﷺ قال: لا يخلون رجل بامرأة إلا ومعها ذو محرم لا يجوز لها الخلوة، لكن إذا جلست مع أخي زوجها، أو عم زوجها بحضرة أبيها، بحضرة أمها، بحضرة أخواتها لا بأس، المحرم الخلوة، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15398/حكم-جلوس-المراة-مع-عم-او-اخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58322.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16896,"question":"تقول أختنا: أنا لا أحب زيارة بعض الأقارب؛ لأن بناتهم يكثرن الاختلاط مع الرجال، ويكثرن الحكي معهم، ويجلسون معهم، وأنا لا أحب هذه التصرفات، ويقولون: إني معقدة، فهل أنا مذنبة لأني لا أحب الاختلاط مع أولاد الخالة، وأولاد الخال، ولا أولاد العم؟ أم أنا على صواب؛ لعدم مخالطة الرجال عامة، ولست معقدة؟ جزاكم الله خيرًا.","title":"حكم اختلاط المرأة مع أولاد عمها وخالها","answer":"الجواب: قد أصبت -بارك الله فيك- وأحسنت؛ لأن الاختلاط بالرجل الأجنبي فيه خطر عظيم، وابن العم، وابن الخال، وابن الخالة كلهم يعتبرون أجانب، غير محارم، أما الاختلاط الذي معناه رد السلام عليهم في المجلس، أو كيف حالكم، وكيف أولادكم؟ مع البعد عن أسباب الريبة، والكلام الباطل، فلا حرج في ذلك، إذا سلمت على بني عمها، أو بني خالها سلامًا ليس فيه ريبة، وليس فيه خلوة، بل سلمت عليه في مجلس، أو زاروهم، وسلموا عليها من باب صلة الرحم؛ هذا لا بأس به. المحرم الخلوة بالرجل، أو تعاطي أسباب الريبة، والفتنة مع الرجال، بالكلام، أو بالفعال، أما سلامًا نزيهًا، وكلامًا نزيهًا، بعيدًا عن الفتنة، فلا حرج أن تسلم على ابن عمها، أو ابن خالتها، أو ترد عليه السلام، أو تسأله عن أهله، وأولاده، لا بأس بذلك من دون خلوة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15653/حكم-اختلاط-المراة-مع-اولاد-عمها-وخالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76511.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":16897,"question":"آخر سؤال لأختنا تقول فيه: هل يجوز للمرأة الصلاة خارج البيت، وأمام بعض الأقارب؛ علمًا أنا في الريف، ولا يوجد لدينا بيت، مع أنه أيضًا لبسنا غير محتشم؟ وجهونا جزاكم الله خيرًا.","title":"ما حكم صلاة المرأة في غير بيتها؟","answer":"الجواب: إذا كانت الصلاة في بيت الأقارب، أو بيت الناس الذي زارتهم المرأة، وحضرت الصلاة، تصلي عندهم، ولكن إذا كان حولها رجل تصلي في محل بعيد عن رؤية الرجل؛ حتى لا يرى منها شيئًا، ولاسيما إذا كانت ثيابها غير محتشمة، يجب عليها أن تبتعد عن رؤية الرجال الأجانب، سواءً في بيتها، أو في غير بيتها، وإذا كانت محتشمة وصَلَّت في البيت، أو عند بعض من زارتهم لما حضرت الصلاة؛ فكل هذا لا بأس به، أما عند الأجنبي ولو ابن خال، أو ابن خالة، أو ابن عم؛ فلا بد أن تكون تامة الستر، ولا يوجد خلوة، بل تصلي في البيت من دون خلوة، من دون أي خلوة بها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15654/ما-حكم-صلاة-المراة-في-غير-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76512.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17033,"question":"يقول السائل من اليمن سماحة الشيخ: عندنا عادة وهي مصافحة الرجال للنساء غير المحارم، وإذا قلنا لهم: بأن هذا لا يجوز، قالوا: إن قلوبنا نظيفة، ونحن كالأهل، وجهونا في ضوء ذلك مأجورين.","title":"حرمة مصافحة المرأة الأجنبية","answer":"الجواب: لا يجوز للرجل أن يصافح المرأة التي ليست محرمًا له، سواءٌ كانت زوجة أخيه، أو زوجة عمه، أو من جيرانه، لا ليس له مصافحتها، يسلم عليها بالكلام فقط، أما المصافحة لا، لا يصافح إلا محارمه، كأمه، وأخته، وزوجته، وزوجة أبيه لا بأس، أما امرأة ليست محرمًا له، بل أجنبية كزوجة أخيه، أو زوجة عمه، أو بعض جيرانه، أو بعض بنات عمه، كل هؤلاء ليسوا محارم، لسن محارمًا له، فلا يجوز له أن يصافحهن، يقول النبي ﷺ لما مدت امرأة يدها إليه قال: إني لا أصافح النساء -عليه الصلاة والسلام- في البيعة، قال: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: «والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام » -عليه الصلاة والسلام- ولأن مسها وسيلة للفتنة، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/15817/حرمة-مصافحة-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58711.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17154,"question":"تقول السائلة أم هادي: هل يجوز لبنت في الثامنة من العمر أن تذهب مع ابن الجيران، أو مع ابن عمها لضرورة، مثلًا أن تكون مريضة، وبحاجة للطبيب تذهب معه، وإخوان هذه البنت الصغيرة ليسوا موجودين في البيت؟","title":"حكم خروج البنت مع غير المحارم","answer":"الجواب: لا حرج إن شاء الله، لا حرج إن شاء الله. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15972/حكم-خروج-البنت-مع-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58932.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17269,"question":"من أسئلتها تقول: هل يجوز للمرأة أن تجلس مع حماها إذا اضطرت إلى ذلك، وتكون هذه المرأة متغطية، وعليها الحجاب الذي يغطي الرأس، وجميع جسمها؟","title":"حكم جلوس المرأة مع أخي زوجها","answer":"الجواب: نعم لها أن تجلس مع أخي زوجها، وعم زوجها إذا كان معهما ثالث بدون شبهة، أما وأن تخلو بعم زوجها، أو بأخي زوجها لا ما يجوز لها الخلوة؛ الرسول ﷺ قال: لا يخلون رجل بامرأة إلا ومعها ذو محرم لا يجوز لها الخلوة، لكن إذا جلست مع أخي زوجها، أو عم زوجها بحضرة أبيها، بحضرة أمها، بحضرة أخواتها، لا بأس المحرم الخلوة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16111/حكم-جلوس-المراة-مع-اخي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59219.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17280,"question":"تقول: أنا لا أحب زيارة بعض الأقارب؛ لأن بناتهم يكثرن الاختلاط مع الرجال، ويكثرن الحكي معهم، ويجلسون معهم، وأنا لا أحب هذه التصرفات، ويقولون: إني معقدة، فهل أنا مذنبة والحال ما ذكرت، أو أنني معقدة، أو أنني على صواب؟ وجهوني، ووجهوا أمثال هؤلاء جزاكم الله خيرًا.","title":"حكم زيارة من تخالط الرجال وتجالسهم","answer":"الجواب: الواجب على كل امرأة أن تتقي الله، وأن تحذر ما حرم الله عليها من الاختلاط بالرجال على وجه يسبب الفتنة من كشف، أو التغنج، وخضوع بالقول، أو غير هذا من أسباب الفتنة. أما الاختلاط الذي لا يضر: مثل دخولها السوق لشراء حاجة، مثل صلاتها مع الناس خلف الجماعة، هذا ما يسمى اختلاط، ولا حرج فيه مع التستر، والبعد عن الفتنة، أما اختلاط بحيث تجلس مع الرجل، أو تكشف بعض محاسنها، ومفاتنها حتى يراها الرجال، أو تغازل الرجال، أو تخضع بالقول للرجل؛ هذا كله من المحرمات.. المقدم: أو تخضع..؟ الشيخ: بالقول؛ لأن الله قال: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] يعني: لا تغنج، لا تزينه تكسر في القول، فالمقصود أنها تبتعد عن كل ما يسبب الفتنة مع الرجال، سواء كان الرجال بني عم، أو أزواج أخوات، أو إخوان زوج، أو خدامًا، أو غير ذلك، يجب الحذر، وأنت مأجورة في الحذر من هذه الأشياء، والحرص على السلامة، أنت مأجورة -إن شاء الله- بذلك، نسأل الله للجميع الهداية، والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/16121/حكم-زيارة-من-تخالط-الرجال-وتجالسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76812.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17357,"question":"تقول: انتشرت النميمة، والغيبة، والقيل، والقال بين جميع الناس، وبقيت -والحالة هذه- في البيت، لا أخرج مع الأهل لزيارتهم، بل جلست مع إخواني في البيت، فهل أصير قاطعة للرحم، أرجو أن تنصحون الذين ينقلون الكلام من شخص..الشيخ: أعد.. أعد..المقدم: تقول: انتشرت النميمة، والغيبة، والقيل، والقال بين الناس، فبقيت في البيت لا أخرج مع الأهل لزيارة أحد، بل جلست مع إخواني في البيت فهل أصير قاطعة للرحم؟ أرجو أن تنصحون الذين ينقلون الكلام من شخص إلى شخص آخر، فيصير بينهم مشاكل بسبب نقل الكلام، جزاكم الله خيرًا.","title":"حكم ترك زيارة الأقارب بسبب المنكرات","answer":"الجواب: خروجك مع الوالدة، ومع أخواتك الطيبات إلى الجيران، أو إلى الأقارب لا حرج فيه، وإذا رأيت شيئًا من المنكر أنكريه بالكلام الطيب، والأسلوب الحسن كما قال النبي ﷺ: الدين النصيحة والله يقول في كتابه الكريم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. وإياك والعزلة، والشذوذ إلا عند الضرورة، إذا رأيت أن من خرجوا إليه عندهم منكر لا يزيلونه، ولا يقبلون منك، فلا تخرجي معهم، أما سوء الظن، وتشديد الأمور من دون منكر ترينه فلا ينبغي منك، بل اخرجي مع الوالدة، مع أخواتك للجيران، أو لعيادة المريض، أو صلة الرحم ما دام الخروج لا يترتب عليه منكر، بالتستر، والحجاب والعناية، وما دام المزورون ليس عندهم منكر، أو عندهم منكر، لكن إذا حضرت زال، وقبلوا منك النصيحة، فأنت على خير عظيم، أما الخروج إلى محل فيه منكر لا يزول، ولو بحضورك، لا تخرجي له، ولا تكوني معهم فيه، وعليك نفسك، ودينك، نسأل الله للجميع التوفيق. أما النميمة فهي محرمة، ولم يزل العلماء ينصحون عنها الناس، ويحذرون منها الناس، فنقل الكلام السيئ من شخص إلى شخص، أو من جماعة إلى جماعة، أو من قبيلة إلى قبيلة، هذا منكر، وهذا يسمى النميمة، ولا يجوز، والواجب الحذر منه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16198/حكم-ترك-زيارة-الاقارب-بسبب-المنكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83402.mp3","categories":["الأخلاق المذمومة","الدعوة والدعاة"]},{"id":17388,"question":"تسأل أيضًا وتقول: هل يجوز للمرأة أن تجلس مع الرجال من أقربائها على أن تكون متسترة، وتتكلم معهم في أمور الدين، وأمور عامة؟","title":"حكم جلوس المرأة متسترة مع أقاربها","answer":"الجواب: نعم، لا بأس أن تجلس المرأة مع الرجال على صفة ليس فيها تبذل، ولا فتنة، بل متحجبة للنصيحة، أو للتحدث في أمر تحتاج إليه، كالجلوس مع أحمائها، إخوان زوجها، أو مع أزواج أخواتها، أو بني عمها، أو ما أشبه ذلك، للتحدث معهم فيما يحتاجه البيت، أو فيما يتعلق بالنصيحة، أو ما أشبه هذا من الأمور التي تحتاج الكلام معهم فيها، من غبر خلوة بواحد منهم، ومن دون تكشف، وعدم حجاب، بل تكون متسترة بالحجاب الشرعي، تستر وجهها، وبدنها، وتتكلم معهم بالكلام الطيب الذي ليس فيه ما يفتن أحدًا منهم، وليس فيه خضوع بالقول، بل بالكلام العادي؛ لقول الله -جل وعلا-: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]. فالمشروع للمرأة أن تتكلم كلامًا معروفًا، ليس فيه تبذل، ولا تكسر، ولا تغنج، ولا خضوع، وليس بفاحش وغليظ وعنيف، ولكن بين ذلك. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16250/حكم-جلوس-المراة-متسترة-مع-اقاربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83503.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17398,"question":"تسأل أيضًا وتقول: هل يجوز للمرأة أن تجلس مع الرجال من أقربائها على أن تكون متسترة، وتتكلم معهم في أمور الدين، وأمور عامة؟","title":"حكم جلوس المرأة متسترة مع أقاربها","answer":"الجواب: نعم، لا بأس أن تجلس المرأة مع الرجال على صفة ليس فيها تبذل، ولا فتنة، بل متحجبة للنصيحة، أو للتحدث في أمر تحتاج إليه، كالجلوس مع أحمائها، إخوان زوجها، أو مع أزواج أخواتها، أو بني عمها، أو ما أشبه ذلك، للتحدث معهم فيما يحتاجه البيت، أو فيما يتعلق بالنصيحة، أو ما أشبه هذا من الأمور التي تحتاج الكلام معهم فيها، من غبر خلوة بواحد منهم، ومن دون تكشف، وعدم حجاب، بل تكون متسترة بالحجاب الشرعي، تستر وجهها، وبدنها، وتتكلم معهم بالكلام الطيب الذي ليس فيه ما يفتن أحدًا منهم، وليس فيه خضوع بالقول، بل بالكلام العادي؛ لقول الله -جل وعلا-: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]. فالمشروع للمرأة أن تتكلم كلامًا معروفًا، ليس فيه تبذل، ولا تكسر، ولا تغنج، ولا خضوع، وليس بفاحش وغليظ وعنيف، ولكن بين ذلك. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16250/حكم-جلوس-المراة-متسترة-مع-اقاربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83503.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17529,"question":"المستمعة (ف. م. ع) من اليمن لها مجموعة من الأسئلة تقول: إذا تكلم الإنسان على الناس الآخرين في غيبتهم وهو لا يقصد شيئًا سوى الضحك، فهل عليه في ذلك ذنب؟","title":"حكم الكلام على الناس في غيبتهم بقصد الضحك","answer":"الجواب: إذا ذكر كلامًا يكرهونه فهو غيبة، أما إذا كان كلامًا طيبًا -كلام يمدحهم به ويثني عليهم- ... لا بأس، أما كلام يغتابهم به ويذمهم به فهذا لا يجوز، لقول الله تعالى: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا[الحجرات:12]، إلا إذا كانت أعمالًا منكرة قد أظهروها بين الناس وجاهروا بها فلا غيبة لهم، نسأل الله العافية. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16449/حكم-الكلام-على-الناس-في-غيبتهم-بقصد-الضحك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77506.mp3","categories":["الأخلاق المذمومة"]},{"id":17673,"question":"هل يجوز للرجل أن يصافح زوجة عمه وخاله؟","title":"هل يجوز مصافحة زوجة الخال والعم؟","answer":"الجواب: لا، زوجة عمه وخاله ليستا محرمًا له، ليس له مصافحتهما ولا الخلوة بواحدة منهما؛ لأنهما ليستا محرمًا له، زوجة العم والخال ولا زوجة الأخ أيضًا؛ كلهن لسن محرمًا له، فلا يصافح زوجة أخيه ولا زوجة عمه ولا زوجة خاله، لكن يصافح زوجة أبيه ما يخالف، زوجة أبيه جده زوجة ابنه لا بأس ابن بنته، أما زوجة أخيه وزوجة خاله وزوجة عمه فكلهن أجنبيات. نعم.","link":"https://binbaz.org.sa/fatwas/16604/هل-يجوز-مصافحة-زوجة-الخال-والعم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59502.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":17716,"question":"هذا السائل أحمد سليمان يقول يا سماحة الشيخ: ما حكم الشرع في نظركم- حفظكم الله- في أكل مال الحرام وخاصةً من قبل رجل متزوج له أولاد؟ فهل ينعكس ذلك على الأطفال؟ وهل يلحقهم ذنب من جراء ما فعله الوالد؟ أفيدونا بذلك.","title":"حكم أكل المال الحرام وأثره على الأهل","answer":"الجواب: الواجب عليه الحذر من ذلك والتوبة إلى الله مما سلف، أما أطفاله فلا يضرهم، فالإثم عليه هو .. أما زوجته وأطفاله لا إثم عليهم، لكن لا يجوز له تعاطي الحرام، بل يجب الحذر من ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16671/حكم-اكل-المال-الحرام-واثره-على-الاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59526.mp3","categories":["الأخلاق المذمومة"]},{"id":17857,"question":"هل الاستهزاء بالشخص الملتزم في دينه كفر؟","title":"حكم الاستهزاء بالرجل الصالح","answer":"الجواب: الاستهزاء به منكر عظيم، لكن لا يكون كفرًا إلا إذا استهزأ بالدين، إذا استهزأ بالدين بالصلاة أو بالتوحيد أو بالزكاة، قال تعالى: قلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66]، أما استهزاء به هو في مشيه أو في قيامه أو قعوده، هذا منكر لا يجوز. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16863/حكم-الاستهزاء-بالرجل-الصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59802.mp3","categories":["الأخلاق المذمومة"]},{"id":17881,"question":"السائل من الرياض (ح. ح. ع) يقول سماحة الشيخ: من وسوس له الشيطان وغش في الامتحان، ولكنه تاب إلى الله وندم على ذلك، مع العلم بأنه والله لا يحب الغش، ولكن وسوس له الشيطان، فهل هذه الشهادة التي أوصلته حرام وحصل عليها؟ وهل يجوز أن يتوظف بها؟","title":"حكم التوظف بالشهادة التي حصل عليها بالغش","answer":"الجواب: عليه التوبة، والحمد لله، التوبة إلى الله جل وعلا، والشهادة معتبرة يستعملها، لكن عليه التوبة إلى الله جل وعلا، وعليه أن ينصح في العمل. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16886/حكم-التوظف-بالشهادة-التي-حصل-عليها-بالغش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59811.mp3","categories":["الأخلاق المذمومة"]},{"id":17900,"question":"هذا السائل من الرياض يقول سماحة الشيخ: ما حكم تزكية النفس، كأن يتحدث الإنسان عن نفسه؟","title":"ما حكم تزكية النفس؟","answer":"الجواب: ينبغي له أن لا يزكي نفسه، بل ينبغي له أن يتهمها ويتنقصها ويجتهد في طاعة الله ورسوله، لكن إذا دعت الحاجة إلى إخباره عن نفسه بشيء؛ من دون تزكية للنفس ومن دون رياء، إنما عند الحاجة، كأن يُسأل عن صلاته أو صومه، فيخبر أنه يصلي في المسجد الفلاني، وأنه بحمد الله محافظ على الجماعة، أو عند الحاجة إلى إخبار أنه يصوم ثلاثة أيام أو يصوم يوم ويفطر يوم؛ عند الحاجة لا قصد الرياء، فلا بأس، كما أخبر عبد الله بن عمرو للنبي ﷺ، أما كونه يتكلم بهذا رياء وسمعة؛ فلا يجوز.","link":"https://binbaz.org.sa/fatwas/16906/ما-حكم-تزكية-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59818.mp3","categories":["الأخلاق المذمومة"]},{"id":17911,"question":"الجانب الآخر: بعض الآباء والأمهات قد يستعجلون يا سماحة الشيخ في حالة غضب ويدعون على أولادهم أو يلعنونهم ثم يندمون على ذلك، هل من توجيه للآباء والأمهات؟","title":"حكم اللعن والدعاء على الأبناء","answer":"الجواب:  نعم. لا يجوز للآباء اللعن ولا الأمهات ولا غيرهم، اللعن لا يجوز، هذا منكر، الرسول ﷺ حذر من هذا وأمر العباد أن يحذروا ذلك، فالإنسان إذا لعن أخاه بغير حق أو دعا عليه إذا كان لا يستحق رجعت لعنته عليه، وفي الحديث الصحيح: من قال لأخيه: يا عدو الله؛ وليس كذلك إلا حار عليه وهكذا من سبه أو دعا عليه وليس كذلك ترجع دعوته ولعنته إليه، فالواجب الحذر، ويقول ﷺ: لعن المؤمن كقتله جعل اللعن كالقتل، فالواجب الحذر من السب، والشتم للوالدين وغيرهما، وعلى الوالدين أن يحذرا ذلك، أن يحذرا سب أولادهم، ولعن أولادهم، بل يدعون لهم بالهداية، اللهم اهد فلانًا، اللهم اهد ذريتي، اللهم أصلح ذريتي، اللهم اهد فلانًا، اللهم اهد فلانة، أما السب لا، لا يجوز. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16917/حكم-اللعن-والدعاء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78010.mp3","categories":["نصائح وتوجيهات","الأخلاق المذمومة"]},{"id":18072,"question":"الواقع أختنا سماحة الشيخ تذكر مأساة يشكو منها كثير من الآباء، تلكم هي ما يعرف بين كثير من الشباب بالانقطاع الكلي للفكر، وتمحيص الآراء حتى أن هذا أدى بالأبناء إلى الانقطاع عن آبائهم وببعض البنات أيضًا، لابد لسماحة الشيخ من كلمة وأعتقد أن هذا غزو دخل إلى شبيبة الإسلام.","title":"حكم الابتعاد عن الوالدين بحجة الانقطاع للفكر","answer":"الجواب: لا حول ولا قوة إلا بالله! لاشك أن هذا أمر خطير، والواجب على الشباب أن يتقي الله  وأن يعرف قدر الوالدين، وحق الوالدين، فحقهما عظيم وواجبهما كبير، ولا ينبغي للشباب من الذكور والإناث أن ينقطعوا للوساوس والأفكار المخالفة المنحرفة، بل يجب على المؤمن شابًا أو شيخًا وعلى المؤمنة فتاة أو كبيرة على الجميع أن يحاسبوا أنفسهم، وأن يتقوا الله في أقاربهم وفي والديهم بوجه أخص، وأن يحرصوا على الاستقامة، وأن يحذروا وساوس الشيطان ونزغات الشيطان. والله جل وعلا قال: قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ [الناس:1-4] فهو وسواس عند الغفلة خناس عند الذكر. فالواجب على الشباب جميعًا من الذكور والإناث أن يتقوا الله وأن يستقيموا على دينه، وأن يعرفوا قدر الوالدين وقدر الأقارب، وأن يبروا والديهم، وأن يصلوا أرحامهم، ولو فرضنا أن الوالدين كافران لوجب الإحسان إليهما، قال الله جل وعلا في كتابه الكريم في حق الوالدين الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران عليه أن يحسن إليهما وأن يصحبهما بالمعروف وأن ينصح لهما، وأن يدعوهما إلى الخير، وأن يحسن إليهما بما يستطيع من مال وجاه ودعوة إلى الله  لعل الله يهديهما بأسبابه. فكيف إذا كان الوالدان مسلمين فالأمر أعظم وأكبر، وهكذا الرحم، وصل الرحم من أهم الواجبات وقطيعتها من أقبح الكبائر، يقول عليه الصلاة والسلام: لا يدخل الجنة قاطع رحم ويقول عليه الصلاة والسلام: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله ثم قال: وعقوق الوالدين فجعل العقوق من أكبر الكبائر. فالواجب على الجميع من ذكور وإناث أن يعرفوا قدر الوالدين، وأن يعظموا قدر الوالدين، وأن يحسنوا إليهما، ولو جرى منهما بعض الشيء من التقصير في حق الولدين، أو من الكلام الشديد على الولدين أو من الإساءة إليهما فحقهما عظيم. فالواجب الإحسان إليهما والتلطف بهما واستسماحهما وطلب العفو منهما، وتوسيط الناس الطيبين في الإصلاح بين الإنسان وبين والديه إذا كان هناك شيء من الاختلاف بينهما لا ينفر من والديه ولا يبتعد عن والديه، بل يجتهد في إيجاد الصلح وفي إيجاد التقارب بينه وبين الوالدين حتى ولو أساءا إليه ليتحمل ولينظر إلى حقهما العظيم، وليوسط الأخيار من إخوة كبارًا أو أخوالًا أو أعمامًا أو غيرهم حتى يزول الإشكال وحتى يعود الوئام بين الولد ووالديه وبين البنت ووالديها.. هكذا ينبغي، أما الانقطاع والتباعد عن الوالدين والغفلة عنهما فهذا شره عظيم وعاقبته وخيمةن وهو من أعظم العقوق، نسأل الله للجميع الهداية والعافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17107/حكم-الابتعاد-عن-الوالدين-بحجة-الانقطاع-للفكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90207.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":18073,"question":"من الصور المحزنة سماحة الشيخ: أن يأنف الشباب من السير مع الآباء، ولاسيما إذا كان الآباء من العوام أي من أولئك الذين لم يكن لهم فرصة للتعلم والتعليم والثقافة، توجيهكم هذا جزاكم الله خيرًا.","title":"حكم الترفع عن السير مع الآباء","answer":"الجواب: وهذا أيضًا غلط، والواجب على الولد أن يتواضع، وأن يعرف قدر والديه، وأن يحمد الله على ما أعطاه من العلم والبصيرة، وأن يستعين بذلك على توجيه والديه بالحكمة والكلام الطيب، وينبههما على ما قد يخفى عليهما، ويكون في غاية العطف عليهما، والذل لهما والاستكانة والتواضع كما أمر الله بذلك  قال: وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ [الإسراء:24]. فالواجب أن يتواضع لوالديه، وأن يعرف قدرهما ولو كانا عاميين، يجب عليه أن يعرف قدرهما، وأن يحسن إليهما، وأن يعاملهما بالبشاشة، والتواضع والكلام الطيب، هذا من أهم الواجبات، وأن لا يؤثر عليهما زميلًا أو صديقًا أو غير ذلك، بل يجب أن يعرف حقهما، وأن يحسن إليهما في جميع الأوقات، ولو قدر أنهما تكلما عليه في بعض الأشياء، أو انتقداه في بعض الأشياء يبين لهما ما قد يخفى عليهما، ويبصرهما، وليستعن بأهل الخير من أقاربه إذا لم ينفع كلامه هو معهما ليستعن بالأخيار الطيبين من أعمام وأخوال وجيران طيبين حتى يشرحوا للوالدين ما يجب شرحه من حال الولد وحق الولد على والديه من أن يعيناه على الخير وأن يوجهاه إلى الخير، فالوالدان لهما حق، والولد له حق أيضًا. فالوالدان عليهما أن يعيناه على الخير وأن لا يثبطاه عن الخير، بل عليهما أن يعيناه على الصلاة في الجماعة، وعلى صحبة الأخيار وعلى ترك صحبة الأشرار، ويعيناه على طلب العلم وعلى كسب الحلال، وهو عليه أن يعرف قدرهما، ويحسن إليهما، ويتواضع لهما، ويبرهما ويؤدي حقهما. رزق الله الجميع التوفيق والهداية. المقدم: اللهم آمين. سماحة الشيخ! في الختام أتوجه لكم بالشكر الجزيل بعد شكر الله  على تفضلكم بإجابة السادة المستمعين، وآمل أن يتجدد اللقاء وأنتم على خير. الشيخ: آمين، نسأل الله ذلك.","link":"https://binbaz.org.sa/fatwas/17108/حكم-الترفع-عن-السير-مع-الاباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90208.mp3","categories":["الأخلاق المذمومة"]},{"id":18130,"question":"مع مطلع هذه الحلقة سماحة الشيخ هذه رسالة وصلت إلى البرنامج من البحرين وباعثتها إحدى الأخوات تقول: (ف. ك) أختنا رسالتها مطولة بعض الشيء، لكنها تحكي مشكلة وقعت بينها وبين إحدى صديقاتها فتقول: في يوم من الأيام حدث سوء تفاهم بيني وبين قريبة لي، مما جعل هذه القريبة تخاصمني، وهذه هي السنة الثالثة من تخاصمنا، وإنني لم أخطئ ولا أريد أن أخاصمها، هي التي بدأت وهي التي خاصمتني، والله خير شاهد على ما أقول، فأنا فتاة متدينة ومتحجبة وأعرف أصول ديني الإسلامي، وهذا من فضل الله تعالى.كذلك تدخلت أمها بيننا وأخذت تنازعني وخاصمتني هي أيضًا، ذهبت إليها وسلمت عليها في عيد رمضان ولم تكلمني، توفي زوجها وذهبت إليها لأعزيها ولم تكلمني، ذهبت إليها عندما خرجت من العدة وسلمت عليها أيضًا ولم تكلمني، حتى السلام لم تسلم علي إذا شاهدتني في الشارع، لكنني أنا عندما أشاهدها أسلم عليها؛ ذلك لأن السلام لوجه الله تعالى، وأنا خائفة من الله ورسوله عليه السلام؛ لأنني قرأت وعرفت أن المؤمن لا يخاصم أخاه المؤمن لثلاثة أيام، وأن أعمالنا لا ترتفع إلى الله  إلى أن نتصالح، وأنا يا سماحة الشيخ! أريد هذا الصلح لأفوز برضا الخالق ّعلي ورضا رسوله ﷺ، فهل أنا مخطئة؟ أفيدوني جزاكم الله ثواب الدنيا والآخرة.","title":"هل يأثم من يريد الصلح مع الأقارب وهم رافضون؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان الواقع هو ما ذكرت فإن الإثم عليها، أما أنت فليس عليك إثم؛ لأنك قد أديت ما عليك، قد حرصت على رضاها وإزالة الهجر، فلم تفعل هي فالإثم عليها وليس عليك شيء، وقد أديت ما عليك من طلب المسامحة والمصالحة، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام، وجاء في بعض الأحاديث: \"أن الرجل إذا بدأ أخاه وسلم عليه فلم يرد فالإثم على من ترك الرد\". والذي بدأ بالسلام قد سلم من التبعة؛ لأنه أدى ما عليه من الحق، فأنت قد أديت ما عليك إذا كان الواقع هو ما ذكرت والإثم عليها، والحمد لله الذي جعلك تجاهدين نفسك وتجتهدين في أداء الحق، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: تعرض الأعمال على الله سبحانه في كل إثنين وخميس، فيغفر الله لكل مسلم لا يشرك بالله شيئًا، إلا رجلًا كانت بينه وبين أخيه شحناء، فيقول الله: دعوا هذين حتى يصطلحا. وهكذا المرأة إذا كانت بينها وبين أختها شحناء مثل الرجلين الحكم واحد، فينبغي للمؤمن والمؤمنة الحرص على عدم الشحناء، والحرص على التحاب في الله والتناصح والتعاون على الخير حتى لا يجد الشيطان طريقًا إلى إبعاد كل منهما عن الآخر بأسباب طاعة الهوى والشيطان. والمؤمن دائمًا يتحرى ما يرضي الله، ويقرب لديه، وما يوافق شرعه في كل حال، ولو خالف هواه، فإذا وقعت بينه وبين أخيه شحناء أو تهاجر فالواجب عليه ألا يصر على الباطل، وأن يحرص على موافقة الشرع، فلا يزيد على ثلاثة أيام فيما يتعلق بالشحناء التي بينه وبين أخيه في أمور الدنيا من المخاصمات التي تقع بين الناس، وهكذا النساء فيما بينهن. أما إذا كان الهجر في حق الله من أجل إظهار المعاصي أو من أجل إظهار البدع، فهذا ليس له حد بالأيام وإنما حده التوبة، فمتى تاب المعلن للمعاصي أو البدع ترك هجره، ومتى بقي على حاله فإنه يهجر، وقد هجر النبي ﷺ ثلاثة من الصحابة تخلفوا عن الغزو بغير عذر شرعي، بعدما استنفرهم النبي ﷺ فهجرهم وهجرهم المسلمون خمسين ليلة حتى تاب الله عليهم فأذن بكلامهم عليه الصلاة والسلام. فالمقصود: أن الواجب على المؤمن ألا يتبع هواه وألا يحكم رأيه، بل يجعل رأيه وهواه تابعين لحكم الله ورسوله. والواجب على المؤمن والمؤمنة أن يخافا الله، قول: أخاف الله ورسوله، هذا فيه نظر، فالخوف لله جل وعلا: فَلا تَخَافُوهُمْ وَخَافُونِ إِنْ كُنْتُمْ مُؤْمِنِينَ [آل عمران:175]، فالرسول ﷺ يطاع ويتبع، ولا يخاف بعد وفاته عليه الصلاة والسلام، وإنما يخاف الله  هو الذي بيده الحل والعقد وبيده تدبير الأمور وإليه الرغبة، كما قال جل وعلا: فَإِذَا فَرَغْتَ فَانصَبْ ۝ وَإِلَى رَبِّكَ فَارْغَبْ [الشرح:7-8]، قال: فَإِيَّايَ فَارْهَبُونِ [النحل:51]. فالرهبة إليه والرغبة إليه ، هو اللي يخاف ويرجى، ويرغب إليه ويرهب منه، فيقول المؤمن: إني أخاف الله، إني أخشى الله سبحانه، كما قال تعالى: وَلَمْ يَخْشَ إِلَّا اللَّهَ [التوبة:18]، فالمؤمن يخشى ربه ويحاسب نفسه ويطيع الله ورسوله، فيقول: أطيع الله ورسوله، أتبع أمر الله ورسوله، ويقول: أخاف الله وأخشى الله؛ لأنه هو الذي بيده تصريف الأمور وهو المانع المعطي وهو النافع الضار، وهو الذي بيده النجاة والسعادة وضد ذلك. أما المخلوق فليس بيده شيء من ذلك، لكن إذا كان حيًا فلا بأس أن يخاف الخوف الطبيعي الخوف المعروف العادي الذي يقتضي أداء الحق والأخذ بالأسباب فيخاف السلطان، فلا يتعرض لأسباب عقوبة السلطان، يخاف أهل البيت فلا يتعرض لسرقة متاعهم وإيذائهم، لئلا يؤذوه ويضروه أو يرفعوا أمره إلى السلطان فيعاقب بالقطع في السرقة.. ونحو ذلك، هذا خوف عادي خوف طبيعي، لا يضر الإنسان إذا لم يحمله على معصية الله ، وكما يخاف من السراق فيغلق بابه ويحفظ متاعه، ويخاف من قطاع الطريق فيحمل سلاحه، ويخاف من السباع فيحذر شرها ويأخذ سلاحه، ويخاف مما يضره من بعض الأطعمة أو بعض الأشربة فيتركها.. ونحو ذلك، هذا خوف طبعي معروف يقدر عليه المخلوق، فيخاف بقدر ذلك، مع ثبات الخوف من الله في كل شيء واستقراره في القلب، ولكن يخاف المخلوق الحي الحاضر على قدر ما لديه من العقوبات والخطر، كما يخاف الإنسان أيضاً من السباع كما تقدم والحيات والعقارب فيتقي شرها بالطرق التي يتقى به شرها ولا حرج في ذلك. أما خوف السر فهذا يتعلق بالله وحده، كون الإنسان يخاف الله في سر قلبه، ويعلم أن الله هو الذي بيده التصريف للأمور فيخافه سبحانه ويخشاه؛ لأنه القادر على كل شيء؛ لأنه العالم بما في القلب؛ لأنه العالم بكل شيء هذا هو الواجب، فمن أشرك غير الله في هذا الخوف صار شركًا بالله، فمن اعتقد أن الأولياء يعرفون ما في القلب أو النبي ﷺ يعرف ما في قلبه، وأنه يجب عليه أن يخافه بعد وفاته، وأنه إذا ما خافه يضره، هذا جهل وشرك، نسأل الله العافية. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17163/هل-ياثم-من-يريد-الصلح-مع-الاقارب-وهم-رافضون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85201.mp3","categories":["الأخلاق المذمومة"]},{"id":18176,"question":"رسالة وصلت إلى البرنامج من جمهورية السودان الديمقراطية -الخرطوم- وباعثتها إحدى الأخوات من هناك تقول مستمعة البرنامج زهرة الطاهر محمد، أختنا تقول في أحد أسئلتها في هذه الرسالة: سمعت في إحدى حلقات برنامجكم بأنه لا يجوز أن تركب النساء بجانب الرجال في المركبات العامة، وحيث أنه لا يمكن تخصيص مركبات خاصة عندنا وبحكم عملي أضطر لركوب هذه المركبات يوميًا ما رأيكم؟ وبم توجهونني؟ جزاكم الله خيرًا.","title":"حكم ركوب المرأة في وسائل المواصلات العامة","answer":"الجواب: إذا كان ولابد من الركوب في الحافلات العامة فليكن مركب النساء على حدة وراء الرجال، والرجال أمامهم على حدة حتى لا تمس المرأة الرجل، وحتى لا يحصل تماس وتقارب يخشى منه الفتنة، ينبغي أن تكون مراكب النساء خلف الرجال والرجال أمامهم يخصص لهؤلاء مراكب ولهؤلاء مراكب. فإذا اضطرت إلى خلاف ذلك فلتحرص على التحجب والتستر والبعد عن مماسة الرجل فيما يسبب الفتنة حتى تصل إلى جهتها إذا كانت قريبة لا تعد سفرًا. أما إن كانت المسافة تعتبر سفرًا فلابد من المحرم؛ لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم وعلى كل حال الواجب على النساء والرجال أن يتقوا الله جميعًا وأن يحرصوا على البعد عن أسباب الفتنة. وإذا دعت الحاجة إلى المراكب العامة فليجتهد المسئولون عنها أن يجعلوا مراكب النساء على حدة، ومراكب الرجال على حدة، إبعادًا لأسباب الفتنة، وينبغي للركاب المعروفين أن يفعلوا ذلك وأن يطلبوا من المسئولين عن الحافلات أن يفعلوا هذا حتى تكون الفتنة أقل وحتى يكون الشر أقل إن شاء الله. نعم. المقدم: هل تنصحون المرأة بعدم جلوسها في نفس الكرسي الذي يجلس عليه الرجل؟ الشيخ: نعم أنصحها بألا تجلس معه إذا كان فيه مماسة وتقارب يخشى منه الفتنة فلتبتعد ولتجلس في مركب بعيد عن ذلك ليس فيه مماساة، وإذا تيسر أن تكون مراكب النساء على حدة، ومراكب الرجال على حدة انتهى الموضوع وزالت المشكلة. نعم. المقدم: نعم نعم، إذًا النصيحة أيضًا توجه للرجال؟ الشيخ: نعم للرجال والنساء جميعًا، كلهم عليهم أن يحذروا الفتنة، وأن يجتهدوا في أن تكون مراكب الرجال على حدة في الجهة الأمامية، والنساء وراءهم في الجهة الخلفية حتى يحصل المقصود من دون ارتكاب للفتنة مع التحجب من النساء والحرص على الستر والبعد عن أسباب الفتنة، وعدم إظهار ما يفتن الرجال من التبرج، وإظهار زينة المرأة في وجهها وغيرها، بل تكون مستورة الوجه مستورة الشعر ومستورة البدن، بعيدة عن أسباب الفتنة، والله المستعان. نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/17216/حكم-ركوب-المراة-في-وساىل-المواصلات-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85403.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18224,"question":"ما حكم عمل المرأة كمدرسة للبنات في مدرسة بها رجال مدرسين وهي متنقبة، والسائلة من السودان؟","title":"حكم تدريس المرأة للبنات في مدرسة بها مدرسون","answer":"الجواب: إذا كانت تدرس النساء من غير اختلاط بالرجال هؤلاء على حدة وهؤلاء على حدة لا بأس، أما مع اختلاطها بالرجال لا يجوز؛ لأن هذا فتنة يسبب شرًا كثيرًا، لكن إذا كانت تدرس النساء وحدهن في مدرسة وحدها في مكان وحده لا بأس، أما مختلطة مع الرجال فلا يجوز. نعم. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/17272/حكم-تدريس-المراة-للبنات-في-مدرسة-بها-مدرسون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78213.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18394,"question":"تسأل سؤال أخير سماحة الشيخ وتقول: أختي لديها طفلة معاقة وتبلغ هذه الطفلة من العمر ست سنوات وهي متعبة جدًا بالنسبة لوالدتها، وتحتاج إلى كثير من الرعاية علمًا بأن والدتها غير مؤهلة صحيًا لذلك، وذلك لأنها مريضة ولها أطفال وحامل أيضًا، ولا تضع إلا بالعملية القيصرية، وينصحها الأطباء بعدم حمل الثقيل وعدم شد الأشياء الثقيلة، فهل يجوز لها جلب خادمة مسلمة تتولى العناية بهذه الطفلة علمًا بأن هذه الخادمة ستكون بدون محرم وستعيش معهم في البيت، فهل هذا جائز أم لا؟ أفيدوني وجزاكم الله خيرًا.","title":"حكم استقدام خادمة مسلمة بغير محرم","answer":"الجواب: إذا كان في البيت نساء غيرك فلا حرج في ذلك، وعلى والد الأطفال أن يقدم للمحرم ما يلزم من جهة تذكرة السفر ذهابًا وإيابًا مع المرأة، وإذا تيسر من دون محرم خادمة في البلد من دون حاجة إلى استجلابها من خارج وتيسر خادمة طيبة فلا بأس إذا كان هناك من يكون معها في البيت غيرك حتى لا يحصل خلوة بها من والد الأطفال. فالمقصود إذا كان المقام ليس فيه خطر ولا خشية من وقوع الفاحشة بل في البيت من تشترك معه الخادمة وتكون معه الخادمة ويكون سببًا للسلامة من الخلوة بزوجك فلا بأس إن شاء الله ولا حرج، وعليك وعلى زوجك أن تقوما بقيمة تذكرة المحرم إذا كانت تستقدم من خارج، وإن تيسر من الداخل فذلك طيب. نعم.","link":"https://binbaz.org.sa/fatwas/17495/حكم-استقدام-خادمة-مسلمة-بغير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86307.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18645,"question":"تسأل أختنا عن حكم من يستهزئ بالنساء المتحجبات، وخاصة من تغطي وجهها.","title":"حكم الاستهزاء بالمتحجبات","answer":"الجواب: هذا على كل حال حكمه أنه غالط، وأتى منكرًا. فالواجب عليه التوبة إلى الله من ذلك، وأن يشجعهن على الحجاب، وليس له ولا لغيره الاستهزاء بالمتحجبات، بل الواجب شكرهن وتشجيعهن على التحجب، لما في ذلك من المصلحة العظيمة؛ ولما في ذلك أيضًا من اتباع الشرع، والتمسك بالأوامر التي جاء بها الكتاب والسنة. كما قال الله سبحانه في كتابه العظيم: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] وقال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فالحجاب للمرأة فيه خير عظيم، ومصالح جمة لها وللمسلمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17760/حكم-الاستهزاء-بالمتحجبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73503.mp3","categories":["اللباس والزينة","الأخلاق المذمومة"]},{"id":18651,"question":"ظهرت في الآونة الأخيرة -والأسئلة لا زالت لأخينا من السودان- يقول: ظهرت في الآونة الأخيرة في مجتمعنا الإسلامي ظاهرة الإدارات النسائية في بعض المؤسسات والمصالح، وحتى الوزارات، والتي يعمل تحت إمرتها كثير من الرجال الذين عليهم بالطاعة، وإراقة ماء الوجه لتنفيذ الأوامر على مضض من أجل الوظيفة لضمان لقمة العيش، فكيف يتفق كل هذا والشريعة السمحة تقول بأن الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ [النساء:34]؟","title":"حكم اختلاط النساء بالرجال في الأماكن العامة","answer":"الجواب: هذا قد سبق فيه غير مرة التنبيه في الإذاعة والتلفاز، وأن الواجب على النساء أن يكن في عمل النساء، وأن يكون الرجال في عمل الرجال، وألا يبرز الرجال في محل النساء؛ كطبيب النساء وممرض النساء، أو أشباه ذلك، بل يكون الطبيب للرجال والطبيبة للنساء، والممرض للرجال، والممرضة للنساء هذا هو الواجب، وكما تكون المعلمة للبنات، والمعلم للرجال، كل له ما يناسبه درءًا للفتنة، وحماية للمجتمع من أسباب الفساد. فليس للرجال أن يتولوا تدريس النساء، وليس للنساء أن يتولين تدريس الأولاد، بل يجب أن تكون المدرسة للبنات، وأن يكون المدرس للذكور؛ حسمًا لمادة الفتن، وهكذا في الدوائر، يجب أن تكون الدوائر للرجال، إذا كانت الدائرة للرجال، وأيضًا أن تكون الدائرة للنساء كمدارس النساء، وأشباه ذلك مما يكون فيه عمل النساء. ومستشفيات النساء يكون فيها النساء، كل طائفة يكون فيها ما يناسبها، طائفة الرجال يكون فيها الموظفون من الرجال بقدر الحاجة، وطائفة النساء يكون لهن موظفات من النساء، هذا هو الواجب سدًا لباب الشر، وحسمًا لأسباب الفساد. ولا مانع من استثناء بعض الحالات التي يضطر إليها، كأن يتولى الطبيب المختص علاج امرأة لم يوجد طبيبة تعالجها، أو طبيبة مختصة تعالج رجلًا بمرض لم يوجد في البلد أو في المستشفى من يعالجه، هذه ضرورات؛ مع الحشمة، ومع البعد عن أسباب الفتنة، ومع البعد عن الخلوة، هذا يجب عند الحاجة التقيد بهذه القيود، والحذر من أسباب الشر، فتكون الطبيبة التي اضطر إليها في علاج الرجل غير متعاطية لأسباب الفتنة، وغير خالية بالمريض، وهكذا الرجل إذا أراد أن يطب المرأة يكون هكذا عند الضرورة، ومن غير خلوة، وهي كذلك لا تتعاطى أسباب الفتنة، وإلا فالأصل هو ما تقدم: الأصل أن يكون الرجال للرجال والنساء للنساء؛ في التعليم، وفي الدوائر، وفي كل شيء؛ حسمًا لأسباب الفتن، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/17786/حكم-اختلاط-النساء-بالرجال-في-الاماكن-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_872/nour_87206.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18678,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: زكي محمد محمود من دولة قطر، أخونا يسأل ثلاثة أسئلة، يقول: أشاهد بعض الناس عندما يقبل البعض الآخر، ينحني، بل ولربما سلم في يده، هل هذه الطريقة جائزة أو لا؟","title":"حكم التقبيل والانحناء عند السلام","answer":"الجواب: لا يجوز الانحناء في السلام، وقد روي عن النبي ﷺ النهي عن ذلك، فقد روي عنه ﷺ أنه نهى عن ذلك، وإن كان في الحديث بعض النظر والضعف، لكنه أمر لا ينبغي، وإنما السنة أن يسلم وهو منتصب، يصافح أخاه أو يعانقه إن كان قدم من سفر، هذا هو السنة أن يصافحه عند اللقاء، ولا بأس بالمعانقة عند القدوم من السفر، وكان أصحاب النبي ﷺ إذا تلاقوا تصافحوا ، وكانوا يصافحون النبي -عليه الصلاة والسلام-، وقال أنس : \"كان أصحاب النبي ﷺ إذا تلاقوا تصافحوا، وإذا قدموا من سفر تعانقوا\"، وقد روي عنه -عليه الصلاة والسلام- أنه قال: إذا التقى المسلمان وتصافحا واستغفرا الله  حطت عنهما خطاياهما. فهذه المصافحة عند اللقاء فيها خير عظيم، وفيها إيناس وتعارف وتقارب ومودة، وإبعاد للوحشة؛ فلا ينبغي ترك ذلك، بل ينبغي المحافظة على هذا الشيء، ولا حاجة إلى تقبيل اليد، ترك التقبيل أولى، فإن فعله بعض الأحيان لأسباب؛ كأن يكون عالمًا، أو أميرًا جرت العادة بتقبيل يديه، فإذا فعله بعض الأحيان لا بأس، أما اتخاذه عادة فأقل أحواله أنه مكروه لا ينبغي أن يتخذ عادة، لكن إذا فعل بعض الأحيان لبعض الأسباب فلا بأس، وتركه أولى بكل حال. وكان أصحاب النبي ﷺ إذا تلاقوا إذا لقوه ﷺ يصافحونه، ولا يقبلون يده، وربما قبل يده بعض الصحابة بعض الأحيان، لكنها أحوال قليلة، والمشهور عنهم  المصافحة، وهذا هو الأكثر، وتقبيل يده أو قدمه إنما هو شيء قليل جاء في بعض الأحاديث لأسباب فعلها بعض الصحابة عند قدومه من السفر. فالحاصل: أن السنة الغالبة هي المصافحة عند السلام واللقاء، أما تقبيل اليد إذا فعل بعض الأحيان فلا حرج فيه؛ لمصلحة شرعية أما اتخاذه عادة فهو خلاف السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17828/حكم-التقبيل-والانحناء-عند-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87310.mp3","categories":["الأخلاق المذمومة"]},{"id":18679,"question":"أعيش مع زوج أمي منذ أن كان عمري سبعة أشهر فقط، والآن عمري اثنتان وعشرون سنة، وأنا لا أعرف والدي، ولم أره في حياتي، وهو لا يعرفني، ولا يعرف شيئًا عني، ولا ينفق عليّ، وفي الفترة الأخيرة سكنت في نفس المنطقة التي يسكن فيها هو، وأيضًا لم يحاول رؤيتي أو حتى السؤال عني، وأنا إنسانة أخاف الله كثيرًا، وأبكي لعلمي بنتيجة قاطع الرحم، وأنا فتاة ومحكومة من أهلي، وهو رجل حر نفسه؛ لذلك لا أستطيع زيارته، فكيف أزور رجلًا إن رأيته بطريق لا أعرفه، فبماذا تنصحني؟جزاكم الله عني خير الجزاء.","title":"حكم قطيعة الأب لابنته","answer":"الجواب: لا ريب أنّ هذا العمل منكر منه، وقطيعة للرحم، والواجب عليه تقوى الله في ذلك، وأن يصل ابنته، ويحسن إليها، ويعرفها نفسه، وأن يظهر حنو الأبوة؛ حتى تعرفه ابنته، وحتى يبر ابنته، ويصل رحمه، وعليها هي أن تبره وتصله ولو جفا، وعليها أن تزوره مع من يعرفها به؛ حتى لا تغلط فيه، تزوره مع أخيها الذي يعرفه، أو مع أمها، أو مع خالتها، مع من يعرفها به؛ حتى تعرفه جيدًا، ولا تكن مثله قاطعة، بل تكون خيرًا منه، كما قال النبي ﷺ في الحديث الصحيح: ليس الواصل بالمكافئ، ولكن الواصل الذي إذا قطعت رحمه وصلها. فهي إذا وصلته تكون هي الواصلة وهو القاطع، ويكون لها أجر الصلة، وقد قال النبي ﷺ في الحديث الصحيح: لا يدخل الجنة قاطع رحم وقال ﷺ عن الله  أنه قال للرحم لما اشتكت إليه قال: ألا ترضين أن أصل من وصلك وأن أقطع من قطعك؟ قالت: بلى يا رب، قال: إن ذلك لك وفي اللفظ الآخر قال -جل وعلا-: من وصلك -يعني: الرحم- وصلته، ومن قطعك بتته هذا وعيد عظيم، وقال -عليه الصلاة والسلام-: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله؛ فليصل رحمه. فالواجب عليه أن يصلك، ويحسن إليك، ويتعرف عليك، ويقوم بواجب الأبوة، وعليك أنت ما هو أكبر من ذلك؛ لأنك بنته وحقه أكبر، فعليك أن تتعرفي عليه بواسطة الثقات من أمك أو أخيك ونحو ذلك، وعليك أن تصليه وتزوريه وتعتذريه إن كنت قصرت في حقه، وأنه إنما هجرك لأسباب فاعتذري إليه، وأحسني مخاطبته، واسأليه أن يعفو عما قصرت فيه. هذا هو الواجب عليك أن تكوني أكثر عناية بالصلة منه؛ لأن حقه أكبر؛ ولأن الواصل هو الذي يبدأ ليس الذي يكافئ، وإن كان المكافئ مأجور، لكن أفضل منه، وأعظم أجرًا الذي يصل من قطعه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17826/حكم-قطيعة-الاب-لابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87309.mp3","categories":["الأخلاق المذمومة"]},{"id":18725,"question":"إذا كان للمرأة ابن عم وعمره خمس عشرة سنة، هل يجب عليها أن تحتجب عنه أو لا؟","title":"حكم احتجاب المرأة عن ابن عمها","answer":"الجواب: نعم، إذا بلغ الطفل خمسة عشر سنة؛ وجب الاحتجاب على المرأة الأجنبية التي هي ليست محرمًا له، ووجب عليه الاستئذان، كما قال الله  في سورة النور: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ [النور:59]. فهذا يدل على أنهم قبل ذلك لا يجب عليهم الاستئذان إلا في العورات الثلاث، كما في الآيات الأخرى.  فالحاصل: أنه إذا بلغ خمسة عشر سنة، أو احتلم، ولو قبل ذلك بأن رأى في نومه أنه جامع المرأة، وأنزل المني، أو أنزل من دون جماع بأن تحركت شهوته فأنزل، ولو في غير نوم؛ فإنه يكون بهذا قد بلغ الحلم، ولو كان أقل من خمسة عشر سنة، وهكذا إذا أنبت الشعر الخشن حول الفرج؛ فإنه يبلغ بذلك. فينبغي للمرأة أن تحتاط وتستتر وتحتجب عن المراهق؛ لأن المراهق قد يكون بلغ بالسن أو بالاحتلام وإنزال المني أو بإنبات الشعر، فإذا علمت أنه كمل خمسة عشر سنة، فإن هذا رجل يتعين الاحتجاب عنه من كل امرأة ليست محرمًا له، ولو كانت ابنة عمه أو ابنة خاله أو ابنة عمته أو نحو ذلك؛ لقول الله -عز وجل- في الآية الأخرى: إِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولقوله سبحانه: يا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: ما يوضع فوق الرأس وفوق البدن، فيستر وجه المرأة وأطرافها. ولقوله  أيضًا في سورة النور: لا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31].. الآية، والبعولة هم الأزواج؛ ولما ثبت في الصحيحين عن عائشة -رضي الله عنها- أنها ذكرت لما سمعت صوت صفوان بن المعطل يسترجع حين تخلفت في بعض الغزوات قالت: \"إنه عرفني؛ فاسترجع، وذلك أنه كان قد رآني قبل الحجاب؛ فلما سمعت صوته خمرت وجهي\".  فدل ذلك على أنهم بعد الحجاب بعد نزول آية الحجاب أمروا بتخمير الوجوه، يعني: أمر النساء بتخمير الوجوه، وهذا كان في غزوة الإفك التي تخلفت فيها عائشة عن الغزو لما ذهبت تقضي حاجتها، فجاء الذين يرحلون فرحلوا هودجها يظنون أنها في الهودج لخفتها، فلما جاءت ولم تجدهم اضطجعت في محلها، وعلمت أنهم سيرجعون إليها. فلما رآها صفوان المعطل استرجع لما رآها، وأركبها فوق راحلته، وجعل يقود بها حتى أوصلها الجيش، وقالت عند ذلك أنها لما سمعت صوته خمرت وجهها، وكان قد رآها قبل الحجاب؛ فعرفها، فدل ذلك على أن النساء أمرن بعد الحجاب بتخمير الوجوه.  وأما حديث أسماء بنت أبي بكر الذي روته عائشة -رضي الله عنها- أختها فيما رواه أبو داود في سننه من طريق عائشة -رضي الله عنها- أن أسماء بنت أبي بكر دخلت على النبي ﷺ في بيت عائشة وعليها ثياب رقاق، فلما رآها النبي ﷺ أعرض عنها وقال: يا أسماء إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه فهذا الحديث قد تعلق به بعض الناس في التسهيل في كشف الوجه للنساء، وهو خطأ عظيم وغلط واضح؛ لأن هذا الحديث ضعيف جدًا من وجوه كثيرة، ولأن كشف المرأة وجهها من أسباب الفتنة والخطر؛ لأن زينتها في وجهها وعنوانها في وجهها دمامة وجمالًا. وهذا الحديث كما سبق ضعيف من وجوه: منها: أنه منقطع بين عائشة، والراوي عنها، فإن الراوي عنها هو خالد بن دريك ، وهو لم يسمع منها كما قال أبو داود وغيره، والحديث المنقطع يعتبر ضعيفًا لا حجة فيه. الوجه الثاني: أنه من رواية قتادة عن خالد بالعنعنة، وقتادة مدلس، وروايته بالعنعنة ضعيفة كسائر المدلسين المعروفين بالتدليس إذا لم يصرحوا بالسماع: كـابن إسحاق وغيره من المدلسين، فإن روايتهم تعتبر ضعيفة حتى يصرحوا بالسماع، ما عدا ما في الصحيحين، فإن ما رواه الشيخان محتمل؛ لأنهم فتشوا عن أحاديث المدلسين ورووا منها ما صح عندهم وثبت عندهم فيه السماع.\nوهناك وجه ثالث يضعف به الحديث أيضًا: وهو أنه من رواية سعيد بن بشير ، وهو ضعيف الرواية لا يحتج به. وهناك وجه رابع: وهو أنه لو صح لكان يحتمل أنه قبل نزول آية الحجاب، وما كان محتملًا، فلا يحتج به؛ لأن آية الحجاب دلت على وجوب التستر والحجاب، فلو صح لكان محمولًا على أن هذا كان قبل الحجاب، فإن النساء كن قبل الحجاب يكشفن وجوههن وأيديهن، فلما نزل الحجاب منعن من ذلك. وهناك وجه خامس: وهو أنه يبعد أن يقع هذا من أسماء، فالمتن منكر، المتن في نفسه منكر؛ لأنه يبعد أن يقع مثل هذا من أسماء مع فضلها وعلمها وجلالة قدرها، وكونها زوجة الزبير بن العوام حواري الرسول ﷺ ، يبعد أن يخفى عليها هذا الأمر، ويبعد أن تدخل على النبي ﷺ بالرقاق، فإن هذا لا يليق بأمثالها، ولا يظن بأمثالها، فهو منكر من هذه الحيثية.  فاجتمع في تضعيفه خمسة وجوه، كلها تدل على ضعفه، وأنه لا يجوز التعلق به في إباحة السفور للنساء، والله المستعان.","link":"https://binbaz.org.sa/fatwas/17850/حكم-احتجاب-المراة-عن-ابن-عمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_874/nour_87404.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":18837,"question":"سماحة الشيخ، إحداهن أكرهت على الزواج، وتزوجت من رجل معين، ودعت على نفسها بدعاء، ثم قدر أن تستمر الحياة الزوجية فترة معينة، وتصاب تلك المرأة بمرض مزمن أقعدها لمدة عشر سنوات، وهي الآن تفكر في ذلكم الموضوع إلى اليوم، ولا سيما وهي مقعدة مريضة، نصيحتكم لها.","title":"نصيحة لمن دعت على نفسها بمصيبة فمرضت","answer":"الجواب: ننصحها أن تتوب إلى الله، وتستغفر من دعائها على نفسها؛ لأنه لا يجوز للمسلم أن يدعو على نفسه، ليس للرجل أن يدعو على نفسه، ولا المرأة أن تدعو على نفسها، لا بالموت، ولا بالعمى، ولا بالمرض، ولا بأشباهها مما يضرها، المؤمن لا يدعو على نفسه، والمؤمنة كذلك لا تدعو على نفسها، فإذا قدر أنها أصيبت بشيء مما دعت به، أو بغيره من المصائب، فعليها التوبة والاستغفار، والحمد لله باب التوبة مفتوح لكل شيء، الحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17991/نصيحة-لمن-دعت-على-نفسها-بمصيبة-فمرضت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87808.mp3","categories":["الأخلاق المذمومة"]},{"id":18842,"question":"رسالة وصلت إلى البرنامج من اليمن الديمقراطية، محافظة حضرموت، صاحبها -آثر عدم ذكر اسمه- يسأل ويقول: الوالدان غصباني على الزواج من بنت عمي، وتزوجتها خوفًا من معصيتهما، وفكرت فيما بعد في تطليقها؛ لكني خفت أيضًا، ومن شدة غضبي؛ تمنيت لها الموت، وبعد سنة توفيت على ولادة، وخلفت بنتًا، ثم إني ندمت عدة مرات، وبكيت كثيرًا، حتى ظننت أني أنا السبب، هل أنا آثم في ذلك؟ أفتوني، جزاكم الله خيرًا.","title":"حكم تمني الموت للغير","answer":"الجواب: ليس عليك بأس في ذلك -إن شاء الله- فإن تمني الموت ليس من الدعاء، وليس من الظلم، بل هذا من شدة غضبك عليها، وبغضك لها، فلا يضرك ذلك، تمني الموت لا يضر الناس، تمني الموت إنما يتعب صاحبه، أما التمني فلا يضر المتمنى له الشيء، فلو تمنيت أن الإنسان يكون فقيرًا أو كذا، قد يقال في هذا أنه من باب تعاطي ما لا ينبغي للمؤمن؛ لأن المؤمن إنما يحب لأخيه ما يحب لنفسه، والمؤمن لا يحب لنفسه الموت؛ فلا يحبه لأخيه. فقصارى ما في هذا: أنه لا ينبغي لك التمني، ولكن ليس هذا هو السبب في موتها، ولا ينبغي لك في مثل هذا أن تجزع، بل تحمد الله على ما حصل، وتقول: إنا لله وإنا إليه راجعون، وتستغفر الله عما حصل منك، والتوبة بابها مفتوح، والحمد لله. فقصارى ما في هذا: أنك تمنيت شيئًا لا ينبغي لك أن تفعله؛ لأن المؤمن يحب لأخيه ما يحب لنفسه، فقد يدخل هذا في هذا، ويقول القائل: إنك تمنيت شيئًا لا ترضاه لنفسك، فكيف تتمناه لأختك في الله، فأكثر ما فيها أن تكون أخطأت في هذا؛ فعليك التوبة والاستغفار، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17983/حكم-تمني-الموت-للغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87803.mp3","categories":["الأخلاق المذمومة"]},{"id":18879,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ حامد محمد عيسى من رابغ، أخونا يسأل ويقول: حيث أنني عامل في بقالة لبيع المواد الغذائية، وقد لاحظت العديد من المظاهر التي اشمأزيت منها، وإنني أسأل: هل يجوز الكذب على من أعرفه أنه لا يصلي ولا يصوم ويدعي أنه مسلم، وكذلك هل يجوز غشهم؟أرجو أن ترشدوني جزاكم الله خيرًا.","title":"حكم غش وخيانة من لا يصلي ولا يصوم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الله  حرم على عباده الخيانة والغش؛ حيث قال : إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58]، وقال : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]، وقال : وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8] فهذه من صفات أهل الإيمان، وقال النبي ﷺ: من غشنا فليس منا فليس لك -أيها السائل- أن تغش من يشتري منك ويعاملك، سواء كان كافرًا أو مسلمًا، سواء كان يصلي أو لا يصلي. الواجب عليك أن تؤدي الأمانة، وأن تبيع بأمانة ونظافة، وعدم غش، وعدم خيانة، وإذا علمت أن أحدًا لا يصلي، أو أنه يفعل شيء من المنكر؛ فعليك أن تنصحه إذا استطعت ذلك، وأن تعلمه ما ينفعه، وأن ترشده إلى الخير، وأن تنكر عليه المنكر، كما قال الله  وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] وقال النبي ﷺ: الدين النصيحة، قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله، ولأئمة المسلمين وعامتهم فانصح من ترى منه ما يخالف الشرع حسب طاقتك، أما الغش والخيانة فلا، نعم.","link":"https://binbaz.org.sa/fatwas/18016/حكم-غش-وخيانة-من-لا-يصلي-ولا-يصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88001.mp3","categories":["الأخلاق المذمومة"]},{"id":18947,"question":"هذه سائلة تقول: بالنسبة لرمضان سماحة الشيخ، الغيبة والنميمة هل تفطر في رمضان؟ وما الأسباب المعينة على التدبر والخشوع في الصلاة؟","title":"حكم الغيبة والنميمة في رمضان","answer":"الجواب: الغيبة والنميمة معصيتان كبيرتان، ولكن لا تفطر الصائم، لكن عليه إثم كبير؛ لأنهما من كبائر الذنوب في رمضان أو في غيره، لكن لا تفطر الصائم.","link":"https://binbaz.org.sa/fatwas/18136/حكم-الغيبة-والنميمة-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88238.mp3","categories":["الأخلاق المذمومة"]},{"id":18985,"question":"من الباحة هذه رسالة بعثت بها إحدى الأخوات تقول: مشاعل الغامدي، أختنا لها مجموعة من الأسئلة في أحد أسئلتها سؤال يقول: هل يجوز الغش في الامتحان؟ علمًا بأن ذلك ليس في المواد الدينية.","title":"حكم الغش في الامتحانات في غير المواد الدينية","answer":"الجواب: لا يجوز الغش في الامتحان لا في المواد الدينية، ولا في غيرها، الواجب على الطالب والطالبة أن يؤدي الامتحان بغاية الأمانة؛ لأن المقصود أن تعرف منزلته في العلم وأهليته ومدى ذكائه وفطنته، فالخيانة تفسد هذا وتضيع هذا، فالواجب على الطالب وعلى الطالبة أن يؤدي الأمانة، وأن يبتعد عن الغش؛ لعموم قوله ﷺ: من غشنا فليس منا فالرسول ﷺ نهى عن الغش، وقال: من غشنا فليس منا وهذا من جوامع الكلم يعم الغش في البيع والشراء، ويعم الغش في الامتحان والاختبار، ويعم الغش في غير ذلك، حتى ولو كانت المادة إنجليزية أو حسابية أو غير ذلك، الواجب أن تؤدي الأمانة الطالبة والطالب جميعًا، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18083/حكم-الغش-في-الامتحانات-في-غير-المواد-الدينية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92406.mp3","categories":["الأخلاق المذمومة","العالم والمتعلم"]},{"id":19005,"question":"يسأل أخونا ويقول: إذا التزم العبد بأوامر الله ، وبسنة رسوله ﷺ فماذا يفعل؟ وهل يجوز له أن يضحك في كل الأوقات؟ علمًا بأنه ساكن مع جماعة يكثرون الضحك، والكلام الذي لا يليق. أفيدوني جزاكم الله خيرًا.","title":"حكم الإكثار من الضحك","answer":"الجواب: إذا التزم المؤمن بكل ما أمر الله به ورسوله هذا هو كمال الإيمان، وهذا من توفيق الله جل وعلا، فإذا التزم بطاعة الله ورسوله في كل ما أمر الله به ورسوله، والتزم بترك ما نهى الله عنه ورسوله، وجاهد نفسه، وتاب إلى الله من سالف معاصيه؛ فهذا هو المؤمن حقًا، وهو المسلم حقًا. فعليه أن يجتهد في ذلك، ويلزم التوبة، والاستقامة، ويسأل ربه التوفيق والإعانة، ويحذر مجالسة من يجره إلى ما حرم الله، يحرص على صحبة الأخيار. ولا بأس بأن يضحك عند الحاجة والتبسم، النبي ﷺ وهو سيد ولد آدم، وهو سيد المؤمنين وأفضلهم؛ كان يضحك عند وجود أسباب، ويتبسم عند وجود أسباب، يتحدث مع أصحابه في الأشياء الطيبة، ويضاحكهم عليه الصلاة والسلام، ويتبسم في كثير من الأوقات، ويسألهم عن أحوالهم، ويبدؤهم بالسلام، ويرد عليهم السلام، ويسألهم عن بعض الأمور الجاهلية للتنبيه على ما فيها من الشر والخطأ، ولما فيها من بعض العجائب. فعليك أن تكون حسن الخلق مع إخوانك طيب الخلق، ولا بأس عليك بالضحك عند وجود أسباب أو التبسم، ولا بأس بالتحدث معهم فيما أباح الله أو فيما شرع الله. ومع أهلك تحسن خلقك مع أهلك، تحدث معهم في الكلام الطيب، والأشياء التي تتعلق بالبيت، أو السواليف التي تتعلق بالأهل فيما لا يحرم من الأشياء المباحة، والأشياء التي تؤنسهم وليس فيها معصية. لا تكن مكفهرًا عنيفًا، سيء الخلق، لا، هذا ما هو من الإسلام، هذا ما هو من الدين، من الدين أن تكون حسن الخلق، طيب البشر، حسن المقابلة، طيب الكلام، طيب المجالسة، هكذا ينبغي للمؤمن والمؤمنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18167/حكم-الاكثار-من-الضحك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79508.mp3","categories":["الأخلاق المذمومة"]},{"id":19035,"question":"هذه السائلة أم رشيدة من اليمن الخضراء تقول سماحة الشيخ: أحيانًا أكون في مجلس ومعي بعض من النساء، فيدخل علينا الرجل الكبير في العمر فيسلم ويمد يده للمصافحة، وأنا لم أمد يدي لكن النساء الذي معي يغضبن علي، هل هذا العمل صحيح أم لا ؟","title":"حكم مصافحة المرأة للرجل الأجنبي المسن","answer":"الجواب: المرأة لا تصافح الرجال من غير محارمها، ولكن يرد عليه السلام يقال: وعليكم السلام أما أنه يصافح لا، لا تجوز مصافحة المرأة للرجل الأجنبي، إنما تصافح محرمها كأخيها وأبيها، أما الأجانب لا، يقول النبي ﷺ: إني لا أصافح النساء، وتقول عائشة رضي الله عنها: \"والله ما مست يد رسول الله يد امرأة قط ما كان يبايعهن إلا بالكلام\"، عليه الصلاة والسلام. فعليك أن تنكري عليهم إذا صافحوا أنكري عليهم وعلميهم وأرشديهم بارك الله فيك. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18198/حكم-مصافحة-المراة-للرجل-الاجنبي-المسن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88303.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":19069,"question":"هذه أخت سائلة تقول: بأنها فتاة ملتزمة بفضل الله، ومن الله عليها بالتقوى وحلاوة الإيمان وغض البصر، علمًا تقول: بأنها في جامعة مختلطة، وأسرتها غير ملتزمة، وتلبس الحجاب بدون غطاء الوجه، فهل عليها وزر؛ لأنها تكشف الوجه؟","title":"حكم دراسة المرأة في الجامعات المختلطة","answer":"الجواب: لا يجوز لها الدراسة مع الطلبة مختلطة بالشباب، ولا يجوز لها كشف الوجه، بل يجب عليها الحجاب، والبعد عن الاختلاط، ولو تركت الدراسة حتى يتيسر لها دراسة غير مختلطة؛ لأن الدراسة المختلطة وسيلة إلى شر كبير إذا كانت مع الأولاد في الصفوف صفوف الدراسة، وليس لها كشف الوجه بل عليها [تغطيته] الله يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31]، الآية. والوجه من أعظم الزينة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18261/حكم-دراسة-المراة-في-الجامعات-المختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88326.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":19113,"question":"قضية أخرى يسأل فيها أخونا محمد يوسف من جدة ويقول: ظهرت طريقة سيئة بين تلاميذ المدارس هذه الأيام، وهي الاعتماد الكلي على الغش في الامتحانات، ويفعلون ذلك حتى في نهار رمضان، وعندما أخبرتهم أن هذا لا يجوز استنادًا للحديث الشريف: من غشنا فليس منا إلا أنهم يعتذرون بأن الغش أفضل وسيلة للنجاح، علمًا بأن البعض منهم يحصل على أعلى الدرجات عن طريق الغش وينجحون بتفوق.وهذا ما يجعلني دائمًا متأخرًا في دراستي لأنني اعتمد على نفسي، فهل أنا على خطأ؟ أم أن القول المأثور صحيح حيث يقولون: إن الضرورات تبيح المحظورات؟أرجو من سماحتكم الإجابة الشافية جزاكم الله خيرًا.","title":"حكم الغش في الامتحانات","answer":"الجواب: الغش في الامتحان محرم ومنكر كالغش في المعاملات، وقد يكون أعظم من الغش في المعاملات؛ لأنه قد يحصل له وظائف كبيرة بأسباب الغش، فالغش محرم في الامتحانات في جميع الدروس؛ لقول النبي ﷺ في الحديث الصحيح: من غشنا فليس منا ولأنه خيانة والله يقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27]. فالواجب على الطلبة في أي مادة أن لا يغشوا، وأن يجتهدوا في الاستعداد حتى ينجحوا نجاحًا شرعيًا. وأما أنت فقد أحسنت في عدم الغش، وعليك أن تجتهد وعليك أن تسلك الطريق السوي ولو تأخرت في بعض المواد، فالحق أحق بالاتباع وأبشر بالخير والعاقبة الحميدة. وإذا صدقت في الاستعداد والعناية يسر الله أمرك كما قال سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا .. [الأنفال:29] الآية، والفرقان النور والعلم والهدى. فاجتهد في طلب العلم من طريقه الطيب واحرص على بذل الجهد في تحصيل العلم، وأحسن ظنك بالله واسأله التوفيق، وأبشر بالخير والعاقبة الحميدة، ولا تغتر بالغشاشين ولا تغبطهم على غشهم لأنهم قد ارتكبوا كبيرة من الكبائر وحصلوا على خطر عظيم، نسأل الله السلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18288/حكم-الغش-في-الامتحانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_931/nour_93105.mp3","categories":["الأخلاق المذمومة"]},{"id":19211,"question":"من اليمن الشمالي الحديدة المستمع (س. ب. أ) بعث يسأل ويقول: ما الحكم في شهادة الزور عمدًا على الأبرياء؟ وما جزاء شاهدها بالأدلة الصحيحة؟ جزاكم الله خيرًا.","title":"التحذير من شهادة الزور","answer":"الجواب: شهادة الزور من أكبر الكبائر ومن أعظم الذنوب يقول الله سبحانه: فَاجْتَنِبُوا الرِّجْسَ مِنَ الأَوْثَانِ وَاجْتَنِبُوا قَوْلَ الزُّورِ [الحج:30]، ويقول النبي ﷺ في الحديث الصحيح: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين، وكان متكئًا فجلس فقال: ألا وقول الزور ألا وشهادة الزور، فما زال يكررها حتى قلنا: ليته سكت. يعني: ما زال يكرر التحذير من شهادة الزور، حتى قال الصحابة: ليته سكت، يعني: إبقاءً عليه لئلا يشق على نفسه عليه الصلاة والسلام. والمقصود من هذا التحذير منها، وإن كان الشرك أكبر والعقوق أكبر لكنها جريمة عظيمة يتعلق بها شر عظيم وظلم للناس، واستحلال الفروج والأموال والأعراض والدماء بغير ما شرع الله، فلهذا صارت جريمة عظيمة. ويجب على ولي الأمر إذا عرف ذلك أن يعاقب شاهد الزور بالعقوبة الرادعة، من الجلد والسجن، ونحو ذلك مما يكون زاجرًا له ولأمثاله؛ لأنها جريمة يترتب عليها فساد كبير وشر عظيم فاستحق صاحبها أن يعاقب عقوبة رادعة من ولي الأمر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18386/التحذير-من-شهادة-الزور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93306.mp3","categories":["القضاء والشهادات","الأخلاق المذمومة"]},{"id":19225,"question":"شيخ عبد العزيز ! اجتمع لي في هذه الحلقة ثلاث رسائل، ومرسلوها من أخواتنا المسلمات المستمعات، وقضيتهن واحدة تقريبًا، لعل إحدى هذه الرسائل تعبر عن تلكم القضية، فهذه إحداهن تقول: أنا أختكم في الإسلام، وأنا أعاني من مشاكل في حياتي، وهي أنني أعيش في وسط بعيد كل الناس فيه عن الدين، فأنا أدرس في معهد، وهذا المعهد مختلط بين الجنسين، ويمنع فيه لبس أي نوع من الحجاب، وكل الذين موجودين فيه بعيدين عن الدين، وأنا أجد نفسي أتأثر بتصرفاتهم، ويزداد بعدي عن الله وعن إقامة فرائضه وهي الصلاة، حيث أقول لنفسي: ما نفع صلاتي، وأنا أضطر كل يوم إلى ارتكاب المحرمات والمعاصي بقصد وبدون قصد، وأريد منكم أن ترشدوني إلى الطريق الذي فيه سلامتي من غضب الله وراحة للنفس، مع أنني لا أستطيع أن أترك الدراسة وأحافظ على العزلة؛ لأن الشهادة في هذا الزمن ضرورية جدًا وبخاصة لي، أفيدوني جزاكم الله خيرًا.ورسالة أخرى وصلت من العراق في نفس المعنى، وثالثة من جمهورية مصر العربية، نرجو من سماحة الشيخ أن يتفضل بتوجيه الأخوات إلى الطريق الأمثل وهن في ذلكم الوسط الذي وصفنه في رسائلهم.","title":"نصيحة لمن تدرس في بيئة مختلطة","answer":"الجواب: مقتضى الأدلة الشرعية أن الدراسة إذا كانت تشتمل على ما يضر الدارسة أو الدارس أنه لا حاجة إليها؛ لأن الواجب أن يتعلم المسلم ما لا يسعه جهله، وهذا في إمكانه أن يتعلمه من المعلمين في المساجد مع الحجاب والبعد عن الفتنة، في المدارس الأهلية السليمة، في بيت بواسطة أبيه أو أمه أو امرأة صالحة أو ما أشبه ذلك. أما هذه الدراسة المختلطة، هذه خطرها عظيم وفسادها كبير ولا سيما أيضًا مع السفور وعدم الحجاب، فيجتمع الشر كله، فالذي أنصح به هؤلاء الأخوات أن يدعن هذه الدراسة وأن يبتعدن عن هذه الدراسة حفاظًا على دينهن وعلى أخلاقهن، وسوف يجعل الله لهن فرجًا ومخرجًا من طريق دراسة سليمة يحصل بها معرفة الدين من دون وقوع فيما حرم الله. وليست الوظائف ضرورية وليست الشهادات ضرورية، فقد مر السلف الأول وليسوا ممن يتعاطى هذا الأمر، ويمكن العمل في أشياء أخرى بدون هذه الشهادة. وليس من الضروري أيضًا العمل؛ لأن الرجال قوامون على النساء، وفي إمكانها أن تتزوج ويقوم عليها الزوج، أو يقوم عليها والدها أو إخوتها فيما تحتاج إليه، فالرجال قوامون على النساء. وبكل حال هذه الدراسة منكر وشر عظيم وعواقبها وخيمة، وسوف يجعل الله لمن تركها فرجًا ومخرجًا، وسوف يسهل الله له طلبه السليم إذا صدق في ذلك، وكان قصده وجه الله والدار الآخرة، كما قال الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]، فعلى الطالب والطالبة في هذه الأقسام عليه الحذر وعليها الحذر، عليهما الحذر جميعًا، فالبقاء في هذه الدراسة تعريض للنفس والعرض والدين لما لا تحمد عقباه، والمسلم مأمور بأن يصون نفسه عما حرم الله، وأن يبتعد عن أسباب الخطر، وقد وعد الله عباده بتفريج الكروب وتيسير الأمور، فعند الضيق يجيء الفرج، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فهذه نصيحتي لهؤلاء الأخوات ولأشباههن من الطالبات في المدارس والمعاهد والكليات المختلطة، نصيحتي للجميع ترك هذه الدراسة والمطالبة لولاة الأمور بدراسة غير مختلطة للنساء على حدة وللرجال على حدة، ومتى صدق الشعب في هذه الأمور وطلب من ولاة الأمور إفراد النساء وإفراد الرجال كل على حدة، كل في دراسة تخصه، فإن ولاة الأمور لا بد أن يستجيبوا؛ لأن هذا أمر معقول ومصلحته ظاهرة، وإذا جد فيه الشعب الطيب، وبين لولاة الأمور الأضرار العظيمة والعواقب الوخيمة فإن ولاة الأمور إن شاء الله يستجيبون لهذا الأمر إذا رأوا من الشعب الصدق في ذلك والهمة العالية في ذلك. ولا يجوز للإنسان أن يقول: هذا مستحيل أو هذا أمر غير ممكن، لا، كل هذه دعوى لا تليق، بل ينبغي أن نحسن الظن بالله وأن لا نيئس من الإصلاح، وولاة الأمور في بلاد المسلمين يرجى لهم الهداية إذا صدقوا وإذا أرادوا الخير، والله المسئول أن يهديهم ويوفقهم للخير، وأن يصلح لهم القلوب والأعمال والبطانة، وأن يشرح صدورهم للتمسك بشريعة الله وللحكم بشريعة الله، فعلى الشعب أن يعينهم على هذا، وأن لا يطاوع فيما حرم الله، بل يكون عنده النشاط والهمة العالية في فعل ما أمر الله وترك ما نهى الله، رزق الله الجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18416/نصيحة-لمن-تدرس-في-بيىة-مختلطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89005.mp3","categories":["الأخلاق المذمومة","قضايا المرأة","النظر والخلوة والاختلاط"]},{"id":19273,"question":"أيضًا نعود إلى رسالة المستمعة: هدى، أختنا تسأل في هذه الحلقة وتقول: عندما أكون مذاكرة جدًا، ولكنني نسيت شيئًا ما، وحاولت سؤال صديقتي وكان ذلك في امتحان، هل هذا يعتبر من الغش؟","title":"حكم سؤال الطالب زميله في الامتحان","answer":"الجواب: الذي يظهر أن حال الامتحان ليس فيه سؤال، إذا كان الامتحان يمنع فيه السؤال من التلميذة لزميلتها، والتلميذ لزميله، فهو يكون من الغش، فيكون البحث والاجتهاد قبل ذلك، قبل الحضور في قاعة الامتحان، أما في قاعة الامتحان فعلى الطالب والطالبة الالتزام بالتعليمات، وليس لأحد منهم مخالفة التعليمات؛ لأن المقصود معرفة ما لديهم من العلم والفضل والبصيرة والفقه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18459/حكم-سوال-الطالب-زميله-في-الامتحان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89205.mp3","categories":["الأخلاق المذمومة"]}]
